function M.short_label(role)
    if not role then return "STAFF" end
    if role == "Game Moderator" then return "MOD" end
    if role == "Game Tester" then return "TESTER" end
    if role == "Lead Developer" or role == "Developers" then return "DEV" end
    if role == "Co-Founder" then return "CO-FOUNDER" end
    if role == "Founder" then return "FOUNDER" end
    if role == "OG" then return "OG" end
    if role == "Contribution" then return "CONTRIB" end
    return role:upper()
end
function M.glyph_kind(role)
    if not role then return "staff" end
    local r = role:lower()
    if r:find("moderator", 1, true) then return "mod" end
    if r:find("tester", 1, true) then return "tester" end
    if r:find("developer", 1, true) or r:find("founder", 1, true) then return "dev" end
    if r == "og" then return "og" end
    if r:find("contribution", 1, true) then return "contrib" end
    return "staff"
end
local function normalize_uid(user_id)
    local uid = tonumber(user_id)
    if not uid or uid == 0 then return nil end
    return uid
end
M._player_roles = {}
local function mod_group()
    return Infernal.require("game.mod_group")
end
local function player_state()
    return Infernal.require("game.player_state")
end
function M.reset_session()
    M._player_roles = {}
    local group = mod_group()
    if group.reset_session then
        group.reset_session()
    end
end
function M.clear_role_cache()
    M._player_roles = {}
end
function M.invalidate_uid(user_id)
    local uid = normalize_uid(user_id)
    if uid then
        M._player_roles[uid] = nil
    end
end
local function player_uid(player)
    local ep = Infernal.require("core.entity_props")
    return normalize_uid(ep.user_id(player))
end
local function cache_key(player)
    local uid = player_uid(player)
    if uid then return uid end
    return player.name or player.display_name
end
local function read_cached_role(key)
    if key == nil then return nil, false end
    if M._player_roles[key] == nil then
        return nil, false
    end
    local cached = M._player_roles[key]
    if cached == false then return nil, true end
    return cached, true
end
local function write_cached_role(key, role)
    if key == nil then return end
    M._player_roles[key] = role or false
end
local function role_from_game_tag(player)
    local tag = player_state().staff_tag(player)
    if tag == "OWNER" then return "Founder" end
    if tag == "ADMIN" then return "Developers" end
    if tag == "MOD" then return "Game Moderator" end
    return nil
end
function M.role_for(user_id)
    local uid = normalize_uid(user_id)
    if not uid then return nil end
    local group = mod_group()
    if group.available() then
        local live = group.role_for(uid)
        if live then return live end
    end
    return M.ROLES[uid]
end
function M.role_for_player(player, opts)
    if not player or player.is_local then return nil end
    opts = opts or {}
    local key = cache_key(player)
    local cached, hit = read_cached_role(key)
    if hit then
        return cached
    end
    local tag_role = role_from_game_tag(player)
    if tag_role then
        local uid = player_uid(player)
        if uid then
            local precise = opts.live_lookup == false and M.ROLES[uid] or M.role_for(uid)
            if precise then
                write_cached_role(key, precise)
                return precise
            end
        end
        write_cached_role(key, tag_role)
        return tag_role
    end
    local uid = player_uid(player)
    if not uid then
        return nil
    end
    local group = mod_group()
    if opts.live_lookup ~= false and group.available() then
        local live = group.role_for(uid)
        if live then
            write_cached_role(key, live)
            return live
        end
        if opts.queue_lookup and group.is_started and group.is_started() then
            group.queue_lookup(uid)
        end
    end
    local static_role = M.ROLES[uid]
    if static_role then
        write_cached_role(key, static_role)
        return static_role
    end
    if opts.mark_unknown then
        write_cached_role(key, false)
    end
    return nil
end
function M.is_mod(user_id)
    return M.role_for(user_id) ~= nil
end
function M.is_staff_player(player)
    return M.role_for_player(player) ~= nil
end
function M.ensure_started()
    local group = mod_group()
    if group.available() then
        return group.ensure_started()
    end
    return false
end
function M.stop(reason)
    local group = mod_group()
    if group.stop then group.stop(reason) end
end
function M.tick()
    M.ensure_started()
end
function M.invalidate_player(player)
    if not player then return end
    local key = cache_key(player)
    if key ~= nil then
        M._player_roles[key] = nil
    end
end
return M
end)()

Infernal._mods["game.mod_group"] = (function()
local debug = Infernal.require("core.debug")
local M = {}
M.GROUP_ID = 1154360
M.MIN_STAFF_RANK = 6
M._cache = {}
M._cache_ready = false
M._cache_at = 0
M._refresh_ms = 30 * 60 * 1000
M._started = false
M._thread_id = nil
local TICK_MS = 3500
local RATE_LIMIT_MS = 15 * 60 * 1000
local RETRY_BASE_MS = 30 * 1000
local RETRY_MAX_MS = 10 * 60 * 1000
local MAX_QUEUE = 64
local MAX_PAGES = 80
local MAX_ROLES = 32
local MAX_TOTAL_PAGES = 256
local MAX_STAFF_ENTRIES = 10000
local MAX_BODY_BYTES = 2 * 1024 * 1024
local lookup_queue = {}
local lookup_pending = {}
local lookup_seen = {}
local lookup_attempts = {}
local crawl = nil
local next_attempt_at = 0
local crawl_failure_count = 0
local lookup_failure_count = 0
local loaded_notified = false
local tick_busy = false
local function tick_ms()
    local fn = utility and (utility.get_tick_count or utility.GetTickCount)
    if type(fn) ~= "function" then return 0 end
    local ok, value = pcall(fn)
    return ok and (tonumber(value) or 0) or 0
end
local function log(message)
    debug.file("STAFF_CRAWLER " .. tostring(message))
end
local function normalize_uid(value)
    local uid = tonumber(value)
    return uid and uid ~= 0 and uid or nil
end
local function http_fn()
    return utility and (utility.http_get or utility.HttpGet) or nil
end
local function status_code(status)
    local code = tonumber(status)
    if code then return code end
    if type(status) == "string" then return tonumber(status:match("(%d%d%d)")) end
    return nil
end
local function request(url)
    local fn = http_fn()
    if type(fn) ~= "function" then return nil, "no HttpGet", nil end
    local ok, body, status = pcall(fn, url)
    if not ok then return nil, tostring(body), nil end
    local code = status_code(status)
    if type(body) == "string" and #body > MAX_BODY_BYTES then
        return nil, "response too large", code
    end
    if type(body) ~= "string" or body == "" then
        return nil, tostring(status or "empty response"), code
    end
    if code and (code < 200 or code >= 300) then
        return nil, "HTTP " .. tostring(code), code
    end
    return body, nil, code or 200
end
local function cache_count(tbl)
    local count = 0
    for _ in pairs(tbl or {}) do count = count + 1 end
    return count
end
local function url_encode(value)
    return (tostring(value or ""):gsub("([^%w%-_%.%~])", function(ch)
        return string.format("%%%02X", string.byte(ch))
    end))
end
local function parse_cursor(body)
    if not body or body:find('"nextPageCursor"%s*:%s*null') then return nil end
    local cursor = body:match('"nextPageCursor"%s*:%s*"([^"]+)"')
    return cursor ~= "" and cursor ~= "null" and cursor or nil
end
local function parse_roles(body)
    local roles = {}
    local overflow = false
    local payload = body and (body:match('"roles"%s*:%s*(%b[])') or body) or ""
    for block in payload:gmatch("%b{}") do
        local id = tonumber(block:match('"id"%s*:%s*(%d+)'))
        local name = block:match('"name"%s*:%s*"([^"]+)"')
        local rank = tonumber(block:match('"rank"%s*:%s*(%d+)'))
        local members = tonumber(block:match('"memberCount"%s*:%s*(%d+)')) or 0
        if id and name and rank and rank >= M.MIN_STAFF_RANK then
            if #roles >= MAX_ROLES then
                overflow = true
            else
                roles[#roles + 1] = {
                    id = id,
                    name = name,
                    rank = rank,
                    members = members,
                    loaded = 0,
                    pages = 0,
                }
            end
        end
    end
    table.sort(roles, function(a, b) return a.rank > b.rank end)
    return roles, overflow
end
local function parse_role_users(body, role_name, out, max_new)
    local added = 0
    for uid_text in tostring(body or ""):gmatch('"userId"%s*:%s*(%d+)') do
        local uid = tonumber(uid_text)
        if uid then
            if out[uid] == nil then
                if added >= max_new then return added, true end
                added = added + 1
            end
            out[uid] = role_name
        end
    end
    return added, false
end
local function parse_user_role(body)
    local gid = tostring(M.GROUP_ID)
    local pos = 1
    while true do
        local start_at = body:find('"group"', pos, true)
        if not start_at then return nil end
        local chunk = body:sub(start_at, math.min(#body, start_at + 500))
        if chunk:match('"id"%s*:%s*(%d+)') == gid then
            local role = chunk:match('"role"%s*:%s*{(.-)}')
            local rank = role and tonumber(role:match('"rank"%s*:%s*(%d+)'))
            local name = role and role:match('"name"%s*:%s*"([^"]+)"')
            if rank and name then return rank >= M.MIN_STAFF_RANK and name or false end
            return nil
        end
        pos = start_at + 7
    end
end
local function invalidate_role_cache(uid)
    pcall(function()
        local ids = Infernal.require("game.mod_ids")
        if uid and ids.invalidate_uid then
            ids.invalidate_uid(uid)
        elseif ids.clear_role_cache then
            ids.clear_role_cache()
        end
    end)
end
local function notify_loaded(count, roles)
    if loaded_notified then return end
    loaded_notified = true
    pcall(function()
        Infernal.require("core.notify").success(string.format(
            "Live staff crawler ready (%d people, %d roles)", count, roles
        ), 5500)
    end)
end
local function abort_crawl()
    crawl = nil
end
local function backoff(reason, code, uid)
    if uid then
        lookup_failure_count = lookup_failure_count + 1
    else
        crawl_failure_count = crawl_failure_count + 1
    end
    local failures = uid and lookup_failure_count or crawl_failure_count
    local now = tick_ms()
    local delay
    if code == 429 then
        delay = RATE_LIMIT_MS
    else
        delay = math.min(RETRY_BASE_MS * (2 ^ math.min(failures - 1, 5)), RETRY_MAX_MS)
    end
    next_attempt_at = now + delay
    abort_crawl()
    if uid and (lookup_attempts[uid] or 0) < 3 and not lookup_pending[uid] then
        lookup_pending[uid] = true
        lookup_queue[#lookup_queue + 1] = uid
    end
    log(string.format(
        "backoff reason=%s status=%s delay_ms=%d",
        tostring(reason), tostring(code or "none"), delay
    ))
end
local function begin_crawl()
    crawl = {
        phase = "roles",
        roles = nil,
        role_index = 1,
        cursor = nil,
        staging = {},
        entry_count = 0,
        total_pages = 0,
    }
    log("state=roles")
end
local function commit_crawl()
    local count = cache_count(crawl.staging)
    if count < 1 then
        backoff("empty roster", nil)
        return
    end
    M._cache = crawl.staging
    M._cache_ready = true
    M._cache_at = tick_ms()
    local role_count = #crawl.roles
    crawl = nil
    crawl_failure_count = 0
    next_attempt_at = 0
    invalidate_role_cache()
    log(string.format("commit people=%d roles=%d", count, role_count))
    notify_loaded(count, role_count)
end
local function step_lookup()
    local uid = table.remove(lookup_queue, 1)
    if not uid then return false end
    lookup_pending[uid] = nil
    lookup_attempts[uid] = (lookup_attempts[uid] or 0) + 1
    local body, err, code = request(string.format(
        "https://groups.roblox.com/v2/users/%d/groups/roles", uid
    ))
    if not body then
        backoff("user " .. tostring(uid) .. ": " .. tostring(err), code, uid)
        return true
    end
    local role = parse_user_role(body)
    lookup_seen[uid] = true
    lookup_attempts[uid] = nil
    lookup_failure_count = 0
    if role then
        M._cache[uid] = role
        invalidate_role_cache(uid)
        log("user_match uid=" .. tostring(uid) .. " role=" .. tostring(role))
    end
    return true
end
local function step_roles()
    local body, err, code = request(string.format(
        "https://groups.roblox.com/v1/groups/%d/roles", M.GROUP_ID
    ))
    if not body then
        backoff("roles: " .. tostring(err), code)
        return
    end
    local roles, overflow = parse_roles(body)
    if overflow then
        backoff("role limit", code)
        return
    end
    if #roles < 1 then
        backoff("roles: empty response", code)
        return
    end
    crawl.roles = roles
    crawl.role_index = 1
    crawl.cursor = nil
    crawl.phase = "pages"
    log("state=pages roles=" .. tostring(#roles))
end
local function advance_role()
    crawl.role_index = crawl.role_index + 1
    crawl.cursor = nil
    if crawl.role_index > #crawl.roles then commit_crawl() end
end
local function step_page()
    local role = crawl.roles[crawl.role_index]
    if not role then
        commit_crawl()
        return
    end
    role.pages = role.pages + 1
    crawl.total_pages = crawl.total_pages + 1
    if role.pages > MAX_PAGES or crawl.total_pages > MAX_TOTAL_PAGES then
        backoff("page limit for " .. tostring(role.name), nil)
        return
    end
    local url = string.format(
        "https://groups.roblox.com/v1/groups/%d/roles/%d/users?limit=100&sortOrder=Asc",
        M.GROUP_ID, role.id
    )
    if crawl.cursor then url = url .. "&cursor=" .. url_encode(crawl.cursor) end
    local body, err, code = request(url)
    if not body then
        backoff("role " .. tostring(role.name) .. ": " .. tostring(err), code)
        return
    end
    local added, overflow = parse_role_users(
        body, role.name, crawl.staging, MAX_STAFF_ENTRIES - crawl.entry_count
    )
    role.loaded = role.loaded + added
    crawl.entry_count = crawl.entry_count + added
    if overflow then
        backoff("staff entry limit", nil)
        return
    end
    crawl.cursor = parse_cursor(body)
    if not crawl.cursor then
        if role.members > 0 and role.loaded < role.members then
            backoff(string.format(
                "incomplete %s %d/%d", role.name, role.loaded, role.members
            ), nil)
            return
        end
        log(string.format(
            "role_complete name=%s members=%d pages=%d",
            role.name, role.loaded, role.pages
        ))
        advance_role()
    end
end
local function scheduler_tick()
    if not M._started then return end
    local now = tick_ms()
    if now < next_attempt_at then return end
    if step_lookup() then return end
    if not crawl then
        if M._cache_ready and now - M._cache_at < M._refresh_ms then return end
        begin_crawl()
    end
    if crawl.phase == "roles" then
        step_roles()
    elseif crawl.phase == "pages" then
        step_page()
    end
end
local function guarded_tick()
    if tick_busy then return end
    tick_busy = true
    local ok, err = pcall(scheduler_tick)
    tick_busy = false
    if not ok then backoff("scheduler error: " .. tostring(err), nil) end
end
function M.available()
    return type(http_fn()) == "function"
end
function M.is_started()
    return M._started == true
end
function M.role_for(user_id)
    local uid = normalize_uid(user_id)
    return uid and M._cache[uid] or nil
end
function M.is_ready()
    return M._cache_ready == true
end
function M.queue_lookup(user_id)
    local uid = normalize_uid(user_id)
    if not uid or M._cache[uid] or lookup_seen[uid] or lookup_pending[uid] then return end
    if #lookup_queue >= MAX_QUEUE or (lookup_attempts[uid] or 0) >= 3 then return end
    lookup_pending[uid] = true
    lookup_queue[#lookup_queue + 1] = uid
end
function M.lookup_user(user_id)
    M.queue_lookup(user_id)
    return M.role_for(user_id)
end
function M.refresh_all()
    if tick_ms() < next_attempt_at then return false end
    M._cache_at = 0
    abort_crawl()
    return M._started
end
function M.force_refresh()
    loaded_notified = false
    return M.refresh_all()
end
function M.ensure_started()
    if M._started or not M.available() then return M._started end
    local create = thread and (thread.create or thread.Create)
    if type(create) ~= "function" then
        debug.warn_once("mod_group:nothread", "Live staff crawler unavailable: no thread API")
        return false
    end
    M._started = true
    local ok, id = pcall(create, guarded_tick, TICK_MS)
    if not ok or not id then
        M._started = false
        M._thread_id = nil
        debug.error_once("mod_group:start", id or "thread.Create failed")
        return false
    end
    M._thread_id = id
    local first_tick = tick_ms() + TICK_MS
    if next_attempt_at < first_tick then next_attempt_at = first_tick end
    log("started interval_ms=" .. tostring(TICK_MS))
    return true
end
function M.stop(reason)
    if M._thread_id then
        local stop = thread and (thread.stop or thread.Stop)
        if type(stop) == "function" then pcall(stop, M._thread_id) end
    end
    M._thread_id = nil
    M._started = false
    tick_busy = false
    abort_crawl()
    lookup_queue = {}
    lookup_pending = {}
    log("stopped reason=" .. tostring(reason or "disabled"))
end
function M.reset_session()
    M.stop("session_changed")
    lookup_seen = {}
    lookup_attempts = {}
    M._cache_at = 0
end
function M.tick()
    return M.ensure_started()
end
return M
end)()

Infernal._mods["game.cheater_detect"] = (function()
local ep = Infernal.require("core.entity_props")
local env = Infernal.require("core.env")
local M = {}
local AGE_THRESHOLD_DAYS = 60
local VERT_SPEED_ABS = 1000
local RESCAN_MS = 3000
local cache = {}
local last_scan_ms = 0
local function tick_ms()
    return utility and utility.get_tick_count and utility.get_tick_count() or 0
end
local function cache_key(player)
    local uid = ep.user_id(player)
    if uid and uid ~= 0 then
        return "u:" .. tostring(uid)
    end
    local name = ep.name(player)
    if name and name ~= "" then
        return "n:" .. name
    end
    return nil
end
local function read_account_age(player)
    local age = tonumber(ep.get(player, "AccountAge", "account_age"))
    if age then return age end
    local pl = ep.player_inst(player)
    if not pl then return nil end
    local ok, v = pcall(function()
        return pl.AccountAge or pl.account_age
    end)
    if ok then
        return tonumber(v)
    end
    return nil
end
local function vertical_speed(player)
    local vel = ep.velocity(player)
    if vel then
        local y = tonumber(vel.Y or vel.y)
        if y then return y end
    end
    local char = ep.character(player)
    if not char or not env.is_valid(char) then return nil end
    local root = env.safe_call(function()
        return char:FindFirstChild("HumanoidRootPart")
            or char:find_first_child("HumanoidRootPart")
    end)
    if not root or not env.is_valid(root) then return nil end
    local v = root.AssemblyLinearVelocity or root.Velocity or root.velocity
    if not v then return nil end
    return tonumber(v.Y or v.y)
end
local function evaluate(player)
    local age = read_account_age(player)
    if age ~= nil and age <= AGE_THRESHOLD_DAYS then
        return true
    end
    local vy = vertical_speed(player)
    if vy ~= nil and (vy <= -VERT_SPEED_ABS or vy >= VERT_SPEED_ABS) then
        return true
    end
    return false
end
function M.is_cheater(player)
    if not player or ep.is_local(player) then return false end
    local key = cache_key(player)
    if not key then return false end
    local now = tick_ms()
    local entry = cache[key]
    if entry and entry.flagged then
        return true
    end
    if entry and now - (entry.at or 0) < RESCAN_MS then
        return entry.flagged == true
    end
    local flagged = evaluate(player)
    cache[key] = { flagged = flagged, at = now }
    return flagged
end
function M.tick()
    local now = tick_ms()
    if now - last_scan_ms < RESCAN_MS then return end
    last_scan_ms = now
    local players = entity and (entity.get_players or entity.GetPlayers)
    if not players then return end
    local ok, list = pcall(players)
    if not ok or type(list) ~= "table" then return end
    local live = {}
    for i = 1, #list do
        local p = list[i]
        if p and not ep.is_local(p) then
            local key = cache_key(p)
            if key then live[key] = true end
            M.is_cheater(p)
        end
    end
    for key in pairs(cache) do
        if not live[key] then cache[key] = nil end
    end
end
function M.clear()
    cache = {}
    last_scan_ms = 0
end
return M
end)()

Infernal._mods["core.settings"] = (function()
local M = {}
local _callbacks = {}
local feature_bind = nil
local _frame = 0
local _value_cache = {}
local _color_cache = {}
-- enabled() is the gate every feature and ESP sub-toggle checks each frame, and it
-- recurses through COMBAT_HIDDEN and calls into feature_bind; its result is constant
-- within a frame, so it is cached like get/color and cleared each frame.
local _enabled_cache = {}
local NIL = {}
local function clear_table(t)
    for key in pairs(t) do t[key] = nil end
end
function M.begin_frame(frame)
    frame = tonumber(frame) or (_frame + 1)
    if frame == _frame then return end
    _frame = frame
    clear_table(_value_cache)
    clear_table(_color_cache)
    clear_table(_enabled_cache)
end
function M.frame()
    return _frame
end
function M.invalidate(id)
    if id ~= nil then
        _value_cache[id] = nil
        _color_cache[id] = nil
        clear_table(_enabled_cache)
        return
    end
    clear_table(_value_cache)
    clear_table(_color_cache)
    clear_table(_enabled_cache)
end
function M.get(id, default)
    local cached = _value_cache[id]
    if cached ~= nil then
        if cached == NIL then return default end
        return cached
    end
    if menu and menu.get then
        local v = menu.get(id)
        _value_cache[id] = v == nil and NIL or v
        if v ~= nil then return v end
    end
    _value_cache[id] = NIL
    return default
end
function M.bool(id, default)
    local v = M.get(id, default)
    if v == false or v == 0 or v == "false" then return false end
    return v == true or v == 1
end
-- Combat Mode: while it is active these world-clutter features read as off, so they stop
-- drawing, scanning and applying chams. Player and NPC ESP are not affected.
local COMBAT_HIDDEN = {
    infernal_world_enabled = true,
    infernal_loot_enabled = true,
    infernal_base_enabled = true,
    infernal_base_xray_enabled = true,
    infernal_raid_enabled = true,
}
-- Features taken out of the menu stay off even if an old config had them on.
local REMOVED = {
    infernal_map_enabled = true,
}
function M.enabled(id)
    local cached = _enabled_cache[id]
    if cached ~= nil then return cached end
    local result
    if REMOVED[id] then
        result = false
    elseif COMBAT_HIDDEN[id] and M.enabled("infernal_combat_mode") then
        result = false
    else
        if not feature_bind then
            local ok, fb = pcall(Infernal.require, "core.feature_bind")
            if ok then feature_bind = fb end
        end
        if feature_bind and feature_bind.is_registered(id) then
            result = feature_bind.active(id) == true
        else
            result = M.bool(id, false)
        end
    end
    _enabled_cache[id] = result
    return result
end
function M.num(id, default)
    return tonumber(M.get(id, default)) or default or 0
end
local function as_bool(v, default)
    if v == nil then
        return default == true
    end
    if v == true or v == 1 or v == "1" or v == "true" or v == "True" then
        return true
    end
    if v == false or v == 0 or v == "0" or v == "false" or v == "False" then
        return false
    end
    return default == true
end
function M.multi(id, index, default)
    local t = M.get(id)
    if type(t) ~= "table" then
        return default == true
    end
    if t[index] ~= nil then
        return as_bool(t[index], default)
    end
    if index >= 1 and t[index - 1] ~= nil then
        return as_bool(t[index - 1], default)
    end
    return default == true
end
function M.combo_index(id, labels, default)
    default = default or 0
    local v = M.get(id, default)
    if type(v) == "string" then
        local lower = v:lower()
        for i, label in ipairs(labels or {}) do
            if label:lower() == lower then return i - 1 end
        end
        return default
    end
    local n = tonumber(v)
    if n == nil then return default end
    return n
end
function M.str(id, default)
    local v = M.get(id, default)
    if v == nil then return default or "" end
    return tostring(v)
end
function M.color(id, default)
    local cached = _color_cache[id]
    if cached ~= nil then
        if cached == NIL then return default or { 1, 1, 1, 1 } end
        return cached
    end
    if menu and menu.get_color then
        local c = menu.get_color(id)
        _color_cache[id] = c or NIL
        if c then return c end
    end
    _color_cache[id] = NIL
    return default or { 1, 1, 1, 1 }
end
function M.on_change(id, fn)
    if not id or not fn then return end
    _callbacks[id] = _callbacks[id] or {}
    _callbacks[id][#_callbacks[id] + 1] = fn
    if menu and menu.set_callback then
        menu.set_callback(id, function(new_val)
            M.invalidate(id)
            for _, cb in ipairs(_callbacks[id] or {}) do
                pcall(cb, new_val)
            end
        end)
    end
end
function M.flush() end
function M.mark_dirty() end
return M
end)()

Infernal._mods["core.feature_bind"] = (function()
local settings = Infernal.require("core.settings")
local M = {}
M.MODES = { "Always", "Hold", "Toggle" }
local registry = {}
local last_down = {}
local last_key = {}
local last_mode = {}
local migrated = {}
local function key_down(vk)
    if not input then return false end
    local fn = input.is_key_down or input.IsKeyDown
    if type(fn) ~= "function" then return false end
    local ok, down = pcall(fn, vk)
    return ok and down == true
end
local function key_capture_active()
    local ok, widgets = pcall(function()
        return Infernal.require("ui.gs_widgets")
    end)
    return ok and widgets and widgets.listening_key ~= nil
end
local function migrate_mode(mode_id)
    if not mode_id or migrated[mode_id] then return end
    migrated[mode_id] = true
    local flag = mode_id .. "_v3m"
    local state = nil
    pcall(function()
        state = Infernal.require("ui.gs_state")
    end)
    if state then
        state.define(flag, true)
        state.set(flag, true)
    end
end
function M.register(spec)
    if not spec or not spec.id then return end
    local mode_id = spec.mode_id or (spec.id .. "_mode")
    registry[spec.id] = {
        id = spec.id,
        label = spec.label or spec.id,
        mode_id = mode_id,
        key_id = spec.key_id or spec.id,
    }
    migrate_mode(mode_id)
end
function M.is_registered(id)
    return registry[id] ~= nil
end
function M.get_label(id)
    local e = registry[id]
    return e and e.label or id
end
function M.list_ids()
    local out = {}
    for id in pairs(registry) do
        out[#out + 1] = id
    end
    table.sort(out)
    return out
end
function M.list_entries()
    local out = {}
    for id, e in pairs(registry) do
        out[#out + 1] = e
    end
    table.sort(out, function(a, b)
        return (a.label or a.id) < (b.label or b.id)
    end)
    return out
end
function M.get_key(id)
    local e = registry[id]
    local key_id = e and e.key_id or id
    if menu and menu.get_key then
        local k = menu.get_key(key_id)
        if k and k > 0 then return k end
    end
    local ok, gs = pcall(function()
        return Infernal.require("ui.gs_state")
    end)
    if ok and gs then
        local k = gs.get_key(key_id)
        if k and k > 0 then return k end
    end
    return 0
end
function M.mode_index(id)
    local e = registry[id]
    if not e then return 0 end
    migrate_mode(e.mode_id)
    return settings.combo_index(e.mode_id, M.MODES, 0)
end
function M.mode_name(id)
    local name = M.MODES[M.mode_index(id) + 1] or "Toggle"
    local ok, i18n = pcall(Infernal.require, "ui.i18n")
    if ok and i18n and i18n.t then
        return i18n.t(name)
    end
    return name
end
function M.hide_key_id(id)
    return id .. "_hide_kb"
end
function M.is_hidden_from_list(id)
    return settings.bool(M.hide_key_id(id), false)
end
function M.is_always(id)
    return M.mode_index(id) == 0
end
function M.is_hold(id)
    return M.mode_index(id) == 1
end
function M.is_toggle(id)
    return M.mode_index(id) == 2
end
function M.armed(id)
    return settings.bool(id, false)
end
function M.active(id)
    if not registry[id] then
        return settings.bool(id, false)
    end
    local mode = M.mode_index(id)
    if mode == 1 then
        if not M.armed(id) then return false end
        local key = M.get_key(id)
        if key <= 0 then return true end
        return key_down(key)
    end
    return M.armed(id)
end
function M.tick()
    if not input or type(input.is_key_down or input.IsKeyDown) ~= "function" then return end
    local capturing = key_capture_active()
    for id in pairs(registry) do
        local mode = M.mode_index(id)
        local key = M.get_key(id)
        local changed = last_key[id] ~= key or last_mode[id] ~= mode
        if changed then
            last_key[id] = key
            last_mode[id] = mode
            last_down[id] = key > 0 and key_down(key) or false
        end
        if capturing then
            last_down[id] = key > 0 and key_down(key) or false
            goto continue
        end
        if mode == 0 then
            if key > 0 then
                last_down[id] = key_down(key)
            end
            goto continue
        end
        if mode == 1 then
            if key > 0 then
                last_down[id] = key_down(key)
            end
            goto continue
        end
        if key <= 0 then goto continue end
        local down = key_down(key)
        if not changed and down and not last_down[id] then
            local cur = settings.bool(id, false)
            if menu and menu.set then
                pcall(menu.set, id, not cur)
            else
                pcall(function()
                    Infernal.require("ui.gs_state").set(id, not cur)
                end)
            end
            pcall(function()
                Infernal.require("core.menu_util").sync_master(id)
            end)
        end
        last_down[id] = down
        ::continue::
    end
end
return M
end)()

Infernal._mods["core.aim_key"] = (function()
local settings = Infernal.require("core.settings")
local M = {}
M.MODES = { "Always", "Hold", "Toggle" }
local toggled = {}
local last_down = {}
local last_key = {}
local last_mode = {}
local function key_down(vk)
    if not input then return false end
    local fn = input.is_key_down or input.IsKeyDown
    if type(fn) ~= "function" then return false end
    local ok, down = pcall(fn, vk)
    return ok and down == true
end
local function key_capture_active()
    local ok, widgets = pcall(function()
        return Infernal.require("ui.gs_widgets")
    end)
    return ok and widgets and widgets.listening_key ~= nil
end
local function key_store()
    return Infernal.require("ui.gs_state")
end
function M.mode_index(mode_id)
    return settings.combo_index(mode_id, M.MODES, 0)
end
function M.tick(key_id, mode_id)
    if not input or type(input.is_key_down or input.IsKeyDown) ~= "function" then return end
    local mode = M.mode_index(mode_id)
    local vk = key_store().get_key(key_id)
    local changed = last_key[key_id] ~= vk or last_mode[key_id] ~= mode
    if changed then
        last_key[key_id] = vk
        last_mode[key_id] = mode
        last_down[key_id] = vk > 0 and key_down(vk) or false
    end
    if key_capture_active() then
        last_down[key_id] = vk > 0 and key_down(vk) or false
        return
    end
    if mode == 0 then
        if vk > 0 then last_down[key_id] = key_down(vk) end
        return
    end
    if vk <= 0 then return end
    local down = key_down(vk)
    if mode == 1 then
        last_down[key_id] = down
        return
    end
    if not changed and down and not last_down[key_id] then
        toggled[key_id] = not (toggled[key_id] == true)
    end
    last_down[key_id] = down
end
function M.active(key_id, mode_id)
    local mode = M.mode_index(mode_id)
    if mode == 0 then return true end
    local vk = key_store().get_key(key_id)
    if vk <= 0 then return mode == 0 end
    if mode == 1 then
        return key_down(vk)
    end
    return toggled[key_id] == true
end
function M.reset(key_id)
    toggled[key_id] = false
    last_down[key_id] = false
    last_key[key_id] = nil
    last_mode[key_id] = nil
end
return M
end)()

Infernal._mods["core.draw_util"] = (function()
local math_util = Infernal.require("core.math_util")
local text_util = Infernal.require("core.text_util")
local M = {}
local _aliases_ready = false
local function ensure_draw_aliases()
    if _aliases_ready then return end
    pcall(function()
        Infernal.require("core.api_aliases").apply()
    end)
    _aliases_ready = true
end
-- Filled FOV circle when the feature's Fill FOV toggle (id) is on; drawn under the outline.
function M.fill_fov(id, x, y, r, default_col)
    local settings = Infernal.require("core.settings")
    if not settings.bool(id, false) then return end
    local fn = draw and (draw.circle_filled or draw.CircleFilled)
    if type(fn) == "function" then pcall(fn, x, y, r, settings.color(id, default_col), 64) end
end
function M.white(r, g, b, a)
    return { r or 1, g or 1, b or 1, a or 1 }
end
function M.text_centered(x, y, text, col, size)
    if not draw then return end
    ensure_draw_aliases()
    local text_fn = draw.text or draw.Text
    local size_fn = draw.get_text_size or draw.GetTextSize
    if not text_fn then return end
    text = text_util.sanitize(text)
    size = size or 14
    local tw = 0
    if size_fn then
        tw = select(1, size_fn(text, size)) or 0
    end
    text_fn(x - tw * 0.5, y, text, col, size)
end
function M.text_centered_strong(x, y, text, col, size)
    if not draw or not draw.text or not draw.get_text_size then return end
    text = text_util.sanitize(text)
    size = size or 14
    local tw = draw.get_text_size(text, size)
    local tx = x - tw * 0.5
    local a = (col and col[4]) or 1
    local shadow = { 0, 0, 0, a * 0.55 }
    draw.text(tx + 1, y + 1, text, shadow, size)
    draw.text(tx, y, text, col, size)
end
function M.text_outlined(x, y, text, col, size)
    if not draw then return end
    ensure_draw_aliases()
    local text_fn = draw.text or draw.Text
    if not text_fn then return end
    text_fn(x, y, text_util.sanitize(text), col, size or 14)
end
function M.text(x, y, text, col, size)
    M.text_outlined(x, y, text, col, size)
end
function M.box_esp(x, y, w, h, col, style)
    if not draw then return end
    ensure_draw_aliases()
    local corner = draw.corner_box or draw.CornerBox
    local box = draw.box or draw.Box
    local rect = draw.rect or draw.Rect
    if style == 1 and corner then
        corner(x, y, w, h, col)
        return
    end
    if box then
        box(x, y, w, h, col, style or 0)
        return
    end
    if rect then
        rect(x, y, w, h, col)
    end
end
function M.box_esp_nice(x, y, w, h, col, style)
    if not draw then return end
    local a = (col and col[4]) or 1
    local outer = { 0, 0, 0, a * 0.7 }
    if style == 1 and draw.corner_box then
        draw.corner_box(x - 1, y - 1, w + 2, h + 2, outer)
        draw.corner_box(x, y, w, h, col)
        return
    end
    if draw.box then
        draw.box(x - 1, y - 1, w + 2, h + 2, outer, 0, 0)
        draw.box(x, y, w, h, col, 0, style or 0)
    end
end
function M.health_bar(x, y, h, hp, max_hp)
    if not draw or not draw.health_bar then return end
    draw.health_bar(x, y, h, hp, max_hp)
end
function M.health_bar_nice(x, y, h, hp, max_hp, bar_w)
    if not draw then return end
    ensure_draw_aliases()
    local fill = draw.rect_filled or draw.RectFilled
    if not fill then return end
    if not hp or not max_hp or max_hp <= 0 then return end
    h = math.max(4, h)
    bar_w = math.max(2, math.min(4, bar_w or 3))
    local pct = math_util.clamp(hp / max_hp, 0, 1)
    local fill_h = math.max(0, math.floor(h * pct + 0.5))
    fill(x, y, bar_w, h, { 0.08, 0.08, 0.08, 0.85 })
    if fill_h > 0 then
        local r, g, b
        if pct > 0.5 then
            local t = (pct - 0.5) * 2
            r, g, b = (1 - t) * 0.95, 1, 0.15
        else
            local t = pct * 2
            r, g, b = 1, t * 0.9, 0.12
        end
        fill(x, y + (h - fill_h), bar_w, fill_h, { r, g, b, 1 })
    end
    return bar_w
end
function M.health_bar_on_box(bounds, hp, max_hp)
    if not bounds or not bounds.valid or not hp or not max_hp or max_hp <= 0 then
        return
    end
    local h = bounds.h or 0
    if h < 4 then return end
    local bar_w = 3
    if h >= 40 then
        bar_w = 4
    elseif h <= 14 then
        bar_w = 2
    end
    M.health_bar_nice(bounds.x - bar_w - 1, bounds.y, h, hp, max_hp, bar_w)
end
function M.line(x1, y1, x2, y2, col, thick)
    if not draw then return end
    local line = draw.line or draw.Line
    if not line then return end
    line(x1, y1, x2, y2, col, thick or 1)
end
function M.snapline(tx, ty, col, thick, sw, sh)
    if not draw or not draw.line then return end
    if not sw or not sh then
        local dw, dh = M.screen_size()
        sw = sw or dw
        sh = sh or dh
    end
    col = col or { 1, 1, 1, 1 }
    thick = thick or 1.5
    local sx = sw * 0.5
    local sy = sh - 1
    local a = col[4] or 1
    M.line(sx, sy, tx, ty, { 0, 0, 0, a * 0.9 }, thick + 1.5)
    M.line(sx, sy, tx, ty, col, thick)
end
function M.circle(x, y, r, col, filled)
    if not draw then return end
    if filled and draw.circle_filled then
        draw.circle_filled(x, y, r, col, 24)
    elseif draw.circle then
        draw.circle(x, y, r, col, 24, 1)
    end
end
function M.screen_size()
    local w, h
    if draw then
        local fn = draw.get_screen_size or draw.GetScreenSize
        if fn then w, h = fn() end
    end
    if (not w or w <= 0) and utility then
        local fn = utility.get_screen_size or utility.GetScreenSize
        if fn then w, h = fn() end
    end
    if not w or w <= 0 then w = 1920 end
    if not h or h <= 0 then h = 1080 end
    return w, h
end
function M.world_label(inst, text, col, max_dist)
    if not utility or not utility.world_to_screen then return end
    local env = Infernal.require("core.env")
    if not env.is_valid(inst) then return end
    local pos = inst.Position
    if not pos or pos.x == nil then return end
    local me = env.get_local_player()
    if me and me.position and max_dist then
        local dx = pos.x - me.position.x
        local dy = pos.y - me.position.y
        local dz = pos.z - me.position.z
        local dist = math_util.distance3(dx, dy, dz)
        if dist > max_dist then return end
        text = string.format("%s [%dm]", text, math.floor(dist))
    end
    local sx, sy, vis = Infernal.require("core.esp_util").w2s(pos.x, pos.y, pos.z)
    if vis then
        M.text_centered(sx, sy, text, col, 13)
    end
end
return M
end)()

