    local div_y = y + title_h
    if draw.line then
        draw.line(x + pad, div_y, x + width - pad, div_y, M.alpha(M.BORDER, 0.55), 1)
    end
    local ry = div_y + 6
    for i = 1, count do
        local row = rows[i]
