end
function M.zero_character(char, root)
    if root then M.zero_part(root) end
    for i = 1, #NOCLIP_PARTS do
        local p = char and M.find_part(char, NOCLIP_PARTS[i])
        if p and p ~= root then
            M.zero_part(p)
        end
    end
end
function M.camera_flat_axes()
    if not camera or not camera.get_look_vector then return nil end
    local ok, look = pcall(camera.get_look_vector)
    if not ok or not look then return nil end
    local lx = look.x or look.X or 0
    local lz = look.z or look.Z or 0
    local lm = math.sqrt(lx * lx + lz * lz)
    if lm < 0.001 then return nil end
    lx, lz = lx / lm, lz / lm
    return lx, lz, -lz, lx
end
function M.read_flat_input()
    local lx, lz, rx, rz = M.camera_flat_axes()
    if not lx then return 0, 0 end
    local mx, mz = 0, 0
    if M.key_down(0x57) then mx, mz = mx + lx, mz + lz end
    if M.key_down(0x53) then mx, mz = mx - lx, mz - lz end
    if M.key_down(0x41) then mx, mz = mx - rx, mz - rz end
    if M.key_down(0x44) then mx, mz = mx + rx, mz + rz end
    local mag = math.sqrt(mx * mx + mz * mz)
    if mag < 0.001 then return 0, 0 end
    return mx / mag, mz / mag
end
function M.read_fly_input()
    local mx, mz = M.read_flat_input()
    local my = 0
    if M.key_down(0x20) then my = 1 end
    if M.key_down(0x11) then my = -1 end
    return mx, my, mz
end
local function local_character()
    local ok, char = pcall(function()
        local lp = env.get_local_player()
        if lp and (lp.Character or lp.character) then return lp.Character or lp.character end
        local game_lp = game and (game.LocalPlayer or game.local_player)
        return game_lp and (game_lp.Character or game_lp.character) or nil
    end)
    return ok and char or nil
end
local function is_own_part(inst, char)
    if not inst or not char then return false end
    local ok, inside = pcall(function() return inst:IsDescendantOf(char) end)
    if ok and inside then return true end
    local cid = char.Address or char.address
    local ok2, same = pcall(function()
        local p = inst.Parent
        for _ = 1, 3 do
            if p == nil then return false end
            if p == char or (cid and (p.Address or p.address) == cid) then return true end
            p = p.Parent
        end
        return false
    end)
    return ok2 and same == true
end
-- Distance from 2 studs above (x, y, z) straight down to the first thing under it.
-- Vector's raycast.Cast only takes two Vector3s (six plain numbers always errored, so this
-- used to return nil every time). IsReady is the visibility cache, not Cast. Hits on your
-- own character (legs under the root) are stepped through.
function M.ground_distance(x, y, z)
    if not raycast then return nil end
    local cast = raycast.cast or raycast.Cast
    if type(cast) ~= "function" then return nil end
    if not (Vector3 and Vector3.New) then return nil end
    local top = y + 2
    local from_y = top
    local char = local_character()
    -- lowest point of your own body the ray touched; when you stand, the next cast starts
    -- inside the floor and misses, so the bottom of your feet is the ground
    local own_y = nil
    for _ = 1, 4 do
        local ok, hit, hpos, dist, hinst = pcall(cast, Vector3.New(x, from_y, z), Vector3.New(x, y - 512, z))
        if not ok then return nil end
        if not hit then return own_y and (top - own_y) or nil end
        local hy = hpos and tonumber(hpos.Y or hpos.y)
        if hy == nil then
            dist = tonumber(dist)
            if dist == nil then return nil end
            hy = from_y - dist
        end
        if not is_own_part(hinst, char) then return top - hy end
        own_y = hy
        from_y = hy - 0.05
    end
    return own_y and (top - own_y) or nil
end
function M.set_noclip_parts(char, enabled)
    return M.set_noclip_parts_owned(char, enabled, "default")
end
local function another_owner_holds(char, except_owner)
    for owner, held_char in pairs(noclip_owners) do
