end
local function apply_fly_velocity(root, mx, my, mz, speed)
    local tx, ty, tz = 0, 0, 0
    local mag = math.sqrt(mx * mx + my * my + mz * mz)
    if mag >= 0.001 then
        tx = mx / mag * speed
        ty = my / mag * speed
        tz = mz / mag * speed
    end
