-- names Infernal also sees for the same guns
WIKI_STATS["Salvaged AK47"] = WIKI_STATS["Salvaged AK-47"]
WIKI_STATS["Military Barret"] = WIKI_STATS["Military Barrett"]
WIKI_STATS["Salvaged Double Barrel"] = WIKI_STATS["Salvaged Break Action"]
M._last_held = nil
M._last_held_ranged = nil
M._was_in_game = false
M._weapon_changed_at = 0
local function inst_name(inst)
    if not inst then return nil end
    return inst.name or inst.Name
end
local function is_tool(inst)
    if not inst then return false end
    local cn = inst.ClassName or inst.class_name
    return cn == "Tool"
end
local function rebuild_weapon_names()
    weapon_names = {}
    for name in pairs(FALLBACK_STATS) do
        weapon_names[name] = true
    end
    for name in pairs(toolinfo) do
        if type(name) == "string" then
            weapon_names[name] = true
        end
    end
end
function M.is_weapon_name(name)
    return name and weapon_names[name] == true
end
local MELEE_NAME_HINTS = {
    "hatchet", "pickaxe", "pick axe", " axe", "axe ",
    "spear", "machete", "knife", "sword",
    "bone tool", "hammer", "crowbar",
    "chainsaw", "mining drill", "shovel", "scythe",
    "candy cane", "carrot blade", "boulder", "saw bat",
}
local function is_spear_name(name)
    if not name or name == "" then return false end
    return name:lower():find("spear", 1, true) ~= nil
end
local function name_looks_melee(name)
    if is_spear_name(name) then return false end
    local n = (name or ""):lower()
    for _, hint in ipairs(MELEE_NAME_HINTS) do
        if n:find(hint, 1, true) then return true end
    end
    return false
end
function M.is_ranged_weapon_name(name)
    if not name or name == "" then return false end
    local lower = name:lower()
    if lower:find("bow", 1, true) or lower:find("crossbow", 1, true) then return true end
    if is_spear_name(name) then return true end
    if name_looks_melee(name) then return false end
    if not loaded then M.load() end
    local entry = toolinfo[name]
    if entry then
        if entry.Bullet then return true end
        if entry.Melee and not entry.Bullet then return false end
        if entry.Weapon and (entry.Weapon.RPM or entry.Weapon.ActualRPM) then
            return true
        end
        if entry.Melee then return false end
    end
    if FALLBACK_STATS[name] then
        return true
    end
    return false
end
local function children_of(inst)
    if not inst then return {} end
    return env.safe_call(function()
        if inst.get_children then return inst:get_children() end
        return inst:GetChildren()
    end) or {}
end
local function find_child(parent, name)
    if not parent then return nil end
    return env.safe_call(function()
        return parent:find_first_child(name) or parent:FindFirstChild(name)
    end)
end
local function pick_weapon_from_model(model)
    if not model then return nil, nil end
    local n = inst_name(model)
    if n and M.is_weapon_name(n) then
        return n, model
    end
    for _, child in ipairs(children_of(model)) do
        local cn = inst_name(child)
        if cn and M.is_weapon_name(cn) then
            return cn, child
        end
        local class = child.ClassName or child.class_name
        if class == "Model" and cn and M.is_ranged_weapon_name(cn) then
            return cn, child
        end
    end
    return nil, nil
end
local function find_held_in_viewmodels()
    local ws = env.get_workspace()
    if not ws then return nil end
    local cam = env.safe_call(function()
        return ws.CurrentCamera or ws.currentCamera
            or (ws.FindFirstChild and ws:FindFirstChild("CurrentCamera"))
    end)
    if cam then
        for _, child in ipairs(children_of(cam)) do
            local class = child.ClassName or child.class_name
            if class == "Model" then
                local n, inst = pick_weapon_from_model(child)
                if n then return n, inst end
            end
        end
    end
    local vfx = find_child(ws, "VFX")
    local vms_live = vfx and find_child(vfx, "VMs")
    if vms_live then
        for _, child in ipairs(children_of(vms_live)) do
            local n, inst = pick_weapon_from_model(child)
            if n then return n, inst end
        end
    end
    local vms = find_child(ws, "Viewmodels")
    if vms then
        for _, vm in ipairs(children_of(vms)) do
            if inst_name(vm) == "Viewmodel" then
                local n, inst = pick_weapon_from_model(vm)
                if n then return n, inst end
            end
        end
    end
    return nil, nil
end
local function find_held_in_character(lp)
    local char = lp and lp.character
    if not char or not env.is_valid(char) then return nil, nil end
    local fallback_tool = nil
    for _, child in ipairs(env.safe_call(function() return char:get_children() end) or {}) do
        local n = inst_name(child)
        if n and M.is_weapon_name(n) then
            return n, child
        end
        if is_tool(child) and n then
            fallback_tool = fallback_tool or { name = n, inst = child }
        end
    end
    if fallback_tool then
        return fallback_tool.name, fallback_tool.inst
    end
    return nil, nil
end
local function read_tool_attributes(inst)
    if not inst then return nil end
    local speed, gravity
    pcall(function()
        if inst.GetAttribute then
            speed = inst:GetAttribute("BulletSpeed") or inst:GetAttribute("MuzzleVelocity")
            gravity = inst:GetAttribute("BulletGravity") or inst:GetAttribute("ProjectileGravity")
        elseif inst.get_attribute then
            speed = inst:get_attribute("BulletSpeed") or inst:get_attribute("MuzzleVelocity")
            gravity = inst:get_attribute("BulletGravity") or inst:get_attribute("ProjectileGravity")
        end
    end)
    if speed then
        local grav = gravity
        if not grav or grav <= 0 or grav > 2 then
            grav = 0.55
        end
        return {
            speed = speed,
            gravity = grav,
            name = inst_name(inst),
            from_attributes = true,
        }
    end
    return nil
end
-- The weapon model in your first-person viewmodel, and the item another character holds.
function M.viewmodel_weapon()
    return find_held_in_viewmodels()
end
function M.held_in_character(char)
    if not char or not env.is_valid(char) then return nil, nil end
    local fallback = nil
    for _, child in ipairs(children_of(char)) do
        local n = inst_name(child)
        if n and M.is_weapon_name(n) then return n, child end
        if is_tool(child) and n then fallback = fallback or child end
    end
    if fallback then return inst_name(fallback), fallback end
    return nil, nil
end
function M.get_held_ranged_weapon_name()
    if not loaded then M.load() end
    local lp = env.get_local_player()
    if not lp then return nil end
    local function pick(name)
        if name and M.is_ranged_weapon_name(name) then return name end
    end
    local char = lp.character
    if char and env.is_valid(char) then
        for _, child in ipairs(env.safe_call(function() return char:get_children() end) or {}) do
            local hit = pick(inst_name(child))
            if hit then return hit end
        end
    end
    local name = find_held_in_viewmodels()
    if name then
        local hit = pick(name)
        if hit then return hit end
    end
    return pick(lp.tool_name)
end
function M.holding_ranged_weapon()
    return M._last_held_ranged ~= nil
end
function M.cached_held_ranged()
    return M._last_held_ranged
end
function M.is_bow_weapon_name(name)
    if not name then return false end
    if not loaded then M.load() end
    local entry = toolinfo[name]
    if entry and entry.Weapon and entry.Weapon.IsBow then
        return true
    end
    local n = name:lower()
    if n:find("crossbow", 1, true) then return true end
    if n:find("wooden bow", 1, true) then return true end
    if n == "bow" or n:sub(-4) == " bow" then return true end
    return false
end
function M.invalidate()
    loaded = false
    toolinfo = {}
    recoil_weapons = {}
    weapon_names = {}
    M._last_held = nil
    M._last_held_ranged = nil
    M._weapon_changed_at = 0
    pcall(function()
        local origin = Infernal.require("game.combat_origin")
        if origin.invalidate then origin.invalidate() end
    end)
end
function M.in_game_ready()
    if env.get_local_player() then return true end
    local cache = Infernal.require("core.cache")
    if cache.local_player or #cache.all_entities > 0 then return true end
    return false
end
function M.load()
    if loaded then return true end
    local data = bootstrap.get_module("ToolInfo")
    if type(data) ~= "table" then
        rebuild_weapon_names()
        return false
    end
    toolinfo = data
    rebuild_weapon_names()
    loaded = next(toolinfo) ~= nil
    return loaded
end
function M.get(name)
    if not loaded then M.load() end
    return toolinfo[name]
end
function M.profile_weapon_names()
    if not loaded then M.load() end
    local farm = nil
    pcall(function()
        farm = Infernal.require("game.farm_tools")
        if farm and farm.load then farm.load() end
    end)
    local seen = {}
    local list = {}
    local function add(name)
        if not name or name == "" or seen[name] then return end
        if not M.is_ranged_weapon_name(name) then return end
        if farm and farm.is_farm_tool_name and farm.is_farm_tool_name(name) then return end
        seen[name] = true
        list[#list + 1] = name
    end
    for name in pairs(toolinfo) do
        add(name)
    end
    for name in pairs(FALLBACK_STATS) do
        add(name)
    end
    table.sort(list)
    return list
end
function M.get_held_weapon_name()
    rebuild_weapon_names()
    local lp = env.get_local_player()
    if not lp then return nil end
    local name, inst = find_held_in_character(lp)
    if name then return name end
    name = find_held_in_viewmodels()
    if name then return name end
    if lp.tool_name and lp.tool_name ~= "" then
        if M.is_weapon_name(lp.tool_name) or loaded then
            return lp.tool_name
        end
    end
    return nil
end
function M.get_held_tool()
    local lp = env.get_local_player()
    if not lp then return nil, nil end
    local name, inst = find_held_in_character(lp)
    if name then return name, inst end
    name = find_held_in_viewmodels()
    return name, nil
end
function M.drop_gravity(grav)
    if not grav or grav <= 0 then return ROBLOX_GRAV * 0.55 end
    if grav <= 2 then return grav * ROBLOX_GRAV end
    return grav
end
function M.wiki_stats(name)
    return name and WIKI_STATS[name] or nil
end
function M.shot_interval_ms(name)
    name = name or M.cached_held_ranged() or M.get_held_ranged_weapon_name()
    if not name then return 100 end
    local entry = M.get(name)
    local weapon = entry and entry.Weapon
    if type(weapon) == "table" then
        local rpm = tonumber(weapon.RPM or weapon.rpm)
        if rpm and rpm > 0 then
            return math.max(16, math.floor(60000 / rpm + 0.5))
        end
        local cd = tonumber(weapon.Cooldown or weapon.cooldown)
        if cd and cd > 0 then
            return math.max(16, math.floor(cd * 1000 + 0.5))
        end
    end
    local wiki = WIKI_STATS[name]
    if wiki and wiki.rpm then
        return math.max(16, math.floor(60000 / wiki.rpm + 0.5))
    end
    return 100
end
function M.get_weapon_stats(name)
    name = name or M.get_held_weapon_name()
    if not name then return nil end
    local bow = BOW_STATS[name]
    if bow then
        return { speed = bow.speed, gravity = bow.gravity, name = name, from_fallback = true, is_bow = true }
    end
    local entry = M.get(name)
    if entry and entry.Bullet then
        return {
            speed = entry.Bullet.Speed or 950,
            gravity = entry.Bullet.Gravity or 0.55,
            name = name,
            from_toolinfo = true,
            is_bow = M.is_bow_weapon_name(name),
        }
    end
    local fb = FALLBACK_STATS[name]
    if fb then
        return {
            speed = fb.speed,
            gravity = fb.gravity,
            name = name,
            from_fallback = true,
            is_bow = M.is_bow_weapon_name(name),
        }
    end
    local _, tool_inst = M.get_held_tool()
    if tool_inst then
        local from_attrs = read_tool_attributes(tool_inst)
        if from_attrs then
            from_attrs.name = name
            return from_attrs
        end
    end
    return { speed = 950, gravity = 0.55, name = name }
end
-- A gun's range (studs): MaxRange from ToolInfo when it is loaded, otherwise where the wiki's
-- damage dropoff band ends. Past it there is nothing to lead or drop. Small values are melee
-- reach and are ignored.
function M.max_range(name)
    local entry = name and M.get(name)
    if type(entry) == "table" then
        for _, t in ipairs({ entry.Bullet, entry.Weapon, entry }) do
            if type(t) == "table" then
                local v = tonumber(t.MaxRange or t.maxRange or t.max_range)
                if v and v > 20 then return v end
            end
        end
    end
    local wiki = name and WIKI_STATS[name]
    if wiki and wiki.drop and wiki.drop[2] > 20 then return wiki.drop[2] end
    return nil
end
function M.tick()
    local in_game = M.in_game_ready()
    if not in_game then
        if M._was_in_game then
            M._last_held = nil
            M._last_held_ranged = nil
            M._weapon_changed_at = 0
        end
        M._was_in_game = false
        return nil
    end
    if not M._was_in_game then
        M._was_in_game = true
        M.load()
    end
    if not loaded and bootstrap.is_ready and bootstrap.is_ready() then
        M.load()
    end
    local held = M.get_held_ranged_weapon_name()
    if held ~= M._last_held_ranged then
        M._last_held = held
        M._last_held_ranged = held
        M._weapon_changed_at = utility and utility.get_tick_count and utility.get_tick_count() or 0
        pcall(function()
            local origin = Infernal.require("game.combat_origin")
            if origin.invalidate then origin.invalidate() end
        end)
    end
    return held
end
function M.on_modules_ready()
    M.load()
    pcall(function()
        farm_tools = Infernal.require("game.farm_tools")
        if farm_tools.invalidate then farm_tools.invalidate() end
        if farm_tools.load then farm_tools.load() end
    end)
end
return M
end)()

Infernal._mods["game.combat_stats"] = (function()
local settings = Infernal.require("core.settings")
local weapons = Infernal.require("game.weapons")
local M = {}
local function profile_speed_mult()
    if not settings.enabled("infernal_gunmods_enabled") then return 0 end
    if not settings.enabled("infernal_gm_speed") then return 0 end
    return settings.num("infernal_gm_speed_mult", 100)
end
function M.get_effective_stats(weapon_name)
    weapon_name = weapon_name or weapons.cached_held_ranged() or weapons.get_held_ranged_weapon_name()
    local base = weapons.get_weapon_stats(weapon_name)
    if not base then
        base = { speed = 950, gravity = 0.55, name = weapon_name or "Unknown" }
    end
    local speed = base.speed or 950
    local gravity = base.gravity or 0.55
    local is_bow = base.is_bow
        or (weapon_name and (weapon_name:find("Bow", 1, true) or weapon_name:find("Crossbow", 1, true)))
    local sm = profile_speed_mult()
    if sm ~= 0 then
        speed = speed * (1 + sm)
    end
    return {
        speed = speed,
        gravity = gravity,
        name = weapon_name or base.name,
        is_bow = is_bow == true,
        base_speed = base.speed,
        speed_mult = sm,
    }
end
return M
end)()

Infernal._mods["game.damage"] = (function()
-- Damage of one hit, used by the ragebot's Min Damage and its target info. From the Fallen
-- Survival wiki: the gun's damage and dropoff band, headshots 1.5x (Crossbow, Pipe Rifle and
-- Barrett 1.75x, Wooden Bow 1.6x), body 1x, the Silencer (-20%) and Compensator (-10%) on your
-- gun, and the bullet protection of what the target wears where the shot lands. Each piece
-- protects its own area and pieces on the same area add up (a full steel set totals over 100%,
-- so it cannot be one shared number). The game's ToolInfo still wins whenever it is loaded.
-- The one number no source gives is how low damage gets at the end of the dropoff band; it is
-- taken as a straight line from full damage at the start to DROPOFF_FLOOR at the end.
local weapons = Infernal.require("game.weapons")
local M = {}
M.DEFAULT_BASE = 30
M.HEADSHOT = 1.5
M.DROPOFF_FLOOR = 0.5
local ARMOR_TTL_MS = 1500
local OWN_TTL_MS = 1000
local HEAD, BODY, LEGS = "head", "body", "legs"
-- bullet protection of each item (wiki armor and clothing tables) and the areas it covers
M.ARMOR = {
    ["Wooden Helmet"] = { 0.15, HEAD }, ["Salvaged Helmet"] = { 0.35, HEAD },
    ["Steel Helmet"] = { 0.50, HEAD }, ["Military Helmet"] = { 0.45, HEAD },
    ["Bruno's Helmet"] = { 0.45, HEAD }, ["Altyn Helmet"] = { 0.48, HEAD },
    ["Hard Hat"] = { 0.20, HEAD }, ["Baseball Cap"] = { 0.05, HEAD },
    ["Balaclava"] = { 0.10, HEAD }, ["Cloth Headwrap"] = { 0.10, HEAD },
    ["Wooden Chestplate"] = { 0.10, BODY }, ["Salvaged Chestplate"] = { 0.20, BODY },
    ["Steel Chestplate"] = { 0.30, BODY }, ["Military Chestplate"] = { 0.25, BODY },
    ["Bruno's Chestplate"] = { 0.25, BODY }, ["Boris's Chestplate"] = { 0.25, BODY },
    ["Bone Armor"] = { 0.13, BODY }, ["Hoodie"] = { 0.20, BODY },
    ["Collared Shirt"] = { 0.15, BODY }, ["Leather Shirt"] = { 0.10, BODY },
    ["Cloth Shirt"] = { 0.05, BODY }, ["Tank Top"] = { 0.05, BODY },
    ["Flannel Jacket"] = { 0.15, BODY }, ["Leather Poncho"] = { 0.10, BODY },
    ["Wooden Leggings"] = { 0.10, LEGS }, ["Salvaged Leggings"] = { 0.15, LEGS },
    ["Steel Leggings"] = { 0.25, LEGS }, ["Military Leggings"] = { 0.20, LEGS },
    ["Pants"] = { 0.15, LEGS }, ["Leather Pants"] = { 0.10, LEGS }, ["Cloth Pants"] = { 0.05, LEGS },
    ["Hazmat Suit"] = { 0.25, HEAD, BODY, LEGS },
}
local PART_AREA = { Head = HEAD, UpperTorso = BODY, LowerTorso = BODY, Torso = BODY }
-- Fallen's chest armor models cover the arm pieces and the leggings cover the legs and feet
for _, side in ipairs({ "Left", "Right" }) do
    for _, piece in ipairs({ "UpperArm", "LowerArm", "Hand" }) do PART_AREA[side .. piece] = BODY end
    for _, piece in ipairs({ "UpperLeg", "LowerLeg", "Foot" }) do PART_AREA[side .. piece] = LEGS end
    PART_AREA[side .. " Arm"] = BODY
    PART_AREA[side .. " Leg"] = LEGS
end
local MULT_KEYS = {
    Head = { "HeadshotMultiplier", "HeadMultiplier", "HeadshotMult", "HeadMult" },
    UpperTorso = { "TorsoMultiplier", "BodyMultiplier", "ChestMultiplier" },
    LowerTorso = { "LowerTorsoMultiplier", "BodyMultiplier" },
}
local PELLET_KEYS = { "Pellets", "PelletCount", "BulletCount", "Bullets" }
local function now_ms()
    local fn = utility and (utility.get_tick_count or utility.GetTickCount)
    if type(fn) ~= "function" then return 0 end
    local ok, v = pcall(fn)
    return ok and tonumber(v) or 0
end
-- "Boris Chestplate", "Boris's Chestplate" and "Cloth Head Wrap" / "Cloth Headwrap" match
local function norm(name)
    return (tostring(name or ""):lower():gsub("'s", ""):gsub("[^%w]", ""))
end
local ARMOR_BY_KEY = {}
for name, row in pairs(M.ARMOR) do
    local areas = {}
    for i = 2, #row do areas[row[i]] = true end
    ARMOR_BY_KEY[norm(name)] = { bullet = row[1], areas = areas }
end
local function num_in(t, keys)
    if type(t) ~= "table" then return nil end
    for _, k in ipairs(keys) do
        local v = tonumber(t[k])
        if v and v > 0 then return v end
    end
    return nil
end
local function entry_of(weapon_name)
    if not weapon_name then return nil end
    local ok, e = pcall(weapons.get, weapon_name)
    return ok and type(e) == "table" and e or nil
end
local function wiki_of(weapon_name)
    if not weapon_name or not weapons.wiki_stats then return nil end
    local ok, w = pcall(weapons.wiki_stats, weapon_name)
    return ok and type(w) == "table" and w or nil
end
-- Base damage of one shot and whether it is known (game data or wiki) rather than the fallback.
function M.base(weapon_name)
    local entry = entry_of(weapon_name)
    if entry then
        for _, t in ipairs({ entry.Bullet, entry.Weapon, entry }) do
            local d = num_in(t, { "Damage", "BaseDamage", "BulletDamage" })
            if d then
                local pellets = num_in(entry.Bullet, PELLET_KEYS) or num_in(entry.Weapon, PELLET_KEYS) or 1
                return d * pellets, true
            end
        end
    end
    local wiki = wiki_of(weapon_name)
    if wiki and wiki.dmg then return wiki.dmg, true end
    return M.DEFAULT_BASE, false
end
function M.multiplier(weapon_name, part)
    local keys = MULT_KEYS[part]
    local entry = entry_of(weapon_name)
    if keys and entry then
        local v = num_in(entry.Bullet, keys) or num_in(entry.Weapon, keys) or num_in(entry, keys)
        if v then return v end
    end
    if part == "Head" then
        local wiki = wiki_of(weapon_name)
        return wiki and wiki.hs or M.HEADSHOT
    end
    return 1
end
-- Share of damage left at a distance: full up to the start of the dropoff band, then a straight
-- line down to DROPOFF_FLOOR at its end.
function M.dropoff(weapon_name, dist)
    local wiki = wiki_of(weapon_name)
    local band = wiki and wiki.drop
    if not band or not dist then return 1 end
    local a, b = band[1], band[2]
    if dist <= a then return 1 end
    if dist >= b or b <= a then return M.DROPOFF_FLOOR end
    return 1 - (1 - M.DROPOFF_FLOOR) * (dist - a) / (b - a)
end
local function scan_gear(who)
    local ok, gear = pcall(function() return Infernal.require("game.player_gear").scan_player(who) end)
    return ok and type(gear) == "table" and gear or nil
end
-- Bullet protection from a list of worn item names, for one hit area.
function M.protection_of(names, part)
    local area = PART_AREA[part]
    if not area then return 0 end
    local sum = 0
    for _, n in ipairs(names or {}) do
        local a = ARMOR_BY_KEY[norm(n)]
        if a and a.areas[area] then sum = sum + a.bullet end
    end
    return math.min(sum, 1)
end
local worn = {}
local worn_count = 0
local function key_of(obj)
    local ok, a = pcall(function() return obj.Address end)
    if ok and a then return tostring(a) end
    return tostring(obj)
end
-- What a target wears, read the same way as the Inventory Viewer, kept for 1.5s.
function M.worn(target)
    if not target or not target.obj then return {} end
    local key = key_of(target.obj)
    local now = now_ms()
    local c = worn[key]
    if c and now - c.t < ARMOR_TTL_MS then return c.names end
    local names = {}
    local gear = scan_gear({ character = target.obj, player = target.player })
    for _, piece in ipairs(gear and gear.armor or {}) do
        if piece.name then names[#names + 1] = piece.name end
    end
    if not c then
        worn_count = worn_count + 1
        if worn_count > 96 then
            for k, v in pairs(worn) do
                if now - v.t > ARMOR_TTL_MS * 4 then worn[k] = nil; worn_count = worn_count - 1 end
            end
        end
    end
    worn[key] = { t = now, names = names }
    return names
end
function M.protection(target, part)
    return M.protection_of(M.worn(target), part)
end
local own = { t = -1e9, mult = 1 }
-- Damage change from the attachments on your own gun.
function M.attachment_mult()
    local now = now_ms()
    if now - own.t < OWN_TTL_MS then return own.mult end
    local mult = 1
    local lp, char = nil, nil
    pcall(function()
        lp = Infernal.require("core.env").get_local_player()
        char = lp.Character
    end)
    local gear = lp and scan_gear({ player = lp, character = char }) or nil
    for _, a in ipairs(gear and gear.attachments or {}) do
        local n = tostring(a.name or ""):lower()
        if n:find("silencer", 1, true) or n:find("suppressor", 1, true) then
            mult = mult * 0.8
        elseif n:find("compensator", 1, true) then
            mult = mult * 0.9
        end
    end
    own.t, own.mult = now, mult
    return mult
end
-- One hit with this gun on this part. With a target and distance it counts their armor and the
-- dropoff; without, it is the most one hit can do.
function M.estimate(weapon_name, part, target, dist)
    local base, known = M.base(weapon_name)
    local dmg = base * M.multiplier(weapon_name, part)
    if target then
        dmg = dmg * M.attachment_mult() * M.dropoff(weapon_name, dist) * (1 - M.protection(target, part))
    end
    return dmg, known
end
return M
end)()

Infernal._mods["game.combat_origin"] = (function()
local env = Infernal.require("core.env")
local weapons = Infernal.require("game.weapons")
local M = {}
local frame = { t = 0, weapon = nil, muzzle = nil, server = nil }
local flash_lookup = {}
local FLASH_TTL_MS = 450
local FLASH_CACHE_MAX = 48
local function tick_ms()
    return utility and utility.get_tick_count and utility.get_tick_count() or 0
end
local function find_child(parent, name)
    if not parent then return nil end
    return env.safe_call(function()
        return parent:find_first_child(name) or parent:FindFirstChild(name)
    end)
end
local function part_pos(part)
    if not part or not env.is_valid(part) then return nil end
    local p = part.Position or part.position
    if p and p.x ~= nil then
        return { x = p.x, y = p.y, z = p.z }
    end
    return nil
end
local function vec3_from_cf(cf)
    if not cf then return nil end
    local pos = cf.Position or cf.position
    if pos and pos.x ~= nil then
        return { x = pos.x, y = pos.y, z = pos.z }
    end
    return nil
end
local function camera_origin()
    if not camera or not camera.get_position then return nil end
    local ok, pos = pcall(camera.get_position)
    if ok and pos and pos.x then
        return { x = pos.x, y = pos.y, z = pos.z }
    end
    return nil
end
local function viewmodel_cframe_origin()
    local lp = env.get_local_player()
    local char = lp and lp.character
    if not char or not env.is_valid(char) then return nil end
    local cc = find_child(char, "CameraController")
    if not cc then return nil end
    local cf = env.safe_call(function() return cc:GetAttribute("ViewmodelCFrame") end)
    if not cf then return nil end
    local pos = vec3_from_cf(cf)
    if not pos then return nil end
    local look = cf.LookVector or cf.lookVector
    if look and look.x then
        return {
            x = pos.x + look.x * 0.5,
            y = pos.y + look.y * 0.5,
            z = pos.z + look.z * 0.5,
        }
    end
    return pos
end
local function flash_cache_get(model)
    local addr = model and tonumber(model.Address or model.address)
    if not addr then return nil, false end
    local hit = flash_lookup[addr]
    if not hit then return nil, false end
    if (tick_ms() - (hit.t or 0)) >= FLASH_TTL_MS then
        flash_lookup[addr] = nil
        return nil, false
    end
    return hit.pos, true
end
local function flash_cache_set(model, pos)
    local addr = model and tonumber(model.Address or model.address)
    if not addr then return end
    local n = 0
    for _ in pairs(flash_lookup) do
        n = n + 1
        if n >= FLASH_CACHE_MAX then
            flash_lookup = {}
            break
        end
    end
    flash_lookup[addr] = { t = tick_ms(), pos = pos }
end
local function find_flash_in(model)
    if not model then return nil end
