menu_util.bind_children(P, {
ID_BOX, ID_BOX_COLOR, ID_HEALTH, ID_SKELETON,
ID_NAME, ID_CLAN, ID_HELD, ID_DIST,
FILTERS, FLAGS,
ID_FLAG_DOWN, ID_FLAG_SZ, ID_FLAG_STAFF, ID_FLAG_REVIVE,
ID_FLAG_MOVE, ID_FLAG_VIP, ID_FLAG_CHEATER, ID_FLAG_ANIM,
ID_RANGE,
})
end
local function held_label(player)
local uid = ep.user_id(player)
local key = uid and uid ~= 0 and tostring(uid)
or tostring(player.Address or player.address or player.name or player)
local now = tick_ms()
local cached = held_cache[key]
if cached and now - cached.t < HELD_TTL_MS then
return cached.value or nil
end
local name = player_gear.held_name(player)
if not name or player_gear.is_empty_held_name(name) then
held_cache[key] = { t = now, value = false }
return nil
end
local base = name:match("^([^/]+)") or name
base = text_util.sanitize(base)
if base == "" then
held_cache[key] = { t = now, value = false }
return nil
end
held_cache[key] = { t = now, value = base }
return base
end
local function horizontal_speed(p)
local vel = p.Velocity or p.velocity
if not vel then return 0 end
local x = tonumber(vel.X or vel.x)
local z = tonumber(vel.Z or vel.z)
if not x or not z then return 0 end
return math.sqrt(x * x + z * z)
end
local function movement_label(p)
local speed = horizontal_speed(p)
if speed < 1.0 then return "IDLE" end
if speed > 15.0 then return "SPRINTING" end
return "WALKING"
end
local function native_bounds(player)
if thick_bullet and thick_bullet.esp_bounds then
local ok, bounds = pcall(thick_bullet.esp_bounds, player)
if ok and esp_util.bounds_usable(bounds) then
return bounds
end
end
local fn = player and (player.GetBounds or player.get_bounds)
if not fn then return nil end
local ok, bounds = pcall(fn, player)
if ok then return bounds end
return nil
end
local function native_bones(player)
local fn = player and (player.GetBonesScreen or player.get_bones_screen)
if not fn then return nil end
return fn(player)
end
local function emit_side_tag(x, y, ts, row, text, col)
draw_util.text(x, y + row * (ts + 1), text, col, ts)
return row + 1
end
local function draw_side_tags(p, snap, show_clan, clan_menu_col, flag_cols, flags, x, y, ts)
local row = 0
if show_clan and snap and snap.clan_tag then
local cc = snap.clan_color
row = emit_side_tag(x, y, ts, row, "[" .. snap.clan_tag .. "]", (cc and cc[1]) and cc or clan_menu_col)
end
if flags[FL_CHEATER] and cheater_detect.is_cheater(p) then
row = emit_side_tag(x, y, ts, row, "[CHEATER]", flag_cols.cheater)
end
if flags[FL_SAFEZONE] and snap and snap.safezone then
row = emit_side_tag(x, y, ts, row, "[SZ]", flag_cols.sz)
end
if flags[FL_DOWNED] and snap and snap.downed then
row = emit_side_tag(x, y, ts, row, "[DOWN]", flag_cols.down)
end
if flags[FL_STAFF] then
if snap and snap.staff then
row = emit_side_tag(x, y, ts, row, "[" .. snap.staff .. "]", flag_cols.staff)
else
local role = mod_checker.staff_role(p)
if role then
row = emit_side_tag(x, y, ts, row, "[" .. mod_ids.short_label(role) .. "]", flag_cols.staff)
end
end
end
if flags[FL_REVIVING] and snap and snap.reviving then
row = emit_side_tag(x, y, ts, row, "[REVIVE]", flag_cols.revive)
end
if flags[FL_VIP] and snap and snap.vip then
row = emit_side_tag(x, y, ts, row, "[VIP]", flag_cols.vip)
end
if flags[FL_ANIM] then
local anim = anim_sense.label_for(p)
if anim then
row = emit_side_tag(x, y, ts, row, "[" .. anim .. "]", flag_cols.anim)
end
end
if flags[FL_MOVEMENT] then
emit_side_tag(x, y, ts, row, "[" .. movement_label(p) .. "]", flag_cols.move)
end
end
function M.draw()
if not M._flags_migrated then
M._flags_migrated = true
migrate_flags_table()
end
if not settings.enabled(P) then return end
local now = tick_ms()
if now - last_held_prune_ms >= HELD_PRUNE_MS then
last_held_prune_ms = now
for key, entry in pairs(held_cache) do
if now - (entry.t or 0) > HELD_PRUNE_MS then held_cache[key] = nil end
end
end
local players = cache.players
if type(players) ~= "table" or #players == 0 then return end
local range = settings.num(ID_RANGE, 500)
local range_sq = range * range
local box_mode = settings.num(ID_BOX, 1)
local show_health = settings.bool(ID_HEALTH, true)
local show_skel = settings.bool(ID_SKELETON, false)
local show_name = settings.bool(ID_NAME, true)
local show_clan = settings.bool(ID_CLAN, true)
local show_held = settings.bool(ID_HELD, false)
local show_dist = settings.bool(ID_DIST, true)
local show_tracer = settings.bool("infernal_player_tracers", false)
local show_arrow = settings.bool("infernal_player_offscreen", false)
local tracer_col = settings.color("infernal_player_tracers", { 1, 0.35, 0.35, 0.85 })
local arrow_col = settings.color("infernal_player_offscreen", { 1, 0.35, 0.35, 0.95 })
local filter_team = settings.multi(FILTERS, F_TEAM, true)
local filter_sz = settings.multi(FILTERS, F_SAFEZONE, false)
local skip_downed = settings.multi(FILTERS, F_SKIP_DOWNED, false)
local flags = frame_flags
flags[FL_DOWNED] = settings.multi(FLAGS, FL_DOWNED, false)
flags[FL_SAFEZONE] = settings.multi(FLAGS, FL_SAFEZONE, false)
flags[FL_STAFF] = settings.multi(FLAGS, FL_STAFF, false)
flags[FL_REVIVING] = settings.multi(FLAGS, FL_REVIVING, false)
flags[FL_MOVEMENT] = settings.multi(FLAGS, FL_MOVEMENT, false)
flags[FL_VIP] = settings.multi(FLAGS, FL_VIP, false)
flags[FL_CHEATER] = settings.multi(FLAGS, FL_CHEATER, false)
flags[FL_ANIM] = settings.multi(FLAGS, FL_ANIM, false)
if flags[FL_CHEATER] then
cheater_detect.tick()
end
if flags[FL_ANIM] then
if now - last_anim_prune_ms >= ANIM_PRUNE_MS then
last_anim_prune_ms = now
local live = {}
for i = 1, #players do
local p = players[i]
if p then
local uid = p.UserId or p.user_id
if uid and uid ~= 0 then
live[uid] = true
else
local addr = p.Address or p.address
if addr then live[tostring(addr)] = true end
end
end
end
anim_sense.prune(live)
end
elseif last_anim_prune_ms ~= 0 then
last_anim_prune_ms = 0
anim_sense.prune(nil)
end
local need_snap = show_clan or filter_sz or skip_downed
or flags[FL_DOWNED] or flags[FL_SAFEZONE]
or flags[FL_STAFF] or flags[FL_REVIVING] or flags[FL_VIP]
local need_side = need_snap or flags[FL_MOVEMENT] or flags[FL_CHEATER] or flags[FL_ANIM]
local skel_col = settings.color(ID_SKELETON, { 1, 1, 1, 0.92 })
local name_col = settings.color(ID_NAME, DEFAULT_TEXT)
local clan_menu_col = settings.color(ID_CLAN, DEFAULT_CLAN)
local held_col = settings.color(ID_HELD, DEFAULT_HELD)
local dist_col = settings.color(ID_DIST, DEFAULT_MUTED)
local box_col = settings.color(ID_BOX_COLOR, DEFAULT_BOX)
local flag_cols = frame_flag_cols
flag_cols.down = settings.color(ID_FLAG_DOWN, DEFAULT_FLAG.DOWN)
flag_cols.sz = settings.color(ID_FLAG_SZ, DEFAULT_FLAG.SZ)
flag_cols.staff = settings.color(ID_FLAG_STAFF, DEFAULT_FLAG.STAFF)
flag_cols.revive = settings.color(ID_FLAG_REVIVE, DEFAULT_FLAG.REVIVE)
flag_cols.move = settings.color(ID_FLAG_MOVE, DEFAULT_FLAG.MOVE)
flag_cols.vip = settings.color(ID_FLAG_VIP, DEFAULT_FLAG.VIP)
flag_cols.cheater = settings.color(ID_FLAG_CHEATER, DEFAULT_FLAG.CHEATER)
flag_cols.anim = settings.color(ID_FLAG_ANIM, DEFAULT_FLAG.ANIM)
local base_ts = esp_util.text_size()
local live_on = live_view.active()
local me = cache.local_player
local mx, my, mz = nil, nil, nil
if me then
mx, my, mz = esp_util.vec3_pos(me.Position or me.position or me.HeadPosition or me.head_position)
end
for i = 1, #players do
local p = players[i]
if not p then goto continue end
if p.IsAlive == false or p.is_alive == false then goto continue end
local pname = p.Name or p.name or p.DisplayName or p.display_name
local hx, hy, hz = esp_util.vec3_pos(
p.HeadPosition or p.head_position or p.Position or p.position
)
if not hx then goto continue end
local dist = 0
if mx then
local dx, dy, dz = hx - mx, hy - my, hz - mz
local dist_sq = dx * dx + dy * dy + dz * dz
if dist_sq > range_sq then goto continue end
dist = math.sqrt(dist_sq)
end
if filter_team and not player_state.passes_team_check(p) then goto continue end
local snap = nil
if need_snap then
snap = player_state.esp_state(p)
if skip_downed and snap and snap.downed then goto continue end
if filter_sz and snap and snap.safezone then goto continue end
end
if show_arrow and esp_util.draw_offscreen_to(hx, hy, hz, arrow_col, 14, 36, ARROW_OPTS) then goto continue end
local bounds = native_bounds(p)
if not esp_util.bounds_usable(bounds) then goto continue end
local sdx, sdy = nil, nil
if live_on then
sdx, sdy = live_view.shift(hx, hy, hz)
if sdx then bounds = live_view.moved(bounds, sdx, sdy) end
end
if show_tracer then
draw_util.snapline(bounds.x + bounds.w * 0.5, bounds.y + bounds.h, tracer_col, 1)
end
if show_skel then
local bones = native_bones(p)
if bones and sdx then bones = live_view.moved_points(bones, sdx, sdy) end
if bones then
esp_util.draw_skeleton_bones(bones, skel_col, 1)
end
end
local ts = base_ts
if dist > 200 then ts = math.max(9, ts - 1) end
if dist > 400 then ts = math.max(8, ts - 1) end
local cx = bounds.x + bounds.w * 0.5
if show_name then
draw_util.text_centered(cx, bounds.y - ts - 5, pname or "?", name_col, ts)
end
if need_side then
draw_side_tags(
p, snap, show_clan, clan_menu_col, flag_cols, flags,
bounds.x + bounds.w + 4, bounds.y, ts
)
end
if box_mode == 1 then
draw_util.box_esp(bounds.x, bounds.y, bounds.w, bounds.h, box_col, 0)
elseif box_mode == 2 then
draw_util.box_esp(bounds.x, bounds.y, bounds.w, bounds.h, box_col, 1)
end
if show_health then
draw_util.health_bar_on_box(bounds, p.Health or p.health, p.MaxHealth or p.max_health)
end
local below_y = bounds.y + bounds.h + 3
if show_held then
local held = held_label(p)
if held then
draw_util.text_centered(cx, below_y, held, held_col, ts)
below_y = below_y + ts + 2
end
end
if show_dist then
draw_util.text_centered(
cx,
below_y,
string.format("%dm", math.floor(dist + 0.5)),
dist_col,
ts
)
end
::continue::
end
end
return M
end)()

Infernal._mods["features.visuals.sound_esp"] = (function()
local settings = Infernal.require("core.settings")
local menu_util = Infernal.require("core.menu_util")
local draw_util = Infernal.require("core.draw_util")
local esp_util = Infernal.require("core.esp_util")
local math_util = Infernal.require("core.math_util")
local cache = Infernal.require("core.cache")
local ep = Infernal.require("core.entity_props")
local rbx_offsets = Infernal.require("core.rbx_offsets")
local player_state = Infernal.require("game.player_state")
local M = {}
local draw_cells = {}
local touched_cells = {}
local gather_seen = {}
local P = "infernal_sound_esp"
local ID_FADE_IN = P .. "_fade_in"
local ID_FADE_OUT = P .. "_fade_out"
local ID_SIZE = P .. "_size"
local ID_COLOR = P .. "_color"
local ID_MAX_DIST = P .. "_max_dist"
local ID_UNDER = P .. "_under"
local ID_SCREEN_Y = P .. "_screen_y"
local ID_CHIP = P .. "_chip"
local ID_DETAIL = P .. "_detail"
local ID_CAT_COLOR = P .. "_cat_color"
local ID_FILTERS = P .. "_filters"
local ID_MAX_PER = P .. "_max_per"
local PLAYER_FILTERS = "infernal_player_esp_filters"
local F_TEAM, F_SAFEZONE, F_SKIP_DOWNED = 1, 2, 3
local PLAYER_RANGE = "infernal_player_range"
local CF_FOOT, CF_COMBAT, CF_UTIL, CF_WORLD, CF_OTHER = 1, 2, 3, 4, 5
local SCAN_MS = 110
local HRP_CACHE_MS = 1000
local MAX_SOUNDS_PER_PLAYER = 24
local MAX_GATHER_PER_SCAN = 4
local CLASSIFY_MAX = 1024
local VOL_DEADBAND = 0.025
local SPD_DEADBAND = 0.02
local DEFAULT_MAX_DIST = 450
local DEFAULT_UNDER = 2.8
local DEFAULT_SCREEN_Y = 2
local DEFAULT_SIZE = 10
local DEFAULT_MAX_PER = 4
local CAT_PRIORITY = {
    GUN = 100, EXPL = 95, HIT = 90, RELOAD = 85, HEAL = 80, MELEE = 75,
    INTER = 55, VEH = 45, VOICE = 30, FOOT = 20, OTHER = 10,
}
local CAT = {
    FOOT = {
        key = "FOOT", filter = CF_FOOT,
        color = { 0.72, 0.86, 1.0, 0.95 },
        rules = { "foot", "step", "run", "walk", "land", "jump", "sprint", "crawl" },
    },
    GUN = {
        key = "GUN", filter = CF_COMBAT,
        color = { 1.0, 0.45, 0.38, 0.95 },
        rules = { "gun", "fire", "shot", "shoot", "bullet", "rifle", "pistol", "smg", "shotgun", "sniper", "ak", "m4", "ar15" },
    },
    RELOAD = {
        key = "RELOAD", filter = CF_COMBAT,
        color = { 1.0, 0.72, 0.35, 0.95 },
        rules = { "reload", "mag", "chamber", "bolt" },
    },
    HIT = {
        key = "HIT", filter = CF_COMBAT,
        color = { 1.0, 0.28, 0.28, 0.95 },
        rules = { "hit", "impact", "flesh", "hurt", "damage", "headshot" },
    },
    EXPL = {
        key = "EXPL", filter = CF_COMBAT,
        color = { 1.0, 0.55, 0.15, 0.95 },
        rules = { "explod", "grenade", "boom", "rpg", "rocket", "c4" },
    },
    HEAL = {
        key = "HEAL", filter = CF_UTIL,
        color = { 0.45, 1.0, 0.62, 0.95 },
        rules = { "heal", "bandage", "med", "syringe", "stim", "revive", "cpr" },
    },
    MELEE = {
        key = "MELEE", filter = CF_COMBAT,
        color = { 0.95, 0.8, 0.4, 0.95 },
        rules = { "melee", "swing", "slash", "punch", "knife", "axe" },
    },
    VEH = {
        key = "VEH", filter = CF_WORLD,
        color = { 0.55, 0.75, 1.0, 0.95 },
        rules = { "car", "engine", "vehicle", "heli", "bike", "tire", "horn" },
    },
    INTER = {
        key = "INTER", filter = CF_UTIL,
        color = { 0.85, 0.78, 1.0, 0.95 },
        rules = { "door", "open", "close", "loot", "pickup", "item", "craft", "build", "place" },
    },
    VOICE = {
        key = "VOICE", filter = CF_OTHER,
        color = { 0.95, 0.7, 0.95, 0.95 },
        rules = { "voice", "talk", "radio", "mic", "chat" },
    },
    OTHER = {
        key = "OTHER", filter = CF_OTHER,
        color = { 0.78, 0.9, 1.0, 0.92 },
        rules = {},
    },
}
local CAT_ORDER = { "FOOT", "GUN", "RELOAD", "HIT", "EXPL", "HEAL", "MELEE", "VEH", "INTER", "VOICE", "OTHER" }
local indicators = {}
local sound_prev = {}
local player_cache = {}
local classify_cache = {}
local classify_n = 0
local last_scan_ms = 0
local mem_read_fn = nil
local cached_off = nil
local gather_budget = 0
local function tick_ms()
    local fn = utility and (utility.get_tick_count or utility.GetTickCount)
    if type(fn) ~= "function" then return 0 end
    local ok, v = pcall(fn)
    return (ok and tonumber(v)) or 0
end
local function ensure_mem()
    if mem_read_fn then return mem_read_fn end
    if not memory then return nil end
    mem_read_fn = memory.read or memory.Read
    if type(mem_read_fn) ~= "function" then
        mem_read_fn = nil
    end
    return mem_read_fn
end
local function mem_bool(addr, off)
    local fn = ensure_mem()
    if not fn or not addr or not off then return false end
    local ok, value = pcall(fn, addr + off, "bool")
    return ok and value == true
end
local function mem_float(addr, off)
    local fn = ensure_mem()
    if not fn or not addr or not off then return nil end
    local ok, value = pcall(fn, addr + off, "float")
    if ok then return tonumber(value) end
    return nil
end
local function sound_offs()
    if cached_off then return cached_off end
    cached_off = {
        is_playing = rbx_offsets.sound_is_playing(),
        volume = rbx_offsets.sound("Volume"),
        speed = rbx_offsets.sound("PlaybackSpeed"),
        looped = rbx_offsets.sound("Looped"),
        rolloff = rbx_offsets.sound("RollOffMaxDistance"),
        rolloff_min = rbx_offsets.sound("RollOffMinDistance"),
        sound_id = rbx_offsets.sound("SoundId"),
    }
    return cached_off
end
local function camera_pos()
    if not camera then return nil end
    local fn = camera.get_position or camera.GetPosition
    if type(fn) ~= "function" then return nil end
    local ok, pos = pcall(fn)
    if not ok or not pos then return nil end
    local x, y, z = esp_util.vec3_pos(pos)
    if not x then return nil end
    return x, y, z
end
local function player_alive(p)
    if not p or p.IsAlive == false then return false end
    local hp = ep.health(p)
    if hp ~= nil and hp <= 0 then return false end
    return true
end
local function passes_player_esp_filters(p)
    if settings.multi(PLAYER_FILTERS, F_TEAM, true) then
        if not player_state.passes_team_check(p) then
            return false
        end
    end
    local need_snap = settings.multi(PLAYER_FILTERS, F_SAFEZONE, false)
        or settings.multi(PLAYER_FILTERS, F_SKIP_DOWNED, false)
    if need_snap then
        local snap = player_state.esp_state(p)
        if settings.multi(PLAYER_FILTERS, F_SKIP_DOWNED, false) and snap and snap.downed then
            return false
        end
        if settings.multi(PLAYER_FILTERS, F_SAFEZONE, false) and snap and snap.safezone then
            return false
        end
    end
    return true
end
local function player_key(p)
    local uid = ep.user_id(p)
    if uid and uid ~= 0 then return uid end
    local addr = p.Address or p.address
    if addr then return tostring(addr) end
    return tostring(p)
end
local function pretty_name(raw)
    raw = tostring(raw or "Sound")
    if raw == "" then return "Sound" end
    raw = raw:gsub("^rbxassetid://%d+", "Sound")
    raw = raw:gsub("%.ogg$", ""):gsub("%.mp3$", ""):gsub("%.wav$", "")
    raw = raw:gsub("_", " ")
    raw = raw:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    if #raw > 22 then
        raw = raw:sub(1, 20) .. ".."
    end
    return raw
end
local function classify_blob(blob)
    local hit = classify_cache[blob]
    if hit then return hit end
    if classify_n >= CLASSIFY_MAX then
        classify_cache = {}
        classify_n = 0
    end
    for i = 1, #CAT_ORDER do
        local key = CAT_ORDER[i]
        if key ~= "OTHER" then
            local def = CAT[key]
            local rules = def.rules
            for ri = 1, #rules do
                if blob:find(rules[ri], 1, true) then
                    classify_cache[blob] = def
                    classify_n = classify_n + 1
                    return def
                end
            end
        end
    end
    classify_cache[blob] = CAT.OTHER
    classify_n = classify_n + 1
    return CAT.OTHER
end
local function classify_sound(name, sound_id)
    local n = tostring(name or "")
    local by_name = classify_blob(n:lower())
    if by_name.key ~= "OTHER" or not sound_id or sound_id == "" then
        return by_name
    end
    return classify_blob((n .. " " .. tostring(sound_id)):lower())
end
local function filter_allows(cat_def)
    local slot = cat_def and cat_def.filter or CF_OTHER
    return settings.multi(ID_FILTERS, slot, true)
end
local function under_studs()
    return math.max(0, settings.num(ID_UNDER, DEFAULT_UNDER))
end
local function anchor_world(px, py, pz)
    return px, py - under_studs(), pz
end
local function read_sound_id(child, addr, off)
    if child then
        local sid = child.SoundId or child.sound_id
        if type(sid) == "string" and sid ~= "" then return sid end
    end
    if memory and memory.ReadString and addr and off.sound_id then
        local ok, ptr = pcall(function()
            return (memory.Read or memory.read)(addr + off.sound_id, "ptr")
        end)
        if ok and ptr and ptr ~= 0 then
            local ok2, s = pcall(memory.ReadString, ptr, 96)
            if ok2 and type(s) == "string" and s ~= "" then return s end
        end
    end
    return nil
end
local function gather_sounds(character, hrp, prev_entry)
    local sounds = {}
    local seen = gather_seen
    for addr in pairs(seen) do seen[addr] = nil end
    local deep_done = prev_entry and prev_entry.deep_done == true
    local char_addr = character and tonumber(character.Address or character.address) or nil
    local function push(child)
        if not child then return end
        local class_name = child.ClassName or child.class_name
        if class_name ~= "Sound" then return end
        if #sounds >= MAX_SOUNDS_PER_PLAYER then return end
        local addr = tonumber(child.Address or child.address)
        if not addr or addr <= 0 or seen[addr] then return end
        seen[addr] = true
        sounds[#sounds + 1] = {
            addr = addr,
            name = pretty_name(child.Name or child.name),
            child = child,
        }
    end
    local function push_children(inst)
        if not inst or not inst.GetChildren then return end
        local ok, kids = pcall(function() return inst:GetChildren() end)
        if not ok or type(kids) ~= "table" then return end
        for i = 1, #kids do
            push(kids[i])
            if #sounds >= MAX_SOUNDS_PER_PLAYER then return end
        end
    end
    push_children(hrp)
    if #sounds == 0 and character and character.FindFirstChildOfClass then
        local ok_tool, tool = pcall(function()
            return character:FindFirstChildOfClass("Tool")
        end)
        if ok_tool and tool then
            push_children(tool)
            local handle = tool.FindFirstChild and tool:FindFirstChild("Handle")
            if handle then push_children(handle) end
        end
    end
    if #sounds == 0 then
        if prev_entry and prev_entry.char_addr == char_addr and prev_entry.deep_done and prev_entry.sounds then
            return prev_entry.sounds, char_addr, true
        end
        if character and character.GetDescendantsOfClass then
            local ok, list = pcall(function()
                return character:GetDescendantsOfClass("Sound")
            end)
            if ok and type(list) == "table" then
                local n = math.min(#list, MAX_SOUNDS_PER_PLAYER)
                for i = 1, n do push(list[i]) end
            end
            deep_done = true
        end
    end
    return sounds, char_addr, deep_done
end
local function refresh_player_sounds(p, now)
    local key = player_key(p)
    local entry = player_cache[key]
    if entry and entry.sounds and (now - (entry.t or 0)) < HRP_CACHE_MS then
        local px, py, pz = esp_util.vec3_pos(p.Position)
        if px then
            entry.px, entry.py, entry.pz = px, py, pz
        end
        return entry
    end
    if entry and entry.sounds and gather_budget <= 0 then
        local px, py, pz = esp_util.vec3_pos(p.Position)
        if px then
            entry.px, entry.py, entry.pz = px, py, pz
        end
        return entry
    end
    local character = p.Character
    if not character then
        player_cache[key] = nil
        return nil
    end
    local ok_hrp, hrp = pcall(function()
        return character:FindFirstChild("HumanoidRootPart")
    end)
    if not ok_hrp or not hrp then
        player_cache[key] = nil
        return nil
    end
    gather_budget = gather_budget - 1
    local px, py, pz = esp_util.vec3_pos(p.Position or hrp.Position)
    local sounds, char_addr, deep_done = gather_sounds(character, hrp, entry)
    entry = {
        hrp = hrp,
        sounds = sounds,
        t = now,
        px = px, py = py, pz = pz,
        char_addr = char_addr,
        deep_done = deep_done == true,
    }
    player_cache[key] = entry
    return entry
end
local function read_sound_state(child, addr, off, want_sid)
    local vol = tonumber(child and child.Volume)
    if vol == nil then vol = mem_float(addr, off.volume) or 0 end
    local spd = tonumber(child and child.PlaybackSpeed)
    if spd == nil then spd = mem_float(addr, off.speed) or 0 end
    local looped
    if child and child.Looped ~= nil then
        looped = child.Looped == true
    else
        looped = mem_bool(addr, off.looped)
    end
    local rolloff = tonumber(child and child.RollOffMaxDistance)
    if rolloff == nil then rolloff = mem_float(addr, off.rolloff) or 0 end
    local sid = nil
    if want_sid then
        sid = read_sound_id(child, addr, off)
    end
    return vol, spd, looped, rolloff, sid
end
local function format_label(cat_key, name, vol, dist, detail)
    if detail then
        local v = math.floor((tonumber(vol) or 0) * 100 + 0.5)
        local d = math.floor((tonumber(dist) or 0) + 0.5)
        return string.format("%s · %dm · %d%%", cat_key, d, v)
    end
    return cat_key
end
local function bump_indicator(addr, payload)
    local ax, ay, az = anchor_world(payload.px, payload.py, payload.pz)
    local ind = indicators[addr]
    if not ind then
        indicators[addr] = {
            name = payload.name,
            cat = payload.cat,
            text = payload.text,
            color = payload.color,
            pkey = payload.pkey,
            pri = payload.pri or 0,
            alpha = 0,
            state = "fade_in",
            timer = 0,
            x = ax, y = ay, z = az,
            seen = true,
        }
        return
    end
    ind.x, ind.y, ind.z = ax, ay, az
    ind.name = payload.name or ind.name
    ind.cat = payload.cat or ind.cat
    ind.text = payload.text or ind.text
    ind.color = payload.color or ind.color
    ind.pkey = payload.pkey or ind.pkey
    ind.pri = payload.pri or ind.pri or 0
    ind.seen = true
    if ind.state == "fade_out" then
        ind.state = "fade_in"
        ind.timer = 0
    end
end
local function enforce_max_per_player(max_per)
    max_per = math.floor(tonumber(max_per) or DEFAULT_MAX_PER)
    if max_per < 1 then max_per = 1 end
    if max_per > 10 then max_per = 10 end
    local by_player = {}
    for addr, ind in pairs(indicators) do
        if ind and ind.state ~= "fade_out" and ind.pkey ~= nil then
            local list = by_player[ind.pkey]
            if not list then
                list = {}
                by_player[ind.pkey] = list
            end
            list[#list + 1] = {
                addr = addr,
                pri = tonumber(ind.pri) or 0,
                age = tonumber(ind.timer) or 0,
            }
        end
    end
    for _, list in pairs(by_player) do
        if #list > max_per then
            table.sort(list, function(a, b)
                if a.pri ~= b.pri then return a.pri > b.pri end
                return a.age < b.age
            end)
            for i = max_per + 1, #list do
                local ind = indicators[list[i].addr]
                if ind then
                    ind.state = "fade_out"
                    ind.timer = 0
                    ind.seen = false
                end
            end
        end
    end
end
local function scan_sounds(now)
    local cam_x, cam_y, cam_z = camera_pos()
    if not cam_x then return end
    local off = sound_offs()
    if not ensure_mem() or not off.is_playing then return end
    local sound_range = math.max(50, settings.num(ID_MAX_DIST, DEFAULT_MAX_DIST))
    local player_range = math.max(50, settings.num(PLAYER_RANGE, 500))
    local max_dist = math.min(sound_range, player_range)
    local detail = settings.bool(ID_DETAIL, true)
    local use_cat_color = settings.bool(ID_CAT_COLOR, true)
    local max_per = settings.num(ID_MAX_PER, DEFAULT_MAX_PER)
    gather_budget = MAX_GATHER_PER_SCAN
    for _, prev in pairs(sound_prev) do
        prev.seen = false
    end
    for _, ind in pairs(indicators) do
        ind.seen = false
    end
    local players = cache.players or {}
    local live_keys = {}
    for i = 1, #players do
        local p = players[i]
        if p and p.IsLocal ~= true and player_alive(p) and passes_player_esp_filters(p) then
            local px0, py0, pz0 = esp_util.vec3_pos(p.Position)
            if px0 then
                local dist = math_util.distance3(px0 - cam_x, py0 - cam_y, pz0 - cam_z)
                if dist <= max_dist then
                    local key = player_key(p)
                    live_keys[key] = true
                    local entry = refresh_player_sounds(p, now)
                    if entry and entry.sounds then
                        local px = entry.px or px0
                        local py = entry.py or py0
                        local pz = entry.pz or pz0
                        local sounds = entry.sounds
                        for si = 1, #sounds do
                            local s = sounds[si]
                            local addr = s.addr
                            local child = s.child
                            local cat = classify_sound(s.name, nil)
                            if not filter_allows(cat) then
                                goto next_sound
                            end
                            local need_sid = cat.key == "OTHER"
                            local vol, spd, looped, rolloff, sid = read_sound_state(child, addr, off, need_sid)
                            if need_sid and sid then
                                cat = classify_sound(s.name, sid)
                                if not filter_allows(cat) then
                                    goto next_sound
                                end
                            end
                            local is_playing = mem_bool(addr, off.is_playing)
                            local is_audible = rolloff <= 0 or dist <= rolloff
                            local prev = sound_prev[addr]
                            if not prev then
                                sound_prev[addr] = {
                                    vol = vol, spd = spd, looped = looped,
                                    playing = is_playing, audible = is_audible,
                                    seen = true,
                                }
                            else
                                prev.seen = true
                                local started = false
                                local stopped = false
                                if vol > (prev.vol + VOL_DEADBAND) then started = true end
                                if vol < (prev.vol - VOL_DEADBAND) then stopped = true end
                                if spd > (prev.spd + SPD_DEADBAND) then started = true end
                                if spd < (prev.spd - SPD_DEADBAND) then stopped = true end
                                if looped and not prev.looped then started = true end
                                if (not looped) and prev.looped then stopped = true end
                                if is_playing and not prev.playing then started = true end
                                if (not is_playing) and prev.playing then stopped = true end
                                local emitting = vol > 0 and spd > 0 and is_playing
                                if emitting and is_audible and not prev.audible then
                                    started = true
                                end
                                if (not is_audible) and prev.audible then
                                    stopped = true
                                end
                                prev.vol, prev.spd, prev.looped = vol, spd, looped
                                prev.playing, prev.audible = is_playing, is_audible
                                local text = format_label(cat.key, s.name, vol, dist, detail)
                                local col = use_cat_color and cat.color or nil
                                local payload = {
                                    name = s.name,
                                    cat = cat.key,
                                    text = text,
                                    color = col,
                                    px = px, py = py, pz = pz,
                                    pkey = key,
                                    pri = CAT_PRIORITY[cat.key] or 10,
                                }
                                if started and not stopped and is_audible then
                                    bump_indicator(addr, payload)
                                elseif stopped then
                                    local ind = indicators[addr]
                                    if ind and ind.state ~= "fade_out" then
                                        ind.state = "fade_out"
                                        ind.timer = 0
                                    end
                                else
                                    local ind = indicators[addr]
                                    if ind and ind.state ~= "fade_out" and is_audible then
                                        local ax, ay, az = anchor_world(px, py, pz)
                                        ind.x, ind.y, ind.z = ax, ay, az
                                        ind.text = text
                                        ind.cat = cat.key
                                        ind.color = col or ind.color
                                        ind.pkey = key
                                        ind.pri = CAT_PRIORITY[cat.key] or ind.pri or 10
                                        ind.seen = true
                                    elseif emitting and is_audible and not indicators[addr] then
                                        bump_indicator(addr, payload)
                                    end
                                end
                            end
                            ::next_sound::
                        end
                    end
                end
            end
        end
    end
    enforce_max_per_player(max_per)
    for key in pairs(player_cache) do
        if not live_keys[key] then
            player_cache[key] = nil
        end
    end
    for addr, prev in pairs(sound_prev) do
        if not prev.seen then
            sound_prev[addr] = nil
        end
    end
end
local function tick_indicators(dt)
    local fade_in = math.max(0.05, settings.num(ID_FADE_IN, 0.25))
    local fade_out = math.max(0.05, settings.num(ID_FADE_OUT, 5.0))
    for addr, ind in pairs(indicators) do
        if not ind.seen and ind.state ~= "fade_out" then
            ind.state = "fade_out"
            ind.timer = 0
        end
        ind.timer = (ind.timer or 0) + dt
        if ind.state == "fade_in" then
            ind.alpha = math.min(1, ind.timer / fade_in)
            if ind.alpha >= 1 then
                ind.state = "visible"
                ind.timer = 0
            end
        elseif ind.state == "visible" then
            ind.alpha = 1
        elseif ind.state == "fade_out" then
            ind.alpha = math.max(0, 1 - ind.timer / fade_out)
            if ind.alpha <= 0 then
                indicators[addr] = nil
            end
        end
    end
end
function M.register_menu()
    local G = menu_util.G
    local T = menu_util.group(G.VISUALS)
    local root = menu_util.parent(P)
    menu_util.section(T, G.VISUALS, "Audio Radar")
    menu.add_checkbox(T, G.VISUALS, P, "Sound ESP", false)
    menu.add_slider_float(T, G.VISUALS, ID_FADE_IN, "Sound Fade In", 0.05, 2.0, 0.25, "%.2f", root)
    menu.add_slider_float(T, G.VISUALS, ID_FADE_OUT, "Sound Fade Out", 0.5, 15.0, 5.0, "%.2f", root)
    menu.add_slider_int(T, G.VISUALS, ID_SIZE, "Sound Text Size", 8, 20, DEFAULT_SIZE, root)
    menu.add_slider_float(T, G.VISUALS, ID_UNDER, "Under Offset", 0, 6, DEFAULT_UNDER, "%.1f", root)
    menu.add_slider_int(T, G.VISUALS, ID_SCREEN_Y, "Screen Offset", -20, 40, DEFAULT_SCREEN_Y, root)
    menu.add_slider_int(T, G.VISUALS, ID_MAX_DIST, "Sound Range", 50, 2000, DEFAULT_MAX_DIST, root)
    menu.add_slider_int(T, G.VISUALS, ID_MAX_PER, "Max Per Player", 1, 10, DEFAULT_MAX_PER, root)
    menu.add_multicombo(T, G.VISUALS, ID_FILTERS, "Radar Filters", {
        "Footsteps", "Combat", "Utility", "World", "Other",
    }, { true, true, true, true, true }, root)
    menu.add_checkbox(T, G.VISUALS, ID_DETAIL, "Radar Detail", true, root)
    menu.add_checkbox(T, G.VISUALS, ID_CAT_COLOR, "Category Colors", true, root)
    menu.add_checkbox(T, G.VISUALS, ID_CHIP, "Sound Chip", false, root)
    menu.add_colorpicker(T, G.VISUALS, ID_COLOR, "Sound Color", { 0.78, 0.9, 1.0, 0.92 }, root)
    menu_util.bind_children(P, {
        ID_FADE_IN, ID_FADE_OUT, ID_SIZE, ID_UNDER, ID_SCREEN_Y, ID_MAX_DIST, ID_MAX_PER,
        ID_FILTERS, ID_DETAIL, ID_CAT_COLOR, ID_CHIP, ID_COLOR,
    })
end
function M.update(dt)
    if not settings.enabled(P) then
        if next(indicators) then indicators = {} end
        if next(sound_prev) then sound_prev = {} end
        if next(player_cache) then player_cache = {} end
        if next(classify_cache) then
            classify_cache = {}
            classify_n = 0
        end
        return
    end
    dt = tonumber(dt) or 0
    if dt <= 0 then dt = 1 / 60 end
    local now = tick_ms()
    if (now - last_scan_ms) >= SCAN_MS then
        last_scan_ms = now
        scan_sounds(now)
    else
        for _, ind in pairs(indicators) do
            ind.seen = ind.state ~= "fade_out"
        end
    end
    tick_indicators(dt)
end
local function draw_label(sx, sy, text, col, size, chip)
    local size_fn = draw.get_text_size or draw.GetTextSize
    local tw, th = 0, size
    if size_fn then
        local ok, w, h = pcall(size_fn, text, size)
        if ok then
            tw = tonumber(w) or 0
            th = tonumber(h) or size
        end
    end
    local a = col[4] or 1
    if chip and draw.rect_filled then
        local pad_x, pad_y = 4, 1
        local bw = tw + pad_x * 2
        local bh = th + pad_y * 2
        local bx = sx - bw * 0.5
        local by = sy
        draw.rect_filled(bx, by, bw, bh, { 0.04, 0.05, 0.07, a * 0.45 }, 3)
        draw_util.text(bx + pad_x + 1, by + pad_y + 1, text, { 0, 0, 0, a * 0.5 }, size)
        draw_util.text(bx + pad_x, by + pad_y, text, col, size)
        return
    end
    local tx = sx - tw * 0.5
    draw_util.text(tx + 1, sy + 1, text, { 0, 0, 0, a * 0.55 }, size)
    draw_util.text(tx, sy, text, col, size)
end
function M.draw()
    if not settings.enabled(P) then return end
    if not draw then return end
    local size = math.floor(settings.num(ID_SIZE, DEFAULT_SIZE))
    local screen_y = math.floor(settings.num(ID_SCREEN_Y, DEFAULT_SCREEN_Y))
    local chip = settings.bool(ID_CHIP, false)
    local base = settings.color(ID_COLOR, { 0.78, 0.9, 1.0, 0.92 })
    local br, bg, bb, ba = base[1] or 0.78, base[2] or 0.9, base[3] or 1, base[4] or 0.92
    for i = 1, #touched_cells do
        draw_cells[touched_cells[i]] = nil
        touched_cells[i] = nil
    end
    for _, ind in pairs(indicators) do
        local a = (ind.alpha or 0) * ba
        if a > 0.02 and ind.x then
            local sx, sy, vis = esp_util.w2s(ind.x, ind.y, ind.z)
            if vis and esp_util.screen_point_ok(sx, sy, 64) then
                local key = math.floor(sx / 10) .. ":" .. math.floor(sy / 10)
                local slot = draw_cells[key] or 0
                if slot == 0 then touched_cells[#touched_cells + 1] = key end
                draw_cells[key] = slot + 1
                local y = sy + screen_y + slot * (size + 2)
                local source = ind.color
                local col = ind._draw_color
                if not col then
                    col = {}
                    ind._draw_color = col
                end
                if type(source) ~= "table" then
                    col[1], col[2], col[3], col[4] = br, bg, bb, a
                else
                    col[1], col[2], col[3], col[4] = source[1] or br, source[2] or bg, source[3] or bb, a
                end
                draw_label(sx, y, ind.text or ind.cat or ind.name or "Sound", col, size, chip)
            end
        end
    end
end
return M
end)()

Infernal._mods["features.visuals.target_overlay"] = (function()
local settings = Infernal.require("core.settings")
local draw_util = Infernal.require("core.draw_util")
local menu_util = Infernal.require("core.menu_util")
local image_cache = Infernal.require("core.image_cache")
local items = Infernal.require("game.items")
local player_gear = Infernal.require("game.player_gear")
local player_state = Infernal.require("game.player_state")
local text_util = Infernal.require("core.text_util")
local theme = Infernal.require("core.ui_theme")
local overlay_theme = Infernal.require("core.overlay_theme")
local ep = Infernal.require("core.entity_props")
local esp_util = Infernal.require("core.esp_util")
local math_util = Infernal.require("core.math_util")
local cache = Infernal.require("core.cache")
local M = {}
local P = "infernal_target_overlay"
local P_FOV = P .. "_fov"
local P_DIST = P .. "_max_dist"
local GEAR_SLOTS = 7
local GEAR_TTL = 500
local TARGET_POLL_MS = 120
local MAX_ATTACHMENTS = 5
local DEFAULT_FOV = 100
local DEFAULT_MAX_DIST = 500
local gear_cache = {}
local last_poll_ms = 0
local last_cache_prune_ms = 0
local CACHE_PRUNE_MS = 2000
M._target = nil
M._layout = nil
local function tick_ms()
    return utility and utility.get_tick_count and utility.get_tick_count() or 0
end
local function img_key(prefix, id)
    return prefix .. tostring(id)
end
local function resolve_image_key(piece)
    if not piece then return nil end
    if type(piece) == "table" and piece.asset_id then
        local key = img_key("item_", piece.asset_id)
        image_cache.ensure(key, piece.asset_id)
        return key
    end
    if type(piece) == "table" and piece.name then
        local resolved = items.resolve_item_label(
            piece.variant and (piece.name .. "/" .. piece.variant) or piece.name
        )
        if resolved and resolved.asset_id then
            local key = img_key("item_", resolved.asset_id)
            image_cache.ensure(key, resolved.asset_id)
            return key
        end
        local asset_id = items.get_image_asset_id(piece.name, piece.variant)
        if asset_id then
            local key = img_key("item_", asset_id)
            image_cache.ensure(key, asset_id)
            return key
        end
    end
    return nil
end
local function local_origin()
    local me = cache.local_player
    if not me then return nil end
    return esp_util.vec3_pos(
        me.Position or me.position or me.HeadPosition or me.head_position
    )
end
local function find_overlay_target()
    local fov = settings.num(P_FOV, DEFAULT_FOV)
    local max_dist = settings.num(P_DIST, DEFAULT_MAX_DIST)
    if fov <= 0 or max_dist <= 0 then return nil end
    local ox, oy, oz = local_origin()
    local sw, sh = draw_util.screen_size()
    local cx, cy = sw * 0.5, sh * 0.5
    local best, best_d = nil, fov
    local max_dist_sq = max_dist * max_dist
    for _, player in ipairs(cache.players or {}) do
        if player_state.is_combat_target(player) then
            local hx, hy, hz = esp_util.vec3_pos(ep.head_position(player) or ep.position(player))
            if hx then
                if ox then
                    local dx, dy, dz = hx - ox, hy - oy, hz - oz
                    if dx * dx + dy * dy + dz * dz > max_dist_sq then
                        goto continue
                    end
                end
                local sx, sy, on_screen = esp_util.w2s(hx, hy, hz)
                if on_screen then
                    local dist = math_util.screen_fov_dist(sx, sy, cx, cy)
                    if dist <= fov and dist < best_d then
                        best, best_d = player, dist
                    end
                end
            end
        end
        ::continue::
    end
    return best
end
local function player_key(player)
    if not player then return "?" end
    local uid = ep.user_id(player)
    if uid and uid ~= 0 then return uid end
    return player.name or player.display_name or "?"
end
local function get_gear(player)
    if not player then return nil end
    local uid = player_key(player)
    local now = tick_ms()
    local cached = gear_cache[uid]
    if cached and (now - cached.t) < GEAR_TTL then
        return cached.data
    end
    local data = player_gear.scan_player(player)
    gear_cache[uid] = { t = now, data = data }
    return data
end
local function armor_sort_key(piece)
    local n = (piece.name or ""):lower()
    if n:find("helmet", 1, true) or n:find("head", 1, true) or n:find("cap", 1, true)
        or n:find("wrap", 1, true) or n:find("balaclava", 1, true) or n:find("hood", 1, true) then
        return 1
    end
    if n:find("chest", 1, true) or n:find("plate", 1, true) or n:find("shirt", 1, true)
        or n:find("jacket", 1, true) or n:find("hoodie", 1, true) or n:find("vest", 1, true)
        or n:find("suit", 1, true) or n:find("torso", 1, true) then
        return 2
    end
    if n:find("legging", 1, true) or n:find("pants", 1, true) or n:find("shorts", 1, true) then
        return 3
    end
    if n:find("glove", 1, true) or n:find("handwrap", 1, true) then
        return 4
    end
    if n:find("boot", 1, true) or n:find("footwrap", 1, true) or n:find("shoe", 1, true) then
        return 5
    end
    if n:find("backpack", 1, true) or n:find("bag", 1, true) then
        return 6
    end
    return 7
end
local function pack_gear(armor_list)
    local sorted = {}
    for _, piece in ipairs(armor_list or {}) do
        table.insert(sorted, piece)
    end
    table.sort(sorted, function(a, b)
        return armor_sort_key(a) < armor_sort_key(b)
    end)
    local packed = {}
    for _, piece in ipairs(sorted) do
        table.insert(packed, piece)
        if #packed >= GEAR_SLOTS then break end
    end
    return packed
end
local function pack_attachments(list)
    local packed = {}
    for i = 1, math.min(#(list or {}), MAX_ATTACHMENTS) do
        packed[#packed + 1] = list[i]
    end
    return packed
end
local function build_layout(gear, gear_sz)
    local held = gear and gear.held
    local packed = pack_gear(gear and gear.armor)
    local attachments = pack_attachments(gear and gear.attachments)
    local held_sz = math.floor(gear_sz * 1.28)
    local att_sz = math.floor(gear_sz * 0.78)
    local gap = 5
    local att_gap = 4
    local row_w = GEAR_SLOTS * gear_sz + (GEAR_SLOTS - 1) * gap
    local att_row_w = #attachments > 0 and (#attachments * att_sz + (#attachments - 1) * att_gap) or 0
    local held_row_w = held_sz + (#attachments > 0 and (10 + att_row_w) or 0)
    local panel_w = math.max(row_w, held_row_w)
    local layout = {
        held = held,
        attachments = attachments,
        packed = packed,
        filled = #packed,
        gear_sz = gear_sz,
        held_sz = held_sz,
        att_sz = att_sz,
        gap = gap,
        att_gap = att_gap,
        row_w = row_w,
        held_row_w = held_row_w,
        panel_w = panel_w,
        row_gap = 8,
        name_fs = 11,
        held_key = nil,
        att_keys = {},
        gear_keys = {},
    }
    layout.held_key = held and resolve_image_key(held) or nil
    for i = 1, layout.filled do
        layout.gear_keys[i] = resolve_image_key(packed[i])
        local key = layout.gear_keys[i]
        if key then image_cache.begin_load(key) end
    end
    for i = 1, #attachments do
        layout.att_keys[i] = resolve_image_key(attachments[i])
        local key = layout.att_keys[i]
        if key then image_cache.begin_load(key) end
    end
    if layout.held_key then
        image_cache.begin_load(layout.held_key)
    end
    return layout
end
local function held_piece(held)
    if not held then return nil end
    if type(held) == "table" then
        if held.name and player_gear.is_empty_held_name and player_gear.is_empty_held_name(held.name) then
            return nil
        end
        return held
    end
    if player_gear.is_empty_held_name and player_gear.is_empty_held_name(held) then
        return nil
    end
    return { name = held }
end
local function split_words(text)
    local words = {}
    for word in text:gmatch("%S+") do
        words[#words + 1] = word
    end
    return words
end
local function wrap_words(words, max_w, fs)
    local lines = {}
    local i = 1
    while i <= #words do
        local line = words[i]
        local j = i + 1
        while j <= #words do
            local try = line .. " " .. words[j]
            if select(1, draw.get_text_size(try, fs)) <= max_w then
                line = try
                j = j + 1
            else
                break
            end
        end
        lines[#lines + 1] = line
        i = j
    end
    return lines
end
local function words_fit(words, fs, max_w)
    for _, word in ipairs(words) do
        if select(1, draw.get_text_size(word, fs)) > max_w then
            return false
        end
    end
    return true
end
local function slot_label(piece)
    if type(piece) ~= "table" then return nil end
    local name = piece.name
    if not name or name == "" then return nil end
    name = text_util.sanitize(name)
    local base, slash_var = name:match("^([^/]+)/(.+)$")
    if base and slash_var then
        return base .. " " .. slash_var
    end
    local variant = piece.variant
    if variant and variant ~= "" and variant ~= "Default" then
        return name .. " " .. text_util.sanitize(variant)
    end
    return name
end
local function draw_fitted_label(x, y, size, text)
    if not draw or not draw.text or not draw.get_text_size then return end
    text = text_util.sanitize(text)
    if text == "" then return end
    local pad = 4
    local inner = size - pad * 2
    local words = split_words(text)
    if #words == 0 then return end
    local max_fs = math.max(8, math.floor(size * 0.26))
    local min_fs = 6
    local chosen_fs, chosen_lines
    for fs = max_fs, min_fs, -1 do
        if words_fit(words, fs, inner) then
            local lines = wrap_words(words, inner, fs)
            local line_h = fs + 1
            if #lines * line_h <= inner then
                chosen_fs = fs
                chosen_lines = lines
                break
            end
        end
    end
    if not chosen_lines then
        chosen_fs = min_fs
        chosen_lines = wrap_words(words, inner, min_fs)
    end
    local line_h = chosen_fs + 1
    local total_h = #chosen_lines * line_h
    local ty = y + pad + (inner - total_h) * 0.5
    for i, line in ipairs(chosen_lines) do
        local tw = select(1, draw.get_text_size(line, chosen_fs))
        draw.text(
            x + size * 0.5 - tw * 0.5,
            ty + (i - 1) * line_h,
            line,
            theme.TEXT_MUTED,
            chosen_fs
        )
    end
end
local function draw_slot(x, y, size, key, piece, style, boxed)
    local pad = 3
    local bg = overlay_theme.slot()
    local edge = overlay_theme.border()
    if style == "held" then
        bg = overlay_theme.slot("held")
        edge = theme.alpha(overlay_theme.accent(), 0.88)
    elseif style == "attachment" then
        bg = theme.alpha(overlay_theme.slot(), 0.82)
    elseif style == "empty" then
        bg = overlay_theme.slot("empty")
        edge = theme.alpha(theme.BORDER, 0.28)
    end
    -- without Background only the item itself is drawn, and empty slots not at all
    if boxed ~= false then
        draw.rect_filled(x, y, size, size, bg, 0)
        if draw.rect then
            draw.rect(x, y, size, size, edge, 0, style == "held" and 1.5 or 1)
        end
        if style == "held" and draw.rect_filled then
            draw.rect_filled(x + 1, y + 1, size - 2, 2, overlay_theme.accent(), 0)
        end
    end
    if not piece then return end
    if key and image_cache.draw_fit(key, x + pad, y + pad, size - pad * 2, size - pad * 2)
        and not image_cache.loading_hint(key) then
        return
    end
    -- No picture (none exists or every source failed), or the first moments of a download:
    -- show the item name so the slot is never blank.
    local label = slot_label(piece)
    if label then
        draw_fitted_label(x, y, size, label)
    end
end
local function same_target(a, b)
    if a == b then return true end
    if not a or not b then return false end
    local aid = player_key(a)
    local bid = player_key(b)
    return aid and bid and aid == bid
end
function M.register_menu()
    local G = menu_util.G
    local T, _ = menu_util.group(G.VISUALS)
    menu_util.section(T, G.VISUALS, "Target Gear")
    menu_util.register_keybind(T, G.VISUALS, P, "Target Gear Overlay", false)
    local root = menu_util.parent(P)
    menu.add_slider_int(T, G.VISUALS, P_FOV, "Gear FOV", 5, 500, DEFAULT_FOV, root)
    menu.add_slider_int(T, G.VISUALS, P_DIST, "Max Distance", 50, 2000, DEFAULT_MAX_DIST, root)
    menu.add_slider_int(T, G.VISUALS, P .. "_gear_size", "Gear Icon Size", 32, 64, 48, root)
    menu.add_slider_int(T, G.VISUALS, P .. "_top_y", "Top Offset", 0, 160, 4, root)
    menu.add_checkbox(T, G.VISUALS, P .. "_bg", "Background", false, root)
    menu_util.bind_children(P, {
        P_FOV, P_DIST, P .. "_gear_size", P .. "_top_y", P .. "_bg",
    })
end
function M.refresh_target()
    if not settings.enabled(P) then
        M._target = nil
        M._layout = nil
        return
    end
    local gear_sz = settings.num(P .. "_gear_size", 48)
    local target = find_overlay_target()
    if not target or not player_state.is_combat_target(target) then
        M._target = nil
        M._layout = nil
        return
    end
    local target_changed = not same_target(M._target, target)
    local uid = player_key(target)
    local cached = gear_cache[uid]
    local gear_stale = not cached or (tick_ms() - cached.t) >= GEAR_TTL
    M._target = target
    if target_changed or not M._layout or gear_stale then
        M._layout = build_layout(get_gear(target), gear_sz)
    end
end
function M.update(_dt)
    if not settings.enabled(P) then
        M._target = nil
        M._layout = nil
        return
    end
    local now = tick_ms()
    if now - last_poll_ms < TARGET_POLL_MS then return end
    last_poll_ms = now
    if now - last_cache_prune_ms >= CACHE_PRUNE_MS then
        last_cache_prune_ms = now
        local live = {}
        for _, player in ipairs(cache.players or {}) do
            live[player_key(player)] = true
        end
        for uid in pairs(gear_cache) do
            if not live[uid] then gear_cache[uid] = nil end
        end
    end
    M.refresh_target()
end
local function truncate_text(text, max_w, fs)
    if not text or text == "" then return "" end
    if select(1, draw.get_text_size(text, fs)) <= max_w then
        return text
    end
    local out = text
    while #out > 1 and select(1, draw.get_text_size(out .. "..", fs)) > max_w do
        out = out:sub(1, -2)
    end
    return out .. ".."
end
local function resolve_player_name(target)
    local name = ep.display_name(target) or ep.name(target)
    if (not name or name == "") and target then
        name = target.DisplayName or target.display_name or target.Name or target.name
    end
    name = text_util.sanitize(name or "")
    if name == "" then name = "Unknown" end
    return name
end
-- Only the player's name; distance and health are left to the player ESP.
local function draw_info_band(panel_x, y, panel_w, target)
    local name_fs = 13
    local shown = truncate_text(resolve_player_name(target), panel_w - 24, name_fs)
    local tw = select(1, draw.get_text_size(shown, name_fs)) or 0
    draw.text(panel_x + (panel_w - tw) * 0.5, y, shown, overlay_theme.text(), name_fs)
    return 18
end
function M.draw()
    if not settings.enabled(P) then return end
    if not draw or not draw.text or not draw.rect_filled then return end
    local target = M._target
    local layout = M._layout
    if not target or not layout then return end
    local sw, _ = draw_util.screen_size()
    local top = settings.num(P .. "_top_y", 4)
    local cx = sw * 0.5
    local content_w = math.max(layout.held_row_w, layout.row_w)
    local panel_w = math.max(248, content_w + 20)
    local boxed = settings.bool(P .. "_bg", false)
    -- the title row only exists on the panel; without it the items start right at Top Offset
    local info_h = 18
    local title_h = boxed and 24 or 0
    local panel_h = title_h + 4 + info_h + 8 + layout.held_sz + layout.row_gap + layout.gear_sz + 10
    if not held_piece(layout.held) and layout.filled == 0 then
        panel_h = panel_h + 16
    end
    local panel_x = cx - panel_w * 0.5
    local i18n = Infernal.require("ui.i18n")
    if boxed then
        overlay_theme.draw_panel(panel_x, top, panel_w, panel_h, i18n.t("TARGET LOADOUT"), { title_center = true })
    end
    local y = top + title_h + 4
    y = y + draw_info_band(panel_x, y, panel_w, target) + 8
    local held = held_piece(layout.held)
    local row_x = cx - layout.held_row_w * 0.5
    draw_slot(row_x, y, layout.held_sz, layout.held_key, held, held and "held" or "empty", boxed)
    if #layout.attachments > 0 then
        local ax = row_x + layout.held_sz + 10
        for i = 1, #layout.attachments do
            local sx = ax + (i - 1) * (layout.att_sz + layout.att_gap)
            draw_slot(sx, y + (layout.held_sz - layout.att_sz) * 0.5, layout.att_sz, layout.att_keys[i], layout.attachments[i], "attachment", boxed)
        end
    end
    y = y + layout.held_sz + layout.row_gap
    local start_x = cx - layout.row_w * 0.5
    for i = 1, GEAR_SLOTS do
        local piece = i <= layout.filled and layout.packed[i] or nil
        local sx = start_x + (i - 1) * (layout.gear_sz + layout.gap)
        draw_slot(sx, y, layout.gear_sz, layout.gear_keys[i], piece, piece and "gear" or "empty", boxed)
    end
    if not held and layout.filled == 0 then
        local hint = "No gear detected"
        local hw = select(1, draw.get_text_size(hint, 10))
        draw.text(cx - hw * 0.5, y + layout.gear_sz + 6, hint, theme.TEXT_DIM, 10)
    end
end
return M
end)()

Infernal._mods["game.shots"] = (function()
-- Your own shots, shared by bullet tracers and hitsounds. A shot is noticed when Fallen puts its
-- bullet effect (ShotTracer, RifleBullet, arrows...) beside your camera, or, if no effect shows
-- up, when you click with a gun out. Each shot is resolved once: where it went (toward the
-- silent aim / ragebot target when one of them is pointing the shot, otherwise along your
-- crosshair), whether it ended on a character, and whether that was the head. Every feature
-- that subscribed gets its own copy of each shot.
local env = Infernal.require("core.env")
local silent_hook = Infernal.require("core.silent_hook")
local weapons = Infernal.require("game.weapons")
local M = {}
local BULLET_HINTS = { "tracer", "bullet", "arrow", "bolt", "nail", "pellet", "slug", "rocket", "projectile" }
local DEBRIS_HINTS = { "gib", "casing", "fire", "impact", "explosion", "spark", "smoke", "flash", "muzzle", "shell" }
local NEAR_CAMERA = 14
local MERGE_MS = 35
local FALLBACK_MS = 160
local MAX_RANGE = 3000
local HEAD_RADIUS = 1.3
local MAGIC_START_STUDS = 3     -- a redirected ray starting further than this from your camera
local LMB = 0x01
local queues = {}
local seen = {}
local seeded = false
local pending = nil
local last_shot = -1e9
local lmb_was = false
local sqrt = math.sqrt
local function now_ms()
    local fn = utility and (utility.get_tick_count or utility.GetTickCount)
    if type(fn) ~= "function" then return 0 end
    local ok, v = pcall(fn)
    return ok and tonumber(v) or 0
end
local function key_down(vk)
    local fn = input and (input.is_key_down or input.IsKeyDown)
    if type(fn) ~= "function" then return false end
    local ok, v = pcall(fn, vk)
    return ok and v == true
end
local function get(inst, field)
    local ok, v = pcall(function() return inst[field] end)
    if ok then return v end
    return nil
end
local function kids(inst)
    if not inst then return {} end
    local ok, t = pcall(function() return inst:GetChildren() end)
    return ok and type(t) == "table" and t or {}
end
local function find(inst, name)
    if not inst then return nil end
    local ok, c = pcall(function() return inst:FindFirstChild(name) end)
    return ok and c or nil
end
local function xyz(v)
    if v == nil then return nil end
    local ok, x, y, z = pcall(function() return v.X or v.x, v.Y or v.y, v.Z or v.z end)
    if ok and type(x) == "number" then return x, y, z end
    return nil
end
local function pos_of(inst)
    local x, y, z = xyz(get(inst, "Position"))
    if x then return x, y, z end
    local cf = get(inst, "CFrame")
    if cf then
        x, y, z = xyz(get(cf, "Position"))
        if x then return x, y, z end
    end
    local pp = get(inst, "PrimaryPart")
    if pp then return xyz(get(pp, "Position")) end
    return nil
end
local function addr(inst)
    local a = get(inst, "Address")
    return a and tostring(a) or tostring(inst)
end
local function has_hint(name, list)
    for _, h in ipairs(list) do
        if name:find(h, 1, true) then return true end
    end
    return false
end
local function looks_bullet(name)
    local n = tostring(name or ""):lower()
    if n == "" or has_hint(n, DEBRIS_HINTS) then return false end
    return has_hint(n, BULLET_HINTS)
end
local function camera_pos()
    local ok, p = pcall(function() return (camera.get_position or camera.GetPosition)() end)
    if not ok then return nil end
    local x, y, z = xyz(p)
    if x then return { x = x, y = y, z = z } end
    return nil
end
local function camera_look()
    local ok, p = pcall(function() return (camera.get_look_vector or camera.GetLookVector)() end)
    if not ok then return nil end
    local x, y, z = xyz(p)
    if x then return { x = x, y = y, z = z } end
    return nil
end
local function menu_open()
    local ok, ui = pcall(function() return Infernal.require("ui.custom_menu") end)
    return ok and ui and ui.is_open and ui.is_open() == true
end
local function vfx_folders()
    local ws = env.get_workspace()
    local vfx = ws and find(ws, "VFX")
    if not vfx then return {} end
    local list = { vfx }
    for _, c in ipairs(kids(vfx)) do
        local cn = get(c, "ClassName")
        if cn == "Folder" or cn == "Model" then list[#list + 1] = c end
    end
    return list
end
-- A bullet effect that just appeared beside the camera, or a pooled one that just jumped
-- there from far away, means you fired.
function M.scan_vfx(cam)
    local fired = false
    local fresh = {}
    for _, folder in ipairs(vfx_folders()) do
        for _, c in ipairs(kids(folder)) do
            if looks_bullet(get(c, "Name")) then
                local x, y, z = pos_of(c)
                if x then
                    local key = addr(c)
                    local dx, dy, dz = x - cam.x, y - cam.y, z - cam.z
                    if seeded and dx * dx + dy * dy + dz * dz <= NEAR_CAMERA * NEAR_CAMERA then
                        local prev = seen[key]
                        if not prev then
                            fired = true
                        else
                            local px, py, pz = prev[1] - x, prev[2] - y, prev[3] - z
                            if px * px + py * py + pz * pz > (NEAR_CAMERA * 3) ^ 2 then fired = true end
                        end
                    end
                    fresh[key] = { x, y, z }
                end
            end
        end
    end
    seen = fresh
    seeded = true
    return fired
end
-- The character a hit part belongs to (a model with a HumanoidRootPart or Humanoid that is not
-- yours), or nil.
local function character_of(inst)
    if not inst then return nil end
    local me = nil
    pcall(function() me = game.LocalPlayer.Character end)
    local cur = inst
    for _ = 1, 6 do
        cur = get(cur, "Parent")
        if not cur then return nil end
        if me and cur == me then return nil end
        if get(cur, "ClassName") == "Model" and (find(cur, "HumanoidRootPart") or find(cur, "Humanoid")) then
            return cur
        end
    end
    return nil
end
local function cast(ax, ay, az, bx, by, bz)
    local fn = raycast and (raycast.Cast or raycast.cast)
    if type(fn) ~= "function" or not (Vector3 and Vector3.New) then return nil end
    local ok, hit, hpos, _, hinst = pcall(fn, Vector3.New(ax, ay, az), Vector3.New(bx, by, bz))
    if not ok or not hit then return nil end
    local x, y, z = xyz(hpos)
    if not x then return nil end
    return x, y, z, hinst
end
local function is_head(model, part_name, x, y, z)
    if part_name == "Head" then return true end
    local head = find(model, "Head")
    local hx, hy, hz = xyz(head and get(head, "Position"))
    if not hx then return false end
    local dx, dy, dz = x - hx, y - hy, z - hz
    return dx * dx + dy * dy + dz * dz <= HEAD_RADIUS * HEAD_RADIUS
end
-- Camera, aim direction and gun position at the moment of the shot.
function M.capture()
    local cam = camera_pos()
    if not cam then return nil end
    local muzzle = nil
    pcall(function() muzzle = Infernal.require("game.combat_origin").get_muzzle_origin() end)
    local dir, owner, meta, origin = silent_hook.current_dir(150)
    if dir then
        return { cam = cam, dir = dir, redirected = true, owner = owner, meta = meta, muzzle = muzzle, origin = origin }
    end
    local look = camera_look()
    if not look then return nil end
    return { cam = cam, dir = look, redirected = false, muzzle = muzzle }
end
-- Where a captured shot went: end point, whether it ended on a character, which one, the part
-- and whether that was the head.
function M.resolve(shot, t)
    if not shot then return nil end
    local cam, dir = shot.cam, shot.dir
    local len = sqrt(dir.x * dir.x + dir.y * dir.y + dir.z * dir.z)
    if len < 1e-6 then return nil end
    local ux, uy, uz = dir.x / len, dir.y / len, dir.z / len
    local ex, ey, ez, model, part, hit
    local o = shot.origin
    local from_cam = 0
    if o and o.x then
        local ox, oy, oz = o.x - cam.x, o.y - cam.y, o.z - cam.z
        from_cam = sqrt(ox * ox + oy * oy + oz * oz)
    end
    if shot.redirected and from_cam > MAGIC_START_STUDS then
        -- magic bullet: the ray starts beside the target and lands on the first thing along it,
        -- the target the ragebot checked is in plain sight from you
        local meta = shot.meta or {}
        local tx, ty, tz = o.x + dir.x, o.y + dir.y, o.z + dir.z
        local hx, hy, hz = cast(o.x, o.y, o.z, tx, ty, tz)
        if hx then
            ex, ey, ez = hx, hy, hz
        elseif type(meta.aim) == "table" and meta.aim.x then
            ex, ey, ez = meta.aim.x, meta.aim.y, meta.aim.z
        else
            ex, ey, ez = tx, ty, tz
        end
        model, part, hit = meta.model, meta.part, true
    elseif shot.redirected then
        -- sent at a target the hook already checked is reachable; a wall in front still wins
        ex, ey, ez = cam.x + dir.x, cam.y + dir.y, cam.z + dir.z
        local meta = shot.meta or {}
        model, part, hit = meta.model, meta.part, true
        local hx, hy, hz, hinst = cast(cam.x, cam.y, cam.z, ex, ey, ez)
        if hx then
            local dx, dy, dz = hx - cam.x, hy - cam.y, hz - cam.z
            if sqrt(dx * dx + dy * dy + dz * dz) < len - 2 then
                ex, ey, ez = hx, hy, hz
                model = character_of(hinst)
                part = model and get(hinst, "Name") or nil
                hit = model ~= nil
            end
        end
    else
        ex, ey, ez = cam.x + ux * MAX_RANGE, cam.y + uy * MAX_RANGE, cam.z + uz * MAX_RANGE
        local hx, hy, hz, hinst = cast(cam.x, cam.y, cam.z, ex, ey, ez)
        if hx then
            ex, ey, ez = hx, hy, hz
            model = character_of(hinst)
            part = model and get(hinst, "Name") or nil
        end
        hit = model ~= nil
    end
    local head = false
    if hit then
        if model then head = is_head(model, part, ex, ey, ez) else head = part == "Head" end
    end
    return {
        t = t, cam = cam, muzzle = shot.muzzle, redirected = shot.redirected == true,
        ex = ex, ey = ey, ez = ez, hit = hit, model = model, part = part, head = head,
    }
end
function M.subscribe(id)
    if not queues[id] then queues[id] = {} end
end
function M.unsubscribe(id)
    queues[id] = nil
    if next(queues) == nil then
        seen, seeded, pending = {}, false, nil
    end
end
function M.take(id)
    local q = queues[id]
    if not q or #q == 0 then return {} end
    queues[id] = {}
    return q
end
local function publish(r)
    if not r then return end
    for _, q in pairs(queues) do q[#q + 1] = r end
end
-- Safe to call from every subscriber each frame: the second call in a frame finds nothing new.
function M.poll()
    if next(queues) == nil then return end
    local now = now_ms()
    local cam = camera_pos()
    if not cam or menu_open() then return end
    local fired = M.scan_vfx(cam)
    local lmb = key_down(LMB)
    if fired then
        if now - last_shot >= MERGE_MS then
            publish(M.resolve(M.capture(), now))
            last_shot = now
        end
        pending = nil
    elseif lmb and not lmb_was and weapons.cached_held_ranged() then
        -- remember where the click went in case no bullet effect turns up
        pending = { t = now, shot = M.capture() }
    end
    if pending and now - pending.t >= FALLBACK_MS then
        if last_shot < pending.t then
            publish(M.resolve(pending.shot, pending.t))
            last_shot = now
        end
        pending = nil
    end
    lmb_was = lmb
end
return M
end)()

Infernal._mods["features.visuals.bullet_tracers"] = (function()
-- Bullet tracers for your own shots (found by game.shots), drawn on the overlay so they always
-- show through walls.
local settings = Infernal.require("core.settings")
local shots = Infernal.require("game.shots")
local M = {}
local P = "infernal_btracer_enabled"
local SUB = "tracers"
M.STYLES = { "Neon", "Laser", "Smooth", "Lightning", "Dashed", "Pulse" }
M.IMPACTS = { "None", "Dot", "Ring", "Cross", "Box" }
local SAMPLES = 24
local tracers = {}
local sqrt, floor = math.sqrt, math.floor
local function now_ms()
    local fn = utility and (utility.get_tick_count or utility.GetTickCount)
    if type(fn) ~= "function" then return 0 end
    local ok, v = pcall(fn)
    return ok and tonumber(v) or 0
end
function M.add(r)
    if not r then return nil end
    if settings.bool("infernal_btracer_hits_only", false) and not r.hit then return nil end
    local origin = r.cam
    if settings.num("infernal_btracer_origin", 0) == 0 and type(r.muzzle) == "table" and r.muzzle.x then
        origin = r.muzzle
    end
    local tr = {
        t = r.t, hit = r.hit, seed = math.random() * 1000,
        sx = origin.x, sy = origin.y, sz = origin.z, ex = r.ex, ey = r.ey, ez = r.ez,
    }
    tracers[#tracers + 1] = tr
    local max = math.max(1, floor(settings.num("infernal_btracer_max", 30)))
    while #tracers > max do table.remove(tracers, 1) end
    return tr
end
function M.list()
    return tracers
end
function M.clear()
    tracers = {}
end
-- ---------------------------------------------------------------- drawing
local function w2s_fn()
    -- the same true-camera projection as ESP
    return function(x, y, z) return Infernal.require("core.esp_util").w2s(x, y, z) end
end
local function line(x1, y1, x2, y2, col, th)
    local fn = draw and (draw.line or draw.Line)
    if fn then pcall(fn, x1, y1, x2, y2, col, th) end
end
local function with_alpha(c, a)
    return { c[1], c[2], c[3], (c[4] or 1) * a }
end
local function mix_white(c, t)
    return { c[1] + (1 - c[1]) * t, c[2] + (1 - c[2]) * t, c[3] + (1 - c[3]) * t, c[4] or 1 }
end
local function hue(h)
    h = h % 1
    local i = floor(h * 6)
    local f = h * 6 - i
    local q, t = 1 - f, f
    local r, g, b
    if i == 0 then r, g, b = 1, t, 0 elseif i == 1 then r, g, b = q, 1, 0
    elseif i == 2 then r, g, b = 0, 1, t elseif i == 3 then r, g, b = 0, q, 1
    elseif i == 4 then r, g, b = t, 0, 1 else r, g, b = 1, 0, q end
    return { r, g, b, 1 }
end
local function rand01(seed, i, bucket)
    local v = math.sin(seed * 12.9898 + i * 78.233 + bucket * 37.719) * 43758.5453
    return v - floor(v)
end
-- The 3D line is sampled and projected; parts behind the camera are dropped, so each run is
-- a piece that is on screen. A line with both ends in front of the camera stays straight on
-- screen, so plain styles draw it as one segment.
local function project_runs(tr, w2s, plain)
    if plain then
        local ok1, ax, ay, on1 = pcall(w2s, tr.sx, tr.sy, tr.sz)
        local ok2, bx, by, on2 = pcall(w2s, tr.ex, tr.ey, tr.ez)
        if ok1 and ok2 and on1 and on2 and ax and bx then
            return { { { ax, ay, 0, 0 }, { bx, by, 1, SAMPLES } } }
        end
    end
    local runs, cur = {}, nil
    for i = 0, SAMPLES do
        local u = i / SAMPLES
        local x = tr.sx + (tr.ex - tr.sx) * u
        local y = tr.sy + (tr.ey - tr.sy) * u
        local z = tr.sz + (tr.ez - tr.sz) * u
        local ok, px, py, on = pcall(w2s, x, y, z)
        if ok and on and px then
            if not cur then
                cur = {}
                runs[#runs + 1] = cur
            end
            cur[#cur + 1] = { px, py, u, i }
        else
            cur = nil
        end
    end
    return runs
end
local function glow_layers(p, q, col, th, glow, a)
    for g = glow, 1, -1 do
        line(p[1], p[2], q[1], q[2], with_alpha(col, a * 0.10 * (1 - (g - 1) / (glow + 1))), th + g * 2)
    end
end
local STYLE_DRAW = {}
STYLE_DRAW[1] = function(p, q, col, th, glow, a)
    glow_layers(p, q, col, th, glow, a)
    line(p[1], p[2], q[1], q[2], with_alpha(col, a), th)
    line(p[1], p[2], q[1], q[2], with_alpha(mix_white(col, 0.6), a), math.max(1, th * 0.45))
end
STYLE_DRAW[2] = function(p, q, col, th, _glow, a)
    line(p[1], p[2], q[1], q[2], with_alpha(col, a * 0.18), th + 3)
    line(p[1], p[2], q[1], q[2], with_alpha(col, a * 0.35), th + 1.5)
    line(p[1], p[2], q[1], q[2], with_alpha(mix_white(col, 0.75), a), math.max(1, th * 0.6))
end
STYLE_DRAW[3] = function(p, q, col, th, _glow, a)
    line(p[1], p[2], q[1], q[2], with_alpha(col, a), th)
end
local function draw_run(run, style, col, th, glow, a, tr, now)
    if style == 3 then
        -- Lightning: each point is pushed sideways a little; the zigzag is fixed for each tracer
        local bucket = 0
        local pts = {}
        for i, p in ipairs(run) do
            local prev, nxt = run[i - 1] or p, run[i + 1] or p
            local dx, dy = nxt[1] - prev[1], nxt[2] - prev[2]
            local l = sqrt(dx * dx + dy * dy)
            local off = 0
            if i > 1 and i < #run and l > 0 then off = (rand01(tr.seed, p[4], bucket) - 0.5) * 2 * (3 + th * 1.5) end
            pts[i] = l > 0 and { p[1] - dy / l * off, p[2] + dx / l * off } or { p[1], p[2] }
        end
        for i = 2, #pts do STYLE_DRAW[1](pts[i - 1], pts[i], col, th, math.floor(glow * 0.6), a) end
        return
    end
    if style == 4 then
        -- Dashed: every other sample segment
        for i = 2, #run do
            if run[i][4] % 2 == 0 then STYLE_DRAW[3](run[i - 1], run[i], col, th, glow, a) end
        end
        return
    end
    if style == 5 then
        -- Pulse: a dim beam with a bright pulse running from the gun to the impact
        local head = ((now - tr.t) / 700) % 1
        for i = 2, #run do
            local u = (run[i - 1][3] + run[i][3]) * 0.5
            STYLE_DRAW[3](run[i - 1], run[i], col, th, glow, a * 0.35)
            local d = math.abs(u - head)
            if d < 0.1 then STYLE_DRAW[1](run[i - 1], run[i], col, th * 1.6, glow, a * (1 - d / 0.1)) end
        end
        return
    end
    local fn = STYLE_DRAW[style + 1] or STYLE_DRAW[1]
    for i = 2, #run do fn(run[i - 1], run[i], col, th, glow, a) end
end
local function draw_impact(tr, w2s, kind, size, col)
    if kind == 0 then return end
    local ok, x, y, on = pcall(w2s, tr.ex, tr.ey, tr.ez)
    if not ok or not on or not x then return end
    if kind == 1 then
        local fn = draw and (draw.circle_filled or draw.CircleFilled)
        if fn then pcall(fn, x, y, size, col) end
    elseif kind == 2 then
        local fn = draw and (draw.circle or draw.Circle)
        if fn then pcall(fn, x, y, size, col, 20, 1.5) end
    elseif kind == 3 then
        line(x - size, y - size, x + size, y + size, col, 1.5)
        line(x - size, y + size, x + size, y - size, col, 1.5)
    else
        local fn = draw and (draw.rect or draw.Rect)
        if fn then pcall(fn, x - size, y - size, size * 2, size * 2, col, 0, 1.5) end
    end
end
function M.render(now)
    local w2s = w2s_fn()
    if type(w2s) ~= "function" then return end
    local life = math.max(0.05, settings.num("infernal_btracer_time", 2.5)) * 1000
    local fade = settings.bool("infernal_btracer_fade", true)
    local hits_only = settings.bool("infernal_btracer_hits_only", false)
    local style = settings.num("infernal_btracer_style", 0)
    local th = math.max(1, settings.num("infernal_btracer_thickness", 2))
    local glow = math.max(0, floor(settings.num("infernal_btracer_glow", 4)))
    local impact = settings.num("infernal_btracer_impact", 1)
    local impact_size = settings.num("infernal_btracer_impact_size", 5)
    local rainbow = settings.bool("infernal_btracer_rainbow", false)
    local base = settings.color(P, { 0.35, 0.75, 1, 1 })
    local hit_col = settings.color("infernal_btracer_hit_color", { 1, 0.3, 0.35, 1 })
    local keep = {}
    for i, tr in ipairs(tracers) do
        local age = now - tr.t
        if age < life then
            keep[#keep + 1] = tr
            if not hits_only or tr.hit then
                local a = fade and (1 - age / life) or 1
                local col = tr.hit and hit_col or base
                if rainbow then col = hue(now / 2000 + i * 0.07) end
                for _, run in ipairs(project_runs(tr, w2s, style <= 2)) do
                    draw_run(run, style, col, th, glow, a, tr, now)
                end
                draw_impact(tr, w2s, impact, impact_size, with_alpha(col, a))
            end
        end
    end
    tracers = keep
end
function M.update(_dt) end
function M.draw()
    if not settings.bool(P, false) then
        tracers = {}
        shots.unsubscribe(SUB)
        return
    end
    shots.subscribe(SUB)
    shots.poll()
    for _, r in ipairs(shots.take(SUB)) do M.add(r) end
    M.render(now_ms())
end
return M
end)()

Infernal._mods["features.visuals.arm_chams"] = (function()
-- Arm Chams: hides your first-person arms by writing Transparency 1 into each arm part
-- (BasePart.Transparency, offset from the live offsets list) and puts the old values back when
-- it is turned off. Every first-person model Fallen keeps is checked (gun, tool or empty
-- hands), so the arms stay hidden whatever you hold. Vector's engine chams do not draw on these
-- parts, so invisible is the only look.
local settings = Infernal.require("core.settings")
local env = Infernal.require("core.env")
local gpu_chams = Infernal.require("core.gpu_chams")
local weapons = Infernal.require("game.weapons")
local M = {}
local P = "infernal_arm_chams"
local DEFAULT_TRANSPARENCY_OFFSET = 280
local HIDE_EVERY_MS = 100
local hidden = {}
local last_hide = -1e9
local function now_ms()
    local fn = utility and (utility.get_tick_count or utility.GetTickCount)
    if type(fn) ~= "function" then return 0 end
    local ok, v = pcall(fn)
    return ok and tonumber(v) or 0
end
local function find(inst, name)
    if not inst then return nil end
    local ok, c = pcall(function() return inst:FindFirstChild(name) end)
    return ok and c or nil
end
local function parent_of(inst)
    if not inst then return nil end
    local ok, p = pcall(function() return inst.Parent end)
    return ok and p or nil
end
local function kids(inst)
    if not inst then return {} end
    local ok, t = pcall(function() return inst:GetChildren() end)
    return ok and type(t) == "table" and t or {}
end
local function addr_of(inst)
    local ok, a = pcall(function() return tonumber(inst.Address) end)
    return ok and a or nil
end
local function name_of(inst)
    local ok, n = pcall(function() return inst.Name end)
    return ok and n or nil
end
local function mem(a, b)
    local fn = memory and (memory[a] or memory[b])
    return type(fn) == "function" and fn or nil
end
local function t_offset()
    local ok, off = pcall(function() return Infernal.require("core.rbx_offsets").base_part("Transparency") end)
    off = ok and tonumber(off) or nil
    if not off or off <= 0 or off > 0x2000 then off = DEFAULT_TRANSPARENCY_OFFSET end
    return off
end
-- Reads first: anything that is not a plausible transparency (0 to 1) means the offset does not
-- match this Roblox build, and that memory is left alone.
local function read_t(a, off)
    local read = mem("Read", "read")
    if not read or not a or a <= 0x10000 then return nil end
    local ok, v = pcall(read, a + off, "float")
    v = ok and tonumber(v) or nil
    if v and v >= 0 and v <= 1 then return v end
    return nil
end
local function write_t(a, off, v)
    local write = mem("Write", "write")
    if not write then return false end
    local ok, r = pcall(write, a + off, "float", v)
    return ok and r ~= false
end
local function add_root(out, seen, inst)
    if not inst then return end
    local key = addr_of(inst) or inst
    if seen[key] then return end
    seen[key] = true
    out[#out + 1] = inst
end
-- Every Arms model where Fallen keeps first-person models: next to or inside the held gun, and
-- in the camera, Workspace.VFX.VMs and Workspace.Viewmodels (tools and empty hands live there).
function M.arm_roots()
    local out, seen = {}, {}
    local ok, _, vm_weapon = pcall(weapons.viewmodel_weapon)
    vm_weapon = ok and vm_weapon or nil
    add_root(out, seen, find(vm_weapon, "Arms"))
    add_root(out, seen, find(parent_of(vm_weapon), "Arms"))
    local ws = env.get_workspace()
    if not ws then return out end
    local cam = find(ws, "Camera") or env.safe_call(function() return ws.CurrentCamera end)
    local vfx = find(ws, "VFX")
    for _, holder in ipairs({ cam, vfx and find(vfx, "VMs"), find(ws, "Viewmodels") }) do
        for _, c in ipairs(kids(holder)) do
            if name_of(c) == "Arms" then
                add_root(out, seen, c)
            else
                add_root(out, seen, find(c, "Arms"))
            end
        end
    end
    return out
end
function M.arm_parts()
    local list = {}
    for _, root in ipairs(M.arm_roots()) do
        gpu_chams.for_each_part(root, function(p) list[#list + 1] = p end)
    end
    return list
end
local function alive(entry, a)
    local ok, same = pcall(function()
        return entry.part.Parent ~= nil and tonumber(entry.part.Address) == a
    end)
    return ok and same == true
end
function M.hide_arms()
    local off = t_offset()
    for a, e in pairs(hidden) do
        if not alive(e, a) then hidden[a] = nil end
    end
    local n = 0
    for _, p in ipairs(M.arm_parts()) do
        local a = addr_of(p)
        local cur = read_t(a, off)
        if cur then
            if not hidden[a] then hidden[a] = { part = p, orig = cur } end
            if cur < 0.999 then write_t(a, off, 1) end
            n = n + 1
        end
    end
    return n
end
function M.show_arms()
    local off = t_offset()
    for a, e in pairs(hidden) do
        if alive(e, a) and read_t(a, off) then write_t(a, off, e.orig) end
        hidden[a] = nil
    end
end
function M.hidden_count()
    local n = 0
    for _ in pairs(hidden) do n = n + 1 end
    return n
end
function M.update(_dt)
    if settings.bool(P, false) then
        local now = now_ms()
        if now - last_hide >= HIDE_EVERY_MS then
            last_hide = now
            M.hide_arms()
        end
    elseif next(hidden) ~= nil then
        M.show_arms()
        last_hide = -1e9
    end
end
return M
end)()

Infernal._mods["features.visuals.esp_chams"] = (function()
-- Chams for the Player ESP and the NPC ESP.
--   Engine (like ahook): Vector's chams on the real body parts, with Fill / Wireframe / Fill Glow
--     / Wireframe Glow and the glow presets.
--   Overlay: Vector's player chams renderer (Filled / Outline / Glow) in any color and opacity;
--     NPCs without a Vector entity get the same look from their parts' outlines.
-- Both follow the ESP they belong to: its on/off switch, its range, the NPC types that are ticked
-- and, for players, Skip Teammates (the same team check as the ESP). NPC hitbox parts the game
-- keeps invisible are skipped, since chams can only show on parts that are drawn.
local settings = Infernal.require("core.settings")
local env = Infernal.require("core.env")
local cache = Infernal.require("core.cache")
local gpu_chams = Infernal.require("core.gpu_chams")
local esp_scan = Infernal.require("game.esp_scan")
local M = {}
local NPC_PART_CAP = 80
local DEFAULT_T_OFFSET = 280
local SPECS = {
    player = { esp = "infernal_player_enabled", id = "infernal_player_chams", range = "infernal_player_range",
        owner = "player_chams", default_preset = 1, default_color = { 1, 0.25, 0.25, 0.5 } },
    npc = { esp = "infernal_npc_enabled", id = "infernal_npc_chams", range = "infernal_npc_range",
        owner = "npc_chams", default_preset = 3, default_color = { 1, 0.75, 0.2, 0.5 } },
}
local NPC_TYPE_IDS = {
    soldier = "infernal_npc_soldier", bruno = "infernal_npc_bruno", boris = "infernal_npc_boris",
    brutus = "infernal_npc_brutus", heli = "infernal_npc_attack_heli", btr = "infernal_npc_btr",
    diver_dave = "infernal_npc_diver_dave", pilot_pete = "infernal_npc_pilot_pete",
    sleeper = "infernal_npc_sleeper", zombie = "infernal_npc_zombie",
}
local function xyz(v)
    if v == nil then return nil end
    local ok, x, y, z = pcall(function() return v.X or v.x, v.Y or v.y, v.Z or v.z end)
    if ok and type(x) == "number" then return x, y, z end
    return nil
end
local function get(obj, a, b)
    local ok, v = pcall(function() return obj[a] end)
    if ok and v ~= nil then return v end
    if b then
        ok, v = pcall(function() return obj[b] end)
        if ok then return v end
    end
    return nil
end
local function on(spec)
    return settings.enabled(spec.esp) and settings.bool(spec.id, false)
end
function M.chams_type(spec)
    return settings.num(spec.id .. "_type", 0)
end
local function my_pos()
    local me = cache.local_player or env.get_local_player()
    return xyz(me and get(me, "Position", "position"))
end
local function in_range(spec, x, y, z, mx, my, mz)
    if not mx or not x then return true end
    local r = settings.num(spec.range, 500)
    local dx, dy, dz = x - mx, y - my, z - mz
    return dx * dx + dy * dy + dz * dz <= r * r
end
-- ESP players in range, minus teammates when Skip Teammates is on.
function M.players()
    local spec = SPECS.player
    local out = {}
    local skip_team = settings.bool(spec.id .. "_team", true)
    local ok_ps, player_state = pcall(Infernal.require, "game.player_state")
    local mx, my, mz = my_pos()
    for _, p in ipairs(cache.players or {}) do
        if get(p, "IsLocal", "is_local") ~= true and get(p, "IsAlive", "is_alive") ~= false then
            local x, y, z = xyz(get(p, "Position", "position"))
            if in_range(spec, x, y, z, mx, my, mz) then
                local mate = skip_team and ok_ps and player_state and not player_state.passes_team_check(p)
                if not mate then out[#out + 1] = p end
            end
        end
    end
    return out
end
-- NPC ESP entries of ticked types in range (not the pooled ones parked far below the map).
function M.npcs()
    local spec = SPECS.npc
    local out = {}
    local mx, my, mz = my_pos()
    for _, e in ipairs(cache.npcs or {}) do
        local tid = e and NPC_TYPE_IDS[e.kind]
        if tid and settings.bool(tid, false) and e.inst then
            local x, y, z = e.lx, e.ly, e.lz
            if not x and e.root then x, y, z = xyz(get(e.root, "Position", "position")) end
            if x and y > -1000 and in_range(spec, x, y, z, mx, my, mz) then out[#out + 1] = e end
        end
    end
    return out
end
local function transparency(p)
    local read = memory and (memory.Read or memory.read)
    local a = tonumber(get(p, "Address"))
    if type(read) ~= "function" or not a or a <= 0x10000 then return nil end
    local off = nil
    pcall(function() off = tonumber(Infernal.require("core.rbx_offsets").base_part("Transparency")) end)
    if not off or off <= 0 or off > 0x2000 then off = DEFAULT_T_OFFSET end
    local ok, v = pcall(read, a + off, "float")
    v = ok and tonumber(v) or nil
    if v and v >= 0 and v <= 1 then return v end
    return nil
end
-- An NPC's drawn parts (invisible hitbox parts left out), capped for big vehicles.
function M.npc_parts(e)
    local out = {}
    gpu_chams.for_each_part(e.inst, function(p)
        if #out >= NPC_PART_CAP then return end
        local t = transparency(p)
        if t and t >= 0.99 then return end
        out[#out + 1] = p
    end)
    return out
end
-- ---------------------------------------------------------------- engine chams
local function engine_style(spec)
    return gpu_chams.mode_index(spec.id .. "_mode", 2), gpu_chams.color_index(spec.id .. "_preset", spec.default_preset)
end
local function engine_active(spec)
    return on(spec) and M.chams_type(spec) == 0 and gpu_chams.available()
end
gpu_chams.register_owner(SPECS.player.owner, {
    rescan_ms = 500,
    is_active = function() return engine_active(SPECS.player) end,
    style = function() return engine_style(SPECS.player) end,
    collect = function(into)
        for _, p in ipairs(M.players()) do
            local char = get(p, "Character", "character")
            if char then gpu_chams.cham_player_character(char, into) end
        end
    end,
})
gpu_chams.register_owner(SPECS.npc.owner, {
    rescan_ms = 500,
    is_active = function() return engine_active(SPECS.npc) end,
    style = function() return engine_style(SPECS.npc) end,
    collect = function(into)
        for _, e in ipairs(M.npcs()) do
            for _, p in ipairs(M.npc_parts(e)) do gpu_chams.cham_part(p, into) end
        end
    end,
})
local last_style = {}
function M.update(_dt)
    if not gpu_chams.available() then return end
    for key, spec in pairs(SPECS) do
        if engine_active(spec) then
            local mode, color = engine_style(spec)
            local prev = last_style[key]
            if prev and (prev[1] ~= mode or prev[2] ~= color) then gpu_chams.refresh_owner_style(spec.owner) end
            last_style[key] = { mode, color }
        else
            last_style[key] = nil
        end
        gpu_chams.sync_owner(spec.owner)
    end
end
-- ---------------------------------------------------------------- overlay chams
local function w2s_fn()
    -- the same true-camera projection as ESP
    return function(x, y, z) return Infernal.require("core.esp_util").w2s(x, y, z) end
end
local function part_hull(p, w2s)
    local b = esp_scan.read_part_box(p)
    if not b then return nil end
    local pts = {}
    for sx = -1, 1, 2 do
        for sy = -1, 1, 2 do
            for sz = -1, 1, 2 do
                local x = b.x + b.rx * b.hx * sx + b.ux * b.hy * sy + b.lx * b.hz * sz
                local y = b.y + b.ry * b.hx * sx + b.uy * b.hy * sy + b.ly * b.hz * sz
                local z = b.z + b.rz * b.hx * sx + b.uz * b.hy * sy + b.lz * b.hz * sz
                local ok, px, py, vis = pcall(w2s, x, y, z)
                if ok and vis and type(px) == "number" then pts[#pts + 1] = { px, py } end
            end
        end
    end
    if #pts < 3 then return nil end
    local ch = draw and (draw.ComputeHull or draw.compute_hull)
    if type(ch) ~= "function" then return nil end
    local ok, h = pcall(ch, pts)
    if ok and type(h) == "table" and #h >= 3 then return h end
    return nil
end
local function overlay_color(spec)
    return settings.color(spec.id .. "_color", spec.default_color)
end
function M.draw()
    local chams_player = draw and (draw.ChamsPlayer or draw.chams_player)
    local spec = SPECS.player
    if on(spec) and M.chams_type(spec) == 1 and type(chams_player) == "function" then
        local col, style = overlay_color(spec), settings.num(spec.id .. "_style", 0)
        for _, p in ipairs(M.players()) do pcall(chams_player, p, col, style) end
    end
    spec = SPECS.npc
    if on(spec) and M.chams_type(spec) == 1 then
        local col, style = overlay_color(spec), settings.num(spec.id .. "_style", 0)
        local chams = draw and (draw.Chams or draw.chams)
        local w2s = w2s_fn()
        for _, e in ipairs(M.npcs()) do
            if e.entity and type(chams_player) == "function" then
                pcall(chams_player, e.entity, col, style)
            elseif type(chams) == "function" and type(w2s) == "function" then
                local hulls = {}
                for _, p in ipairs(M.npc_parts(e)) do
                    local h = part_hull(p, w2s)
                    if h then hulls[#hulls + 1] = h end
                end
                if #hulls > 0 then pcall(chams, hulls, col, style) end
            end
        end
    end
end
return M
end)()

Infernal._mods["core.audio"] = (function()
-- Hitsound playback with nothing outside Vector: Windows' own PlaySound (winmm.dll) and the folder
-- listing (FindFirstFile) are called through Lua's FFI, inside Vector. No PowerShell or any other
-- program is ever started and no file is ever created: each user puts their own .wav files in
-- Infernal_configs\hitsounds\headshot and Infernal_configs\hitsounds\hit. Without FFI in Vector
-- there is no way to play a sound, so Hitsounds stays silent (the menu says so).
local config_store = Infernal.require("core.config_store")
local M = {}
M.KINDS = { headshot = "headshot", hit = "hit" }
local SND_ASYNC, SND_NODEFAULT, SND_FILENAME = 0x0001, 0x0002, 0x00020000
local api = nil
local lists = {}
-- Plain global lookups only: Vector's Lua has no rawget, and calling it emptied the MISC tab.
local function get_ffi()
    local ok, f = pcall(function() return ffi end)
    if ok and type(f) == "table" and type(f.cdef) == "function" then return f end
    local ok_r, req = pcall(function() return require end)
    if ok_r and type(req) == "function" then
        local ok_m, m = pcall(req, "ffi")
        if ok_m and type(m) == "table" and type(m.cdef) == "function" then return m end
    end
    return nil
end
local function load_api()
    if api ~= nil then return api or nil end
    api = false
    local ok_f, ffi = pcall(get_ffi)
    if not ok_f or not ffi then return nil end
    -- a second load of the script finds these already declared; that error is harmless
    pcall(ffi.cdef, [[
        typedef struct { unsigned int dwFileAttributes; unsigned int ftCreationTime[2];
            unsigned int ftLastAccessTime[2]; unsigned int ftLastWriteTime[2];
            unsigned int nFileSizeHigh; unsigned int nFileSizeLow; unsigned int dwReserved0;
            unsigned int dwReserved1; char cFileName[260]; char cAlternateFileName[14]; } infernal_find_data;
        int PlaySoundA(const char *pszSound, void *hmod, unsigned int fdwSound);
        void *FindFirstFileA(const char *lpFileName, infernal_find_data *lpFindFileData);
        int FindNextFileA(void *hFindFile, infernal_find_data *lpFindFileData);
        int FindClose(void *hFindFile);
    ]])
    local ok, winmm = pcall(ffi.load, "winmm")
    if not ok or not winmm then return nil end
    api = { ffi = ffi, winmm = winmm, k32 = ffi.C }
    return api
end
function M.available()
    return load_api() ~= nil
end
function M.folder(kind)
    local base = nil
    pcall(function() base = config_store.configs_dir() end)
    if not base or base == "" then return nil end
    return base .. "\\hitsounds\\" .. (M.KINDS[kind] or "hit")
end
-- The .wav files in a kind's folder (names without ".wav"), sorted; read once, M.refresh() re-reads.
function M.list(kind)
    if lists[kind] then return lists[kind] end
    local out = {}
    local a, dir = load_api(), M.folder(kind)
    if a and dir then
        pcall(function()
            local data = a.ffi.new("infernal_find_data")
            local h = a.k32.FindFirstFileA(dir .. "\\*.wav", data)
            if h ~= nil and a.ffi.cast("intptr_t", h) ~= -1 then
                repeat
                    local name = a.ffi.string(data.cFileName)
                    if name:lower():sub(-4) == ".wav" then out[#out + 1] = name:sub(1, -5) end
                until a.k32.FindNextFileA(h, data) == 0
                a.k32.FindClose(h)
            end
        end)
    end
    table.sort(out, function(x, y) return x:lower() < y:lower() end)
    lists[kind] = out
    return out
end
function M.refresh()
    lists = {}
end
function M.labels(kind)
    local l = M.list(kind)
    if #l == 0 then return { "(no .wav files)" } end
    return l
end
function M.default_index(kind, preferred)
    for i, n in ipairs(M.list(kind)) do
        if n:lower() == preferred:lower() then return i - 1 end
    end
    return 0
end
function M.path(kind, name)
    local dir = M.folder(kind)
    if not dir or not name then return nil end
    return dir .. "\\" .. name .. ".wav"
end
function M.play(path)
    local a = load_api()
    if not a or not path then return false end
    local ok, r = pcall(a.winmm.PlaySoundA, path, nil, SND_ASYNC + SND_NODEFAULT + SND_FILENAME)
    return ok and r ~= 0
end
return M
end)()

Infernal._mods["features.visuals.hitsounds"] = (function()
-- Hitsounds: one of your own .wav files when a shot hits, one folder for headshots and one for
-- everything else (core.audio plays them inside Vector).
-- Shots come from game.shots. With Only When Damage Lands on (the default) a hit on a player only
-- plays once that player's health actually drops, so misses and blocked shots stay silent; NPC
-- rigs have no health to watch, so their hits play right away.
local settings = Infernal.require("core.settings")
local menu_util = Infernal.require("core.menu_util")
local audio = Infernal.require("core.audio")
local shots = Infernal.require("game.shots")
local M = {}
local P = "infernal_hitsound_enabled"
local SUB = "hitsounds"
local CONFIRM_MS = 700
local pending = {}
local function now_ms()
    local fn = utility and (utility.get_tick_count or utility.GetTickCount)
    if type(fn) ~= "function" then return 0 end
    local ok, v = pcall(fn)
    return ok and tonumber(v) or 0
end
local function find(inst, name)
    if not inst then return nil end
    local ok, c = pcall(function() return inst:FindFirstChild(name) end)
    return ok and c or nil
end
local function health_of(hum)
    local ok, v = pcall(function() return hum.Health end)
    return ok and tonumber(v) or nil
end
-- The chosen file for a headshot or a normal hit, or nil when that folder has no .wav files.
function M.sound_path(head)
    local kind = head and "headshot" or "hit"
    local list = audio.list(kind)
    if #list == 0 then return nil end
    local id = head and "infernal_hitsound_head" or "infernal_hitsound_body"
    local idx = settings.combo_index(id, list, audio.default_index(kind, head and "Rust Headshot" or "Rust Hit"))
    return audio.path(kind, list[idx + 1] or list[1])
end
function M.play(head)
    return audio.play(M.sound_path(head))
end
function M.on_shot(r, now)
    if not r or not r.hit then return end
    local hum = r.model and find(r.model, "Humanoid")
    if hum and settings.bool("infernal_hitsound_confirm", true) then
        local hp = health_of(hum)
        if hp then
            pending[#pending + 1] = { t = now, hum = hum, hp = hp, head = r.head }
            return
        end
    end
    if not hum and not settings.bool("infernal_hitsound_npcs", true) then return end
    M.play(r.head)
end
-- One drop in health answers one waiting shot; other shots on the same player then compare
-- against the new health, so one hit never plays twice.
function M.check_pending(now)
    local keep = {}
    for _, p in ipairs(pending) do
        if now - p.t <= CONFIRM_MS then
            local hp = health_of(p.hum)
            if hp and hp < p.hp - 0.01 then
                M.play(p.head)
                for _, q in ipairs(pending) do
                    if q ~= p and q.hum == p.hum and q.hp > hp then q.hp = hp end
                end
            else
                keep[#keep + 1] = p
            end
        end
    end
    pending = keep
end
function M.pending_count()
    return #pending
end
function M.register_menu()
    local G = menu_util.G
    local T = menu_util.group(G.MISC)
    menu.add_button(T, G.MISC, "infernal_hitsound_test_head", "Test Headshot Sound", function() M.play(true) end)
    menu.add_button(T, G.MISC, "infernal_hitsound_test_body", "Test Hit Sound", function() M.play(false) end)
    menu.add_button(T, G.MISC, "infernal_hitsound_refresh", "Refresh Sound List", function()
        audio.refresh()
        local ok, catalog = pcall(Infernal.require, "ui.catalog")
        if ok and catalog and catalog.invalidate then catalog.invalidate() end
    end)
end
function M.update(_dt) end
function M.draw()
    if not settings.bool(P, false) then
        pending = {}
        shots.unsubscribe(SUB)
        return
    end
    shots.subscribe(SUB)
    shots.poll()
    local now = now_ms()
    for _, r in ipairs(shots.take(SUB)) do M.on_shot(r, now) end
    M.check_pending(now)
end
return M
end)()

Infernal._mods["features.visuals.crosshair"] = (function()
-- Custom crosshair. Styles: Cross, Circle, Dot, T-Shape, Diamond, Plus, Brackets, X.
local settings = Infernal.require("core.settings")
local draw_util = Infernal.require("core.draw_util")
local M = {}
local P = "infernal_crosshair_enabled"
local FOLLOW_TTL_MS = 150
local cur_x, cur_y = nil, nil
local function now_ms()
    local fn = utility and (utility.get_tick_count or utility.GetTickCount)
    if type(fn) ~= "function" then return 0 end
    local ok, v = pcall(fn)
    return ok and tonumber(v) or 0
end
local function delta()
    local fn = utility and (utility.get_delta_time or utility.GetDeltaTime)
    if type(fn) == "function" then
        local ok, v = pcall(fn)
        if ok and tonumber(v) and v > 0 then return math.min(v, 0.1) end
    end
    return 0.016
end
local function hue(h)
    h = (h % 1) * 6
    local i = math.floor(h)
    local f = h - i
    local q, t = 1 - f, f
    if i == 0 then return 1, t, 0 elseif i == 1 then return q, 1, 0
    elseif i == 2 then return 0, 1, t elseif i == 3 then return 0, q, 1
    elseif i == 4 then return t, 0, 1 end
    return 1, 0, q
end
-- Screen point of the current aim target for Follow Target (0 Auto, 1 Silent Aim, 2 Aimbot).
local function follow_point(source)
    local now = now_ms()
    local function fresh(mod_name)
        local ok, mod = pcall(Infernal.require, mod_name)
        local t = ok and mod and mod._screen_target
        if t and now - (t.t or 0) <= FOLLOW_TTL_MS then return t.x, t.y end
        return nil
    end
    if source == 1 then return fresh("features.combat.silent_aim") end
    if source == 2 then return fresh("features.combat.aimbot") end
    local x, y = fresh("features.combat.silent_aim")
    if x then return x, y end
    return fresh("features.combat.aimbot")
end
local function rot(ox, oy, c, s)
    return ox * c - oy * s, ox * s + oy * c
end
function M.draw()
    if not settings.bool(P, false) then
        cur_x, cur_y = nil, nil
        return
    end
    local sw, sh = draw_util.screen_size()
    local gx, gy = sw * 0.5, sh * 0.5
    if settings.bool("infernal_crosshair_follow", false) then
        local tx, ty = follow_point(settings.num("infernal_crosshair_source", 0))
        if tx then gx, gy = tx, ty end
    end
    if not cur_x then cur_x, cur_y = gx, gy end
    local rate = math.max(1, settings.num("infernal_crosshair_follow_smooth", 18))
    local a = 1 - math.exp(-rate * delta())
    cur_x = cur_x + (gx - cur_x) * a
    cur_y = cur_y + (gy - cur_y) * a
    local cx, cy = math.floor(cur_x + 0.5), math.floor(cur_y + 0.5)
    local t = now_ms() / 1000
    local size = settings.num("infernal_crosshair_size", 10)
    local gap = settings.num("infernal_crosshair_gap", 5)
    local th = math.max(1, settings.num("infernal_crosshair_thickness", 2))
    if settings.bool("infernal_crosshair_pulse", false) then
        local sp = settings.num("infernal_crosshair_pulse_speed", 40) / 10
        size = size * (1 + 0.25 * math.sin(t * sp))
    end
    local ang = 0
    if settings.bool("infernal_crosshair_spin", false) then
        ang = t * settings.num("infernal_crosshair_spin_speed", 35) / 10
    end
    local col = settings.color("infernal_crosshair_color", { 0, 1, 0, 1 })
    if settings.bool("infernal_crosshair_rainbow", false) then
        local r, g, b = hue(t * settings.num("infernal_crosshair_rainbow_speed", 10) / 20)
        col = { r, g, b, col[4] or 1 }
    end
    local outline = settings.bool("infernal_crosshair_outline", true)
    local shadow = { 0, 0, 0, (col[4] or 1) * 0.85 }
    local c, s = math.cos(ang), math.sin(ang)
    local segs = {}
    local function seg(x1, y1, x2, y2)
        local ax, ay = rot(x1, y1, c, s)
        local bx, by = rot(x2, y2, c, s)
        segs[#segs + 1] = { cx + ax, cy + ay, cx + bx, cy + by }
    end
    local style = settings.num("infernal_crosshair_type", 0)
    local inner, outer = gap, gap + size
    if style == 0 or style == 3 then
        seg(inner, 0, outer, 0)
        seg(-inner, 0, -outer, 0)
        seg(0, inner, 0, outer)
        if style == 0 then seg(0, -inner, 0, -outer) end
    elseif style == 4 then
        local r = outer
        seg(0, -r, r, 0); seg(r, 0, 0, r); seg(0, r, -r, 0); seg(-r, 0, 0, -r)
    elseif style == 5 then
        seg(-outer, 0, outer, 0)
        seg(0, -outer, 0, outer)
    elseif style == 6 then
        local r, l = outer, math.max(2, size * 0.5)
        seg(-r, -r, -r + l, -r); seg(-r, -r, -r, -r + l)
        seg(r, -r, r - l, -r); seg(r, -r, r, -r + l)
        seg(-r, r, -r + l, r); seg(-r, r, -r, r - l)
        seg(r, r, r - l, r); seg(r, r, r, r - l)
    elseif style == 7 then
        local d = 0.7071
        seg(inner * d, inner * d, outer * d, outer * d)
        seg(-inner * d, -inner * d, -outer * d, -outer * d)
        seg(inner * d, -inner * d, outer * d, -outer * d)
        seg(-inner * d, inner * d, -outer * d, outer * d)
    end
    if outline then
        for i = 1, #segs do
            local q = segs[i]
            draw_util.line(q[1], q[2], q[3], q[4], shadow, th + 2)
        end
    end
    for i = 1, #segs do
        local q = segs[i]
        draw_util.line(q[1], q[2], q[3], q[4], col, th)
    end
    local circle = draw and (draw.circle or draw.Circle)
    local filled = draw and (draw.circle_filled or draw.CircleFilled)
    if style == 1 and circle then
        local r = math.max(2, outer)
        if outline then pcall(circle, cx, cy, r, shadow, 48, th + 2) end
        pcall(circle, cx, cy, r, col, 48, th)
    elseif style == 2 and filled then
        local r = math.max(1.5, size * 0.3)
        if outline then pcall(filled, cx, cy, r + 1, shadow, 20) end
        pcall(filled, cx, cy, r, col, 20)
    end
    if settings.bool("infernal_crosshair_dot", false) and filled and style ~= 2 then
        local r = math.max(1, th * 0.75)
        if outline then pcall(filled, cx, cy, r + 1, shadow, 16) end
        pcall(filled, cx, cy, r, settings.color("infernal_crosshair_dot", { 1, 1, 1, 1 }), 16)
    end
end
return M
end)()

Infernal._mods["features.world.world_esp"] = (function()
local settings = Infernal.require("core.settings")
local cache = Infernal.require("core.cache")
local draw_util = Infernal.require("core.draw_util")
local esp_util = Infernal.require("core.esp_util")
local env = Infernal.require("core.env")
local menu_util = Infernal.require("core.menu_util")
local maps = Infernal.require("game.esp_maps")
local esp_scan = Infernal.require("game.esp_scan")
local gpu_chams = Infernal.require("core.gpu_chams")
local M = {}
local P = "infernal_world_enabled"
local CHAMS_MASTER = "infernal_world_chams_enabled"
local CHAMS_ID = "infernal_world_chams"
local CHAMS_MODE = "infernal_world_chams_mode"
local CHAMS_COLOR = "infernal_world_chams_color"
local draw_candidates = {}
local chams_candidates = {}
local toggle_index = {}
local toggle_enabled = {}
local toggle_colors = {}
for i, t in ipairs(maps.WORLD_TOGGLES) do toggle_index[t.id] = i end
local function refresh_toggle_state(with_colors)
for i = 1, #maps.WORLD_TOGGLES do
local t = maps.WORLD_TOGGLES[i]
toggle_enabled[t.id] = settings.enabled(t.id)
if with_colors then toggle_colors[t.id] = settings.color(t.id, t.color) end
end
end
local function world_chams_labels()
local labels = {}
for i, t in ipairs(maps.WORLD_TOGGLES) do
labels[i] = t.label
end
return labels
end
local function world_chams_index_for(toggle_id)
return toggle_index[toggle_id]
end
local function world_chams_active()
if not gpu_chams.available() then return false end
if not settings.enabled(P) then return false end
if not settings.enabled(CHAMS_MASTER) then return false end
for i = 1, #maps.WORLD_TOGGLES do
if gpu_chams.multicombo_selected(CHAMS_ID, i) then
return true
end
end
return false
end
local function collect_world_chams(applied)
local me = env.get_local_player()
local me_pos = me and me.position
if not me_pos then return end
local range = settings.num("infernal_world_range", 500)
local range_sq = range * range
local entries = cache.world
refresh_toggle_state(false)
if me_pos then
entries = cache.query_spatial(
cache.spatial.world, me_pos.x, me_pos.z, range, chams_candidates
)
end
for _, entry in ipairs(entries) do
if not env.is_valid(entry.inst) then goto continue end
local idx = world_chams_index_for(entry.toggle_id)
if not idx or not gpu_chams.multicombo_selected(CHAMS_ID, idx) then goto continue end
if not toggle_enabled[entry.toggle_id] then goto continue end
local lx, ly, lz = esp_scan.entry_coords(entry)
if not lx then goto continue end
local dx = lx - me_pos.x
local dy = ly - me_pos.y
local dz = lz - me_pos.z
if (dx * dx + dy * dy + dz * dz) > range_sq then goto continue end
gpu_chams.cham_entry_part(entry, applied)
::continue::
end
end
M._static = {}
M._dynamic = {}
local function rebuild_cache()
cache.world = {}
for _, entry in ipairs(M._static) do
table.insert(cache.world, entry)
end
for _, entry in ipairs(M._dynamic) do
table.insert(cache.world, entry)
end
cache.spatial.world = cache.build_spatial(cache.world)
end
local function refresh_dynamic_positions(list)
if not list or #list == 0 then return end
for _, entry in ipairs(list) do
if entry and env.is_valid(entry.inst) then
esp_scan.refresh_entry_position(entry)
end
end
end
function M.register_menu()
local G = menu_util.G
local T, _ = menu_util.group(G.WORLD)
menu_util.section(T, G.WORLD, "Resources")
menu_util.register_keybind(T, G.WORLD, P, "Resource ESP", false)
for _, t in ipairs(maps.WORLD_TOGGLES) do
menu.add_checkbox(T, G.WORLD, t.id, t.label, false, { parent = P, colorpicker = t.color })
end
menu.add_checkbox(T, G.WORLD, "infernal_world_boxes", "Resource 3D Boxes", false, { parent = P })
menu.add_checkbox(T, G.WORLD, "infernal_world_show_name", "Resource Show Name", true, { parent = P })
menu.add_checkbox(T, G.WORLD, "infernal_world_show_distance", "Resource Show Distance", true, { parent = P })
menu_util.gap(T, G.WORLD)
menu.add_slider_int(T, G.WORLD, "infernal_world_range", "Resource Range", 50, 2000, 500, { parent = P })
local child_ids = { "infernal_world_boxes", "infernal_world_show_name", "infernal_world_show_distance", "infernal_world_range" }
local toggle_ids = {}
for _, t in ipairs(maps.WORLD_TOGGLES) do
child_ids[#child_ids + 1] = t.id
toggle_ids[#toggle_ids + 1] = t.id
end
local chams_ids = {}
if gpu_chams.available() then
menu_util.section(T, G.WORLD, "Resource Mesh Chams")
menu.add_checkbox(T, G.WORLD, CHAMS_MASTER, "Enable Mesh Chams", false, { parent = P })
child_ids[#child_ids + 1] = CHAMS_MASTER
chams_ids = gpu_chams.wire_esp_chams({
tab = T,
group = G.WORLD,
parent = CHAMS_MASTER,
chams_id = CHAMS_ID,
mode_id = CHAMS_MODE,
color_id = CHAMS_COLOR,
labels = world_chams_labels(),
owner_id = "world",
master_id = CHAMS_MASTER,
is_active = world_chams_active,
collect = collect_world_chams,
rescan_ms = 900,
toggle_ids = toggle_ids,
})
end
for _, id in ipairs(chams_ids) do
child_ids[#child_ids + 1] = id
end
menu_util.bind_children(P, child_ids)
end
function M.begin_static_scan()
return {
phase = 1,
node_state = esp_scan.create_folder_scan(maps.NODE_FOLDERS, maps.NODE_MAP, maps.NODE_LABELS, false),
plant_state = esp_scan.create_folder_scan(maps.PLANT_FOLDERS, maps.PLANT_MAP, maps.PLANT_LABELS, false),
out = {},
}
end
function M.step_static_scan(state, batch)
if state.phase == 1 then
local done = esp_scan.folder_scan_step(state.node_state, batch)
if done then
state.phase = 2
end
return false
end
local done = esp_scan.folder_scan_step(state.plant_state, batch)
if done then
state.out = {}
for _, entry in ipairs(state.node_state.out) do
table.insert(state.out, entry)
end
for _, entry in ipairs(state.plant_state.out) do
table.insert(state.out, entry)
end
end
return done
end
function M.complete_static_scan(state)
M._static = esp_scan.merge_entries(M._static, state.out)
rebuild_cache()
cache.stats.last_world_scan = utility and utility.get_tick_count and utility.get_tick_count() or 0
end
function M.begin_dynamic_scan()
return esp_scan.create_folder_scan(maps.ANIMAL_FOLDERS, maps.ANIMAL_MAP, maps.ANIMAL_LABELS, true)
end
function M.step_dynamic_scan(state, batch)
return esp_scan.folder_scan_step(state, batch)
end
function M.complete_dynamic_scan(state)
M._dynamic = esp_scan.merge_entries(M._dynamic, state.out)
rebuild_cache()
end
function M.update(_dt)
local world_on = settings.enabled(P)
if world_on then
if cache.should_prune() then
cache.prune_invalid(M._static)
cache.prune_invalid(M._dynamic)
rebuild_cache()
end
if cache.should_refresh_positions() then
if #M._dynamic > 0 then
refresh_dynamic_positions(M._dynamic)
rebuild_cache()
end
end
end
if gpu_chams.available() then
local owner = gpu_chams.get_owner("world")
if world_chams_active() or (owner and (owner.was_active or next(owner.applied))) then
gpu_chams.sync_owner("world")
end
end
end
function M.draw()
if not settings.enabled(P) then return end
local range = settings.num("infernal_world_range", 500)
local range_sq = range * range
local draw_boxes = settings.enabled("infernal_world_boxes")
local show_name = settings.bool("infernal_world_show_name", true)
local show_dist = settings.bool("infernal_world_show_distance", true)
local me = env.get_local_player()
local me_pos = me and me.position
local text_size = esp_util.text_size()
refresh_toggle_state(true)
local entries = cache.world
if me_pos then
entries = cache.query_spatial(
cache.spatial.world, me_pos.x, me_pos.z, range, draw_candidates
)
end
for _, entry in ipairs(entries) do
if not toggle_enabled[entry.toggle_id] then goto continue end
if not env.is_valid(entry.inst) then goto continue end
local lx, ly, lz = esp_scan.entry_coords(entry)
if not lx then goto continue end
local dist_sq = 0
if me_pos then
local dx = lx - me_pos.x
local dy = ly - me_pos.y
local dz = lz - me_pos.z
dist_sq = dx * dx + dy * dy + dz * dz
if dist_sq > range_sq then goto continue end
end
local col = toggle_colors[entry.toggle_id]
if draw_boxes then
esp_util.draw_entry_boxes(entry, col, 1)
end
if show_name or show_dist then
local sx, sy, vis = esp_util.w2s(lx, ly, lz)
if vis then
local label = show_name and (entry.name or "?") or ""
if show_dist and me_pos then
local dist_text = string.format("%dm", math.floor(math.sqrt(dist_sq)))
if label ~= "" then
label = label .. " [" .. dist_text .. "]"
else
label = dist_text
end
end
if label ~= "" then
draw_util.text_centered(sx, sy, label, col, text_size)
end
end
end
::continue::
end
end
return M
end)()

Infernal._mods["features.world.loot_esp"] = (function()
local settings = Infernal.require("core.settings")
local cache = Infernal.require("core.cache")
local folders = Infernal.require("game.folders")
local draw_util = Infernal.require("core.draw_util")
local esp_util = Infernal.require("core.esp_util")
local env = Infernal.require("core.env")
local menu_util = Infernal.require("core.menu_util")
local maps = Infernal.require("game.esp_maps")
local esp_scan = Infernal.require("game.esp_scan")
local gpu_chams = Infernal.require("core.gpu_chams")
local M = {}
local P = "infernal_loot_enabled"
local CHAMS_MASTER = "infernal_loot_chams_enabled"
local CHAMS_ID = "infernal_loot_chams"
local CHAMS_MODE = "infernal_loot_chams_mode"
local CHAMS_COLOR = "infernal_loot_chams_color"
M._static = {}
M._drops = {}
M._unlimited = {}
local draw_candidates = {}
local chams_candidates = {}
local candidate_seen = {}
local toggle_index = {}
local toggle_enabled = {}
local toggle_colors = {}
for i, t in ipairs(maps.LOOT_TOGGLES) do toggle_index[t.id] = i end
local function refresh_toggle_state(with_colors)
for i = 1, #maps.LOOT_TOGGLES do
local t = maps.LOOT_TOGGLES[i]
toggle_enabled[t.id] = settings.enabled(t.id)
if with_colors then toggle_colors[t.id] = settings.color(t.id, t.color) end
end
end
local UNLIMITED_RANGE = {
infernal_timed_crate = true,
infernal_care_package = true,
infernal_btr_crate = true,
}
local function nearby_with_unlimited(me_pos, range, out)
cache.query_spatial(cache.spatial.loot, me_pos.x, me_pos.z, range, out)
for key in pairs(candidate_seen) do candidate_seen[key] = nil end
for i = 1, #out do candidate_seen[out[i]] = true end
for _, entry in ipairs(M._unlimited) do
if not candidate_seen[entry] then out[#out + 1] = entry end
end
return out
end
local function loot_chams_labels()
local labels = {}
for i, t in ipairs(maps.LOOT_TOGGLES) do
labels[i] = t.label
end
return labels
end
local function loot_chams_index_for(toggle_id)
return toggle_index[toggle_id]
end
local function loot_chams_active()
if not gpu_chams.available() then return false end
if not settings.enabled(P) then return false end
if not settings.enabled(CHAMS_MASTER) then return false end
for i = 1, #maps.LOOT_TOGGLES do
if gpu_chams.multicombo_selected(CHAMS_ID, i) then
return true
end
end
return false
end
local function collect_loot_chams(applied)
local me = env.get_local_player()
local me_pos = me and me.position
if not me_pos then return end
local range = settings.num("infernal_loot_range", 300)
local range_sq = range * range
refresh_toggle_state(false)
local entries = nearby_with_unlimited(me_pos, range, chams_candidates)
for _, entry in ipairs(entries) do
if not env.is_valid(entry.inst) then goto continue end
local idx = loot_chams_index_for(entry.toggle_id)
if not idx or not gpu_chams.multicombo_selected(CHAMS_ID, idx) then goto continue end
if not toggle_enabled[entry.toggle_id] then goto continue end
local lx, ly, lz = esp_scan.entry_coords(entry)
if not lx then goto continue end
if not UNLIMITED_RANGE[entry.toggle_id] then
local dx = lx - me_pos.x
local dy = ly - me_pos.y
local dz = lz - me_pos.z
if (dx * dx + dy * dy + dz * dz) > range_sq then goto continue end
end
gpu_chams.cham_entry_part(entry, applied)
::continue::
end
end
local STATIC_SOURCES = {
{ kind = "root", key = "loners" },
{ kind = "root", key = "vegetation" },
{ kind = "root", key = "events" },
{ kind = "nested", key = "military" },
{ kind = "nested", key = "monuments" },
}
local function rebuild_cache()
cache.loot = {}
for _, entry in ipairs(M._static) do
table.insert(cache.loot, entry)
end
for _, entry in ipairs(M._drops) do
table.insert(cache.loot, entry)
end
M._unlimited = {}
for _, entry in ipairs(cache.loot) do
if UNLIMITED_RANGE[entry.toggle_id] then
M._unlimited[#M._unlimited + 1] = entry
end
end
cache.spatial.loot = cache.build_spatial(cache.loot)
end
local function refresh_dynamic_positions(list)
if not list or #list == 0 then return end
for _, entry in ipairs(list) do
if entry and env.is_valid(entry.inst) then
esp_scan.refresh_entry_position(entry)
end
end
end
local function loot_display_name(model, base_name)
if base_name == "Sleeper" then
local label = env.safe_call(function()
local desc = model:get_descendants()
for _, d in ipairs(desc or {}) do
if (d.ClassName or d.class_name) == "TextLabel" then
local text = d.Text or d.text
if text and text ~= "" then return text .. " (Sleeper)" end
end
end
return nil
end)
if label then return label end
elseif base_name == "Timed Crate" then
local extra = env.safe_call(function()
local desc = model:get_descendants()
for _, d in ipairs(desc or {}) do
if (d.ClassName or d.class_name) == "TextLabel" then
local text = d.Text or d.text
if text and text ~= "" then return text end
end
end
return nil
end)
if extra then return base_name .. " (" .. extra .. ")" end
end
return base_name
end
local function append_loot_model(out, model, base_name, toggle_id, dynamic)
if not env.is_valid(model) then return end
local display = loot_display_name(model, base_name)
table.insert(out, esp_scan.make_entry(model, display, toggle_id, { dynamic = dynamic }))
end
local function collect_loot_container(container, type_name, toggle_id, out, dynamic)
if not env.is_valid(container) then return end
local cn = container.ClassName or container.class_name
if cn == "Model" then
append_loot_model(out, container, type_name, toggle_id, dynamic)
return
end
local subs = env.safe_call(function() return container:get_children() end) or {}
for _, model in ipairs(subs) do
append_loot_model(out, model, type_name, toggle_id, dynamic)
end
end
function M.begin_static_scan()
return {
si = 1,
phase = "top",
ci = 1,
sub_ci = 1,
children = nil,
subs = nil,
current = nil,
out = {},
}
end
function M.step_static_scan(state, batch)
local processed = 0
while processed < batch do
if state.si > #STATIC_SOURCES then
return true
end
local source = STATIC_SOURCES[state.si]
if not state.children then
state.phase = "top"
state.ci = 1
state.sub_ci = 1
state.subs = nil
state.current = nil
state.children = env.safe_call(function()
local folder = folders.from_key(source.key)
if not env.is_valid(folder) then return {} end
return folder:get_children()
end) or {}
end
if state.ci > #state.children then
state.si = state.si + 1
state.children = nil
goto continue
end
local child = state.children[state.ci]
if state.phase == "top" then
if not env.is_valid(child) then
state.ci = state.ci + 1
processed = processed + 1
goto continue
end
local name = child.Name or child.name
local toggle_id = name and maps.LOOT_MAP[name]
if toggle_id then
collect_loot_container(child, name, toggle_id, state.out, false)
state.ci = state.ci + 1
processed = processed + 1
elseif source.kind == "nested" then
state.current = child
state.subs = env.safe_call(function() return child:get_children() end) or {}
state.sub_ci = 1
state.phase = "nested"
else
state.ci = state.ci + 1
processed = processed + 1
end
else
if not state.subs or state.sub_ci > #state.subs then
state.phase = "top"
state.ci = state.ci + 1
state.current = nil
state.subs = nil
goto continue
end
local sub = state.subs[state.sub_ci]
state.sub_ci = state.sub_ci + 1
processed = processed + 1
if not env.is_valid(sub) then goto continue end
local sub_name = sub.Name or sub.name
local sub_tid = sub_name and maps.LOOT_MAP[sub_name]
if sub_tid then
collect_loot_container(sub, sub_name, sub_tid, state.out, false)
end
end
::continue::
end
return false
end
function M.complete_static_scan(state)
M._static = esp_scan.merge_entries(M._static, state.out)
rebuild_cache()
cache.stats.last_loot_scan = utility and utility.get_tick_count and utility.get_tick_count() or 0
end
function M.begin_drops_scan()
return { ci = 1, children = nil, out = {} }
end
function M.step_drops_scan(state, batch)
if not state.children then
state.children = env.safe_call(function()
local drops = folders.from_key("drops")
if not env.is_valid(drops) then return {} end
return drops:get_children()
end) or {}
state.ci = 1
end
local processed = 0
while processed < batch and state.ci <= #state.children do
local model = state.children[state.ci]
state.ci = state.ci + 1
processed = processed + 1
if not env.is_valid(model) then goto continue end
local name = model.Name or model.name
-- Goodie Bags (Common / Rare / Epic, limited-time event loot) are hidden from the
-- Dropped Items ESP. The substring catches all tiers and any future one.
if name and name ~= "" and not name:find("Goodie Bag", 1, true) then
append_loot_model(state.out, model, name, "infernal_dropped_item", true)
end
::continue::
end
return state.ci > #state.children
end
function M.complete_drops_scan(state)
M._drops = esp_scan.merge_entries(M._drops, state.out)
rebuild_cache()
end
function M.register_menu()
local G = menu_util.G
local T, _ = menu_util.group(G.WORLD)
menu_util.section(T, G.WORLD, "Loot")
menu_util.register_keybind(T, G.WORLD, P, "Loot ESP", false)
for _, t in ipairs(maps.LOOT_TOGGLES) do
menu.add_checkbox(T, G.WORLD, t.id, t.label, false, { parent = P, colorpicker = t.color })
end
menu.add_checkbox(T, G.WORLD, "infernal_loot_boxes", "Loot 3D Boxes", false, { parent = P })
menu.add_checkbox(T, G.WORLD, "infernal_loot_show_name", "Loot Show Name", true, { parent = P })
menu.add_checkbox(T, G.WORLD, "infernal_loot_show_distance", "Loot Show Distance", true, { parent = P })
menu_util.gap(T, G.WORLD)
menu.add_slider_int(T, G.WORLD, "infernal_loot_range", "Loot Range", 50, 2000, 300, { parent = P })
local child_ids = { "infernal_loot_boxes", "infernal_loot_show_name", "infernal_loot_show_distance", "infernal_loot_range" }
local toggle_ids = {}
for _, t in ipairs(maps.LOOT_TOGGLES) do
child_ids[#child_ids + 1] = t.id
toggle_ids[#toggle_ids + 1] = t.id
end
local chams_ids = {}
if gpu_chams.available() then
menu_util.section(T, G.WORLD, "Loot Mesh Chams")
menu.add_checkbox(T, G.WORLD, CHAMS_MASTER, "Enable Mesh Chams", false, { parent = P })
child_ids[#child_ids + 1] = CHAMS_MASTER
chams_ids = gpu_chams.wire_esp_chams({
tab = T,
group = G.WORLD,
parent = CHAMS_MASTER,
chams_id = CHAMS_ID,
mode_id = CHAMS_MODE,
color_id = CHAMS_COLOR,
labels = loot_chams_labels(),
owner_id = "loot",
master_id = CHAMS_MASTER,
is_active = loot_chams_active,
collect = collect_loot_chams,
rescan_ms = 1200,
toggle_ids = toggle_ids,
})
end
for _, id in ipairs(chams_ids) do
child_ids[#child_ids + 1] = id
end
menu_util.bind_children(P, child_ids)
end
function M.update(_dt)
local map_loot = settings.enabled("infernal_map_enabled") and settings.enabled("infernal_map_show_loot")
local loot_on = settings.enabled(P)
if loot_on or map_loot then
if cache.should_prune() then
cache.prune_invalid(M._static)
cache.prune_invalid(M._drops)
rebuild_cache()
end
if cache.should_refresh_positions() then
if #M._drops > 0 then
refresh_dynamic_positions(M._drops)
rebuild_cache()
end
end
end
if gpu_chams.available() then
local owner = gpu_chams.get_owner("loot")
if loot_chams_active() or (owner and (owner.was_active or next(owner.applied))) then
gpu_chams.sync_owner("loot")
end
end
end
function M.draw()
if not settings.enabled(P) then return end
local range = settings.num("infernal_loot_range", 300)
local range_sq = range * range
local draw_boxes = settings.enabled("infernal_loot_boxes")
local show_name = settings.bool("infernal_loot_show_name", true)
local show_dist = settings.bool("infernal_loot_show_distance", true)
local me = env.get_local_player()
local me_pos = me and me.position
local text_size = esp_util.text_size()
refresh_toggle_state(true)
local entries = cache.loot
if me_pos then
entries = nearby_with_unlimited(me_pos, range, draw_candidates)
end
for _, entry in ipairs(entries) do
if not toggle_enabled[entry.toggle_id] then goto continue end
if not env.is_valid(entry.inst) then goto continue end
local lx, ly, lz = esp_scan.entry_coords(entry)
if not lx then goto continue end
local dist_sq = 0
if me_pos then
local dx = lx - me_pos.x
local dy = ly - me_pos.y
local dz = lz - me_pos.z
dist_sq = dx * dx + dy * dy + dz * dz
if not UNLIMITED_RANGE[entry.toggle_id] and dist_sq > range_sq then goto continue end
end
local col = toggle_colors[entry.toggle_id]
if draw_boxes then
esp_util.draw_entry_boxes(entry, col, 1)
end
if show_name or show_dist then
local sx, sy, vis = esp_util.w2s(lx, ly, lz)
if vis then
local label = show_name and (entry.name or "Loot") or ""
if show_dist and me_pos then
local dist_text = string.format("%dm", math.floor(math.sqrt(dist_sq)))
if label ~= "" then
label = label .. " [" .. dist_text .. "]"
else
label = dist_text
end
end
if label ~= "" then
draw_util.text_centered(sx, sy, label, col, text_size)
end
end
end
::continue::
end
end
return M
end)()

Infernal._mods["features.world.base_esp"] = (function()
local settings = Infernal.require("core.settings")
local cache = Infernal.require("core.cache")
local folders = Infernal.require("game.folders")
local draw_util = Infernal.require("core.draw_util")
local esp_util = Infernal.require("core.esp_util")
local env = Infernal.require("core.env")
local menu_util = Infernal.require("core.menu_util")
local maps = Infernal.require("game.esp_maps")
local turret_stats = Infernal.require("game.turret_stats")
local desync_vis = { draw_sphere_ring = function() end }
local esp_scan = Infernal.require("game.esp_scan")
local gpu_chams = Infernal.require("core.gpu_chams")
local M = {}
local P = "infernal_base_enabled"
local CHAMS_ID = "infernal_base_chams"
local CHAMS_MODE = "infernal_base_chams_mode"
local CHAMS_COLOR = "infernal_base_chams_color"
M._static = {}
local draw_candidates = {}
local chams_candidates = {}
local toggle_index = {}
local toggle_enabled = {}
local toggle_colors = {}
for i, t in ipairs(maps.BASE_TOGGLES) do toggle_index[t.id] = i end
local function refresh_toggle_state(with_colors)
    for i = 1, #maps.BASE_TOGGLES do
        local t = maps.BASE_TOGGLES[i]
        toggle_enabled[t.id] = settings.enabled(t.id)
        if with_colors then toggle_colors[t.id] = settings.color(t.id, t.color) end
    end
end
local function base_chams_labels()
    local labels = {}
    for i, t in ipairs(maps.BASE_TOGGLES) do
        labels[i] = t.label
    end
    return labels
end
local function base_chams_index_for(toggle_id)
    return toggle_index[toggle_id]
end
local function base_chams_active()
    if not gpu_chams.available() then return false end
    if not settings.enabled(P) then return false end
    for i = 1, #maps.BASE_TOGGLES do
        if gpu_chams.multicombo_selected(CHAMS_ID, i) then
            return true
        end
    end
    return false
end
local function collect_base_chams(applied)
    local me = env.get_local_player()
    local me_pos = me and me.position
    if not me_pos then return end
    local range = settings.num("infernal_base_range", 150)
    local range_sq = range * range
    refresh_toggle_state(false)
    local entries = cache.query_spatial(
        cache.spatial.base, me_pos.x, me_pos.z, range, chams_candidates
    )
    for _, entry in ipairs(entries) do
        if not env.is_valid(entry.inst) then goto continue end
        local idx = base_chams_index_for(entry.toggle_id)
        if not idx or not gpu_chams.multicombo_selected(CHAMS_ID, idx) then goto continue end
        if not toggle_enabled[entry.toggle_id] then goto continue end
        local lx, ly, lz = esp_scan.entry_coords(entry)
        if not lx then goto continue end
        local dx = lx - me_pos.x
        local dy = ly - me_pos.y
        local dz = lz - me_pos.z
        if (dx * dx + dy * dy + dz * dz) > range_sq then goto continue end
        gpu_chams.cham_entry_part(entry, applied)
        ::continue::
    end
end
local function rebuild_cache()
    cache.base = {}
    for _, entry in ipairs(M._static) do
        table.insert(cache.base, entry)
    end
    cache.spatial.base = cache.build_spatial(cache.base)
end
local function append_base_model(out, model, type_name, toggle_id)
    if not env.is_valid(model) then return end
    if not esp_scan.find_main_part(model) and not esp_scan.is_part(model) then return end
    table.insert(out, esp_scan.make_entry(model, type_name, toggle_id, { dynamic = false }))
end
local function collect_base_container(container, type_name, toggle_id, out)
    if not env.is_valid(container) then return end
    if type_name == "Sleeping Bag" then
        local bag = env.safe_call(function()
            return container:find_first_child("SleepingBag")
                or container:FindFirstChild("SleepingBag")
                or container:find_first_child("Sleeping_Bag")
                or container:FindFirstChild("Sleeping_Bag")
        end)
        if bag and env.is_valid(bag) then
            append_base_model(out, bag, type_name, toggle_id)
            return
        end
    end
    local cn = container.ClassName or container.class_name
    if cn == "Model" or esp_scan.is_part(container) then
        append_base_model(out, container, type_name, toggle_id)
        return
    end
    local subs = env.safe_call(function() return container:get_children() end) or {}
    for _, model in ipairs(subs) do
        local mc = model.ClassName or model.class_name
        if mc == "Model" or esp_scan.is_part(model) or esp_scan.find_main_part(model) then
            append_base_model(out, model, type_name, toggle_id)
        end
    end
end
function M.register_menu()
    local G = menu_util.G
    local T, _ = menu_util.group(G.WORLD)
    menu_util.section(T, G.WORLD, "Bases")
    menu_util.register_keybind(T, G.WORLD, P, "Base ESP", false)
    for _, t in ipairs(maps.BASE_TOGGLES) do
        menu.add_checkbox(T, G.WORLD, t.id, t.label, false, { parent = P, colorpicker = t.color })
        if t.ring_id then
            menu.add_checkbox(T, G.WORLD, t.ring_id, t.label .. " Range Ring", false, { parent = t.id })
        end
    end
    menu.add_checkbox(T, G.WORLD, "infernal_base_boxes", "Base 3D Boxes", false, { parent = P })
    menu.add_checkbox(T, G.WORLD, "infernal_base_show_name", "Base Show Name", true, { parent = P })
    menu.add_checkbox(T, G.WORLD, "infernal_base_show_distance", "Base Show Distance", false, { parent = P })
    menu_util.gap(T, G.WORLD)
    menu.add_slider_int(T, G.WORLD, "infernal_base_range", "Base Range", 50, 500, 150, { parent = P })
    local child_ids = { "infernal_base_boxes", "infernal_base_show_name", "infernal_base_show_distance", "infernal_base_range" }
    local toggle_ids = {}
    for _, t in ipairs(maps.BASE_TOGGLES) do
        child_ids[#child_ids + 1] = t.id
        toggle_ids[#toggle_ids + 1] = t.id
        if t.ring_id then
            child_ids[#child_ids + 1] = t.ring_id
        end
    end
    local chams_ids = {}
    if gpu_chams.available() then
        menu_util.section(T, G.WORLD, "Base Mesh Chams")
        chams_ids = gpu_chams.wire_esp_chams({
            tab = T,
            group = G.WORLD,
            parent = P,
            chams_id = CHAMS_ID,
            mode_id = CHAMS_MODE,
            color_id = CHAMS_COLOR,
            labels = base_chams_labels(),
            owner_id = "base",
            master_id = P,
            is_active = base_chams_active,
            collect = collect_base_chams,
            rescan_ms = 900,
            toggle_ids = toggle_ids,
        })
    end
    for _, id in ipairs(chams_ids) do
        child_ids[#child_ids + 1] = id
    end
    menu_util.bind_children(P, child_ids)
end
function M.begin_static_scan()
    return {
        ai = 1,
        phase = "top",
        ci = 1,
        sub_ci = 1,
        areas = nil,
        children = nil,
        subs = nil,
        out = {},
    }
end
function M.step_static_scan(state, batch)
    if not state.areas then
        state.areas = env.safe_call(function()
            local bases = folders.from_key("bases")
            if not env.is_valid(bases) then return {} end
            return bases:get_children()
        end) or {}
        state.ai = 1
    end
    local processed = 0
    while processed < batch do
        if state.ai > #state.areas then
            return true
        end
        local area = state.areas[state.ai]
        if not state.children then
            if not env.is_valid(area) then
                state.ai = state.ai + 1
                processed = processed + 1
                goto continue
            end
            local area_name = area.Name or area.name or ""
            if maps.BASE_SKIP_AREAS[area_name] then
                state.ai = state.ai + 1
                processed = processed + 1
                goto continue
            end
            state.phase = "top"
            state.ci = 1
            state.sub_ci = 1
            state.subs = nil
            if maps.BASE_MAP[area_name] then
                state.children = { area }
            else
                state.children = env.safe_call(function() return area:get_children() end) or {}
            end
        end
        if state.ci > #state.children then
            state.ai = state.ai + 1
            state.children = nil
            state.subs = nil
            goto continue
        end
        local child = state.children[state.ci]
        if state.phase == "top" then
            if not env.is_valid(child) then
                state.ci = state.ci + 1
                processed = processed + 1
                goto continue
            end
            local name = child.Name or child.name
            local toggle_id = name and maps.BASE_MAP[name]
            if toggle_id then
                state.subs = env.safe_call(function()
                    local cn = child.ClassName or child.class_name
                    if cn == "Model" or esp_scan.is_part(child) then
                        return { child }
                    end
                    if name == "Sleeping Bag" then
                        local bag = child:find_first_child("SleepingBag")
                            or child:FindFirstChild("SleepingBag")
                            or child:find_first_child("Sleeping_Bag")
                            or child:FindFirstChild("Sleeping_Bag")
                        if bag then return { bag } end
                    end
                    return child:get_children()
                end) or {}
                state.sub_ci = 1
                state.phase = "models"
                state._type_name = name
                state._toggle_id = toggle_id
            else
                state.ci = state.ci + 1
                processed = processed + 1
            end
        else
            if not state.subs or state.sub_ci > #state.subs then
                state.phase = "top"
                state.ci = state.ci + 1
                state.subs = nil
                state._type_name = nil
                state._toggle_id = nil
                goto continue
            end
            local model = state.subs[state.sub_ci]
            state.sub_ci = state.sub_ci + 1
            processed = processed + 1
            if env.is_valid(model) then
                append_base_model(state.out, model, state._type_name, state._toggle_id)
            end
        end
        ::continue::
    end
    return false
end
function M.complete_static_scan(state)
    M._static = esp_scan.merge_entries(M._static, state.out)
    rebuild_cache()
    cache.stats.last_base_scan = utility and utility.get_tick_count and utility.get_tick_count() or 0
end
function M.update(_dt)
    local map_base = settings.enabled("infernal_map_enabled") and settings.enabled("infernal_map_show_base")
    local base_on = settings.enabled(P)
    if base_on or map_base then
        if cache.should_prune() then
            cache.prune_invalid(M._static)
            rebuild_cache()
        end
    end
    if gpu_chams.available() then
        local owner = gpu_chams.get_owner("base")
        if base_chams_active() or (owner and (owner.was_active or next(owner.applied))) then
            gpu_chams.sync_owner("base")
        end
    end
end
function M.draw()
    if not settings.enabled(P) then return end
    local range = settings.num("infernal_base_range", 150)
    local range_sq = range * range
    local draw_boxes = settings.enabled("infernal_base_boxes")
    local show_name = settings.bool("infernal_base_show_name", true)
    local show_dist = settings.bool("infernal_base_show_distance", false)
    local me = env.get_local_player()
    local me_pos = me and me.position
    local text_size = esp_util.text_size()
    refresh_toggle_state(true)
    local entries = cache.base
    if me_pos then
        entries = cache.query_spatial(
            cache.spatial.base, me_pos.x, me_pos.z, range, draw_candidates
        )
    end
    for _, entry in ipairs(entries) do
        if not toggle_enabled[entry.toggle_id] then goto continue end
        if not env.is_valid(entry.inst) then goto continue end
        local lx, ly, lz = esp_scan.entry_coords(entry)
        if not lx then goto continue end
        local dist_sq = 0
        if me_pos then
            local dx = lx - me_pos.x
            local dy = ly - me_pos.y
            local dz = lz - me_pos.z
            dist_sq = dx * dx + dy * dy + dz * dz
            if dist_sq > range_sq then goto continue end
        end
        local col = toggle_colors[entry.toggle_id]
        if draw_boxes then
            esp_util.draw_entry_boxes(entry, col, 1)
        end
        local ring_id = maps.turret_ring_toggle(entry.toggle_id)
        if ring_id and settings.enabled(ring_id) then
            local activation = turret_stats.activation_range(entry.name)
            if activation then
                desync_vis.draw_sphere_ring(lx, ly, lz, activation, { col[1], col[2], col[3], 0.35 }, 1.5)
            end
        end
        if show_name or show_dist then
            local sx, sy, vis = esp_util.w2s(lx, ly, lz)
            if vis then
                local label = show_name and (entry.name or "Base") or ""
                if show_dist and me_pos then
                    local dist_text = string.format("%dm", math.floor(math.sqrt(dist_sq)))
                    if label ~= "" then
                        label = label .. " [" .. dist_text .. "]"
                    else
                        label = dist_text
                    end
                end
                if label ~= "" then
                    draw_util.text_centered(sx, sy, label, col, text_size)
                end
            end
        end
        ::continue::
    end
end
return M
end)()

Infernal._mods["features.world.base_xray"] = (function()
local settings = Infernal.require("core.settings")
local env = Infernal.require("core.env")
local folders = Infernal.require("game.folders")
local menu_util = Infernal.require("core.menu_util")
local maps = Infernal.require("game.esp_maps")
local gpu_chams = Infernal.require("core.gpu_chams")
local M = {}
local P = "infernal_base_xray_enabled"
local P_RANGE = "infernal_base_xray_range"
local OWNER = "base_xray"
local WIREFRAME = 1
local RESCAN_MS = 700
local BATCH = 72
local STRUCT = {
    Wall = true,
    ["Half Wall"] = true,
    ["Wall Frame"] = true,
    Foundation = true,
    ["Triangle Foundation"] = true,
    Floor = true,
    ["Triangle Floor"] = true,
    Doorway = true,
    Window = true,
    ["Foundation Steps"] = true,
    Ramps = true,
    ["Floor Grill"] = true,
    ["L-Shaped Stairs"] = true,
}
local VISUAL_NAMES = {
    Detail = true,
    Detail1 = true,
    Detail2 = true,
    Pole = true,
    Fill = true,
}
local SKIP_PART_NAMES = {
    BuildingPriv = true,
    CollisionPart = true,
    Collision = true,
    WeldPart = true,
}
local installed = false
local scan = nil
local cached_parts = {}
local last_scan_done = 0
local function now_ms()
    local fn = utility and (utility.get_tick_count or utility.GetTickCount)
    if type(fn) ~= "function" then return 0 end
    local ok, value = pcall(fn)
    return ok and (tonumber(value) or 0) or 0
end
local function children_of(parent)
    if not parent then return {} end
    return env.safe_call(function()
        if parent.GetChildren then return parent:GetChildren() end
        if parent.get_children then return parent:get_children() end
        return {}
    end) or {}
end
local function read_pos(inst)
    if not inst then return nil end
    local p = inst.Position or inst.position
    if not p then return nil end
    local x, y, z = p.x or p.X, p.y or p.Y, p.z or p.Z
    if x == nil or y == nil or z == nil then return nil end
    return x, y, z
end
local function local_pos()
    local me = env.get_local_player()
    local p = me and (me.Position or me.position)
    if not p then return nil end
    local x, y, z = p.x or p.X, p.y or p.Y, p.z or p.Z
    if x == nil then return nil end
    return { x = x, y = y, z = z }
end
local function is_visual_part(inst)
    if not gpu_chams.is_part(inst) then return false end
    local name = inst.Name or inst.name
    if not name or SKIP_PART_NAMES[name] then return false end
    if VISUAL_NAMES[name] then return true end
    local cn = inst.ClassName or inst.class_name
    return name == "Main" and (cn == "UnionOperation" or cn == "MeshPart")
end
local function part_key(inst)
    return tostring(inst and (inst.Address or inst.address or inst))
end
local function append_unique(out, seen, part)
    local key = part_key(part)
    if not seen[key] then
        seen[key] = true
        out[#out + 1] = part
    end
end
local function collect_visual_parts(model, out, seen)
    if not model or not env.is_valid(model) then return end
    if is_visual_part(model) then
        append_unique(out, seen, model)
        return
    end
    local kids = children_of(model)
    for i = 1, #kids do
        local child = kids[i]
        if not child or not env.is_valid(child) then goto cont end
        local name = child.Name or child.name
        if name == "CollisionParts" or (name and SKIP_PART_NAMES[name]) then
            goto cont
        end
        if is_visual_part(child) then
            append_unique(out, seen, child)
        else
            local cn = child.ClassName or child.class_name
            if cn == "Folder" or cn == "Model" then
                collect_visual_parts(child, out, seen)
            end
        end
        ::cont::
    end
end
local function model_anchor(model)
    if not model then return nil end
    local detail = env.safe_call(function()
        if model.FindFirstChild then return model:FindFirstChild("Detail") end
        if model.find_first_child then return model:find_first_child("Detail") end
        return nil
    end)
    if detail and gpu_chams.is_part(detail) then return detail end
    local main = env.safe_call(function()
        if model.FindFirstChild then return model:FindFirstChild("Main") end
        if model.find_first_child then return model:find_first_child("Main") end
        return nil
    end)
    if main and gpu_chams.is_part(main) then return main end
    local kids = children_of(model)
    for i = 1, #kids do
        if gpu_chams.is_part(kids[i]) then return kids[i] end
    end
    return nil
end
local function begin_scan()
    return {
        areas = children_of(folders.from_key("bases")),
        ai = 1,
        types = nil,
        ti = 1,
        models = nil,
        mi = 1,
        parts = {},
        parts_seen = {},
    }
end
local function step_scan(state, origin, range_sq, batch)
    local processed = 0
    while processed < batch do
        if state.ai > #state.areas then
            return true
        end
        if not state.types then
            local area = state.areas[state.ai]
            if not env.is_valid(area) then
                state.ai = state.ai + 1
                processed = processed + 1
                goto continue
            end
            local area_name = area.Name or area.name or ""
            if maps.BASE_SKIP_AREAS[area_name] or maps.BASE_MAP[area_name] then
                state.ai = state.ai + 1
                processed = processed + 1
                goto continue
            end
            state.types = children_of(area)
            state.ti = 1
            state.models = nil
        end
        if state.ti > #state.types then
            state.ai = state.ai + 1
            state.types = nil
            state.models = nil
            goto continue
        end
        if not state.models then
            local type_folder = state.types[state.ti]
            if not env.is_valid(type_folder) then
                state.ti = state.ti + 1
                processed = processed + 1
                goto continue
            end
            local type_name = type_folder.Name or type_folder.name
            if not type_name or not STRUCT[type_name] or maps.BASE_MAP[type_name] then
                state.ti = state.ti + 1
                processed = processed + 1
                goto continue
            end
            state.models = children_of(type_folder)
            state.mi = 1
        end
        if state.mi > #state.models then
            state.ti = state.ti + 1
            state.models = nil
            goto continue
        end
        local model = state.models[state.mi]
        state.mi = state.mi + 1
        processed = processed + 1
        if env.is_valid(model) then
            local model_name = model.Name or model.name
            if model_name and maps.BASE_MAP[model_name] then
                goto continue
            end
            local anchor = model_anchor(model)
            local x, y, z = read_pos(anchor)
            if x then
                local dx = x - origin.x
                local dy = y - origin.y
                local dz = z - origin.z
                if (dx * dx + dy * dy + dz * dz) <= range_sq then
                    collect_visual_parts(model, state.parts, state.parts_seen)
                end
            end
        end
        ::continue::
    end
    return false
end
local function xray_active()
    return settings.enabled(P) and gpu_chams.available()
end
local function collect_xray(applied)
    local origin = local_pos()
    if not origin then return end
    local range = math.max(40, settings.num(P_RANGE, 180))
    local range_sq = range * range
    for i = 1, #cached_parts do
        local part = cached_parts[i]
        if part and env.is_valid(part) then
            local x, y, z = read_pos(part)
            if x then
                local dx = x - origin.x
                local dy = y - origin.y
                local dz = z - origin.z
                if (dx * dx + dy * dy + dz * dz) <= range_sq then
                    gpu_chams.cham_part(part, applied)
                end
            end
        end
    end
end
local function ensure_owner()
    if not gpu_chams.available() then return end
    if gpu_chams.get_owner(OWNER) then return end
    gpu_chams.register_owner(OWNER, {
        rescan_ms = 250,
        is_active = xray_active,
        style = function()
            return WIREFRAME, 0
        end,
        collect = collect_xray,
    })
    settings.on_change(P, function(v)
        if v == true or v == 1 then
            gpu_chams.sync_owner(OWNER, true)
        else
            gpu_chams.clear_owner(OWNER)
            scan = nil
            cached_parts = {}
        end
    end)
    settings.on_change(P_RANGE, function()
        gpu_chams.sync_owner(OWNER, true)
    end)
end
function M.install()
    if installed then return end
    installed = true
    ensure_owner()
end
function M.register_menu()
    local G = menu_util.G
    local T = menu_util.group(G.WORLD)
    menu_util.section(T, G.WORLD, "Base Xray")
    menu_util.register_keybind(T, G.WORLD, P, "Base Xray", false)
    menu.add_slider_int(
        T, G.WORLD, P_RANGE, "Xray Range", 40, 500, 180,
        menu_util.parent(P)
    )
    menu_util.bind_children(P, { P_RANGE })
    if gpu_chams.available() then
        ensure_owner()
    end
end
function M.update()
    ensure_owner()
    if not settings.enabled(P) or not gpu_chams.available() then return end
    local origin = local_pos()
    local range = math.max(40, settings.num(P_RANGE, 180))
    local range_sq = range * range
    if origin then
        if not scan or (scan.done and now_ms() - last_scan_done >= RESCAN_MS) then
            scan = begin_scan()
        end
        if scan and not scan.done then
            if step_scan(scan, origin, range_sq, BATCH) then
                scan.done = true
                last_scan_done = now_ms()
                cached_parts = scan.parts
            end
        end
    end
    local owner = gpu_chams.get_owner(OWNER)
    if xray_active() or (owner and (owner.was_active or next(owner.applied))) then
        gpu_chams.sync_owner(OWNER)
    end
end
function M.draw() end
return M
end)()

Infernal._mods["features.world.npc_esp"] = (function()
local settings = Infernal.require("core.settings")
local cache = Infernal.require("core.cache")
local draw_util = Infernal.require("core.draw_util")
local esp_util = Infernal.require("core.esp_util")
local env = Infernal.require("core.env")
local menu_util = Infernal.require("core.menu_util")
local npcs = Infernal.require("game.npcs")
local M = {}
local P = "infernal_npc_enabled"
local NPC_ARROW_OPTS = { outline = true }
local HP_TTL_MS = 250
local function tick_ms()
    return utility and utility.get_tick_count and utility.get_tick_count() or 0
end
local function migrate_legacy_types()
    if M._legacy_migrated then return end
    M._legacy_migrated = true
    if not menu or not menu.set then return end
    if settings.bool("infernal_npc_soldiers", false) then
        menu.set("infernal_npc_soldier", true)
        if menu.set_color then
            menu.set_color("infernal_npc_soldier", settings.color("infernal_npc_soldiers", { 1, 0.3, 0.3, 1 }))
        end
    end
    if settings.bool("infernal_npc_bosses", false) then
        local color = settings.color("infernal_npc_bosses", { 1, 0.5, 0.1, 1 })
        for _, id in ipairs({ "infernal_npc_bruno", "infernal_npc_boris", "infernal_npc_brutus" }) do
            menu.set(id, true)
            if menu.set_color then menu.set_color(id, color) end
        end
    end
    if settings.bool("infernal_npc_heli", false) then
        menu.set("infernal_npc_attack_heli", true)
        if menu.set_color then
            menu.set_color("infernal_npc_attack_heli", settings.color("infernal_npc_heli", { 0.85, 0.2, 0.25, 1 }))
        end
    end
end
function M.register_menu()
    local G = menu_util.G
    local T, _ = menu_util.group(G.WORLD)
    local root = menu_util.parent(P)
    menu_util.section(T, G.WORLD, "NPCs")
    menu_util.register_keybind(T, G.WORLD, P, "NPC ESP", false)
    menu.add_checkbox(T, G.WORLD, "infernal_npc_soldier", "Military", false, menu_util.parent(P, { colorpicker = { 1, 0.3, 0.3, 1 } }))
    menu.add_checkbox(T, G.WORLD, "infernal_npc_bruno", "Bruno", false, menu_util.parent(P, { colorpicker = { 1, 0.65, 0.2, 1 } }))
    menu.add_checkbox(T, G.WORLD, "infernal_npc_boris", "Boris", false, menu_util.parent(P, { colorpicker = { 0.78, 0.42, 1, 1 } }))
    menu.add_checkbox(T, G.WORLD, "infernal_npc_brutus", "Brutus", false, menu_util.parent(P, { colorpicker = { 1, 0.3, 0.48, 1 } }))
    menu.add_checkbox(T, G.WORLD, "infernal_npc_attack_heli", "Attack Heli", false, menu_util.parent(P, { colorpicker = { 0.85, 0.2, 0.25, 1 } }))
    menu.add_checkbox(T, G.WORLD, "infernal_npc_btr", "BTR", false, menu_util.parent(P, { colorpicker = { 0.95, 0.25, 0.15, 1 } }))
    menu.add_checkbox(T, G.WORLD, "infernal_npc_diver_dave", "Diver Dave", false, menu_util.parent(P, { colorpicker = { 0.2, 0.75, 1, 1 } }))
    menu.add_checkbox(T, G.WORLD, "infernal_npc_pilot_pete", "Pilot Pete", false, menu_util.parent(P, { colorpicker = { 0.35, 1, 0.65, 1 } }))
    menu.add_checkbox(T, G.WORLD, "infernal_npc_sleeper", "Sleeper", false, menu_util.parent(P, { colorpicker = { 0.6, 0.85, 1, 1 } }))
    menu.add_checkbox(T, G.WORLD, "infernal_npc_zombie", "Zombie", false, menu_util.parent(P, { colorpicker = { 0.55, 0.9, 0.3, 1 } }))
    menu.add_combo(T, G.WORLD, "infernal_npc_box_mode", "NPC Box", { "None", "2D", "Corner" }, 1, root)
    menu.add_checkbox(T, G.WORLD, "infernal_npc_health", "NPC Health Bar", true, root)
    menu.add_checkbox(T, G.WORLD, "infernal_npc_show_name", "NPC Show Name", true,
        menu_util.parent(P, { colorpicker = { 1, 0.3, 0.3, 1 } }))
    menu.add_checkbox(T, G.WORLD, "infernal_npc_show_distance", "NPC Show Distance", true,
        menu_util.parent(P, { colorpicker = { 0.82, 0.84, 0.88, 0.92 } }))
    menu_util.gap(T, G.WORLD)
    menu.add_slider_int(T, G.WORLD, "infernal_npc_range", "NPC Range", 50, 2000, 500, root)
    menu_util.bind_children(P, {
        "infernal_npc_soldier", "infernal_npc_bruno", "infernal_npc_boris", "infernal_npc_brutus",
        "infernal_npc_attack_heli", "infernal_npc_btr", "infernal_npc_diver_dave", "infernal_npc_pilot_pete",
        "infernal_npc_sleeper",
        "infernal_npc_zombie",
        "infernal_npc_box_mode", "infernal_npc_health",
        "infernal_npc_show_name", "infernal_npc_show_distance",
        "infernal_npc_range",
    })
end
local live_view = Infernal.require("core.live_view")
local function entity_bounds(player)
    if not player then return nil end
    local fn = player.GetBounds or player.get_bounds
    if not fn then return nil end
    return fn(player)
end
local function event_health(entry)
    local now = tick_ms()
    if entry.hp_t and now - entry.hp_t < HP_TTL_MS then
        return entry.hp, entry.max_hp
    end
    local health = npcs.read_health(entry.inst, entry.humanoid)
    entry.hp_t = now
    entry.hp = health and health.hp or nil
    entry.max_hp = health and (health.max_hp or health.hp) or nil
    return entry.hp, entry.max_hp
end
local function event_bounds(entry, dist)
    local x, y, z
    if entry.fixed_pos then
        x, y, z = entry.lx, entry.ly, entry.lz
        if not x then return nil end
    else
        if not entry.root or not env.is_valid(entry.root) then return nil end
        x, y, z = esp_util.vec3_pos(entry.root.Position or entry.root.position)
        if not x then return nil end
        entry.lx, entry.ly, entry.lz = x, y, z
    end
    local vehicle = entry.vehicle == true
    return esp_util.head_body_screen_bounds(x, y, z, {
        dist = dist,
        body_h = vehicle and 8.0 or 5.0,
        width_mul = vehicle and 1.15 or 0.52,
        top_pad = vehicle and 2.0 or 0.35,
        bot_pad = vehicle and 2.0 or 0.15,
    })
end
function M.draw()
    migrate_legacy_types()
    if not settings.enabled(P) then return end
    local list = cache.npcs
    if not list or #list == 0 then return end
    local range = settings.num("infernal_npc_range", 500)
    local range_sq = range * range
    local box_mode = settings.num("infernal_npc_box_mode", 1)
    local show_health = settings.bool("infernal_npc_health", true)
    local show_name = settings.bool("infernal_npc_show_name", true)
    local show_dist = settings.bool("infernal_npc_show_distance", true)
    local show_tracer = settings.bool("infernal_npc_tracers", false)
    local show_arrow = settings.bool("infernal_npc_offscreen", false)
    local enabled = {
        soldier = settings.bool("infernal_npc_soldier", false),
        bruno = settings.bool("infernal_npc_bruno", false),
        boris = settings.bool("infernal_npc_boris", false),
        brutus = settings.bool("infernal_npc_brutus", false),
        heli = settings.bool("infernal_npc_attack_heli", false),
        btr = settings.bool("infernal_npc_btr", false),
        diver_dave = settings.bool("infernal_npc_diver_dave", false),
        pilot_pete = settings.bool("infernal_npc_pilot_pete", false),
        sleeper = settings.bool("infernal_npc_sleeper", false),
        zombie = settings.bool("infernal_npc_zombie", false),
    }
    if not (enabled.soldier or enabled.bruno or enabled.boris or enabled.brutus
        or enabled.heli or enabled.btr or enabled.diver_dave or enabled.pilot_pete
        or enabled.sleeper or enabled.zombie)
    then
        return
    end
    local colors = {
        soldier = settings.color("infernal_npc_soldier", { 1, 0.3, 0.3, 1 }),
        bruno = settings.color("infernal_npc_bruno", { 1, 0.65, 0.2, 1 }),
        boris = settings.color("infernal_npc_boris", { 0.78, 0.42, 1, 1 }),
        brutus = settings.color("infernal_npc_brutus", { 1, 0.3, 0.48, 1 }),
        heli = settings.color("infernal_npc_attack_heli", { 0.85, 0.2, 0.25, 1 }),
        btr = settings.color("infernal_npc_btr", { 0.95, 0.25, 0.15, 1 }),
        diver_dave = settings.color("infernal_npc_diver_dave", { 0.2, 0.75, 1, 1 }),
        pilot_pete = settings.color("infernal_npc_pilot_pete", { 0.35, 1, 0.65, 1 }),
        sleeper = settings.color("infernal_npc_sleeper", { 0.6, 0.85, 1, 1 }),
        zombie = settings.color("infernal_npc_zombie", { 0.55, 0.9, 0.3, 1 }),
    }
    local col_name = settings.color("infernal_npc_show_name", { 1, 0.3, 0.3, 1 })
    local col_dist = settings.color("infernal_npc_show_distance", { 0.82, 0.84, 0.88, 0.92 })
    local text_size = esp_util.text_size()
    local me = cache.local_player or env.get_local_player()
    local mx, my, mz = nil, nil, nil
    if me then
        mx, my, mz = esp_util.vec3_pos(me.Position or me.position)
    end
    for i = 1, #list do
        local entry = list[i]
        if not entry then goto continue end
        if not enabled[entry.kind] then goto continue end
        local col = colors[entry.kind] or colors.soldier
        local player = entry.entity
        if player and (player.IsAlive == false or player.is_alive == false) then goto continue end
        if not player and (not entry.inst or not env.is_valid(entry.inst)) then goto continue end
        local lx, ly, lz
        if player then
            lx, ly, lz = esp_util.vec3_pos(
                player.HeadPosition or player.head_position or player.Position or player.position
            )
            if lx then entry.lx, entry.ly, entry.lz = lx, ly, lz end
        else
            lx, ly, lz = entry.lx, entry.ly, entry.lz
        end
        if not lx then goto continue end
        local dist = 0
        if mx then
            local dx = lx - mx
            local dy = ly - my
            local dz = lz - mz
            local dist_sq = dx * dx + dy * dy + dz * dz
            if dist_sq > range_sq then goto continue end
            dist = math.sqrt(dist_sq)
        end
        if show_arrow and esp_util.draw_offscreen_to(lx, ly, lz, col, 14, 36, NPC_ARROW_OPTS) then goto continue end
        local bounds = player and live_view.shift_bounds(entity_bounds(player), lx, ly, lz) or event_bounds(entry, dist)
        if not esp_util.bounds_usable(bounds) then goto continue end
        if show_tracer then
            draw_util.snapline(bounds.x + bounds.w * 0.5, bounds.y + bounds.h, col, 1)
        end
        local ts = text_size
        if dist > 200 then ts = math.max(9, ts - 1) end
        if dist > 400 then ts = math.max(8, ts - 1) end
        local cx = bounds.x + bounds.w * 0.5
        local label = entry.name or "NPC"
        if show_name then
            draw_util.text_centered(cx, bounds.y - ts - 5, label, col_name, ts)
        end
        if box_mode == 1 then
            draw_util.box_esp(bounds.x, bounds.y, bounds.w, bounds.h, col, 0)
        elseif box_mode == 2 then
            draw_util.box_esp(bounds.x, bounds.y, bounds.w, bounds.h, col, 1)
        end
        if show_health then
            local hp, max_hp
            if player then
                hp = tonumber(player.Health or player.health)
                max_hp = tonumber(player.MaxHealth or player.max_health)
            else
                hp, max_hp = event_health(entry)
            end
            if hp and max_hp then
                draw_util.health_bar_on_box(bounds, hp, max_hp)
            end
        end
        if show_dist and mx then
            draw_util.text_centered(
                cx,
                bounds.y + bounds.h + 3,
                string.format("%dm", math.floor(dist + 0.5)),
                col_dist,
                ts
            )
        end
        ::continue::
    end
end
return M
end)()

Infernal._mods["features.world.raid_esp"] = (function()
local settings = Infernal.require("core.settings")
local cache = Infernal.require("core.cache")
local env = Infernal.require("core.env")
local draw_util = Infernal.require("core.draw_util")
local esp_util = Infernal.require("core.esp_util")
local menu_util = Infernal.require("core.menu_util")
local notify = Infernal.require("core.notify")
local M = {}
local P = "infernal_raid_enabled"
local ID_NOTIFY = "infernal_raid_notifications"
local ID_RANGE = "infernal_raid_range"
local CLUSTER_MERGE_M = 40
local CLUSTER_TTL_MS = 30 * 60 * 1000
local SCAN_MS = 350
local ROCKET_TRACE_SCAN_MS = 50
local ROCKET_TRACE_TTL_MS = 2500
local ROCKET_TRACE_MATCH_M = 45
local NOTIFY_DEDUP_MS = 10000
local RAID_SOUNDS = {
    c4 = { label = "Timed Charge", weight = 3 },
    dynamitebundle = { label = "Dynamite Bundle", weight = 2 },
}
local ROCKET_SIGNAL = { label = "Rocket", weight = 2 }
local IGNORE_NAMES = {
    helirocket = true,
    helicrashing = true,
    militarygrenade = true,
    landmine = true,
    dynamitestick = true,
    explosioneffect = true,
    explosionpart = true,
    explosion = true,
    projectile = true,
    boom = true,
    grenade = true,
    shell = true,
    charge = true,
    bomb = true,
}
local RAID_PROJECTILE = {
    ["timed charge"] = "Timed Charge",
    timedcharge = "Timed Charge",
    c4 = "Timed Charge",
    ["dynamite bundle"] = "Dynamite Bundle",
    dynamitebundle = "Dynamite Bundle",
}
M._processed = {}
M._last_scan = 0
M._last_trace_scan = 0
M._last_notify = {}
M._projectiles = {}
M._rocket_traces = {}
cache.raids = cache.raids or {}
local function tick_ms()
    return utility and utility.get_tick_count and utility.get_tick_count() or 0
end
local function vec_xyz(v)
    if not v then return nil end
    local x = v.X or v.x
    local y = v.Y or v.y
    local z = v.Z or v.z
    if x and y and z then return x, y, z end
    return nil
end
local function dist3(ax, ay, az, bx, by, bz)
    local dx, dy, dz = ax - bx, ay - by, az - bz
    return math.sqrt(dx * dx + dy * dy + dz * dz)
end
local function norm_name(name)
    return tostring(name or ""):lower():gsub("[%s_%-]", "")
end
local function children_of(inst)
    if not inst then return {} end
    return env.safe_call(function()
        if inst.GetChildren then return inst:GetChildren() end
        if inst.get_children then return inst:get_children() end
        return {}
    end) or {}
end
local function instance_pos(inst)
    if not inst then return nil end
    local cn = inst.ClassName or inst.class_name or ""
    local pos = inst.Position or inst.position
    local x, y, z = vec_xyz(pos)
    if x then return x, y, z end
    if cn == "Model" or cn == "model" then
        local primary = inst.PrimaryPart or inst.primary_part
        x, y, z = vec_xyz(primary and (primary.Position or primary.position))
        if x then return x, y, z end
    end
    local ok, cf = pcall(function()
        return inst.CFrame or inst.cframe
    end)
    if ok and cf then
        return vec_xyz(cf.Position or cf.position or cf)
    end
    return nil
end
local function rocket_trace_kind(name)
    local key = norm_name(name)
    if key:find("helirocket", 1, true) then return "heli" end
    if key:find("rocket", 1, true) then return "player" end
    return nil
end
local function update_rocket_traces(vfx, now)
    if not vfx then return end
    for _, child in ipairs(children_of(vfx)) do
        local kind = rocket_trace_kind(child and (child.Name or child.name))
        if kind then
            local x, y, z = instance_pos(child)
            if x then
                local addr = tostring(child.Address or child.address or child)
                M._rocket_traces[addr] = {
                    kind = kind,
                    x = x, y = y, z = z,
                    updated = now,
                }
            end
        end
    end
    for addr, trace in pairs(M._rocket_traces) do
        if not trace or now - (trace.updated or 0) > ROCKET_TRACE_TTL_MS then
            M._rocket_traces[addr] = nil
        end
    end
end
local function rocket_source_near(x, y, z, now)
    local best_kind, best_dist = nil, ROCKET_TRACE_MATCH_M
    for _, trace in pairs(M._rocket_traces) do
        if trace and now - (trace.updated or 0) <= ROCKET_TRACE_TTL_MS then
            local dist = dist3(x, y, z, trace.x, trace.y, trace.z)
            if dist < best_dist or (dist == best_dist and trace.kind == "heli") then
                best_kind, best_dist = trace.kind, dist
            end
        end
    end
    return best_kind
end
local function sound_is_playing(snd)
    if not snd then return false end
    local playing = snd.IsPlaying or snd.is_playing or snd.Playing or snd.playing
    if playing == true then return true end
    local ok, v = pcall(function()
        if snd.IsPlaying ~= nil then return snd.IsPlaying end
        if snd.Playing ~= nil then return snd.Playing end
        return nil
    end)
    return ok and v == true
end
local function raid_signal_from_inst(inst, rocket_source)
    if not inst then return nil end
    local name = inst.Name or inst.name or ""
    local key = norm_name(name)
    if IGNORE_NAMES[key] and not RAID_SOUNDS[key] then
    elseif RAID_SOUNDS[key] then
        return RAID_SOUNDS[key].label, RAID_SOUNDS[key].weight, key
    end
    local best_label, best_weight, best_key = nil, 0, nil
    for _, child in ipairs(children_of(inst)) do
        local cn = child.ClassName or child.class_name or ""
        if cn == "Sound" or cn == "sound" then
            local skey = norm_name(child.Name or child.name)
            local info = RAID_SOUNDS[skey]
            if skey == "rocket" and rocket_source == "player" then
                info = ROCKET_SIGNAL
            end
            if info and (sound_is_playing(child) or key == "explosionpart") then
                if info.weight > best_weight then
                    best_label, best_weight, best_key = info.label, info.weight, skey
                end
            end
        end
    end
    if best_label then
        return best_label, best_weight, best_key
    end
    return nil
end
local function classify_projectile(name)
    local raw = tostring(name or ""):lower()
    local key = norm_name(name)
    if IGNORE_NAMES[key] then return nil end
    if key:find("helirocket", 1, true) or key:find("helicrash", 1, true) then
        return nil
    end
    return RAID_PROJECTILE[raw] or RAID_PROJECTILE[key]
end
local function process_raid(display, x, y, z, weight)
    local now = tick_ms()
    weight = weight or 1
    local raids = cache.raids
    local best, best_d = nil, CLUSTER_MERGE_M
    for _, cl in ipairs(raids) do
        local d = dist3(x, y, z, cl.x, cl.y, cl.z)
        if d < best_d then
            best, best_d = cl, d
        end
    end
    if best then
        best.count = (best.count or 1) + 1
        best.weight = (best.weight or 1) + weight
        best.sum_x = (best.sum_x or best.x) + x
        best.sum_y = (best.sum_y or best.y) + y
        best.sum_z = (best.sum_z or best.z) + z
        best.x = best.sum_x / best.count
        best.y = best.sum_y / best.count
        best.z = best.sum_z / best.count
        best.last_type = display
        best.last_update = now
    else
        raids[#raids + 1] = {
            x = x, y = y, z = z,
            sum_x = x, sum_y = y, sum_z = z,
            count = 1,
            weight = weight,
            last_type = display,
            last_update = now,
        }
    end
    if settings.enabled(P) and settings.bool(ID_NOTIFY, true) and weight >= 2 then
        local key = string.format("%.0f:%.0f:%.0f", x * 0.1, y * 0.1, z * 0.1)
        local prev = M._last_notify[key]
        if not prev or (now - prev) > NOTIFY_DEDUP_MS then
            M._last_notify[key] = now
            notify.warning(string.format("Raid: %s at %.0f, %.0f, %.0f", display, x, y, z), 6000)
        end
    end
end
local function scan_container(container, into, now)
    if not env.is_valid(container) then return end
    for _, child in ipairs(children_of(container)) do
        if not child then goto cont end
        local name = child.Name or child.name or ""
        local cn = child.ClassName or child.class_name or ""
        local x, y, z = instance_pos(child)
        if not x then goto cont end
        local addr = tostring(child.Address or child.address or child)
        local rocket_source = rocket_source_near(x, y, z, now)
        local label, weight = raid_signal_from_inst(child, rocket_source)
        local proj_label = classify_projectile(name)
        if label then
            into[#into + 1] = {
                name = label,
                x = x, y = y, z = z,
                inst = child,
                raid = true,
            }
            if not M._processed[addr] then
                M._processed[addr] = now
                process_raid(label, x, y, z, weight)
            end
        elseif proj_label then
            into[#into + 1] = {
                name = proj_label,
                x = x, y = y, z = z,
                inst = child,
                raid = false,
            }
        elseif cn == "Explosion" and not IGNORE_NAMES[norm_name(name)] then
        end
        ::cont::
    end
end
function M.register_menu()
    local G = menu_util.G
    local T, _ = menu_util.group(G.WORLD)
    local root = menu_util.parent(P)
    menu_util.section(T, G.WORLD, "Raids")
    menu_util.register_keybind(T, G.WORLD, P, "Raid ESP", false, { colorpicker = { 1, 0.5, 0, 1 } })
    menu.add_checkbox(T, G.WORLD, ID_NOTIFY, "Raid Notifications", true, root)
    menu.add_slider_int(T, G.WORLD, ID_RANGE, "Raid ESP Range", 50, 5000, 1000, root)
    menu_util.bind_children(P, { ID_NOTIFY, ID_RANGE })
end
function M.update(_dt)
    local esp_on = settings.enabled(P)
    local map_on = settings.enabled("infernal_map_enabled") and settings.bool("infernal_map_show_raids", false)
    if not esp_on and not map_on then
        M._projectiles = {}
        M._rocket_traces = {}
        return
    end
    local now = tick_ms()
    local scan_due = (now - M._last_scan) >= SCAN_MS
    local trace_due = (now - M._last_trace_scan) >= ROCKET_TRACE_SCAN_MS
    if not scan_due and not trace_due then return end
    local ws = env.get_workspace()
    local vfx = nil
    if ws then
        vfx = env.safe_call(function()
            return ws:FindFirstChild("VFX") or ws:find_first_child("VFX")
        end)
    end
    if trace_due then
        M._last_trace_scan = now
        update_rocket_traces(vfx, now)
    end
    if not scan_due then return end
    M._last_scan = now
    for addr, t in pairs(M._processed) do
        if (now - t) > 30000 then
            M._processed[addr] = nil
        end
    end
    for i = #cache.raids, 1, -1 do
        local cl = cache.raids[i]
        if not cl or (now - (cl.last_update or 0)) > CLUSTER_TTL_MS then
            table.remove(cache.raids, i)
        end
    end
    local projectiles = {}
    if ws then
        if vfx then
            scan_container(vfx, projectiles, now)
        end
        scan_container(ws, projectiles, now)
    end
    M._projectiles = projectiles
end
function M.draw()
    if not settings.enabled(P) then return end
    local range = settings.num(ID_RANGE, 1000)
    local range_sq = range * range
    local col = settings.color(P, { 1, 0.5, 0, 1 })
    local proj_col = { 1, 0.35, 0.15, 1 }
    local text_size = esp_util.text_size()
    local me = env.get_local_player()
    local mx, my, mz = nil, nil, nil
    if me then
        mx, my, mz = esp_util.vec3_pos(me.Position or me.position or me.HeadPosition or me.head_position)
    end
    local now = tick_ms()
    for i = 1, #M._projectiles do
        local proj = M._projectiles[i]
        if not proj then goto pcont end
        local dist_sq = 0
        if mx then
            local dx, dy, dz = proj.x - mx, proj.y - my, proj.z - mz
            dist_sq = dx * dx + dy * dy + dz * dz
            if dist_sq > range_sq then goto pcont end
        end
        local sx, sy, vis = esp_util.w2s(proj.x, proj.y, proj.z)
        if vis then
            local dist = math.sqrt(dist_sq)
            local c = proj.raid and col or proj_col
            draw_util.box_esp(sx - 5, sy - 5, 10, 10, c, 0)
            draw_util.text_centered(sx, sy - text_size - 2, "[" .. tostring(proj.name) .. "]", c, text_size)
            if mx then
                draw_util.text_centered(sx, sy + 4, string.format("[%.0fm]", dist), c, text_size)
            end
        end
        ::pcont::
    end
    for i = 1, #cache.raids do
        local cl = cache.raids[i]
        if not cl then goto rcont end
        local dist_sq = 0
        if mx then
            local dx, dy, dz = cl.x - mx, cl.y - my, cl.z - mz
            dist_sq = dx * dx + dy * dy + dz * dz
            if dist_sq > range_sq then goto rcont end
        end
        local sx, sy, vis = esp_util.w2s(cl.x, cl.y, cl.z)
        if vis then
            local dist = math.sqrt(dist_sq)
            local age = math.floor((now - (cl.last_update or now)) / 1000)
            local lines = {
                string.format("Raid (%d)", cl.count or 1),
                string.format("Last: %s", tostring(cl.last_type or "Explosive")),
                string.format("Updated %ds ago", age),
            }
            if mx then
                lines[#lines + 1] = string.format("[%.0fm]", dist)
            end
            local total_h = #lines * (text_size + 2)
            local start_y = sy - total_h * 0.5
            for li = 1, #lines do
                draw_util.text_centered(sx, start_y + (li - 1) * (text_size + 2), lines[li], col, text_size)
            end
        end
        ::rcont::
    end
end
return M
end)()

Infernal._mods["features.movement.exploits"] = (function()
local menu_util = Infernal.require("core.menu_util")
local M = {}
