Infernal._mods["features.utility.farm_helper"] = (function()
-- Manual Farm Helper: while you hold left-click with a farming tool, turns the camera
-- onto the nearest weak spot (TreeX / NodeSpark) within Farm Range. Camera-only, so
-- your swings land where you are actually looking; nothing is redirected.
local settings = Infernal.require("core.settings")
local env = Infernal.require("core.env")
local farm_tools = Infernal.require("game.farm_tools")
local farm_targets = Infernal.require("game.farm_targets")
local menu_util = Infernal.require("core.menu_util")
local M = {}
local LMB = 0x01
function M.register_menu()
    local G = menu_util.G
    local T = menu_util.group(G.MISC)
    menu_util.register_keybind(T, G.MISC, "infernal_farm_helper", "Manual Farm Helper", false)
end
local function menu_open()
    local ok, ui = pcall(function() return Infernal.require("ui.custom_menu") end)
    return ok and ui and ui.is_open and ui.is_open() == true
end
local function vec(v)
    if not v then return nil end
    local x, y, z = v.X or v.x, v.Y or v.y, v.Z or v.z
    if not x then return nil end
    return { x = x, y = y, z = z }
end
function M.update(_dt)
    if not settings.enabled("infernal_farm_helper") then return end
    if settings.enabled("infernal_autofarm") or menu_open() then return end
    local down = false
    pcall(function() down = (input.is_key_down or input.IsKeyDown)(LMB) == true end)
    if not down then return end
    local tool = farm_tools.get_held_farm_tool_name()
    if not tool then return end
    local lp = env.get_local_player()
    local origin = lp and vec(lp.Position or lp.position)
    if not origin then return end
    local radius = settings.num("infernal_farm_radius", 7)
    local record = farm_targets.find_target(origin, radius, farm_tools.tool_caps(tool))
    if not record then return end
    local aim = record.weak_pos
    if not aim then
        local body = record.body_pos or record.pos
        if not body then return end
        aim = { x = body.x, y = body.y, z = body.z }
        if record.kind == "Trees" then
            local ok, cam = pcall(function() return vec((camera.get_position or camera.GetPosition)()) end)
            if ok and cam then aim.y = cam.y end
        end
    end
    -- Rotation Speed slider: 100% = instant (smooth 1), 1% = slowest (smooth 20).
    local pct = math.max(1, math.min(100, settings.num("infernal_farm_rotation", 90)))
    local smooth = 1 + (100 - pct) / 99 * 19
    local look = camera and (camera.look_at or camera.LookAt)
    if type(look) == "function" then pcall(look, aim.x, aim.y, aim.z, smooth) end
end
function M.draw() end
return M
end)()

Infernal._mods["features.utility.keybind_viewer"] = (function()
local settings = Infernal.require("core.settings")
local menu_util = Infernal.require("core.menu_util")
local draw_util = Infernal.require("core.draw_util")
local theme = Infernal.require("core.ui_theme")
local feature_bind = Infernal.require("core.feature_bind")
local vk_names = Infernal.require("core.vk_names")
local panel_drag = Infernal.require("core.panel_drag")
local overlay_theme = Infernal.require("core.overlay_theme")
local M = {}
local P = "infernal_keybinds_enabled"
local X_ID = "infernal_keybinds_x"
local Y_ID = "infernal_keybinds_y"
local PANEL_W = 282
local TITLE_H = 30
local function strip_enable_prefix(label)
    if type(label) ~= "string" then return tostring(label or "?") end
    label = label:gsub("^Enable%s+", "")
    return label
end
local function collect_rows()
    local rows = {}
    local only_active = settings.bool("infernal_keybinds_active_only", false)
    local show_unbound = settings.bool("infernal_keybinds_show_unbound", true)
    local show_mode = settings.bool("infernal_keybinds_show_mode", true)
    for _, entry in ipairs(feature_bind.list_entries()) do
        local id = entry.id
        local key = feature_bind.get_key(id)
        local active = feature_bind.active(id)
        if key <= 0 and not show_unbound then
            goto continue
        end
        if only_active and not active then
            goto continue
        end
        if feature_bind.is_hidden_from_list(id) then
            goto continue
        end
        rows[#rows + 1] = {
            id = id,
            label = strip_enable_prefix(entry.label or id),
            key = vk_names.chip(key),
            mode = feature_bind.mode_name(id),
            active = active,
            show_mode = show_mode,
        }
        ::continue::
    end
    table.sort(rows, function(a, b)
        if a.active ~= b.active then return a.active end
        return a.label < b.label
    end)
    return rows
end
function M.register_menu()
    local G = menu_util.G
    local T = menu_util.group(G.MISC)
    local root = menu_util.parent(P)
    menu.add_checkbox(T, G.MISC, P, "Keybind Viewer", false)
    menu_util.section(T, G.MISC, "Keybinds Display")
    menu.add_checkbox(T, G.MISC, "infernal_keybinds_active_only", "Only Show Active", false, root)
    menu.add_checkbox(T, G.MISC, "infernal_keybinds_show_unbound", "Show Unbound", true, root)
    menu.add_checkbox(T, G.MISC, "infernal_keybinds_show_mode", "Show Bind Mode", true, root)
    menu_util.bind_children(P, {
        "infernal_keybinds_active_only", "infernal_keybinds_show_unbound", "infernal_keybinds_show_mode",
    })
end
function M.update(_dt) end
function M.draw()
    if not settings.enabled(P) then return end
    if not draw or not draw.text then return end
    local accent = overlay_theme.accent()
    local sw, sh = draw_util.screen_size()
    local rows = collect_rows()
    local pad = 12
    local row_h = 22
    local count = math.max(#rows, 1)
    local height = TITLE_H + count * row_h + 12
    local x, y = panel_drag.update(
        "keybind_viewer",
        X_ID, Y_ID,
        PANEL_W, TITLE_H,
        sw, sh,
        16, 280
    )
    x, y = panel_drag.clamp(x, y, PANEL_W, height, sw, sh)
    local i18n = Infernal.require("ui.i18n")
    overlay_theme.draw_panel(x, y, PANEL_W, height, i18n.t("KEYBINDS"))
    local ry = y + TITLE_H + 4
    if #rows == 0 then
        draw_util.text(x + pad, ry, i18n.t("No binds"), theme.TEXT_MUTED, 11)
        return
    end
    local max_label = math.max(8, math.floor((PANEL_W - pad * 2) * 0.55 / 7))
    for i = 1, #rows do
        local row = rows[i]
        local name_col = row.active and theme.TEXT or theme.TEXT_MUTED
        local key_col = row.active and accent or theme.TEXT_DIM
        local label = i18n.t(row.label)
        if #label > max_label then label = label:sub(1, math.max(1, max_label - 2)) .. ".." end
        draw_util.text(x + pad, ry + 3, label, name_col, 11)
        local right = row.key
        if row.show_mode then
            right = right .. " - " .. row.mode
        end
        local tw = theme.text_w(right, 10)
        draw_util.text(x + PANEL_W - pad - tw, ry + 3, right, key_col, 10)
        ry = ry + row_h
    end
end
return M
end)()

Infernal._mods["features.utility.anti_afk"] = (function()
local settings = Infernal.require("core.settings")
local menu_util = Infernal.require("core.menu_util")
local M = {}
local P = "infernal_anti_afk"
local INTERVAL_MS = 14 * 60 * 1000
M._last_nudge = 0
local function now_ms()
    if utility and utility.get_tick_count then
        return utility.get_tick_count()
    end
    return math.floor(os.clock() * 1000)
end
local function nudge()
    if input and input.move_mouse then
        pcall(input.move_mouse, 1, 0)
        pcall(input.move_mouse, -1, 0)
        return true
    end
    if utility and utility.key_press then
        pcall(utility.key_press, 0x20)
        return true
    end
    if utility and utility.mouse_click then
        return false
    end
    return false
end
function M.register_menu()
    local G = menu_util.G
    local T = menu_util.group(G.MISC)
    menu.add_checkbox(T, G.MISC, P, "Anti AFK", false)
end
function M.update(_dt)
    if not settings.bool(P, false) then
        M._last_nudge = 0
        return
    end
    local now = now_ms()
    if M._last_nudge == 0 then
        M._last_nudge = now
        return
    end
    if (now - M._last_nudge) < INTERVAL_MS then
        return
    end
    M._last_nudge = now
    nudge()
end
function M.draw() end
return M
end)()

Infernal._mods["features.utility.config"] = (function()
local settings = Infernal.require("core.settings")
local menu_util = Infernal.require("core.menu_util")
local store = Infernal.require("core.config_store")
local notify = Infernal.require("core.notify")
local M = {}
local function invalidate_config_catalog()
local ok, catalog = pcall(Infernal.require, "ui.catalog")
if ok and catalog and catalog.invalidate then catalog.invalidate("config") end
end
local function profile_label()
return settings.str("infernal_cfg_profile_name", "Default")
end
local function selected_stem()
return store.active_stem()
end
function M.get_config_path(name)
return store.get_config_path(name)
end
function M.save_config(name)
store.migrate_legacy()
local ok, stem, path = store.save_config(name or profile_label())
if ok then
store.save_meta()
invalidate_config_catalog()
local file = path and path:match("([^\\]+)$") or (tostring(stem) .. ".cfg")
local folder = (path and path:find("Infernal_configs", 1, true)) and "Infernal_configs\\" or ""
notify.success(string.format('Saved "%s" -> %s%s', profile_label(), folder, file), 3500)
return true
end
notify.error("Failed to save config (could not write file)", 4000)
return false
end
function M.load_config(name)
store.migrate_legacy()
local stem = name or selected_stem()
local ok = store.load_config(stem)
if ok then
store.save_meta()
invalidate_config_catalog()
notify.success(string.format('Loaded "%s"', store.display_name(stem)), 3500)
return true
end
notify.error(string.format('Config "%s" not found', store.display_name(stem)), 3500)
return false
end
function M.delete_config(name)
store.migrate_legacy()
local stem = name or selected_stem()
local ok = store.delete_config(stem)
if ok then
store.save_meta()
invalidate_config_catalog()
notify.warning(string.format('Deleted "%s"', store.display_name(stem)), 3500)
return true
end
notify.error(string.format('Could not delete "%s"', store.display_name(stem)), 3500)
return false
end
function M.save_slot(_slot)
return M.save_config(profile_label())
end
function M.load_slot(_slot)
return M.load_config(selected_stem())
end
function M.delete_slot(_slot)
return M.delete_config(selected_stem())
end
function M.try_autoload()
return store.try_autoload()
end
function M.register_menu()
local G = menu_util.G
local T, _ = menu_util.group(G.CONFIG)
store.migrate_legacy()
store.load_meta()
menu.add_checkbox(T, G.CONFIG, "infernal_ui_startup_intro", "Startup Animation", true)
menu_util.input(T, G.CONFIG, "infernal_cfg_profile_name", "Config Name", "Default")
local labels = store.list_config_labels()
if #labels == 0 then labels = { "(no configs)" } end
menu.add_combo(T, G.CONFIG, "infernal_cfg_selected", "Saved Configs", labels, 0)
menu_util.button(T, G.CONFIG, "infernal_cfg_save", "Save Config", function()
M.save_config(profile_label())
end)
menu_util.button(T, G.CONFIG, "infernal_cfg_load", "Load Config", function()
M.load_config(selected_stem())
end)
menu_util.button(T, G.CONFIG, "infernal_cfg_delete", "Delete Config", function()
M.delete_config(selected_stem())
end)
menu_util.button(T, G.CONFIG, "infernal_cfg_refresh", "Refresh List", function()
store.migrate_legacy()
store.refresh_index()
invalidate_config_catalog()
notify.info("Config list refreshed", 2000)
end)
menu_util.gap(T, G.CONFIG)
menu.add_checkbox(T, G.CONFIG, "infernal_cfg_autoload", "Autoload on Start", false)
menu_util.input(T, G.CONFIG, "infernal_cfg_autoload_config", "Autoload Config Name", "")
menu_util.gap(T, G.CONFIG)
menu.add_slider_int(T, G.CONFIG, "infernal_esp_text_size", "ESP Text Size", 8, 24, 13)
menu.add_button(T, G.CONFIG, "infernal_reload_modules", "Reload Game Modules", function()
Infernal.require("game.bootstrap").force_reload()
notify.info("Reloading game modules...", 2500)
end)
settings.on_change("infernal_cfg_selected", function()
local _, stems = store.list_config_labels()
local idx = math.floor(tonumber(settings.num("infernal_cfg_selected", 0)) or 0)
local stem = stems[idx + 1]
if stem and menu and menu.set then
menu.set("infernal_cfg_profile_name", store.display_name(stem))
end
store.save_meta()
end)
settings.on_change("infernal_cfg_autoload", function()
store.save_meta()
end)
settings.on_change("infernal_cfg_autoload_config", function()
store.save_meta()
end)
settings.on_change("infernal_cfg_profile_name", function()
store.save_meta()
end)
menu_util.bind_master("infernal_cfg_autoload", { "infernal_cfg_autoload_config" })
end
function M.update(_dt) end
function M.draw() end
return M
end)()

