end
local function settings()
return settings_ref
end
local function hsv_to_rgb(h, s, v)
h = (h % 1) * 6
local i = math.floor(h)
local f = h - i
local p = v * (1 - s)
local q = v * (1 - f * s)
local t = v * (1 - (1 - f) * s)
if i == 0 then return v, t, p end
if i == 1 then return q, v, p end
if i == 2 then return p, v, t end
if i == 3 then return p, q, v end
if i == 4 then return t, p, v end
return v, p, q
end
function M.now()
if utility and utility.get_time then
return utility.get_time()
end
return 0
end
function M.speed()
local n = settings().num("infernal_ui_anim_speed", 40)
return clamp(n, 1, 100) * 0.028
end
function M.reduce_motion()
return settings().bool("infernal_ui_reduce_motion", false)
end
function M.motion_profile()
return clamp(math.floor(settings().num("infernal_ui_motion_profile", 1) + 0.5), 0, 2)
end
function M.motion_rate(base)
