end
function M.draw_scroll_thumb(x, y, w, h)
if not M.anim_target_enabled(M.TARGET_SCROLL) then
M.draw_flat(x, y, w, h, M.STYLE_SCROLL, M.COL_SCROLL, M.TARGET_SCROLL)
