end
function shim.set_visible(id, show)
    state.set_visible(id, show)
end
local aliases = {
    AddTab = "add_tab",
    AddGroup = "add_group",
    AddSeparator = "add_separator",
    AddLabel = "add_label",
    AddCheckbox = "add_checkbox",
    AddSliderInt = "add_slider_int",
    AddSliderFloat = "add_slider_float",
    AddCombo = "add_combo",
    AddMulticombo = "add_multicombo",
    AddColorpicker = "add_colorpicker",
    AddInput = "add_input",
    AddButton = "add_button",
    AddHotkey = "add_hotkey",
    Get = "get",
    Set = "set",
    GetColor = "get_color",
    SetColor = "set_color",
    GetKey = "get_key",
    SetKey = "set_key",
    SetCallback = "set_callback",
    SetVisible = "set_visible",
    addTab = "add_tab",
    addGroup = "add_group",
    addCheckbox = "add_checkbox",
    addSliderInt = "add_slider_int",
    addSliderFloat = "add_slider_float",
    addCombo = "add_combo",
    addMulticombo = "add_multicombo",
    addColorpicker = "add_colorpicker",
    addInput = "add_input",
    addButton = "add_button",
    addHotkey = "add_hotkey",
    getColor = "get_color",
    setColor = "set_color",
    getKey = "get_key",
    setKey = "set_key",
    setCallback = "set_callback",
    setVisible = "set_visible",
}
for alias, real in pairs(aliases) do
    shim[alias] = shim[real]
end
function M.install()
    if M.installed then return true end
    M._real = menu
    Infernal._vector_menu = M._real
    Infernal.custom_ui = true
    menu = shim
