local function circle(x, y, r, col, filled, segs)
if not draw then return end
segs = segs or 24
if filled and draw.circle_filled then
draw.circle_filled(x, y, r, col, segs)
elseif draw.circle then
draw.circle(x, y, r, col, segs, 1.5)
end
