-- Minimalist flame logo: two nested flame shapes (red, orange) with gently bowed
-- sides and a short tip that leans right. Each shape is convex (round base + two outward
-- bowed curves meeting at the tip) so it fills cleanly with PolyFilled at any size.
local function flame_shape(cx, base_y, r, tip_h, lean)
local pts = {}
local tip_x, tip_y = cx + lean, base_y - tip_h
local a0, a1 = -0.14, math.pi + 0.14
local steps = 24
for i = 0, steps do
local a = a0 + (a1 - a0) * (i / steps)
pts[#pts + 1] = { cx + math.cos(a) * r, base_y - r * 0.15 + math.sin(a) * r }
end
local function bez(p0, c, p1, n, out, skip_first)
for i = skip_first and 1 or 0, n do
local t = i / n
local u = 1 - t
out[#out + 1] = {
u * u * p0[1] + 2 * u * t * c[1] + t * t * p1[1],
u * u * p0[2] + 2 * u * t * c[2] + t * t * p1[2],
}
end
end
-- each side leaves the base along the circle's own tangent, so the joins stay smooth
-- and the outline never dents inward (it must stay convex to fill correctly)
local left, right = pts[#pts], pts[1]
local tl = { -math.sin(a1), math.cos(a1) }
local tr = { math.sin(a0), -math.cos(a0) }
local kl, kr = tip_h * 0.50, tip_h * 0.44
bez(left, { left[1] + tl[1] * kl, left[2] + tl[2] * kl }, { tip_x, tip_y }, 12, pts, true)
bez({ tip_x, tip_y }, { right[1] + tr[1] * kr, right[2] + tr[2] * kr }, right, 12, pts, true)
pts[#pts] = nil
-- convex hull (monotone chain) so the fill is always clean, even where a curve dips
table.sort(pts, function(p, q) return p[1] < q[1] or (p[1] == q[1] and p[2] < q[2]) end)
local function cross(o, a, b) return (a[1] - o[1]) * (b[2] - o[2]) - (a[2] - o[2]) * (b[1] - o[1]) end
local lower, upper = {}, {}
for i = 1, #pts do
while #lower >= 2 and cross(lower[#lower - 1], lower[#lower], pts[i]) <= 0 do lower[#lower] = nil end
lower[#lower + 1] = pts[i]
end
for i = #pts, 1, -1 do
while #upper >= 2 and cross(upper[#upper - 1], upper[#upper], pts[i]) <= 0 do upper[#upper] = nil end
upper[#upper + 1] = pts[i]
end
lower[#lower] = nil
upper[#upper] = nil
for i = 1, #upper do lower[#lower + 1] = upper[i] end
return lower
end
-- Filled shapes get a thin outline in the same color: filled polygons are drawn without
-- edge smoothing, outlines are smoothed, so the outline hides the jagged fill edge.
local function fill_poly(pts, col)
if not draw then return end
local fn = draw.poly_filled or draw.PolyFilled
if type(fn) == "function" then
pcall(fn, pts, col)
end
local outline = draw.poly_closed or draw.PolyClosed
if type(outline) == "function" then
pcall(outline, pts, col, 1.0)
elseif type(fn) ~= "function" then
path(pts, col, true, 1.5)
end
end
-- Two-tone flame icon, `size` tall and centered on (cx, cy): a red flame leaning right with an
-- orange flame inside it. Both round bases share one center, so the bottom is a single smooth
-- curve with an even red rim.
function M.fire_logo(cx, cy, size, alpha, t)
alpha = alpha or 1
t = t or 0
local S = size
-- barely-there flicker of the tips so the logo feels alive without moving around
local f = math.sin(t * 2.3) * 0.010 + math.sin(t * 3.7) * 0.006
local top = cy - S * 0.5
local bottom = cy + S * 0.5
local r = S * 0.31
local base_y = bottom - r * 0.85
fill_poly(flame_shape(cx + S * 0.03, base_y, r, base_y - top, S * (0.10 + f)), { 1, 0.30, 0.17, alpha })
local inset = S * 0.085
local r2 = r - inset
local b2 = bottom - inset - r2 * 0.85
fill_poly(flame_shape(cx + S * 0.04, b2, r2, (b2 - top) * 0.62, S * (0.07 + f * 0.7)), { 1, 0.56, 0.20, alpha })
end
-- Width of the flame for a given height, so text can sit right next to it.
function M.fire_logo_width(size)
return size * 0.72
end
return M
end)()

Infernal._mods["ui.gs_widgets"] = (function()
local theme = Infernal.require("ui.gs_theme")
local input = Infernal.require("ui.gs_input")
local state = Infernal.require("ui.gs_state")
local anim = Infernal.require("ui.gs_anim")
