local M = {}
M.active_slider = nil
M.active_slider_input = nil
M.active_input = nil
M.open_combo = nil
M.open_multi = nil
M.open_color = nil
M.listening_key = nil
M.listen_wait_lmb_up = false
M.drag_offset_x = 0
M.drag_offset_y = 0
M.dragging_window = false
M.clip = nil
M.popup_used_click = false
M.interacted = false
M._hue_cache = {}
M._list_scroll = {}
M._list_middle_drag = nil
M.LIST_MAX_VISIBLE = 8
M.wheel_consumed = false
M.block_under = false
M._color_anchor = nil
M._color_hit = nil
M.open_bind_mode = nil
M._bind_mode_anchor = nil
M._bind_mode_hit = nil
M.open_color_ctx = nil
M._color_ctx_anchor = nil
M._color_ctx_hit = nil
M._color_clipboard = nil
M._active_input_rect = nil
M._active_slider_input_rect = nil
M._slider_input_meta = {}
M._slider_edit_text = {}
M._input_repeat_at = 0
M._input_repeat_vk = nil
M.TIP_DELAY_MS = 450
M.TIP_FADE_MS = 180
M._tip_candidate = nil
M._tip_hover_id = nil
M._tip_hover_ms = 0
local LISTEN_SKIP = {
[0x10] = true,
[0x11] = true,
[0x12] = true,
}
local function begin_key_listen(id)
M.listening_key = id
M.listen_wait_lmb_up = true
end
local function end_key_listen()
M.listening_key = nil
M.listen_wait_lmb_up = false
end
local function listen_skip_vk(vk)
return LISTEN_SKIP[vk] == true
end
local function clamp(v, a, b)
if v < a then return a end
if v > b then return b end
return v
end
local function text_w(str, size)
local fn = draw and (draw.get_text_size or draw.GetTextSize)
if fn then
local w = fn(str, size or theme.FONT)
if type(w) == "number" then return w end
end
return #(tostring(str or "")) * 7
end
local function fit_text(str, max_w, size)
str = tostring(str or "")
if max_w <= 0 or text_w(str, size) <= max_w then return str end
local suffix = "..."
while #str > 0 and text_w(str .. suffix, size) > max_w do
str = str:sub(1, -2)
end
return str .. suffix
end
local function in_clip(y, h)
local c = M.clip
if not c then return true end
return y >= c.y and y + h <= c.y + c.h
end
local function stacked_metrics(y)
local label_y = y + 3
local ctrl_y = y + theme.LABEL_H + theme.LABEL_GAP
return label_y, ctrl_y, theme.CTRL_H, theme.STACKED_ROW_H
end
local function interactive(x, y, w, h)
if M.block_under then return false end
if not in_clip(y, h) then return false end
local c = M.clip
if c and not input.hover(c.x, c.y, c.w, c.h) then
return false
end
return true
end
local function ui_clicked(x, y, w, h)
if M.block_under then return false end
return input.clicked(x, y, w, h)
end
local function ui_rmb_clicked(x, y, w, h)
if M.block_under then return false end
return input.rmb_click and input.hover(x, y, w, h)
end
local function rgb_to_hsv(r, g, b)
local max = math.max(r, g, b)
local min = math.min(r, g, b)
local d = max - min
local h = 0
if d > 1e-6 then
if max == r then
h = ((g - b) / d) % 6
elseif max == g then
h = (b - r) / d + 2
else
h = (r - g) / d + 4
end
h = h / 6
if h < 0 then h = h + 1 end
end
local s = max <= 1e-6 and 0 or (d / max)
return h, s, max
end
local function hsv_to_rgb(h, s, v)
h = (h % 1) * 6
local i = math.floor(h)
local f = h - i
local p = v * (1 - s)
local q = v * (1 - f * s)
local t = v * (1 - (1 - f) * s)
if i == 0 then return v, t, p end
if i == 1 then return q, v, p end
if i == 2 then return p, v, t end
if i == 3 then return p, q, v end
if i == 4 then return t, p, v end
return v, p, q
end
function M.begin_popups()
M.popup_used_click = false
M.interacted = false
M.wheel_consumed = false
M._color_anchor = nil
M._bind_mode_anchor = nil
M._color_ctx_anchor = nil
M._active_input_rect = nil
M._active_slider_input_rect = nil
M._tip_candidate = nil
if not input.mmb then M._list_middle_drag = nil end
M.block_under = false
if M.open_color and M._color_hit then
local r = M._color_hit
if input.hover(r.x, r.y, r.w, r.h) then
M.block_under = true
if input.lmb or input.lmb_click or input.rmb or input.rmb_click then
M.interacted = true
M.popup_used_click = true
end
end
end
if M.open_bind_mode and M._bind_mode_hit then
local r = M._bind_mode_hit
if input.hover(r.x, r.y, r.w, r.h) then
M.block_under = true
if input.lmb or input.lmb_click or input.rmb or input.rmb_click then
M.interacted = true
M.popup_used_click = true
end
end
end
if M.open_color_ctx and M._color_ctx_hit then
local r = M._color_ctx_hit
if input.hover(r.x, r.y, r.w, r.h) then
M.block_under = true
if input.lmb or input.lmb_click or input.rmb or input.rmb_click then
M.interacted = true
M.popup_used_click = true
end
end
end
end
local function mark_interacted()
M.interacted = true
M.popup_used_click = true
end
local function close_color_ctx()
M.open_color_ctx = nil
M._color_ctx_anchor = nil
M._color_ctx_hit = nil
end
local function copy_color_value(col)
if type(col) ~= "table" then
return { 1, 1, 1, 1 }
end
return {
tonumber(col[1]) or 1,
tonumber(col[2]) or 1,
tonumber(col[3]) or 1,
tonumber(col[4]) or 1,
}
end
local function apply_copied_color(id, col)
local next_col = copy_color_value(col)
state.set_color(id, next_col)
M._hue_cache[id] = select(1, rgb_to_hsv(next_col[1], next_col[2], next_col[3]))
if id == "infernal_ui_accent" then
anim.sync_theme()
end
end
local function open_color_popup(id, anchor_x, anchor_y, row_w)
if M.open_color == id then
M.open_color = nil
M._color_anchor = nil
M._color_hit = nil
else
M.open_color = id
M.open_combo = nil
M.open_multi = nil
M.open_bind_mode = nil
M._bind_mode_hit = nil
close_color_ctx()
M._color_anchor = { id = id, x = anchor_x, y = anchor_y, w = row_w or 160 }
end
end
local function open_bind_mode_popup(id, anchor_x, anchor_y, chip_w)
if M.open_bind_mode == id then
M.open_bind_mode = nil
M._bind_mode_anchor = nil
M._bind_mode_hit = nil
else
M.open_bind_mode = id
M.open_combo = nil
M.open_multi = nil
M.open_color = nil
M._color_hit = nil
close_color_ctx()
M._bind_mode_anchor = { id = id, x = anchor_x, y = anchor_y, w = chip_w or 56 }
end
end
local function open_color_ctx_popup(id, anchor_x, anchor_y, swatch_w)
if M.open_color_ctx == id then
close_color_ctx()
else
M.open_color_ctx = id
M.open_combo = nil
M.open_multi = nil
M.open_color = nil
M._color_hit = nil
M.open_bind_mode = nil
M._bind_mode_hit = nil
M._color_ctx_anchor = { id = id, x = anchor_x, y = anchor_y, w = swatch_w or 16 }
end
end
local function handle_color_swatch(id, swatch_x, swatch_y, swatch_w, swatch_h, row_x, row_y, row_w, col)
local hit_x, hit_y, hit_w, hit_h = swatch_x - 2, swatch_y - 2, swatch_w + 4, swatch_h + 4
if ui_rmb_clicked(hit_x, hit_y, hit_w, hit_h) then
mark_interacted()
open_color_ctx_popup(id, swatch_x, swatch_y, swatch_w)
return true
end
if ui_clicked(hit_x, hit_y, hit_w, hit_h) then
mark_interacted()
close_color_ctx()
local hh = rgb_to_hsv(col[1] or 1, col[2] or 1, col[3] or 1)
M._hue_cache[id] = hh
open_color_popup(id, row_x, row_y, row_w)
return true
end
if M.open_color == id then
M._color_anchor = { id = id, x = row_x, y = row_y, w = row_w }
end
if M.open_color_ctx == id then
M._color_ctx_anchor = { id = id, x = swatch_x, y = swatch_y, w = swatch_w }
end
return false
end
local function list_scroll_for(id, count, max_vis)
max_vis = max_vis or M.LIST_MAX_VISIBLE
local max_off = math.max(0, count - max_vis)
local off = M._list_scroll[id] or 0
if off < 0 then off = 0 end
if off > max_off then off = max_off end
M._list_scroll[id] = off
return off, max_off, math.min(count, max_vis)
end
local LIST_SCROLL_EDGE = 22
local function apply_list_wheel_scroll(id, count, max_vis, list_x, list_y, list_w, list_h)
max_vis = max_vis or M.LIST_MAX_VISIBLE
local max_off = math.max(0, count - max_vis)
if max_off <= 0 then return end
local off = M._list_scroll[id] or 0
local drag = M._list_middle_drag
if drag and drag.id == id then
if input.mmb then
local raw_rows = (drag.start_y - input.my) / 18
local rows = raw_rows >= 0 and math.floor(raw_rows) or math.ceil(raw_rows)
off = drag.start_off + rows
M.wheel_consumed = true
M.interacted = true
else
M._list_middle_drag = nil
drag = nil
end
end
if not input.hover(list_x, list_y, list_w, list_h) and not (drag and drag.id == id) then
return
end
if input.mmb_click and not M._list_middle_drag then
M._list_middle_drag = {
id = id,
start_y = input.my,
start_off = off,
}
M.wheel_consumed = true
M.interacted = true
end
if not M.wheel_consumed then
if input.wheel ~= 0 then
off = off - input.wheel
M.wheel_consumed = true
elseif input.my < list_y + LIST_SCROLL_EDGE then
off = off - 1
elseif input.my > list_y + list_h - LIST_SCROLL_EDGE then
off = off + 1
end
end
if off < 0 then off = 0 end
if off > max_off then off = max_off end
M._list_scroll[id] = off
end
local function frame_dt()
if utility and utility.get_delta_time then
local dt = utility.get_delta_time()
if dt and dt > 0 and dt < 0.25 then return dt end
end
return 0.016
end
function M.register_tooltip_hover(id, tip, x, y, w, h)
if not id or not tip or tip == "" then return end
if M.block_under then return end
if not in_clip(y, h) then return end
if input.hover(x, y, w, h) then
M._tip_candidate = { id = id, tip = tip, x = x, y = y, w = w, h = h }
end
end
function M.end_tooltip_frame()
local c = M._tip_candidate
if c and c.id == M._tip_hover_id then
M._tip_hover_ms = M._tip_hover_ms + frame_dt() * 1000
else
M._tip_hover_id = c and c.id or nil
M._tip_hover_ms = 0
end
M._tip_active = c
end
local function wrap_tip_lines(text, max_w, fs)
text = tostring(text or "")
local lines = {}
local line = ""
for word in text:gmatch("%S+") do
local test = line == "" and word or (line .. " " .. word)
if text_w(test, fs) > max_w and line ~= "" then
lines[#lines + 1] = line
line = word
else
line = test
end
end
if line ~= "" then
lines[#lines + 1] = line
end
return #lines > 0 and lines or { text }
end
function M.draw_tooltip_overlay()
if M.block_under or M.open_color or M.open_bind_mode then
return
end
if not M._tip_active or M._tip_hover_ms < M.TIP_DELAY_MS then
return
end
local fade = math.min(1, (M._tip_hover_ms - M.TIP_DELAY_MS) / M.TIP_FADE_MS)
fade = fade * fade * (3 - 2 * fade)
if fade <= 0.01 then return end
local anchor = M._tip_active
local fs = 11
local pad = 8
local max_line_w = 228
local lines = wrap_tip_lines(anchor.tip, max_line_w, fs)
local tw = 0
for i = 1, #lines do
tw = math.max(tw, text_w(lines[i], fs))
end
local box_w = math.min(260, tw + pad * 2)
local box_h = #lines * 13 + pad * 2
local tx = anchor.x + anchor.w * 0.5 - box_w * 0.5
local ty = anchor.y + anchor.h + 6
local sw, sh = 1920, 1080
if draw and draw.get_screen_size then
sw, sh = draw.get_screen_size()
end
tx = math.max(8, math.min(tx, sw - box_w - 8))
if ty + box_h > sh - 8 then
ty = anchor.y - box_h - 6
end
ty = math.max(8, ty)
local bg = theme.alpha(theme.PANEL_RAISED, 0.96 * fade)
local border = theme.alpha(theme.BORDER, 0.55 * fade)
local accent = theme.alpha(theme.ACCENT, fade)
M.rect(tx, ty, box_w, box_h, bg, true, theme.CORNER_SMALL)
M.rect(tx, ty, box_w, box_h, border, false, theme.CORNER_SMALL)
M.rect(tx + 1, ty + 1, box_w - 2, 2, accent, true)
for i = 1, #lines do
local col = theme.alpha(i == 1 and theme.TEXT or theme.TEXT_DIM, fade)
M.text(tx + pad, ty + pad + (i - 1) * 13, lines[i], col, fs)
end
end
function M.end_popups()
if input.lmb_click and M.active_slider_input and M._active_slider_input_rect then
local r = M._active_slider_input_rect
if not input.hover(r.x, r.y, r.w, r.h) then
M.commit_slider_input()
end
end
if input.lmb_click and M.active_input and M._active_input_rect then
local r = M._active_input_rect
if not input.hover(r.x, r.y, r.w, r.h) then
M.active_input = nil
end
end
if (input.lmb_click or input.rmb_click) and not M.popup_used_click then
if M.open_combo or M.open_multi or M.open_color or M.open_bind_mode or M.open_color_ctx then
M.open_combo = nil
M.open_multi = nil
M.open_color = nil
M.open_bind_mode = nil
M.open_color_ctx = nil
M._color_anchor = nil
M._color_hit = nil
M._bind_mode_anchor = nil
M._bind_mode_hit = nil
M._color_ctx_anchor = nil
M._color_ctx_hit = nil
end
end
end
function M.draw_color_overlay()
if not M.open_color then
M._color_hit = nil
return
end
local id = M.open_color
local col = state.get_color(id, { 1, 1, 1, 1 })
local pw, ph = 168, 138
local ax = M._color_anchor
local px, py
if ax and ax.id == id then
px = ax.x + (ax.w or 160) - pw
py = ax.y + theme.ROW_H + 2
else
px = input.mx + 12
py = input.my + 12
end
local sw, sh = 1920, 1080
if draw and draw.get_screen_size then
sw, sh = draw.get_screen_size()
end
if px < 4 then px = 4 end
if py < 4 then py = 4 end
if px + pw > sw - 4 then px = sw - pw - 4 end
if py + ph > sh - 4 then py = sh - ph - 4 end
M._color_hit = { x = px, y = py, w = pw, h = ph }
M.draw_color_picker(px, py, pw, ph, id, col)
if input.hover(px, py, pw, ph) then
if input.lmb or input.lmb_click or input.rmb or input.rmb_click then
mark_interacted()
end
end
end
function M.draw_bind_mode_overlay()
if not M.open_bind_mode then
M._bind_mode_hit = nil
return
end
local id = M.open_bind_mode
local i18n = Infernal.require("ui.i18n")
local modes = i18n.modes()
local mode_id = id .. "_mode"
local cur = tonumber(state.get(mode_id, 2)) or 2
local feature_bind = nil
pcall(function()
feature_bind = Infernal.require("core.feature_bind")
end)
local show_hide = feature_bind and feature_bind.is_registered(id)
local hide_id = show_hide and feature_bind.hide_key_id(id) or nil
local hidden = show_hide and state.get(hide_id, false) == true
local pw = show_hide and 190 or 112
local header_h = 24
local row_h = 22
local footer_h = show_hide and 32 or 0
local ph = header_h + #modes * row_h + footer_h + 5
local ax = M._bind_mode_anchor
local px, py
if ax and ax.id == id then
px = ax.x + (ax.w or 56) - pw
py = ax.y + 18
else
px = input.mx
py = input.my + 8
end
local sw, sh = 1920, 1080
if draw and draw.get_screen_size then
sw, sh = draw.get_screen_size()
end
if px < 4 then px = 4 end
if py < 4 then py = 4 end
if px + pw > sw - 4 then px = sw - pw - 4 end
if py + ph > sh - 4 then py = sh - ph - 4 end
M._bind_mode_hit = { x = px, y = py, w = pw, h = ph }
M.rect(px, py, pw, ph, theme.OVERLAY, true, theme.CORNER_SMALL)
M.rect(px, py, pw, ph, theme.BORDER_SOFT, false, theme.CORNER_SMALL)
M.text(px + 9, py + 6, i18n.t("KEYBIND SETTINGS"), theme.TEXT_TITLE, theme.FONT_CAPTION)
M.rect(px + 8, py + header_h - 1, pw - 16, 1, theme.BORDER_SOFT, true)
for i, name in ipairs(modes) do
local iy = py + header_h + (i - 1) * row_h
local selected = (cur == i - 1)
if input.hover(px, iy, pw, row_h) then
M.rect(px + 5, iy + 2, pw - 10, row_h - 4, theme.HOVER, true, theme.CORNER_SMALL)
end
if selected then
M.rect(px + 5, iy + 2, pw - 10, row_h - 4,
theme.alpha(theme.FOCUS, 0.18), true, theme.CORNER_SMALL)
anim.draw_tab_indicator(px + 5, iy + 5, 2, row_h - 10)
end
local dot_x = px + pw - 15
local dot_y = iy + math.floor(row_h * 0.5)
M.text(px + 13, iy + 4, name, selected and theme.TEXT_ACTIVE or theme.TEXT, theme.FONT_SMALL)
if draw and draw.circle then
draw.circle(dot_x, dot_y, 4, selected and theme.FOCUS or theme.BORDER, 12, 1)
end
if selected and draw and draw.circle_filled then
draw.circle_filled(dot_x, dot_y, 2, anim.checkbox_fill(), 10)
end
if input.clicked(px, iy, pw, row_h) then
mark_interacted()
state.set(mode_id, i - 1)
M.open_bind_mode = nil
M._bind_mode_hit = nil
end
end
if show_hide then
state.define(hide_id, false)
local footer_y = py + header_h + #modes * row_h
M.rect(px + 8, footer_y, pw - 16, 1, theme.BORDER_SOFT, true)
local hide_y = footer_y + 3
local hide_h = footer_h - 4
if input.hover(px, hide_y, pw, hide_h) then
M.rect(px + 5, hide_y + 2, pw - 10, hide_h - 4, theme.HOVER, true, theme.CORNER_SMALL)
end
local box = theme.CHECK_SIZE
local bx = px + 11
local by = hide_y + math.floor((hide_h - box) * 0.5)
M.rect(bx, by, box, box, theme.CHECK_OFF, true, theme.CORNER_SMALL)
M.rect(bx, by, box, box, hidden and theme.FOCUS or theme.BORDER_SOFT, false, theme.CORNER_SMALL)
if hidden then
M.rect(bx + 2, by + 2, box - 4, box - 4, anim.checkbox_fill(), true, theme.CORNER_SMALL)
end
M.text(bx + box + 8, hide_y + 7, i18n.t("Hide from keybind list"),
hidden and theme.TEXT_ACTIVE or theme.TEXT, theme.FONT_SMALL)
if input.clicked(px, hide_y, pw, hide_h) then
mark_interacted()
state.set(hide_id, not hidden)
end
end
if input.hover(px, py, pw, ph) and (input.lmb_click or input.rmb_click) then
mark_interacted()
end
end
function M.draw_color_ctx_overlay()
if not M.open_color_ctx then
M._color_ctx_hit = nil
return
end
local id = M.open_color_ctx
local has_clip = type(M._color_clipboard) == "table"
local i18n = Infernal.require("ui.i18n")
local items = {
{ id = "copy", label = i18n.t("Copy Color"), enabled = true },
{ id = "paste", label = i18n.t("Paste Color"), enabled = has_clip },
}
local pw = 118
local header_h = 24
local row_h = 22
local ph = header_h + #items * row_h + 5
local ax = M._color_ctx_anchor
local px, py
if ax and ax.id == id then
px = ax.x + (ax.w or 12) - pw
py = ax.y + 14
else
px = input.mx
py = input.my + 8
end
local sw, sh = 1920, 1080
if draw and draw.get_screen_size then
sw, sh = draw.get_screen_size()
end
if px < 4 then px = 4 end
if py < 4 then py = 4 end
if px + pw > sw - 4 then px = sw - pw - 4 end
if py + ph > sh - 4 then py = sh - ph - 4 end
M._color_ctx_hit = { x = px, y = py, w = pw, h = ph }
M.rect(px, py, pw, ph, theme.OVERLAY, true, theme.CORNER_SMALL)
M.rect(px, py, pw, ph, theme.BORDER_SOFT, false, theme.CORNER_SMALL)
M.text(px + 9, py + 6, i18n.t("COLOR"), theme.TEXT_TITLE, theme.FONT_CAPTION)
M.rect(px + 8, py + header_h - 1, pw - 16, 1, theme.BORDER_SOFT, true)
if has_clip then
local clip = M._color_clipboard
local chip = 10
local cx = px + pw - chip - 10
local cy = py + 7
M.rect(cx, cy, chip, chip, clip, true, 2)
M.rect(cx, cy, chip, chip, theme.BORDER, false, 2)
end
for i, item in ipairs(items) do
local iy = py + header_h + (i - 1) * row_h
local hot = item.enabled and input.hover(px, iy, pw, row_h)
if hot then
M.rect(px + 5, iy + 2, pw - 10, row_h - 4, theme.HOVER, true, theme.CORNER_SMALL)
end
local label_col = item.enabled and (hot and theme.TEXT_ACTIVE or theme.TEXT) or theme.TEXT_DIM
M.text(px + 13, iy + 4, item.label, label_col, theme.FONT_SMALL)
if item.enabled and input.clicked(px, iy, pw, row_h) then
mark_interacted()
if item.id == "copy" then
M._color_clipboard = copy_color_value(state.get_color(id, { 1, 1, 1, 1 }))
elseif item.id == "paste" and has_clip then
apply_copied_color(id, M._color_clipboard)
end
close_color_ctx()
end
end
if input.hover(px, py, pw, ph) and (input.lmb_click or input.rmb_click) then
mark_interacted()
end
end
function M.vk_name(vk)
return Infernal.require("core.vk_names").label(vk)
end
function M.rect(x, y, w, h, col, filled, rounding)
if not draw then return end
local c = M.clip
if c then
local x2 = x + w
local y2 = y + h
local cx = c.x
local cy = c.y
local cx2 = c.x + c.w
local cy2 = c.y + c.h
if x2 <= cx or y2 <= cy or x >= cx2 or y >= cy2 then return end
if x < cx then
w = w - (cx - x)
x = cx
end
if y < cy then
h = h - (cy - y)
y = cy
end
if x + w > cx2 then w = cx2 - x end
if y + h > cy2 then h = cy2 - y end
if w <= 0 or h <= 0 then return end
end
local fill = draw.rect_filled or draw.RectFilled
local outline = draw.rect or draw.Rect
if filled and fill then
fill(x, y, w, h, col, rounding or 0)
elseif not filled and outline then
outline(x, y, w, h, col, rounding or 0, 1)
end
end
function M.text(x, y, str, col, size)
local fn = draw and (draw.text or draw.Text)
if fn then
fn(x, y, tostring(str), col, size or theme.FONT)
end
end
function M.rainbow_bar(x, y, w, h)
anim.draw_title_bar(x, y, w, h)
end
function M.group_box(x, y, w, h, title)
local c = M.clip
if c then
local top = math.max(y, c.y)
local bot = math.min(y + h, c.y + c.h)
if bot <= top then return end
M.rect(x, top, w, bot - top, theme.PANEL, true)
M.rect(x, top, w, bot - top, theme.BORDER, false)
if y >= c.y - 2 and y < c.y + c.h then
M.text(x + 12, y + 5, title, theme.TEXT_ACTIVE, theme.FONT_TITLE)
end
return
end
M.rect(x, y, w, h, theme.PANEL, true)
M.rect(x, y, w, h, theme.BORDER, false)
M.text(x + 12, y + 5, title, theme.TEXT_ACTIVE, theme.FONT_TITLE)
end
local LISTEN_SIDE_MODS = { 0xA0, 0xA1, 0xA2, 0xA3, 0xA4, 0xA5 }
local LISTEN_VKS = {}
for i = 1, #LISTEN_SIDE_MODS do
LISTEN_VKS[#LISTEN_VKS + 1] = LISTEN_SIDE_MODS[i]
end
local SIDE_MOD_SET = {
[0xA0] = true, [0xA1] = true, [0xA2] = true,
[0xA3] = true, [0xA4] = true, [0xA5] = true,
}
for vk = 0x01, 0xFE do
if not SIDE_MOD_SET[vk] then
LISTEN_VKS[#LISTEN_VKS + 1] = vk
end
end
local function assign_listen_key(vk)
local id = M.listening_key
state.set_key(id, vk)
local mode_id = id .. "_mode"
local mode = state.get(mode_id, nil)
if mode ~= nil and tonumber(mode) == 0 then
state.set(mode_id, 2)
end
end_key_listen()
end
local MODIFIER_PAIRS = {
{ generic = 0x10, left = 0xA0, right = 0xA1 },
{ generic = 0x11, left = 0xA2, right = 0xA3 },
{ generic = 0x12, left = 0xA4, right = 0xA5 },
}
local function try_capture_modifier()
for i = 1, #MODIFIER_PAIRS do
local p = MODIFIER_PAIRS[i]
local l_down = input.key_down(p.left)
local r_down = input.key_down(p.right)
local g_down = input.key_down(p.generic)
if l_down or r_down or g_down then
local edge = input.key_pressed(p.left)
or input.key_pressed(p.right)
or input.key_pressed(p.generic)
if edge then
if l_down and not r_down then
assign_listen_key(p.left)
return true
end
if r_down and not l_down then
assign_listen_key(p.right)
return true
end
if l_down then
assign_listen_key(p.left)
return true
end
if r_down then
assign_listen_key(p.right)
return true
end
assign_listen_key(p.generic)
return true
end
end
end
return false
end
function M.tick_key_listen()
if not M.listening_key then
M.listen_wait_lmb_up = false
return
end
if input.key_pressed(0x1B)
or input.key_pressed(0x08)
or input.key_pressed(0x2E)
then
state.set_key(M.listening_key, 0)
end_key_listen()
return
end
if M.listen_wait_lmb_up then
if not (input.lmb or input.key_down(0x01)) then
M.listen_wait_lmb_up = false
else
if try_capture_modifier() then
return
end
for i = 1, #LISTEN_VKS do
local vk = LISTEN_VKS[i]
if vk ~= 0x01 and not listen_skip_vk(vk) and input.key_pressed(vk) then
assign_listen_key(vk)
return
end
end
return
end
end
if try_capture_modifier() then
return
end
for i = 1, #LISTEN_VKS do
local vk = LISTEN_VKS[i]
if not listen_skip_vk(vk) and input.key_pressed(vk) then
assign_listen_key(vk)
return
end
end
end
local INPUT_VKS = {
0x20,
0x30, 0x31, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37, 0x38, 0x39,
0x41, 0x42, 0x43, 0x44, 0x45, 0x46, 0x47, 0x48, 0x49, 0x4A, 0x4B, 0x4C, 0x4D,
0x4E, 0x4F, 0x50, 0x51, 0x52, 0x53, 0x54, 0x55, 0x56, 0x57, 0x58, 0x59, 0x5A,
0xBA, 0xBB, 0xBC, 0xBD, 0xBE, 0xBF, 0xC0, 0xDB, 0xDC, 0xDD, 0xDE,
}
local INPUT_SHIFT = {
[0x30] = ")", [0x31] = "!", [0x32] = "@", [0x33] = "#", [0x34] = "$",
[0x35] = "%", [0x36] = "^", [0x37] = "&", [0x38] = "*", [0x39] = "(",
[0xBA] = ":", [0xBB] = "+", [0xBC] = "<", [0xBD] = "_", [0xBE] = ">",
[0xBF] = "?", [0xC0] = "~", [0xDB] = "{", [0xDC] = "|", [0xDD] = "}",
[0xDE] = "\"",
}
local INPUT_PLAIN = {
[0x20] = " ",
[0x30] = "0", [0x31] = "1", [0x32] = "2", [0x33] = "3", [0x34] = "4",
[0x35] = "5", [0x36] = "6", [0x37] = "7", [0x38] = "8", [0x39] = "9",
[0xBA] = ";", [0xBB] = "=", [0xBC] = ",", [0xBD] = "-", [0xBE] = ".",
[0xBF] = "/", [0xC0] = "`", [0xDB] = "[", [0xDC] = "\\", [0xDD] = "]",
[0xDE] = "'",
}
local function tick_ms()
return utility and utility.get_tick_count and utility.get_tick_count() or 0
end
local function vk_to_char(vk)
local shift = input.key_down(0x10)
if vk >= 0x41 and vk <= 0x5A then
local ch = string.char(vk)
return shift and ch or string.lower(ch)
end
if shift then
return INPUT_SHIFT[vk] or INPUT_PLAIN[vk]
end
return INPUT_PLAIN[vk]
end
local function input_key_repeat(vk)
if input.key_pressed(vk) then
M._input_repeat_vk = vk
M._input_repeat_at = tick_ms() + 400
return true
end
if M._input_repeat_vk ~= vk or not input.key_down(vk) then
return false
end
local now = tick_ms()
if now >= M._input_repeat_at then
M._input_repeat_at = now + 35
return true
end
return false
end
local function focus_input(id)
M.active_input = id
M.active_slider_input = nil
M.open_combo = nil
M.open_multi = nil
M.open_color = nil
M.open_bind_mode = nil
end_key_listen()
M._input_repeat_vk = nil
end
function M.focus_text_input(id)
focus_input(id)
end
function M.blur_text_input(id)
if id == nil or M.active_input == id then
M.active_input = nil
M._active_input_rect = nil
M._input_repeat_vk = nil
end
end
local SLIDER_INPUT_VKS = {
0x30, 0x31, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37, 0x38, 0x39,
0x60, 0x61, 0x62, 0x63, 0x64, 0x65, 0x66, 0x67, 0x68, 0x69,
0xBD, 0x6D, 0xBE, 0x6E,
}
local function slider_vk_to_char(vk)
if vk >= 0x30 and vk <= 0x39 then
return string.char(vk)
end
if vk >= 0x60 and vk <= 0x69 then
return string.char(vk - 0x30)
end
if vk == 0xBD or vk == 0x6D then return "-" end
if vk == 0xBE or vk == 0x6E then return "." end
return nil
end
local function slider_char_allowed(text, ch, is_float, minv)
if ch:match("%d") then return true end
if ch == "-" and minv < 0 and text == "" then return true end
if is_float and ch == "." and not text:find(".", 1, true) then return true end
return false
end
local function parse_slider_text(text, meta)
if not meta then return nil end
text = tostring(text or ""):match("^%s*(.-)%s*$") or ""
if text == "" or text == "-" or text == "." or text == "-." then return nil end
local n = tonumber(text)
if not n then return nil end
if not meta.float then
n = math.floor(n + 0.5)
end
return clamp(n, meta.min, meta.max)
end
function M.commit_slider_input()
local id = M.active_slider_input
if not id then return end
local meta = M._slider_input_meta[id]
local n = parse_slider_text(M._slider_edit_text[id], meta)
if n ~= nil then
state.set(id, n)
end
M.active_slider_input = nil
M._active_slider_input_rect = nil
M._input_repeat_vk = nil
end
function M.cancel_slider_input()
M.active_slider_input = nil
M._active_slider_input_rect = nil
M._input_repeat_vk = nil
end
function M.begin_slider_input(id, minv, maxv, is_float, val, fmt)
M.active_slider_input = id
M.active_slider = nil
M.active_input = nil
M.open_combo = nil
M.open_multi = nil
M.open_color = nil
M.open_bind_mode = nil
end_key_listen()
M._input_repeat_vk = nil
fmt = fmt or (is_float and "%.2f" or "%d")
M._slider_input_meta[id] = {
min = minv,
max = maxv,
float = is_float == true,
fmt = fmt,
}
M._slider_edit_text[id] = string.format(fmt, val)
end
function M.tick_slider_input()
if not M.active_slider_input or M.listening_key then return end
if input.key_down(0x11) or input.key_down(0x12) then return end
local id = M.active_slider_input
local meta = M._slider_input_meta[id]
if not meta then
M.cancel_slider_input()
return
end
local val = tostring(M._slider_edit_text[id] or "")
if input.key_pressed(0x1B) then
M.cancel_slider_input()
return
end
if input.key_pressed(0x0D) then
M.commit_slider_input()
return
end
if input_key_repeat(0x08) or input_key_repeat(0x2E) then
if #val > 0 then
M._slider_edit_text[id] = val:sub(1, -2)
end
return
end
for i = 1, #SLIDER_INPUT_VKS do
local vk = SLIDER_INPUT_VKS[i]
if input_key_repeat(vk) then
local ch = slider_vk_to_char(vk)
if ch and slider_char_allowed(val, ch, meta.float, meta.min) then
M._slider_edit_text[id] = val .. ch
end
M._input_repeat_vk = nil
return
end
end
end
function M.tick_text_input()
if not M.active_input or M.listening_key then return end
if input.key_down(0x11) or input.key_down(0x12) then return end
local id = M.active_input
local val = tostring(state.get(id, ""))
if input.key_pressed(0x1B) or input.key_pressed(0x0D) then
M.active_input = nil
M._input_repeat_vk = nil
return
end
if input_key_repeat(0x08) then
if #val > 0 then
state.set(id, val:sub(1, -2))
end
return
end
if input_key_repeat(0x2E) then
if #val > 0 then
state.set(id, val:sub(1, -2))
end
return
end
for i = 1, #INPUT_VKS do
local vk = INPUT_VKS[i]
if input.key_pressed(vk) then
local ch = vk_to_char(vk)
if ch then
state.set(id, val .. ch)
end
M._input_repeat_vk = nil
return
end
end
end
-- Fatality-style rows: label on the left, a compact control on the right, soft corners.
local function row_text_y(y, h, size)
return y + math.floor((h - (size or theme.FONT)) * 0.5) - 1
end
local function ctrl_width(w)
return math.max(70, math.floor(w * 0.46))
end
local function label_color(opts, active)
if opts and opts.risky then return theme.RISKY or { 1, 0.63, 0.36, 1 } end
return active and theme.TEXT_ACTIVE or theme.TEXT
end
local function round_for(wd, ht, r)
return math.max(0, math.min(r, math.floor(math.min(wd, ht) * 0.5)))
end
local function chevron(cx, cy, open, col)
local line = draw and (draw.line or draw.Line)
if not line then return end
if open then
line(cx - 3, cy + 1.5, cx, cy - 1.5, col, 1.4)
line(cx, cy - 1.5, cx + 3, cy + 1.5, col, 1.4)
else
line(cx - 3, cy - 1.5, cx, cy + 1.5, col, 1.4)
line(cx, cy + 1.5, cx + 3, cy - 1.5, col, 1.4)
end
end
local function key_chip(id, x_right, y, h, listening, mode_open)
local vk = state.get_key(id)
local klabel = listening and "..." or (vk and vk ~= 0 and M.vk_name(vk) or "-")
local fs = theme.FONT_TINY or theme.FONT_SMALL
local cw = math.max(26, text_w(klabel, fs) + 12)
local ch = math.max(14, fs + 4)
local kx = x_right - cw
local ky = y + math.floor((h - ch) * 0.5)
local hot = input.hover(kx, ky, cw, ch)
local on = listening or mode_open
local bg = on and theme.alpha(theme.ACCENT, 0.22) or (hot and theme.ELEM_HOVER or theme.ELEM)
M.rect(kx, ky, cw, ch, bg, true, 3)
M.rect(kx, ky, cw, ch, on and theme.alpha(theme.ACCENT, 0.7) or theme.LINE, false, 3)
local tcol = on and theme.TEXT_ACTIVE or theme.TEXT_DIM
M.text(kx + (cw - text_w(klabel, fs)) * 0.5, ky + math.floor((ch - fs) * 0.5) - 1, klabel, tcol, fs)
return kx, ky, cw, ch
end
function M.checkbox(x, y, w, id, label, opts)
opts = opts or {}
if id and not state.is_visible(id) then
return 0
end
state.define(id, opts.default == true)
if opts.color then
state.define_color(id, opts.color)
end
local on = state.get(id, false) == true
local h = theme.ROW_H
if not in_clip(y, h) then return h end
local hovered = input.hover(x, y, w, h)
local on_t = anim.transition("check-on:" .. tostring(id), on, anim.motion_rate(22))
local hov_t = anim.transition("check-hover:" .. tostring(id), hovered, 16)
local box = theme.CHECK_SIZE
local bx = x + w - box - 6
local by = y + math.floor((h - box) * 0.5)
M.rect(bx, by, box, box, anim.mix(theme.CHECK_FILL, theme.CHECK_FILL_HOT, hov_t), true, 3)
if on_t > 0.01 then
M.rect(bx - 2, by - 2, box + 4, box + 4, theme.alpha(theme.ACCENT, 0.16 * on_t), true, 5)
local inset = (1 - on_t) * box * 0.5
local fw = box - inset * 2
M.rect(bx + inset, by + inset, fw, fw, theme.alpha(anim.checkbox_fill(), on_t), true, round_for(fw, fw, 3))
end
M.rect(bx, by, box, box, on and theme.alpha(theme.ACCENT, 0.55 + 0.35 * on_t) or theme.CHECK_EDGE, false, 3)
local has_color = not opts.hide_color and (opts.color or state.colors[id])
local right_x = bx - 6
local swatch_clicked = false
if has_color then
local col = state.get_color(id, opts.color or { 1, 1, 1, 1 })
local sx = right_x - box
M.rect(sx, by, box, box, col, true, 3)
M.rect(sx, by, box, box, theme.LINE, false, 3)
swatch_clicked = handle_color_swatch(id, sx, by, box, box, x, y, w, col)
right_x = sx - 6
end
right_x = right_x - (opts.reserve_right or 0)
M.text(x + 8, row_text_y(y, h, theme.FONT), fit_text(label, right_x - x - 12, theme.FONT),
label_color(opts, on), theme.FONT)
local clicked = ui_clicked(x, y, right_x - x, h) or ui_clicked(bx - 4, y, box + 10, h)
if not swatch_clicked and interactive(x, y, w, h) and clicked then
mark_interacted()
state.toggle(id)
pcall(function()
Infernal.require("core.menu_util").sync_master(id)
end)
end
M._last_check_right = right_x + (opts.reserve_right or 0)
return h
end
function M.slider(x, y, w, id, label, minv, maxv, default, opts)
opts = opts or {}
if id and not state.is_visible(id) then return 0 end
local is_float = opts.float == true
state.define(id, default)
local val = tonumber(state.get(id, default)) or default
local h = theme.ROW_H
if not in_clip(y, h) then return h end
local editing = M.active_slider_input == id
if editing then
M._active_slider_input_rect = { x = x, y = y, w = w, h = h }
end
local bw = ctrl_width(w)
local bh = theme.SLIDER_H
local bx = x + w - bw - 6
local by = y + math.floor((h - bh) * 0.5)
M.text(x + 8, row_text_y(y, h, theme.FONT), fit_text(label, bx - x - 14, theme.FONT),
label_color(opts, M.active_slider == id), theme.FONT)
local fmt = opts.fmt or (is_float and "%.2f" or "%d")
local shown = editing and tostring(M._slider_edit_text[id] or "") or string.format(fmt, val)
if opts.suffix and not editing then shown = shown .. opts.suffix end
local t = 0
if maxv > minv then t = clamp((val - minv) / (maxv - minv), 0, 1) end
local st = anim.smooth("slider-val:" .. tostring(id), t, anim.motion_rate(24))
local hot = input.hover(bx, by - 4, bw, bh + 8)
local drag_t = anim.transition("slider-active:" .. tostring(id), M.active_slider == id, anim.motion_rate(24))
local hov_t = anim.transition("slider-hover:" .. tostring(id), hot, 16)
M.rect(bx, by, bw, bh, anim.mix(theme.ELEM, theme.ELEM_HOVER, hov_t), true, 3)
local fw = bw * st
if fw >= 1 then
local fill = anim.checkbox_fill()
M.rect(bx, by, fw, bh, theme.alpha(fill, 0.82 + 0.18 * math.max(drag_t, hov_t)), true, round_for(fw, bh, 3))
end
M.rect(bx, by, bw, bh, editing and theme.alpha(theme.ACCENT, 0.8) or theme.LINE, false, 3)
local fs = theme.FONT_TINY or theme.FONT_SMALL
local vw = text_w(shown ~= "" and shown or "0", fs)
local vx = bx + (bw - vw) * 0.5
M.text(vx, by + math.floor((bh - fs) * 0.5) - 1, shown, theme.TEXT_ACTIVE, fs)
if editing and math.floor(tick_ms() / 500) % 2 == 0 then
M.rect(vx + vw + 1, by + 2, 1, bh - 4, theme.TEXT_ACTIVE, true)
end
if interactive(x, y, w, h) and ui_rmb_clicked(x, y, w, h) then
mark_interacted()
M.begin_slider_input(id, minv, maxv, is_float, val, fmt)
elseif not editing and interactive(x, y, w, h)
and ((input.lmb_click and hot) or (input.lmb and M.active_slider == id)) then
M.active_slider = id
mark_interacted()
local nt = clamp((input.mx - bx) / bw, 0, 1)
local nv = minv + (maxv - minv) * nt
if not is_float then nv = math.floor(nv + 0.5) end
state.set(id, nv)
elseif M.active_slider == id and not input.lmb then
M.active_slider = nil
end
return h
end
local LIST_ROW = 18
local function draw_list_frame(bx, ly, bw, list_h, open_t)
local shown_h = list_h * open_t
M.rect(bx, ly + 2, bw, shown_h, theme.OVERLAY, true, 3)
M.rect(bx, ly + 2, bw, shown_h, theme.BORDER, false, 3)
return shown_h
end
local function list_scrollbar(bx, ly, bw, list_h, off, max_off, vis, n)
if max_off <= 0 then return end
local thumb_h = math.max(10, list_h * (vis / n))
local ty = ly + 2 + (list_h - thumb_h) * (off / math.max(1, max_off))
M.rect(bx + bw - 4, ty, 2, thumb_h, theme.alpha(theme.ACCENT, 0.6), true, 1)
end
local function select_box(x, y, w, h, id, label, value_text, open, opts)
local bw = ctrl_width(w)
local bh = theme.CTRL_H
local bx = x + w - bw - 6
local by = y + math.floor((h - bh) * 0.5)
M.text(x + 8, row_text_y(y, h, theme.FONT), fit_text(label, bx - x - 14, theme.FONT),
label_color(opts, open), theme.FONT)
local hovered = input.hover(bx, by, bw, bh)
local hov_t = anim.transition("select-hover:" .. tostring(id), hovered or open, 16)
M.rect(bx, by, bw, bh, anim.mix(theme.ELEM, theme.ELEM_HOVER, hov_t), true, 3)
M.rect(bx, by, bw, bh, open and theme.alpha(theme.ACCENT, 0.65) or theme.LINE, false, 3)
local fs = theme.FONT_SMALL
M.text(bx + 7, by + math.floor((bh - fs) * 0.5) - 1, fit_text(value_text, bw - 24, fs),
open and theme.TEXT_ACTIVE or theme.TEXT, fs)
chevron(bx + bw - 10, by + bh * 0.5, open, open and theme.TEXT_ACTIVE or theme.TEXT_DIM)
return bx, by, bw, bh
end
function M.combo(x, y, w, id, label, options, default_idx, opts)
if id and not state.is_visible(id) then return 0 end
state.define(id, default_idx or 0)
local idx = tonumber(state.get(id, default_idx or 0)) or 0
local h = theme.ROW_H
local open = M.open_combo == id
if not in_clip(y, h) and not open then return h end
local cur = options[idx + 1] or options[1] or "-"
local bx, by, bw, bh = select_box(x, y, w, h, id, label, cur, open, opts)
if ui_clicked(bx, by, bw, bh) then
mark_interacted()
if open then
M.open_combo = nil
else
M.open_combo = id
M.open_multi = nil
M.open_color = nil
M.open_bind_mode = nil
M._list_scroll[id] = 0
end
open = M.open_combo == id
end
if open then
local n = #options
local off, max_off, vis = list_scroll_for(id, n, M.LIST_MAX_VISIBLE)
local list_h = vis * LIST_ROW + 4
local ly = by + bh
apply_list_wheel_scroll(id, n, M.LIST_MAX_VISIBLE, bx, ly, bw, list_h)
off, max_off, vis = list_scroll_for(id, n, M.LIST_MAX_VISIBLE)
local open_t = anim.transition("list-open:" .. tostring(id), true, anim.motion_rate(26))
local shown_h = draw_list_frame(bx, ly, bw, list_h, open_t)
for row = 0, vis - 1 do
local i = off + row + 1
local opt = options[i]
if not opt then break end
local iy = ly + 4 + row * LIST_ROW
if iy + LIST_ROW > ly + 2 + shown_h then break end
local option_hovered = input.hover(bx, iy, bw, LIST_ROW)
local selected = i - 1 == idx
if option_hovered then
M.rect(bx + 3, iy, bw - 6, LIST_ROW, theme.ELEM, true, 3)
local tip = tooltips.for_option(id, i, opt)
M.register_tooltip_hover(tostring(id) .. ":option:" .. tostring(i), tip, bx, iy, bw, LIST_ROW)
end
M.text(bx + 9, iy + math.floor((LIST_ROW - theme.FONT_SMALL) * 0.5) - 1,
fit_text(opt, bw - 20, theme.FONT_SMALL),
selected and theme.ACCENT or (option_hovered and theme.TEXT_ACTIVE or theme.TEXT), theme.FONT_SMALL)
if ui_clicked(bx, iy, bw, LIST_ROW) then
mark_interacted()
state.set(id, i - 1)
M.open_combo = nil
end
end
list_scrollbar(bx, ly, bw, list_h, off, max_off, vis, n)
if input.hover(bx, by, bw, bh + list_h) and input.lmb_click and not M.block_under then
mark_interacted()
end
return h + list_h
end
anim.transition("list-open:" .. tostring(id), false, 1000)
return h
end
function M.multi(x, y, w, id, label, options, defaults, opts)
opts = opts or {}
if id and not state.is_visible(id) then return 0 end
defaults = defaults or {}
local def = {}
for i = 1, #options do
def[i] = defaults[i] == true
end
state.define(id, def)
local vals = state.get(id, def)
if type(vals) ~= "table" then
vals = def
state.set(id, vals)
end
if type(opts.sync_ids) == "table" then
for i, alias_id in ipairs(opts.sync_ids) do
vals[i] = state.get(alias_id, def[i]) == true
end
state.values[id] = vals
end
local h = theme.ROW_H
local open = M.open_multi == id
if not in_clip(y, h) and not open then return h end
local parts = {}
for i, opt in ipairs(options) do
if vals[i] then parts[#parts + 1] = opt end
end
local i18n = Infernal.require("ui.i18n")
local summary = (#parts > 0) and table.concat(parts, ", ") or i18n.t("None")
local bx, by, bw, bh = select_box(x, y, w, h, id, label, summary, open, opts)
if ui_clicked(bx, by, bw, bh) then
mark_interacted()
if open then
M.open_multi = nil
else
M.open_multi = id
M.open_combo = nil
M.open_color = nil
M.open_bind_mode = nil
M._list_scroll[id] = 0
end
open = M.open_multi == id
end
if open then
local n = #options
local off, max_off, vis = list_scroll_for(id, n, M.LIST_MAX_VISIBLE)
local list_h = vis * LIST_ROW + 4
local ly = by + bh
apply_list_wheel_scroll(id, n, M.LIST_MAX_VISIBLE, bx, ly, bw, list_h)
off, max_off, vis = list_scroll_for(id, n, M.LIST_MAX_VISIBLE)
local open_t = anim.transition("list-open:" .. tostring(id), true, anim.motion_rate(26))
local shown_h = draw_list_frame(bx, ly, bw, list_h, open_t)
for row = 0, vis - 1 do
local i = off + row + 1
local opt = options[i]
if not opt then break end
local iy = ly + 4 + row * LIST_ROW
if iy + LIST_ROW > ly + 2 + shown_h then break end
local on = vals[i] == true
local option_hovered = input.hover(bx, iy, bw, LIST_ROW)
if option_hovered then
M.rect(bx + 3, iy, bw - 6, LIST_ROW, theme.ELEM, true, 3)
local tip = tooltips.for_option(id, i, opt)
M.register_tooltip_hover(tostring(id) .. ":option:" .. tostring(i), tip, bx, iy, bw, LIST_ROW)
end
local cb = 10
local cbx, cby = bx + 7, iy + math.floor((LIST_ROW - cb) * 0.5)
M.rect(cbx, cby, cb, cb, theme.ELEM_HOVER, true, 2)
if on then
M.rect(cbx, cby, cb, cb, anim.checkbox_fill(), true, 2)
end
M.text(bx + 23, iy + math.floor((LIST_ROW - theme.FONT_SMALL) * 0.5) - 1,
fit_text(opt, bw - 32, theme.FONT_SMALL),
on and theme.TEXT_ACTIVE or theme.TEXT, theme.FONT_SMALL)
if ui_clicked(bx, iy, bw, LIST_ROW) then
mark_interacted()
vals[i] = not on
state.set(id, vals)
local alias_id = opts.sync_ids and opts.sync_ids[i]
if alias_id then
state.set(alias_id, vals[i])
end
end
end
list_scrollbar(bx, ly, bw, list_h, off, max_off, vis, n)
if input.hover(bx, by, bw, bh + list_h) and input.lmb_click and not M.block_under then
mark_interacted()
end
return h + list_h
end
anim.transition("list-open:" .. tostring(id), false, 1000)
return h
end
function M.button(x, y, w, id, label)
if id and not state.is_visible(id) then return 0 end
local h = theme.ROW_H + 2
if not in_clip(y, h) then return h end
local bx, bw = x + 6, w - 12
local by, bh = y + 2, h - 4
local hovered = input.hover(bx, by, bw, bh)
local pressed = hovered and input.lmb
local hov_t = anim.transition("button-hover:" .. tostring(id), hovered, 16)
local press_t = anim.transition("button-press:" .. tostring(id), pressed, 28)
local fill = anim.mix(theme.BUTTON, theme.BUTTON_HOVER, hov_t)
fill = anim.mix(fill, theme.alpha(theme.ACCENT, 1), press_t * 0.25)
M.rect(bx, by, bw, bh, fill, true, 4)
M.rect(bx, by, bw, bh, theme.LINE, false, 4)
local fs = theme.FONT_SMALL
local shown = fit_text(label, bw - 16, fs)
local tw = text_w(shown, fs)
M.text(bx + (bw - tw) * 0.5, by + math.floor((bh - fs) * 0.5) - 1, shown,
hovered and theme.TEXT_ACTIVE or theme.TEXT, fs)
if interactive(bx, by, bw, bh) and ui_clicked(bx, by, bw, bh) then
mark_interacted()
state.fire_button(id)
end
return h
end
M._label_lines = {}
local function wrap_label(text, max_w, fs)
local lines, cur = {}, ""
for word in tostring(text or ""):gmatch("%S+") do
local try = cur == "" and word or (cur .. " " .. word)
if cur ~= "" and text_w(try, fs) > max_w then
lines[#lines + 1] = cur
cur = word
else
cur = try
end
end
if cur ~= "" then lines[#lines + 1] = cur end
if #lines == 0 then lines[1] = "" end
return lines
end
function M.label_height(text)
local fs = theme.FONT_SMALL
local n = M._label_lines[text] or 1
return n * (fs + 3) + 3
end
-- Descriptions wrap onto extra lines instead of being cut off.
function M.label(x, y, w, text, dim)
local fs = theme.FONT_SMALL
local lines = wrap_label(text, w - 14, fs)
M._label_lines[text] = #lines
local h = #lines * (fs + 3) + 3
if not in_clip(y, h) then return h end
local col = dim and theme.TEXT_DIM or theme.TEXT
for i, line in ipairs(lines) do
M.text(x + 8, y + 2 + (i - 1) * (fs + 3), line, col, fs)
end
return h
end
function M.separator(x, y, w)
local h = 9
if not in_clip(y, h) then return h end
M.rect(x + 8, y + 4, w - 16, 1, theme.LINE, true)
return h
end
function M.keybind(x, y, w, id, label, default_on, opts)
opts = opts or {}
if id and not state.is_visible(id) then return 0 end
state.define(id, default_on == true)
local mode_id = id .. "_mode"
local hide_id = id .. "_hide_kb"
state.define(mode_id, 0)
state.define(hide_id, false)
local h = theme.ROW_H
if not in_clip(y, h) then return h end
local listening = M.listening_key == id
local mode_open = M.open_bind_mode == id
local vk = state.get_key(id)
local fs = theme.FONT_TINY or theme.FONT_SMALL
local chip_w = math.max(26, text_w(listening and "..." or (vk and vk ~= 0 and M.vk_name(vk) or "-"), fs) + 12)
local used = M.checkbox(x, y, w, id, label, {
default = default_on,
hide_color = opts.hide_color,
risky = opts.risky,
color = opts.color,
reserve_right = chip_w + 6,
})
local right = (M._last_check_right or (x + w - theme.CHECK_SIZE - 12))
local kx, ky, cw, ch = key_chip(id, right, y, h, listening, mode_open)
if ui_rmb_clicked(kx, ky, cw, ch) then
mark_interacted()
end_key_listen()
open_bind_mode_popup(id, kx, ky, cw)
elseif ui_clicked(kx, ky, cw, ch) then
mark_interacted()
M.open_bind_mode = nil
M._bind_mode_hit = nil
if listening then
end_key_listen()
else
begin_key_listen(id)
end
elseif mode_open then
M._bind_mode_anchor = { id = id, x = kx, y = ky, w = cw }
end
return used
end
function M.aim_key_row(x, y, w, key_id, mode_id, label)
if key_id and not state.is_visible(key_id) then return 0 end
mode_id = mode_id or (key_id .. "_mode")
state.define(mode_id, 1)
local h = theme.ROW_H
if not in_clip(y, h) then return h end
local listening = M.listening_key == key_id
local mode_open = M.open_bind_mode == key_id
local kx, ky, cw, ch = key_chip(key_id, x + w - 6, y, h, listening, mode_open)
M.text(x + 8, row_text_y(y, h, theme.FONT), fit_text(label, kx - x - 14, theme.FONT), theme.TEXT, theme.FONT)
if ui_rmb_clicked(kx, ky, cw, ch) then
mark_interacted()
end_key_listen()
open_bind_mode_popup(key_id, kx, ky, cw)
elseif ui_clicked(kx, ky, cw, ch) then
mark_interacted()
M.open_bind_mode = nil
M._bind_mode_hit = nil
if listening then
end_key_listen()
else
begin_key_listen(key_id)
end
elseif mode_open then
M._bind_mode_anchor = { id = key_id, x = kx, y = ky, w = cw }
end
return h
end
function M.hotkey_row(x, y, w, id, label, default_vk)
if id and not state.is_visible(id) then return 0 end
if state.get_key(id) == 0 and default_vk and default_vk ~= 0 then
state.set_key(id, default_vk)
end
local h = theme.ROW_H
if not in_clip(y, h) then return h end
local listening = M.listening_key == id
local kx, ky, cw, ch = key_chip(id, x + w - 6, y, h, listening, false)
M.text(x + 8, row_text_y(y, h, theme.FONT), fit_text(label, kx - x - 14, theme.FONT), theme.TEXT, theme.FONT)
if ui_clicked(kx, ky, cw, ch) then
mark_interacted()
M.open_bind_mode = nil
M._bind_mode_hit = nil
if listening then
end_key_listen()
else
begin_key_listen(id)
end
end
return h
end
function M.color_row(x, y, w, id, label, default_col)
if id and not state.is_visible(id) then return 0 end
state.define_color(id, default_col or { 1, 1, 1, 1 })
local col = state.get_color(id, default_col)
local h = theme.ROW_H
if not in_clip(y, h) then return h end
local box = theme.CHECK_SIZE
local cx = x + w - box - 6
local cy = y + math.floor((h - box) * 0.5)
M.text(x + 8, row_text_y(y, h, theme.FONT), fit_text(label, cx - x - 14, theme.FONT), theme.TEXT, theme.FONT)
M.rect(cx, cy, box, box, col, true, 3)
M.rect(cx, cy, box, box, theme.LINE, false, 3)
handle_color_swatch(id, cx, cy, box, box, x, y, w, col)
return h
end
function M.draw_color_picker(px, py, pw, ph, id, col)
M.rect(px, py, pw, ph, theme.OVERLAY, true, theme.CORNER)
M.rect(px, py, pw, ph, theme.BORDER_HOT, false, theme.CORNER)
local hue = M._hue_cache[id]
if not hue then
hue = select(1, rgb_to_hsv(col[1] or 1, col[2] or 1, col[3] or 1))
M._hue_cache[id] = hue
end
local _, sat, val = rgb_to_hsv(col[1] or 1, col[2] or 1, col[3] or 1)
local alpha = col[4] or 1
local sq = 96
local sx, sy = px + 8, py + 8
local steps = 8
local cell = sq / steps
for iy = 0, steps - 1 do
for ix = 0, steps - 1 do
local s = ix / (steps - 1)
local v = 1 - iy / (steps - 1)
local r, g, b = hsv_to_rgb(hue, s, v)
M.rect(sx + ix * cell, sy + iy * cell, cell + 0.5, cell + 0.5, { r, g, b, 1 }, true)
end
end
M.rect(sx, sy, sq, sq, theme.BORDER, false, theme.CORNER_SMALL)
local hx, hy, hw, hh = sx + sq + 8, sy, 14, sq
for i = 0, 23 do
local t = i / 23
local r, g, b = hsv_to_rgb(t, 1, 1)
M.rect(hx, hy + i * (hh / 24), hw, hh / 24 + 0.5, { r, g, b, 1 }, true)
end
M.rect(hx, hy, hw, hh, theme.BORDER, false, theme.CORNER_SMALL)
local ax, ay, aw, ah = sx, sy + sq + 8, sq + 22, 10
M.rect(ax, ay, aw, ah, { 0.15, 0.15, 0.15, 1 }, true)
M.rect(ax, ay, aw * clamp(alpha, 0, 1), ah, { col[1], col[2], col[3], 1 }, true)
M.rect(ax, ay, aw, ah, theme.BORDER, false, theme.CORNER_SMALL)
local prx = ax + aw + 6
M.rect(prx, ay - 2, 18, 14, { col[1], col[2], col[3], alpha }, true)
M.rect(prx, ay - 2, 18, 14, theme.BORDER, false)
local function apply(s, v, a, new_hue)
if new_hue then
M._hue_cache[id] = new_hue
hue = new_hue
end
local r, g, b = hsv_to_rgb(hue, s, v)
state.set_color(id, { r, g, b, a })
if id == "infernal_ui_accent" then
anim.sync_theme()
end
end
if input.lmb and input.hover(sx, sy, sq, sq) then
M.popup_used_click = true
local ns = clamp((input.mx - sx) / sq, 0, 1)
local nv = clamp(1 - (input.my - sy) / sq, 0, 1)
apply(ns, nv, alpha, nil)
elseif input.lmb and input.hover(hx, hy, hw, hh) then
M.popup_used_click = true
local nh = clamp((input.my - hy) / hh, 0, 1)
apply(sat, val, alpha, nh)
elseif input.lmb and input.hover(ax, ay, aw, ah) then
M.popup_used_click = true
local na = clamp((input.mx - ax) / aw, 0, 1)
apply(sat, val, na, nil)
end
if input.hover(px, py, pw, ph) and input.lmb_click then
M.popup_used_click = true
end
local mx = sx + sat * sq
local my = sy + (1 - val) * sq
M.rect(mx - 2, my - 2, 4, 4, { 1, 1, 1, 1 }, false)
M.rect(hx - 1, hy + hue * hh - 1, hw + 2, 3, { 1, 1, 1, 1 }, false)
end
function M.text_field(x, y, w, h, id, placeholder, default)
state.define(id, default or "")
local val = tostring(state.get(id, default or ""))
if not in_clip(y, h) then return h end
local focused = M.active_input == id
local hot = input.hover(x, y, w, h)
if focused then
M._active_input_rect = { x = x, y = y, w = w, h = h }
end
M.rect(x, y, w, h, anim.interactive_fill("input:" .. tostring(id), theme.BUTTON, hot, focused), true, theme.CORNER_SMALL)
M.rect(x, y, w, h, focused and theme.FOCUS or (hot and theme.BORDER_HOT or theme.BORDER_SOFT), false, theme.CORNER_SMALL)
local shown = val
local text_x = x + 7
local max_w = w - 14
local text_y = y + math.floor((h - theme.FONT_SMALL) * 0.5) - 1
if shown == "" then
M.text(text_x, text_y, placeholder or "...", theme.TEXT_DIM, theme.FONT_SMALL)
else
while #shown > 0 and text_w(shown, theme.FONT_SMALL) > max_w do
shown = shown:sub(2)
end
M.text(text_x, text_y, shown, focused and theme.TEXT_ACTIVE or theme.TEXT, theme.FONT_SMALL)
end
if focused then
local caret_x = text_x + text_w(shown ~= "" and shown or "", theme.FONT_SMALL)
local now = tick_ms()
if math.floor(now / 500) % 2 == 0 then
M.rect(caret_x, y + math.floor((h - 10) * 0.5), 1, 10, theme.TEXT_ACTIVE, true)
end
end
if interactive(x, y, w, h) and ui_clicked(x, y, w, h) then
mark_interacted()
focus_input(id)
end
return h
end
function M.input_row(x, y, w, id, label, default)
if id and not state.is_visible(id) then return 0 end
local h = theme.ROW_H
if not in_clip(y, h) then return h end
local fw = math.max(70, math.floor(w * 0.46))
local fx = x + w - fw - 6
local fh = theme.CTRL_H
M.text(x + 8, y + math.floor((h - theme.FONT) * 0.5) - 1, fit_text(label, fx - x - 14, theme.FONT), theme.TEXT, theme.FONT)
M.text_field(fx, y + math.floor((h - fh) * 0.5), fw, fh, id, "...", default)
return h
end
function M.estimate_height(item)
local t = item.type
local extra = 0
if item.id and M.open_combo == item.id and item.options then
extra = math.min(#item.options, M.LIST_MAX_VISIBLE) * 18 + 4
elseif item.id and M.open_multi == item.id and item.options then
extra = math.min(#item.options, M.LIST_MAX_VISIBLE) * 18 + 4
end
if t == "slider" then
return theme.SLIDER_ROW_H + extra
elseif t == "combo" or t == "multi" or t == "input" then
return theme.STACKED_ROW_H + extra
elseif t == "separator" then
return 9
elseif t == "button" then
return theme.ROW_H + 2
elseif t == "label" then
return M.label_height(Infernal.require("ui.i18n").t(item.label))
elseif t == "color" then
return theme.ROW_H
elseif t == "checkbox" or t == "keybind" or t == "aim_key" or t == "hotkey" then
return theme.ROW_H
end
return theme.ROW_H + extra
end
function M.draw_item(item, x, y, w)
local i18n = Infernal.require("ui.i18n")
local label = i18n.t(item.label)
local options = item.options and i18n.options(item.options) or item.options
local t = item.type
local h = 0
if t == "checkbox" then
h = M.checkbox(x, y, w, item.id, label, item)
elseif t == "keybind" then
h = M.keybind(x, y, w, item.id, label, item.default, item)
elseif t == "aim_key" then
h = M.aim_key_row(x, y, w, item.id, item.mode_id, label)
elseif t == "hotkey" then
h = M.hotkey_row(x, y, w, item.id, label, item.default)
elseif t == "slider" then
h = M.slider(x, y, w, item.id, label, item.min, item.max, item.default, item)
elseif t == "combo" then
h = M.combo(x, y, w, item.id, label, options, item.default, item)
elseif t == "multi" then
h = M.multi(x, y, w, item.id, label, options, item.defaults, item)
elseif t == "button" then
h = M.button(x, y, w, item.id, label)
elseif t == "label" then
h = M.label(x, y, w, label, item.dim)
elseif t == "separator" then
h = M.separator(x, y, w)
elseif t == "color" then
h = M.color_row(x, y, w, item.id, label, item.default)
elseif t == "input" then
h = M.input_row(x, y, w, item.id, label, item.default)
end
local tip = tooltips.for_item(item)
if tip and item.id and h > 0 then
M.register_tooltip_hover(item.id, tip, x, y, w, h)
end
return h
end
return M
end)()

Infernal._mods["ui.catalog_items"] = (function()
local gpu_chams = Infernal.require("core.gpu_chams")
local M = {}
function M.cb(id, label, default, color, gate, extra)
local item = { type = "checkbox", id = id, label = label, default = default == true, color = color, gate = gate }
if type(extra) == "table" then
for k, v in pairs(extra) do item[k] = v end
end
return item
end
function M.kb(id, label, default, gate, extra)
local item = { type = "keybind", id = id, label = label, default = default == true, gate = gate }
if type(extra) == "table" then
for k, v in pairs(extra) do item[k] = v end
end
return item
end
function M.sl(id, label, minv, maxv, default, float, gate, extra)
local item = {
type = "slider",
id = id,
label = label,
min = minv,
max = maxv,
default = default,
float = float == true,
fmt = float and "%.2f" or "%d",
gate = gate,
}
if type(extra) == "table" then
for k, v in pairs(extra) do
item[k] = v
end
end
return item
end
function M.combo(id, label, options, default, gate, extra)
local item = { type = "combo", id = id, label = label, options = options, default = default or 0, gate = gate }
if type(extra) == "table" then
for k, v in pairs(extra) do
item[k] = v
end
end
return item
end
function M.multi(id, label, options, defaults, gate, extra)
local item = { type = "multi", id = id, label = label, options = options, defaults = defaults, gate = gate }
if type(extra) == "table" then
for k, v in pairs(extra) do item[k] = v end
end
return item
end
function M.btn(id, label, gate)
return { type = "button", id = id, label = label, gate = gate }
end
function M.sep(gate)
return { type = "separator", gate = gate }
end
function M.label(text, dim, gate)
return { type = "label", label = text, dim = dim, gate = gate }
end
function M.color(id, label_text, default, gate, override_idx)
return {
type = "color",
id = id,
label = label_text,
default = default,
gate = gate,
color_override_idx = override_idx,
}
end
function M.input(id, label_text, default, gate)
return { type = "input", id = id, label = label_text, default = default or "", gate = gate }
end
function M.ak(key_id, label, gate)
return { type = "aim_key", id = key_id, mode_id = key_id .. "_mode", label = label, gate = gate }
end
function M.hk(id, label, gate, default_vk)
return { type = "hotkey", id = id, label = label, gate = gate, default = default_vk or 0x2D }
end
function M.from_toggles(list, gate)
local out = {}
for _, t in ipairs(list) do
out[#out + 1] = M.cb(t.id, t.label, false, t.color, gate)
if t.ring_id then
out[#out + 1] = M.cb(t.ring_id, t.label .. " Range Ring", false, nil, gate)
end
end
return out
end
function M.append(dst, src)
for _, v in ipairs(src) do
dst[#dst + 1] = v
end
end
function M.toggle_labels(list)
local labels = {}
for i, t in ipairs(list) do
labels[i] = t.label
end
return labels
end
function M.mesh_chams_block(prefix, toggle_list, master)
local chams_id = prefix .. "_chams"
local chams_master = prefix .. "_chams_enabled"
local mode_id = prefix .. "_chams_mode"
local color_id = prefix .. "_chams_color"
return {
M.sep(master),
M.label("Mesh Chams (GPU)", false, master),
M.cb(chams_master, "Enable Mesh Chams", false, nil, master),
M.multi(chams_id, "Cham Types", M.toggle_labels(toggle_list), {}, chams_master),
M.combo(mode_id, "Chams Mode", gpu_chams.MODE_LABELS, 0, chams_master),
M.combo(color_id, "Glow Preset", gpu_chams.COLOR_LABELS, 0, chams_master, {
gate_any_combo = {
{ mode_id, { 2, 3 } },
},
}),
}
end
return M
end)()

