sl("infernal_rage_fov", "FOV Radius", 10, 250, 125, false, R),
sl("infernal_rage_max_dist", "Max Distance", 50, 2000, 800, false, R),
combo("infernal_rage_priority", "Target Priority", { "Crosshair", "Closest" }, 0, R, { tip = "Crosshair: the target nearest your crosshair. Closest: the target nearest to you. Either way it has to be inside the FOV." }),
cb("infernal_rage_autofire", "Auto Fire", true, nil, R, { tip = "Clicks every 5-10ms while a target can be hit, so your gun fires the moment it is ready. Every click checks again that the part is in plain sight, so it stops the instant the target is behind cover. Bows fire while you hold right click to draw. It only clicks while your cursor is over the game." }),
cb("infernal_rage_reload_empty", "Reload When Empty", false, nil, R, { tip = "When Auto Fire keeps clicking and no bullet comes out, the magazine is empty: it presses R once and waits for the reload. Starts working once your gun has fired since you equipped it." }),
