Infernal._mods["ui.catalog"] = (function()
local M = {}
-- Infernal's own tabs in the Fatality layout; every section sits in one of three columns.
M.TABS = {
{ id = "rage", icon = "skull", title = "RAGE", label = "RAGE", description = "Ragebot and silent aim" },
{ id = "aim", icon = "target", title = "AIM", label = "AIM", description = "Aimbot, heli aimbot, recoil" },
{ id = "visuals", icon = "eye", title = "VISUALS", label = "VISUALS", description = "Players, NPCs, inventory, crosshair, audio" },
{ id = "world", icon = "world", title = "WORLD", label = "WORLD", description = "Resources, loot, raids, bases, tactical map" },
{ id = "misc", icon = "gear", title = "MISC", label = "MISC", description = "Automation, movement, HUD, protection, events" },
{ id = "config", icon = "folder", title = "CONFIG", label = "CONFIG", description = "Save, load and autoload configs" },
{ id = "settings", icon = "settings", title = "SETTINGS", label = "SETTINGS", description = "Language, menu look, accent colors, extras" },
}
local BUILDERS = {
"ui.catalog_rage", "ui.catalog_aim", "ui.catalog_visuals", "ui.catalog_world",
"ui.catalog_misc", "ui.catalog_config",
}
local LAYOUT = {
rage = {
{ "Ragebot", "left" }, { "Ragebot Targeting", "center" }, { "Silent Aim", "right" },
},
aim = {
{ "Aimbot", "left" }, { "Aimbot Indicators", "center" }, { "Recoil Control", "center" },
{ "Attack Heli Aimbot", "right" },
},
visuals = {
{ "Player ESP", "left" }, { "NPCs", "center" }, { "Combat Mode", "center" },
{ "Bullet Tracers", "center" },
{ "Inventory Viewer", "right" }, { "Arm Chams", "right" },
{ "Crosshair", "right" }, { "Audio Radar", "right" },
},
world = {
{ "Resources", "left" }, { "Loot", "center" }, { "Raids", "center" },
{ "Bases", "right" }, { "Base Xray", "right" },
},
misc = {
{ "Automation", "left" }, { "Movement", "center" }, { "HUD", "center" }, { "Hitsounds", "center" },
{ "Protection & Access", "right" }, { "Event Status", "right" },
},
config = { { "Config", "left" } },
settings = { { "General", "left" }, { "Appearance", "center" }, { "Accent Colors", "right" } },
}
local group_cache = {}
local by_title = nil
local EMPTY_GROUPS = {}
function M.invalidate(_tab_id)
for key in pairs(group_cache) do group_cache[key] = nil end
by_title = nil
end
local function all_groups()
if by_title then return by_title end
by_title = { _order = {} }
for _, path in ipairs(BUILDERS) do
local ok, groups = pcall(function() return Infernal.require(path).build() end)
if ok and type(groups) == "table" then
for _, g in ipairs(groups) do
if g.title and not by_title[g.title] then
by_title[g.title] = g
by_title._order[#by_title._order + 1] = g
end
end
end
end
return by_title
end
function M.groups_for(tab_id)
local cached = group_cache[tab_id]
if cached then return cached end
local layout = LAYOUT[tab_id]
if not layout then return EMPTY_GROUPS end
local groups_by = all_groups()
local groups = {}
for _, entry in ipairs(layout) do
local g = groups_by[entry[1]]
if g then
g.column = entry[2]
groups[#groups + 1] = g
end
end
-- Any section not placed above (a new module) lands in MISC so nothing is ever hidden.
if tab_id == "misc" then
local placed = {}
for _, lay in pairs(LAYOUT) do
for _, entry in ipairs(lay) do placed[entry[1]] = true end
end
for _, g in ipairs(groups_by._order) do
if not placed[g.title] then
g.column = "right"
groups[#groups + 1] = g
end
end
end
group_cache[tab_id] = groups
return groups
end
return M
end)()

Infernal._mods["ui.search_palette"] = (function()
local theme = Infernal.require("ui.gs_theme")
local input = Infernal.require("ui.gs_input")
local widgets = Infernal.require("ui.gs_widgets")
local anim = Infernal.require("ui.gs_anim")
local icons = Infernal.require("ui.gs_icons")
local state = Infernal.require("ui.gs_state")
local catalog = Infernal.require("ui.catalog")
local i18n = Infernal.require("ui.i18n")
local M = {}
local QUERY_ID = "infernal_ui_search_query"
local MAX_RESULTS = 8
local entries = nil
local results = {}
local selected = 1
local open = false
local pending = nil
local last_query = nil
local focus_pending = false
local function lower(value)
    return tostring(value or ""):lower()
end
local function translated(value)
    return i18n.t(tostring(value or ""))
end
local function add_entry(out, entry, terms)
    local parts = {}
    local function add(value)
        if value ~= nil and tostring(value) ~= "" then
            parts[#parts + 1] = tostring(value)
        end
    end
    add(entry.label)
    add(entry.tab and entry.tab.label)
    add(entry.tab and entry.tab.title)
    add(entry.group and entry.group.title)
    add(entry.item and entry.item.id)
    add(entry.item and entry.item.type)
    if terms then
        for i = 1, #terms do add(terms[i]) end
    end
    entry.haystack = lower(table.concat(parts, " "))
    entry.label_lower = lower(entry.label)
    entry.order = #out + 1
    out[#out + 1] = entry
end
local function build_entries()
    local out = {}
    for tab_index, tab in ipairs(catalog.TABS) do
        add_entry(out, {
            kind = "Tab", label = translated(tab.title or tab.label),
            tab = tab, tab_index = tab_index,
        }, { tab.id, tab.description })
        local groups = catalog.groups_for(tab.id)
        for group_index, group in ipairs(groups) do
            add_entry(out, {
                kind = "Module", label = translated(group.title),
                tab = tab, tab_index = tab_index,
                group = group, group_index = group_index,
            })
            for item_index, item in ipairs(group.items or {}) do
                if item.type ~= "separator" and item.label then
                    local option_terms = {}
                    for _, option in ipairs(item.options or {}) do
                        option_terms[#option_terms + 1] = option
                        option_terms[#option_terms + 1] = translated(option)
                    end
                    local kind = (item.type == "checkbox" or item.type == "keybind")
                        and "Feature" or "Setting"
                    add_entry(out, {
                        kind = kind, label = translated(item.label),
                        tab = tab, tab_index = tab_index,
                        group = group, group_index = group_index,
                        item = item, item_index = item_index,
                    }, option_terms)
                end
            end
        end
    end
    entries = out
end
local function match_rank(entry, query)
    local q = lower(query):match("^%s*(.-)%s*$") or ""
    if q == "" then return nil end
    local cursor = 1
    for token in q:gmatch("%S+") do
        local found = entry.haystack:find(token, 1, true)
        if not found then return nil end
        cursor = cursor + found
    end
    if entry.label_lower == q then return 0 end
    if entry.label_lower:sub(1, #q) == q then return 10 end
    if entry.label_lower:find(" " .. q, 1, true) then return 20 end
    local label_pos = entry.label_lower:find(q, 1, true)
    if label_pos then return 30 + label_pos end
    return 100 + cursor
end
local function refresh_results()
    if not entries then build_entries() end
    local query = tostring(state.get(QUERY_ID, ""))
    if query == last_query then return end
    last_query = query
    results = {}
    for i = 1, #entries do
        local rank = match_rank(entries[i], query)
        if rank then
            results[#results + 1] = { entry = entries[i], rank = rank }
        end
    end
    table.sort(results, function(a, b)
        if a.rank == b.rank then return a.entry.order < b.entry.order end
        return a.rank < b.rank
    end)
    while #results > MAX_RESULTS do results[#results] = nil end
    selected = math.max(1, math.min(selected, #results))
end
function M.init()
    state.define(QUERY_ID, "")
end
function M.is_open()
    return open
end
function M.open()
    open = true
    entries = nil
    selected = 1
    last_query = nil
    state.set(QUERY_ID, "")
    focus_pending = true
end
function M.close()
    open = false
    focus_pending = false
    widgets.blur_text_input(QUERY_ID)
end
function M.toggle()
    if open then M.close() else M.open() end
end
function M.consume_selection()
    local value = pending
    pending = nil
    return value
end
local function choose(entry)
    pending = entry
    M.close()
end
local function breadcrumb(entry)
    if entry.kind == "Tab" then return translated("Open section") end
    local tab_name = translated(entry.tab.label or entry.tab.title)
    if entry.kind == "Module" then return tab_name end
    return tab_name .. "  /  " .. translated(entry.group.title)
end
function M.draw(center_x, top_y, menu_w)
    if not open then return end
    if focus_pending and not input.lmb then
        widgets.focus_text_input(QUERY_ID)
        focus_pending = false
    end
    refresh_results()
    if input.key_pressed(0x1B) then
        M.close()
        return
    end
    if #results > 0 then
        if input.key_pressed(0x28) then
            selected = selected % #results + 1
        elseif input.key_pressed(0x26) then
            selected = (selected - 2) % #results + 1
        end
        if input.key_pressed(0x09) then
            state.set(QUERY_ID, results[selected].entry.label)
            last_query = nil
            widgets.focus_text_input(QUERY_ID)
        elseif input.key_pressed(0x0D) then
            choose(results[selected].entry)
            return
        end
    end
    local scale = theme.SCALE or 1
    local pw = math.min(math.floor(570 * scale), menu_w - 36)
    local row_h = math.floor(36 * scale)
    local header_h = math.floor(48 * scale)
    local footer_h = math.floor(24 * scale)
    local result_count = #results
    local empty_h = math.floor(58 * scale)
    local ph = header_h + (result_count > 0 and result_count * row_h or empty_h) + footer_h
    local px = math.floor(center_x - pw * 0.5)
    local py = top_y
    widgets.block_under = false
    widgets.clip = nil
    widgets.rect(px, py, pw, ph, theme.OVERLAY, true, theme.CORNER)
    widgets.rect(px, py, pw, ph, theme.BORDER_HOT, false, theme.CORNER)
    widgets.rect(px + 1, py + 1, pw - 2, header_h - 1, theme.PANEL_RAISED, true, theme.CORNER)
    icons.draw("search", px + 22, py + math.floor(header_h * 0.5), theme.TEXT_DIM)
    widgets.text_field(px + 38, py + 10, pw - 50, header_h - 20,
        QUERY_ID, translated("Search features, modules, settings..."), "")
    local list_y = py + header_h
    if result_count == 0 then
        local query = tostring(state.get(QUERY_ID, ""))
        local message = query == "" and translated("Type to search every feature and module")
            or translated("No matching features or modules")
        widgets.text(px + 16, list_y + 18, message, theme.TEXT_DIM, theme.FONT_SMALL)
    else
        for i = 1, result_count do
            local entry = results[i].entry
            local iy = list_y + (i - 1) * row_h
            local hot = input.hover(px + 6, iy + 2, pw - 12, row_h - 4)
            local active = i == selected
            local emphasis = anim.transition("search-result:" .. entry.order, active or hot, 18)
            if emphasis > 0.01 then
                widgets.rect(px + 6, iy + 2, pw - 12, row_h - 4,
                    theme.alpha(active and theme.NAV_ACTIVE or theme.HOVER,
                        0.42 + emphasis * 0.30), true, theme.CORNER_SMALL)
            end
            if active then
                widgets.rect(px + 8, iy + 8, 2, row_h - 16, theme.ACCENT, true, 1)
            end
            widgets.text(px + 16, iy + 6, entry.label,
                active and theme.TEXT_ACTIVE or theme.TEXT, theme.FONT)
            local crumb = breadcrumb(entry)
            widgets.text(px + 16, iy + 21, crumb, theme.TEXT_DIM, theme.FONT_CAPTION)
            local kind_w = #entry.kind * math.max(5, theme.FONT_CAPTION * 0.52)
            widgets.text(px + pw - 16 - kind_w, iy + 11,
                translated(entry.kind), theme.TEXT_DIM, theme.FONT_CAPTION)
            if input.clicked(px + 6, iy + 2, pw - 12, row_h - 4) then
                choose(entry)
                return
            end
            if hot then selected = i end
        end
    end
    local footer_y = py + ph - footer_h
    widgets.rect(px + 1, footer_y, pw - 2, 1, theme.BORDER_SOFT, true)
    widgets.text(px + 14, footer_y + 6,
        translated("Tab autocomplete   Up/Down navigate   Enter open   Esc close"),
        theme.TEXT_DIM, theme.FONT_CAPTION)
    widgets.block_under = true
end
return M
end)()

Infernal._mods["ui.hud_dock"] = (function()
local theme = Infernal.require("ui.gs_theme")
local input = Infernal.require("ui.gs_input")
local widgets = Infernal.require("ui.gs_widgets")
local anim = Infernal.require("ui.gs_anim")
local icons = Infernal.require("ui.gs_icons")
local state = Infernal.require("ui.gs_state")
local M = {}
local open_settings = false
local popup_rect = nil
local dock_rect = nil
local settings_opened_this_frame = false
local visible_settings = {}
local panel_widths = {}
local SETTINGS_SEPARATOR = { type = "separator" }
local SETTINGS_EMPTY = {
type = "label",
label = "Enable Binds, Staff, Events, or Map above.",
dim = true,
}
local PANELS = {
{ id = "infernal_keybinds_enabled", icon = "keybinds", label = "Binds" },
{ id = "infernal_mod_checker_enabled", icon = "staff", label = "Staff" },
{ id = "infernal_event_status_enabled", icon = "events", label = "Events" },
{ id = "infernal_map_enabled", icon = "map", label = "Map" },
}
local BIND_SETTINGS = {
{ type = "label", label = "KEYBINDS", dim = true },
{ type = "checkbox", id = "infernal_keybinds_active_only", label = "Only active binds", default = false },
{ type = "checkbox", id = "infernal_keybinds_show_unbound", label = "Show unbound", default = true },
{ type = "checkbox", id = "infernal_keybinds_show_mode", label = "Show bind mode", default = true },
}
local STAFF_SETTINGS = {
{ type = "label", label = "STAFF", dim = true },
{
type = "slider", id = "infernal_mod_checker_interval", label = "Scan interval",
min = 1000, max = 10000, default = 2500,
},
}
local MAP_SETTINGS = {
{ type = "label", label = "MAP", dim = true },
{ type = "button", id = "infernal_map_reset_position", label = "Reset map position" },
}
local EVENT_SETTINGS = {
{ type = "label", label = "EVENTS", dim = true },
{ type = "checkbox", id = "infernal_event_status_active_only", label = "Only active events", default = false },
{ type = "checkbox", id = "infernal_event_status_notify", label = "Event notifications", default = true },
{ type = "checkbox", id = "infernal_event_status_distance", label = "Show distance", default = true },
{ type = "checkbox", id = "infernal_event_status_health", label = "Show health", default = true },
{
type = "combo", id = "infernal_event_status_sort", label = "Sorting",
options = { "Game Order", "Active First", "Nearest First" }, default = 1,
},
}
local function build_visible_settings()
local out = visible_settings
for i = #out, 1, -1 do out[i] = nil end
local function append_group(group)
if #out > 0 then out[#out + 1] = SETTINGS_SEPARATOR end
for _, item in ipairs(group) do out[#out + 1] = item end
end
local binds = state.get("infernal_keybinds_enabled", false) == true
local staff = state.get("infernal_mod_checker_enabled", false) == true
local events = state.get("infernal_event_status_enabled", false) == true
local map = state.get("infernal_map_enabled", false) == true
state.set_visible("infernal_keybinds_active_only", binds)
state.set_visible("infernal_keybinds_show_unbound", binds)
state.set_visible("infernal_keybinds_show_mode", binds)
state.set_visible("infernal_mod_checker_interval", staff)
state.set_visible("infernal_event_status_active_only", events)
state.set_visible("infernal_event_status_notify", events)
state.set_visible("infernal_event_status_distance", events)
state.set_visible("infernal_event_status_health", events)
state.set_visible("infernal_event_status_sort", events)
state.set_visible("infernal_map_reset_position", map)
if binds then append_group(BIND_SETTINGS) end
if staff then append_group(STAFF_SETTINGS) end
if events then append_group(EVENT_SETTINGS) end
if map then append_group(MAP_SETTINGS) end
if #out == 0 then
out[1] = SETTINGS_EMPTY
end
return out
end
local function settings_height(items)
local h = 44
for i, item in ipairs(items) do
h = h + widgets.estimate_height(item)
if i < #items then h = h + theme.ITEM_GAP end
end
return h + 8
end
local function text_width(text, size)
local fn = draw and (draw.get_text_size or draw.GetTextSize)
if fn then
local ok, w = pcall(fn, text, size)
if ok and type(w) == "number" then return w end
end
return #tostring(text or "") * 7
end
function M.init()
state.define("infernal_keybinds_enabled", false)
state.define("infernal_mod_checker_enabled", false)
state.define("infernal_mod_checker_x", -1)
state.define("infernal_mod_checker_y", -1)
state.define("infernal_event_status_enabled", false)
state.define("infernal_event_status_active_only", false)
state.define("infernal_event_status_notify", true)
state.define("infernal_event_status_distance", true)
state.define("infernal_event_status_health", true)
state.define("infernal_event_status_sort", 1)
state.define("infernal_map_enabled", false)
end
function M.begin_frame()
if open_settings and popup_rect
and input.hover(popup_rect.x, popup_rect.y, popup_rect.w, popup_rect.h)
then
widgets.block_under = true
end
end
function M.draw_floating(_default_x, _default_y, sw, _sh)
settings_opened_this_frame = false
local scale = theme.SCALE or 1
local bar_h = math.max(42, math.floor(46 * scale))
local item = math.max(32, math.floor(36 * scale))
local gap = math.max(4, math.floor(5 * scale))
local pad = math.max(6, math.floor(7 * scale))
local count = #PANELS + 1
local bar_w = pad * 2 + count * item + (count - 1) * gap
local x = math.floor((sw - bar_w) * 0.5)
local y = math.max(8, math.floor(10 * scale))
if not dock_rect then dock_rect = {} end
dock_rect.x, dock_rect.y, dock_rect.w, dock_rect.h = x, y, bar_w, bar_h
widgets.rect(x, y, bar_w, bar_h, theme.alpha(theme.NAV_BG, 0.97), true, theme.CORNER)
widgets.rect(x, y, bar_w, bar_h, theme.BORDER, false, theme.CORNER)
local cursor_x = x + pad
local iy = y + math.floor((bar_h - item) * 0.5)
for _, panel in ipairs(PANELS) do
local active = state.get(panel.id, false) == true
local hot = input.hover(cursor_x, iy, item, item)
local active_t, hover_t = anim.dock_transition(panel.id, active, hot)
local fill = anim.mix(theme.DOCK_BG, theme.DOCK_HOVER, hover_t)
fill = anim.mix(fill, theme.DOCK_ACTIVE, active_t)
if active or hot then
widgets.rect(cursor_x, iy, item, item, fill, true, theme.CORNER_SMALL)
end
if active then
widgets.rect(cursor_x + 7, iy + item - 3, item - 14, 2,
theme.alpha(theme.ACCENT, 0.92), true, 1)
end
local col = active and theme.TEXT_ACTIVE or anim.mix(theme.TEXT_DIM, theme.TEXT, hover_t)
icons.draw(panel.icon, cursor_x + item * 0.5, iy + item * 0.5, col)
if input.clicked(cursor_x, iy, item, item) and not widgets.block_under then
state.set(panel.id, not active)
widgets.interacted = true
end
if hot then
local i18n = Infernal.require("ui.i18n")
local plabel = i18n.t(panel.label)
local label_w = text_width(plabel, theme.FONT_CAPTION)
local tx = cursor_x + (item - label_w) * 0.5
widgets.rect(tx - 5, y + bar_h + 5, label_w + 10, 18,
theme.OVERLAY, true, theme.CORNER_SMALL)
widgets.text(tx, y + bar_h + 7, plabel, theme.TEXT_ACTIVE, theme.FONT_CAPTION)
end
cursor_x = cursor_x + item + gap
end
local hot = input.hover(cursor_x, iy, item, item)
local active_t, hover_t = anim.dock_transition("settings", open_settings, hot)
local fill = anim.mix(theme.DOCK_BG, theme.DOCK_HOVER, hover_t)
fill = anim.mix(fill, theme.DOCK_ACTIVE, active_t)
if open_settings or hot then
widgets.rect(cursor_x, iy, item, item, fill, true, theme.CORNER_SMALL)
end
icons.draw("settings", cursor_x + item * 0.5, iy + item * 0.5,
open_settings and theme.TEXT_ACTIVE or anim.mix(theme.TEXT_DIM, theme.TEXT, hover_t))
if input.clicked(cursor_x, iy, item, item) and not widgets.block_under then
settings_opened_this_frame = not open_settings
open_settings = not open_settings
widgets.open_combo = nil
widgets.open_multi = nil
widgets.open_color = nil
widgets.open_bind_mode = nil
widgets.interacted = true
end
build_visible_settings()
if not popup_rect then popup_rect = {} end
popup_rect.x = math.min(x + bar_w - (theme.DOCK_POPUP_W or 270), sw - (theme.DOCK_POPUP_W or 270) - 6)
popup_rect.y = y + bar_h + 9
popup_rect.w = theme.DOCK_POPUP_W or 270
popup_rect.h = settings_height(visible_settings)
return dock_rect
end
function M.rect()
return dock_rect
end
function M.draw(x, y, w, h)
local gap = theme.DOCK_GAP or 6
local chip_h = theme.DOCK_CHIP_H or math.max(22, h - 8)
local icon_w = chip_h
local settings_w = chip_h
local widths = panel_widths
local total = settings_w
local i18n = Infernal.require("ui.i18n")
for i, panel in ipairs(PANELS) do
local plabel = i18n.t(panel.label)
local label_w = text_width(plabel, theme.FONT_CAPTION)
widths[i] = icon_w + label_w + (theme.DOCK_PAD_X or 10)
total = total + widths[i] + gap
end
local cursor_x = x + w - total
local chip_y = y + math.floor((h - chip_h) * 0.5)
local dock_left = cursor_x
for i, panel in ipairs(PANELS) do
local chip_w = widths[i]
local active = state.get(panel.id, false) == true
local hot = input.hover(cursor_x, chip_y, chip_w, chip_h)
local t = anim.transition("hud-dock:" .. panel.id, active or hot, anim.motion_rate(18))
local bg = active
and theme.alpha(theme.NAV_ACTIVE or theme.SIDEBAR_ACTIVE, 0.70 + t * 0.18)
or theme.alpha(theme.NAV_IDLE or theme.BUTTON, 0.44 + t * 0.28)
widgets.rect(cursor_x, chip_y, chip_w, chip_h, bg, true, theme.CORNER_SMALL)
widgets.rect(cursor_x, chip_y, chip_w, chip_h,
active and theme.alpha(theme.ACCENT, 0.62) or theme.BORDER_SOFT, false, theme.CORNER_SMALL)
local icon_col = active and theme.TEXT_ACTIVE
or anim.mix(theme.TEXT_DIM, theme.TEXT_ACTIVE, t)
local plabel = i18n.t(panel.label)
icons.draw(panel.icon, cursor_x + icon_w * 0.5, chip_y + chip_h * 0.5, icon_col, 0.76)
widgets.text(cursor_x + icon_w - 1, chip_y + math.floor((chip_h - theme.FONT_CAPTION) * 0.5) - 1,
plabel, icon_col, theme.FONT_CAPTION)
if input.clicked(cursor_x, chip_y, chip_w, chip_h) and not widgets.block_under then
state.set(panel.id, not active)
widgets.interacted = true
end
cursor_x = cursor_x + chip_w + gap
end
local hot = input.hover(cursor_x, chip_y, settings_w, chip_h)
local t = anim.transition("hud-dock:settings", open_settings or hot, anim.motion_rate(18))
widgets.rect(cursor_x, chip_y, settings_w, chip_h,
theme.alpha(theme.NAV_IDLE or theme.BUTTON, 0.48 + t * 0.30), true, theme.CORNER_SMALL)
widgets.rect(cursor_x, chip_y, settings_w, chip_h,
open_settings and theme.alpha(theme.ACCENT, 0.72) or theme.BORDER_SOFT, false, theme.CORNER_SMALL)
icons.draw("settings", cursor_x + settings_w * 0.5, chip_y + chip_h * 0.5,
anim.mix(theme.TEXT_DIM, theme.TEXT_ACTIVE, t), 0.76)
if input.clicked(cursor_x, chip_y, settings_w, chip_h) and not widgets.block_under then
open_settings = not open_settings
widgets.open_combo = nil
widgets.open_multi = nil
widgets.open_color = nil
widgets.open_bind_mode = nil
widgets.interacted = true
end
if not popup_rect then popup_rect = {} end
popup_rect.x = x + w - (theme.DOCK_POPUP_W or 270)
popup_rect.y = y + h + 7
popup_rect.w = theme.DOCK_POPUP_W or 270
popup_rect.h = theme.DOCK_POPUP_H or 250
return dock_left
end
function M.draw_overlay()
if not open_settings or not popup_rect then return end
local r = popup_rect
local underlay_blocked = widgets.block_under
widgets.block_under = false
widgets.rect(r.x, r.y, r.w, r.h, theme.OVERLAY, true, theme.CORNER)
widgets.rect(r.x, r.y, r.w, r.h, theme.BORDER_SOFT, false, theme.CORNER)
local i18n = Infernal.require("ui.i18n")
widgets.text(r.x + 12, r.y + 10, i18n.t("HUD SETTINGS"), theme.TEXT_ACTIVE, theme.FONT_TITLE)
widgets.text(r.x + r.w - 22, r.y + 9, "x", theme.TEXT_DIM, theme.FONT_TITLE)
if input.clicked(r.x + r.w - 30, r.y + 3, 28, 25) then
open_settings = false
widgets.interacted = true
widgets.block_under = underlay_blocked
return
end
local iy = r.y + 38
local ix = r.x + 10
local iw = r.w - 20
for _, item in ipairs(visible_settings) do
local used = widgets.draw_item(item, ix, iy, iw)
iy = iy + math.max(used or 0, widgets.estimate_height(item)) + theme.ITEM_GAP
end
if input.lmb_click and not settings_opened_this_frame
and not input.hover(r.x, r.y, r.w, r.h)
and not (dock_rect and input.hover(dock_rect.x, dock_rect.y, dock_rect.w, dock_rect.h))
then
open_settings = false
end
widgets.block_under = underlay_blocked
end
return M
end)()

Infernal._mods["ui.menu_fx"] = (function()
local state = Infernal.require("ui.gs_state")
local widgets = Infernal.require("ui.gs_widgets")
local anim = Infernal.require("ui.gs_anim")
local settings = Infernal.require("core.settings")
local M = {}
local flakes = {}
local flake_count = 0
local last_now = nil
local function clamp(v, a, b)
    if v < a then return a end
    if v > b then return b end
    return v
end
local function screen_size()
    local w, h
    if draw then
        local fn = draw.get_screen_size or draw.GetScreenSize
        if fn then
            local ok, a, b = pcall(fn)
            if ok then w, h = a, b end
        end
    end
    if (not w or not h or w <= 0 or h <= 0) and utility then
        local fn = utility.get_screen_size or utility.GetScreenSize
        if fn then
            local ok, a, b = pcall(fn)
            if ok then w, h = a, b end
        end
    end
    w = math.floor(tonumber(w) or 0)
    h = math.floor(tonumber(h) or 0)
    if w <= 0 then w = 1920 end
    if h <= 0 then h = 1080 end
    return w, h
end
local function rebuild(count, sw, sh)
    flakes = {}
    flake_count = count
    for i = 1, count do
        flakes[i] = {
            x = math.random() * sw,
            y = math.random() * sh,
            size = 1.2 + math.random() * 2.4,
            speed = 0.35 + math.random() * 1.15,
            drift = (math.random() - 0.5) * 0.55,
            phase = math.random() * 6.28318,
            wobble = 0.6 + math.random() * 1.4,
        }
    end
end
local function dt()
    local now = anim.now()
    local d = 0.016
    if last_now then d = clamp(now - last_now, 0, 0.05) end
    last_now = now
    return d
end
local function fill_rect(x, y, w, h, col)
    if not draw or w <= 0 or h <= 0 then return end
    local fill = draw.rect_filled or draw.RectFilled or draw.filled_rect
    if not fill then return end
    pcall(fill, x, y, w, h, col, 0)
end
function M.draw_overlay(sw, sh, open_progress)
    -- menu backdrop shading removed: never dim the screen behind the menu
    do return end
    local strength = clamp(settings.num("infernal_ui_overlay_strength", 70), 0, 100)
    if strength <= 0 then
        strength = 70
    end
    local t = open_progress or 0
    if anim.ease_out_cubic then
        t = anim.ease_out_cubic(t)
    end
    t = clamp(t, 0, 1)
    if t < 0.01 then return end
    local a = (strength / 100) * 0.88 * t
    if a < 0.02 then return end
    widgets.clip = nil
    sw = math.floor(tonumber(sw) or 0)
    sh = math.floor(tonumber(sh) or 0)
    if sw <= 0 or sh <= 0 then
        sw, sh = screen_size()
    end
    fill_rect(-1, -1, sw + 2, sh + 2, { 0, 0, 0, a })
end
function M.draw_snow(sw, sh, open_progress)
    if not settings.bool("infernal_ui_snow", false) or anim.reduce_motion() then return end
    local fade = anim.ease_out_cubic and anim.ease_out_cubic(open_progress or 0) or (open_progress or 0)
    if fade < 0.02 then return end
    sw = math.floor(tonumber(sw) or 0)
    sh = math.floor(tonumber(sh) or 0)
    if sw <= 0 or sh <= 0 then
        sw, sh = screen_size()
    end
    local amount = math.floor(clamp(settings.num("infernal_ui_snow_amount", 50), 10, 140) + 0.5)
    local speed_mul = clamp(settings.num("infernal_ui_snow_speed", 40), 1, 100) / 40
    local opacity = clamp(settings.num("infernal_ui_snow_opacity", 55), 10, 100) / 100
    local size_mul = clamp(settings.num("infernal_ui_snow_size", 3), 1, 8) / 3
    if flake_count ~= amount or #flakes == 0 then rebuild(amount, sw, sh) end
    widgets.clip = nil
    local step = dt()
    local fall = 38 * speed_mul * step
    local alpha = opacity * fade * 0.9
    for i = 1, #flakes do
        local f = flakes[i]
        f.phase = f.phase + step * f.wobble
        f.y = f.y + fall * f.speed
        f.x = f.x + math.sin(f.phase) * f.drift * 18 * step * speed_mul
        if f.y > sh + 6 then
            f.y = -6 - math.random() * 24
            f.x = math.random() * sw
        elseif f.x < -8 then
            f.x = sw + 4
        elseif f.x > sw + 8 then
            f.x = -4
        end
        local s = math.max(1, f.size * size_mul)
        local a = alpha * (0.55 + 0.45 * ((math.sin(f.phase * 0.7) + 1) * 0.5))
        fill_rect(f.x, f.y, s, s, { 0.92, 0.95, 1.0, a })
    end
end
function M.draw_backdrop(sw, sh, open_progress)
    if (not sw or not sh or sw <= 0 or sh <= 0) then
        sw, sh = screen_size()
    end
    M.draw_overlay(sw, sh, open_progress)
    M.draw_snow(sw, sh, open_progress)
end
return M
end)()

Infernal._mods["ui.startup_intro"] = (function()
local theme = Infernal.require("ui.gs_theme")
local anim = Infernal.require("ui.gs_anim")
local settings = Infernal.require("core.settings")
local image_cache = Infernal.require("core.image_cache")
local asset_urls = Infernal.require("game.asset_urls")
local M = {}
local DURATION = 4.35
local MENU_REVEAL_AT = 3.72
local TEXT_EXIT_AT = 3.12
local PROFILE_KEY = "startup_author_profile"
local active = false
local started_at = 0
local function clamp01(value)
    if value < 0 then return 0 end
    if value > 1 then return 1 end
    return value
end
local function ease_out_cubic(value)
    local t = clamp01(value)
    local q = 1 - t
    return 1 - q * q * q
end
local function now()
    if utility and utility.get_time then return utility.get_time() end
    if utility and utility.get_tick_count then return utility.get_tick_count() * 0.001 end
    return 0
end
local function screen_size()
    local fn = draw and (draw.get_screen_size or draw.GetScreenSize)
    if fn then
        local ok, width, height = pcall(fn)
        if ok and width and height then return width, height end
    end
    return 1920, 1080
end
local function text_width(text, size)
    local fn = draw and (draw.get_text_size or draw.GetTextSize)
    if fn then
        local ok, width = pcall(fn, text, size)
        if ok and type(width) == "number" then return width end
    end
    return #tostring(text or "") * size * 0.56
end
local function draw_wave(text, center_x, y, size, alpha, phase_offset, amplitude)
    if alpha <= 0 or not draw then return end
    local draw_text = draw.text or draw.Text
    if not draw_text then return end
    local total_width = text_width(text, size)
    local cursor_x = center_x - total_width * 0.5
    local phase = now() * 4.0 + (phase_offset or 0)
    local accent = anim.title_color()
    amplitude = amplitude or 2
    for index = 1, #text do
        local char = text:sub(index, index)
        local wave = math.sin(phase + (index - 1) * 0.68)
        local mix = 0.12 + (wave + 1) * 0.12
        local color = anim.mix(accent, theme.TEXT_ACTIVE, mix)
        color = { color[1], color[2], color[3], alpha * (color[4] or 1) }
        draw_text(cursor_x, y + wave * amplitude, char, color, size)
        cursor_x = cursor_x + text_width(char, size)
    end
end
local function draw_module_status(center_x, y, elapsed, alpha)
    if alpha <= 0 or not Infernal or type(Infernal.load_status) ~= "table" then return end
    local draw_text = draw and (draw.text or draw.Text)
    local line = draw and (draw.line or draw.Line)
    if not draw_text or not line then return end
    local accent = anim.title_color()
    local size = math.max(12, math.floor(13 * (theme.SCALE or 1)))
    local i18n = Infernal.require("ui.i18n")
    local heading = i18n.t("Loading modules")
    local heading_size = math.max(11, size - 1)
    draw_text(center_x - text_width(heading, heading_size) * 0.5, y, heading,
        { theme.TEXT_ACTIVE[1], theme.TEXT_ACTIVE[2], theme.TEXT_ACTIVE[3], alpha * 0.48 },
        heading_size)
    local rows_y = y + 21
    for index, status in ipairs(Infernal.load_status) do
        local appear_at = 0.92 + (index - 1) * 0.24
        local appear = ease_out_cubic((elapsed - appear_at) / 0.22)
        if appear > 0 then
            local loaded = status.state == "loaded"
            local failed = status.state == "failed"
            local checked = loaded and ease_out_cubic((elapsed - appear_at - 0.13) / 0.20) or 0
            local name = i18n.t(tostring(status.name))
            local label = loaded and name
                or failed and (i18n.t("Failed: ") .. name)
                or (i18n.t("Loading ") .. name .. "...")
            local label_width = text_width(label, size)
            local row_alpha = alpha * appear
            local icon_x = center_x - (label_width + 24) * 0.5
            local icon_y = rows_y + (index - 1) * 19 + 7
            local text_color = failed and { 1, 0.28, 0.28, row_alpha }
                or { theme.TEXT_ACTIVE[1], theme.TEXT_ACTIVE[2], theme.TEXT_ACTIVE[3], row_alpha * 0.82 }
            if failed then
                line(icon_x, icon_y - 4, icon_x + 8, icon_y + 4, text_color, 1.5)
                line(icon_x + 8, icon_y - 4, icon_x, icon_y + 4, text_color, 1.5)
            elseif checked > 0 then
                local check_color = {
                    accent[1], accent[2], accent[3], row_alpha * checked,
                }
                line(icon_x, icon_y, icon_x + 3 * checked, icon_y + 4 * checked, check_color, 1.7)
                line(icon_x + 3, icon_y + 4, icon_x + 10 * checked, icon_y - 5 * checked, check_color, 1.7)
            else
                local pulse = 0.35 + (math.sin(now() * 5 + index) + 1) * 0.22
                line(icon_x, icon_y, icon_x + 7, icon_y,
                    { accent[1], accent[2], accent[3], row_alpha * pulse }, 1.7)
            end
            draw_text(icon_x + 18, rows_y + (index - 1) * 19, label, text_color, size)
        end
    end
end
function M.init()
    active = false
    return false
end
function M.cancel()
    active = false
end
function M.is_active()
    return false
end
function M.should_reveal_menu()
    return true
end
function M.draw()
    if not active or not draw then return false end
    local elapsed = math.max(0, now() - started_at)
    if elapsed >= DURATION then
        active = false
        return false
    end
    theme.sync()
    anim.sync_theme()
    local width, height = screen_size()
    local black_alpha
    if elapsed < 0.22 then
        black_alpha = ease_out_cubic(elapsed / 0.22)
    elseif elapsed < MENU_REVEAL_AT then
        black_alpha = 1
    else
        black_alpha = 1 - ease_out_cubic((elapsed - MENU_REVEAL_AT) / (DURATION - MENU_REVEAL_AT))
    end
    local fill = draw.rect_filled or draw.RectFilled
    if fill then fill(-1, -1, width + 2, height + 2, { 0, 0, 0, black_alpha }, 0) end
    local title_t = ease_out_cubic((elapsed - 0.16) / 0.62)
    local author_t = ease_out_cubic((elapsed - 0.58) / 0.52)
    local profile_t = ease_out_cubic((elapsed - 0.86) / 0.72)
    local text_out = 1 - ease_out_cubic((elapsed - TEXT_EXIT_AT) / 0.20)
    local profile_out = 1 - ease_out_cubic((elapsed - (MENU_REVEAL_AT - 0.18)) / 0.26)
    local title_alpha = title_t * text_out * black_alpha
    local author_alpha = author_t * text_out * black_alpha
    local profile_alpha = profile_t * profile_out * black_alpha
    local center_x = width * 0.5
    local center_y = height * 0.5
    local title_x = center_x - (1 - title_t) * math.min(160, width * 0.15)
    local author_x = center_x + (1 - author_t) * math.min(125, width * 0.12)
    local title_size = math.max(40, math.floor(54 * (theme.SCALE or 1)))
    local author_size = math.max(15, math.floor(18 * (theme.SCALE or 1)))
    draw_wave("Infernal.lua", title_x, center_y - 38, title_size, title_alpha, 0, 1.35)
    local i18n = Infernal.require("ui.i18n")
    draw_wave(i18n.t("Made by Cunzaki"), author_x, center_y + 22, author_size, author_alpha, 1.7, 0.8)
    draw_module_status(center_x, center_y + 62, elapsed, author_alpha)
    if profile_alpha > 0.01 then
        local final_w = math.max(230, math.min(420, math.floor(math.min(width, height) * 0.50)))
        local profile_w = final_w
        local profile_h = math.floor(profile_w * 399 / 375)
        local profile_x = width - profile_w * 0.76 + (1 - profile_t) * 94
        local profile_y = height - profile_h * 0.80 + (1 - profile_t) * 74
        image_cache.draw_fit(
            PROFILE_KEY,
            profile_x,
            profile_y,
            profile_w,
            profile_h,
            { 1, 1, 1, profile_alpha }
        )
    end
    local line = draw.line or draw.Line
    if line and author_alpha > 0 then
        local line_t = ease_out_cubic((elapsed - 0.82) / 0.44) * text_out
        local half = 76 * line_t
        local accent = anim.title_color()
        line(center_x - half, center_y + 46, center_x + half, center_y + 46,
            { accent[1], accent[2], accent[3], author_alpha * 0.58 }, 1)
    end
    return true
end
return M
end)()

Infernal._mods["ui.risk_prompt"] = (function()
-- Centered warning with two buttons, drawn on top of the menu. While it is open the menu
-- underneath ignores clicks and stays open so the cursor is available.
local M = {}
local current = nil
function M.open(spec)
    current = spec
end
function M.is_open(id)
    if not current then return false end
    return id == nil or current.id == id
end
function M.close(id)
    if current and (id == nil or current.id == id) then current = nil end
end
local function text_w(str, size)
    local fn = draw and (draw.get_text_size or draw.GetTextSize)
    if type(fn) ~= "function" then return #str * size * 0.55 end
    local ok, w = pcall(fn, str, size)
    return ok and tonumber(w) or #str * size * 0.55
end
local function button(gin, x, y, w, h, label, base, hot_col)
    local hot = gin.hover(x, y, w, h)
    draw.rect_filled(x, y, w, h, hot and hot_col or base, 3)
    draw.rect(x, y, w, h, { 1, 1, 1, hot and 0.35 or 0.15 }, 3, 1)
    draw.text(x + (w - text_w(label, 13)) * 0.5, y + (h - 13) * 0.5 - 1, label, { 1, 1, 1, 1 }, 13)
    return gin.clicked(x, y, w, h)
end
-- `area` is the menu window ({x, y, w, h}); the warning is centered on it, or on the screen.
function M.draw(sw, sh, area)
    if not current or not draw or not draw.rect_filled then return end
    local gin = Infernal.require("ui.gs_input")
    local accent = { 0.95, 0.3, 0.3, 1 }
    pcall(function()
        local theme = Infernal.require("ui.gs_theme")
        if theme.ACCENT then accent = theme.ACCENT end
    end)
    local w, pad = 380, 16
    local lines = current.lines or {}
    local h = 52 + #lines * 18 + 52
    local ax, ay, aw, ah = 0, 0, sw, sh
    if type(area) == "table" and tonumber(area.w) and tonumber(area.h) then
        ax, ay, aw, ah = area.x or 0, area.y or 0, area.w, area.h
    end
    local x = math.floor(ax + (aw - w) * 0.5)
    local y = math.floor(ay + (ah - h) * 0.5)
    draw.rect_filled(0, 0, sw, sh, { 0, 0, 0, 0.45 }, 0)
    draw.rect_filled(x, y, w, h, { 0.07, 0.06, 0.07, 0.98 }, 6)
    draw.rect(x, y, w, h, { 0.95, 0.3, 0.3, 0.9 }, 6, 1.5)
    draw.rect_filled(x + 1, y + 1, w - 2, 3, { 0.95, 0.3, 0.3, 1 }, 0)
    draw.text(x + pad, y + 16, current.title or "Warning", { 1, 0.42, 0.42, 1 }, 15)
    for i, line in ipairs(lines) do
        draw.text(x + pad, y + 44 + (i - 1) * 18, line, { 0.88, 0.88, 0.9, 1 }, 12)
    end
    local bw, bh = 150, 30
    local by = y + h - bh - 14
    local spec = current
    if button(gin, x + pad, by, bw, bh, spec.disable_label or "Disable",
        { 0.22, 0.2, 0.22, 1 }, { 0.32, 0.29, 0.32, 1 }) then
        current = nil
        if spec.on_disable then pcall(spec.on_disable) end
        return
    end
    if button(gin, x + w - pad - bw, by, bw, bh, spec.accept_label or "I Understand",
        { accent[1] * 0.75, accent[2] * 0.75, accent[3] * 0.75, 1 }, accent) then
        current = nil
        if spec.on_accept then pcall(spec.on_accept) end
    end
end
return M
end)()

Infernal._mods["ui.custom_menu"] = (function()
local theme = Infernal.require("ui.gs_theme")
local gin = Infernal.require("ui.gs_input")
local widgets = Infernal.require("ui.gs_widgets")
local anim = Infernal.require("ui.gs_anim")
local icons = Infernal.require("ui.gs_icons")
local catalog = Infernal.require("ui.catalog")
local state = Infernal.require("ui.gs_state")
local hud_dock = Infernal.require("ui.hud_dock")
local menu_fx = Infernal.require("ui.menu_fx")
local search_palette = Infernal.require("ui.search_palette")
local M = {}
local TOGGLE_VK_DEFAULT = 0x2D
local function menu_toggle_vk()
local vk = state.get_key("infernal_ui_menu_key")
if not vk or vk == 0 then
vk = TOGGLE_VK_DEFAULT
end
return vk
end
local open = true
local settled_closed = false
local tab_index = 1
for i, t in ipairs(catalog.TABS) do
if t.id == "aim" then tab_index = i break end
end
local win_x, win_y = 80, 80
local scroll = { left = 0, center = 0, right = 0 }
local scroll_visual = { left = 0, center = 0, right = 0 }
local middle_scroll = nil
local scrollbar_drag = nil
local collapsed_groups = {}
local last_menu_rect = nil
local group_layout_cache = {}
local search_focus = nil
local search_scroll_pending = false
local SCROLL_EDGE = 36
local SCROLL_SPEED = 5
local WHEEL_STEP = 48
local PAGE_STEP = 90
local MIDDLE_DRAG_SCALE = 1.35
local VK_PRIOR, VK_NEXT = 0x21, 0x22
local SEARCH_HIGHLIGHT_SECONDS = 1.8
local function screen_size()
if draw and draw.get_screen_size then
return draw.get_screen_size()
end
if utility and utility.get_screen_size then
return utility.get_screen_size()
end
return 1920, 1080
end
local function text_width(text, size)
local fn = draw and (draw.get_text_size or draw.GetTextSize)
if fn then
local ok, width = pcall(fn, text, size)
if ok and type(width) == "number" then return width end
end
return #tostring(text or "") * math.max(5, (size or 12) * 0.55)
end
local function draw_wave_text(wordmark, x, y, size, phase_offset, alpha)
local cursor_x = x
local phase = anim.now() * 3.4 + (phase_offset or 0)
local accent = anim.title_color()
alpha = alpha or 1
for i = 1, #wordmark do
local char = wordmark:sub(i, i)
local wave = math.sin(phase + (i - 1) * 0.72)
local col = anim.mix(accent, theme.TEXT_ACTIVE, 0.10 + (wave + 1) * 0.10)
col = { col[1], col[2], col[3], (col[4] or 1) * alpha }
widgets.text(cursor_x, y + wave * 1.5, char, col, size)
cursor_x = cursor_x + text_width(char, size)
end
return cursor_x
end
-- Fatality-style wordmark: flame logo, a gap, then bold INFERNAL with a soft accent glow.
-- Returns the x where the brand ends.
local function text_height(text, size)
local fn = draw and (draw.get_text_size or draw.GetTextSize)
if fn then
local ok, _, h = pcall(fn, text, size)
if ok and type(h) == "number" and h > 0 then return h end
end
return size
end
local function draw_brand(x, cy)
local fn = draw and (draw.text or draw.Text)
local ga = theme.GLOBAL_ALPHA or 1
local fs = theme.FONT_BRAND or 20
x = math.floor(x + 0.5)
local word = "INFERNAL"
local th = text_height(word, fs)
local ty = math.floor(cy - th * 0.5 + 0.5)
-- the flame is as tall as the letters and shares their center line
local logo_h = th * 0.92
local logo_w = icons.fire_logo_width(logo_h)
icons.fire_logo(x + logo_w * 0.5, ty + th * 0.5, logo_h, ga, anim.now())
local tx = math.floor(x + logo_w + 8 * (theme.SCALE or 1) + 0.5)
if fn then
-- one pass on whole pixels: overlapping copies and sub-pixel offsets are what made it blurry
fn(tx, ty, word, { 236/255, 236/255, 236/255, ga }, fs)
end
return tx + text_width(word, fs) + 1
end
local function clamp_window()
local sw, sh = screen_size()
win_x = math.max(0, math.min(win_x, sw - theme.WINDOW_W))
win_y = math.max(0, math.min(win_y, sh - 40))
end
local function master_on(id)
if not id then return true end
return state.get(id, false) == true
end
local function combo_value(id)
if not id then return nil end
local v = state.get(id)
if v == nil and menu and menu.get then
v = menu.get(id)
end
return tonumber(v)
end
local function color_override_on(idx)
if not idx then return true end
local t = state.get("infernal_ui_color_overrides")
if type(t) ~= "table" then return false end
local v = t[idx]
if v == nil and idx >= 1 then
v = t[idx - 1]
end
return v == true or v == 1
end
local function item_visible(item, group)
if search_focus and search_focus.group == group and search_focus.item == item then
return true
end
if group and group.master then
if item.id == group.master then
return true
end
if not master_on(group.master) then
return false
end
end
if item.gate and not master_on(item.gate) then
return false
end
if item.gate2 and not master_on(item.gate2) then
return false
end
-- shown only while that toggle is OFF (e.g. manual bullet stats while automatic is off)
if item.gate_off and state.get(item.gate_off, item.gate_off_default ~= false) == true then
return false
end
if item.gate_combo then
local cur = combo_value(item.gate_combo)
local want = tonumber(item.gate_combo_value) or 0
if cur ~= want then
return false
end
end
-- shown only while one option of a multi-select is ticked: { id, index, default }
if item.gate_multi then
local gm = item.gate_multi
local t = state.get(gm[1])
if type(t) ~= "table" and menu and menu.get then t = menu.get(gm[1]) end
local v = nil
if type(t) == "table" then v = t[gm[2]] end
if v == nil then v = gm[3] end
if v ~= true then return false end
end
if item.gate_any_combo then
local ok = false
for _, pair in ipairs(item.gate_any_combo) do
local cid = pair[1] or pair.id
local want = pair[2] or pair.value
local cur = combo_value(cid)
if type(want) == "table" then
for _, w in ipairs(want) do
if cur == w then ok = true; break end
end
elseif cur == want then
ok = true
end
if ok then break end
end
if not ok then return false end
end
if item.color_override_idx and not color_override_on(item.color_override_idx) then
return false
end
if item.id and not state.is_visible(item.id) then
return false
end
return true
end
local function content_height(items, group)
local h = 0
local count = 0
for _, item in ipairs(items) do
if item_visible(item, group) then
h = h + widgets.estimate_height(item)
count = count + 1
end
end
if count > 1 then
h = h + (count - 1) * theme.ITEM_GAP
end
return h + 8
end
local function group_visible(group)
local items = group.items or {}
for _, item in ipairs(items) do
if item_visible(item, group) then
return true
end
end
return false
end
local function reset_scroll()
for _, key in ipairs({ "left", "center", "right" }) do
scroll[key] = 0
scroll_visual[key] = 0
end
end
-- Opening the Rage tab shows a warning first (once per session). Go Back returns to the tab
-- you were on before it.
local rage_ack = false
local function switch_tab(i)
local tab = catalog.TABS[i]
if not tab or i == tab_index then return end
local back = tab_index
tab_index = i
reset_scroll()
anim.clear_tab_progress(tab.id)
widgets.open_combo = nil
widgets.open_multi = nil
if tab.id == "rage" and not rage_ack then
Infernal.require("ui.risk_prompt").open({
id = "rage_tab",
title = "Rage features are risky",
lines = {
"The ragebot and silent aim redirect your shots",
"and the ragebot can fire for you. Both are easier",
"to spot and could get your account flagged or",
"banned. Use them at your own risk.",
},
disable_label = "Go Back",
accept_label = "I Understand",
on_accept = function() rage_ack = true end,
on_disable = function()
local prev = catalog.TABS[back]
tab_index = back
reset_scroll()
if prev then anim.clear_tab_progress(prev.id) end
end,
})
end
end
M.switch_tab = switch_tab
function M.current_tab()
return catalog.TABS[tab_index]
end
-- Fatality tab strip: icon + uppercase label, the active tab sits on a soft pill that glides
-- between tabs. Returns the strip's right edge.
local function draw_tabs(x, y, h)
local tabs = catalog.TABS
local i18n = Infernal.require("ui.i18n")
local s = theme.SCALE or 1
local fs = theme.FONT_CAPTION or 12
local icon_w = math.floor(16 * s)
local pad = math.floor(10 * s)
local gap = math.floor(4 * s)
local cursor_x = x
local active_x, active_w = nil, nil
local rects = {}
for i, tab in ipairs(tabs) do
local label = i18n.t(tab.label or tab.title or tab.id)
local tw = pad + icon_w + math.floor(6 * s) + text_width(label, fs) + pad
rects[i] = { x = cursor_x, w = tw, label = label }
if i == tab_index then active_x, active_w = cursor_x, tw end
cursor_x = cursor_x + tw + gap
end
if active_x then
local hx = anim.smooth("fat-tab-x", active_x - x, anim.motion_rate(20)) + x
local hw = anim.smooth("fat-tab-w", active_w, anim.motion_rate(20))
widgets.rect(hx, y, hw, h, theme.ELEM, true, 4)
widgets.rect(hx, y, hw, h, theme.alpha(theme.LINE, 0.9), false, 4)
end
for i, tab in ipairs(tabs) do
local r = rects[i]
local active = i == tab_index
local hot = gin.hover(r.x, y, r.w, h) and not widgets.block_under
local hov_t = anim.transition("fat-tab-hover:" .. tab.id, hot and not active, 16)
if hov_t > 0.01 then
widgets.rect(r.x, y, r.w, h, theme.alpha(theme.ELEM, 0.55 * hov_t), true, 4)
end
local act_t = anim.transition("fat-tab-active:" .. tab.id, active, anim.motion_rate(18))
local icon_col = anim.mix(anim.mix(theme.TEXT_DIM, theme.TEXT, hov_t), theme.ACCENT, act_t)
local text_col = anim.mix(anim.mix(theme.TEXT_DIM, theme.TEXT, hov_t), theme.TEXT_ACTIVE, act_t)
-- label centered on its measured height; the icon shares that exact center line
local th = text_height(r.label, fs)
local ty = math.floor(y + (h - th) * 0.5 + 0.5)
local mid = ty + th * 0.5
icons.draw(tab.icon or tab.id, r.x + pad + icon_w * 0.5, mid, icon_col)
widgets.text(r.x + pad + icon_w + math.floor(6 * s), ty, r.label, text_col, fs)
if gin.clicked(r.x, y, r.w, h) and not widgets.block_under and not active then
switch_tab(i)
end
end
return cursor_x
end
local function clamp_scroll(key, content_h, view_h)
local max_scroll = math.max(0, content_h - view_h)
if scroll[key] < 0 then scroll[key] = 0 end
if scroll[key] > max_scroll then scroll[key] = max_scroll end
return max_scroll
end
local function draw_scrollbar(x, y, h, content_h, scroll_key, view_h)
view_h = view_h or h
local max_scroll = clamp_scroll(scroll_key, content_h, view_h)
if max_scroll <= 0 then
scroll[scroll_key] = 0
if scrollbar_drag and scrollbar_drag.key == scroll_key then
scrollbar_drag = nil
end
return
end
local rail_x = x
local rail_y = y + 2
local rail_w = math.max(7, math.floor(7 * (theme.SCALE or 1)))
local rail_h = h - 4
local thumb_h = math.max(36, math.min(88, rail_h * (view_h / content_h)))
local visual = scroll_visual[scroll_key] or scroll[scroll_key]
visual = math.max(0, math.min(max_scroll, visual))
local t = visual / max_scroll
local travel = math.max(1, rail_h - thumb_h)
local thumb_y = rail_y + t * travel
local thumb_x = rail_x + 1
local thumb_w = rail_w - 2
local rail_hot = gin.hover(rail_x - 2, rail_y, rail_w + 4, rail_h)
local thumb_hot = gin.hover(thumb_x - 2, thumb_y - 2, thumb_w + 4, thumb_h + 4)
if scrollbar_drag and scrollbar_drag.key == scroll_key then
if gin.lmb then
local raw_t = (gin.my - rail_y - scrollbar_drag.offset_y) / travel
raw_t = math.max(0, math.min(1, raw_t))
scroll[scroll_key] = raw_t * max_scroll
scroll_visual[scroll_key] = scroll[scroll_key]
t = raw_t
thumb_y = rail_y + t * travel
widgets.interacted = true
else
scrollbar_drag = nil
end
elseif gin.lmb_click and rail_hot and not widgets.block_under then
local offset_y = thumb_h * 0.5
if thumb_hot then offset_y = gin.my - thumb_y end
scrollbar_drag = { key = scroll_key, offset_y = offset_y }
local raw_t = (gin.my - rail_y - offset_y) / travel
raw_t = math.max(0, math.min(1, raw_t))
scroll[scroll_key] = raw_t * max_scroll
scroll_visual[scroll_key] = scroll[scroll_key]
thumb_y = rail_y + raw_t * travel
widgets.interacted = true
end
local active = scrollbar_drag and scrollbar_drag.key == scroll_key
local emphasis = anim.transition("scrollbar:" .. scroll_key, rail_hot or active, 18)
-- slim Fatality scrollbar: faint rail, rounded accent thumb that brightens on hover
local slim = math.max(3, math.floor(3 * (theme.SCALE or 1) + emphasis * 1.5))
local sx = rail_x + rail_w - slim - 1
widgets.rect(sx, rail_y, slim, rail_h, theme.alpha(theme.ELEM, 0.35 + emphasis * 0.35), true, slim * 0.5)
widgets.rect(sx, thumb_y, slim, thumb_h, theme.alpha(theme.ACCENT, 0.45 + emphasis * 0.45), true, slim * 0.5)
end
local function handle_column_scroll(x, y, w, h, scroll_key, content_h)
local max_scroll = clamp_scroll(scroll_key, content_h, h)
if max_scroll <= 0 then
if middle_scroll and middle_scroll.key == scroll_key then middle_scroll = nil end
return
end
local hot = gin.hover(x, y, w + 14, h)
if middle_scroll and middle_scroll.key == scroll_key then
if gin.mmb then
scroll[scroll_key] = middle_scroll.start_scroll
+ (middle_scroll.start_y - gin.my) * MIDDLE_DRAG_SCALE
clamp_scroll(scroll_key, content_h, h)
widgets.interacted = true
return
end
middle_scroll = nil
end
if not hot then return end
if gin.mmb_click then
middle_scroll = {
key = scroll_key,
start_y = gin.my,
start_scroll = scroll[scroll_key],
}
widgets.interacted = true
return
end
if gin.wheel ~= 0 and not widgets.wheel_consumed then
scroll[scroll_key] = scroll[scroll_key] - gin.wheel * WHEEL_STEP
clamp_scroll(scroll_key, content_h, h)
widgets.wheel_consumed = true
return
end
if gin.key_pressed(VK_PRIOR) then
scroll[scroll_key] = scroll[scroll_key] - PAGE_STEP
clamp_scroll(scroll_key, content_h, h)
return
end
if gin.key_pressed(VK_NEXT) then
scroll[scroll_key] = scroll[scroll_key] + PAGE_STEP
clamp_scroll(scroll_key, content_h, h)
return
end
if gin.my < y + SCROLL_EDGE then
scroll[scroll_key] = scroll[scroll_key] - SCROLL_SPEED
clamp_scroll(scroll_key, content_h, h)
elseif gin.my > y + h - SCROLL_EDGE then
scroll[scroll_key] = scroll[scroll_key] + SCROLL_SPEED
clamp_scroll(scroll_key, content_h, h)
end
end
local function focus_strength(group, item)
if not search_focus or search_focus.group ~= group or search_focus.item ~= item then
return 0
end
local elapsed = anim.now() - search_focus.started_at
if elapsed >= SEARCH_HIGHLIGHT_SECONDS then return 0 end
local fade = 1 - elapsed / SEARCH_HIGHLIGHT_SECONDS
return math.min(1, fade * 1.8)
end
-- InfernalHook BeginSection title: accent text overlapping the top border
-- Fatality section title: bold uppercase white inside the box's top-left; a small chevron
-- shows on hover for collapsing.
local function draw_group_title(x, box_top, w, title, collapsed, hot, active, focus)
local fs = theme.FONT_TITLE or 14
local tx = x + 10
local ty = box_top + math.floor((theme.GROUP_HEADER_H - fs) * 0.5) - 1
local upper = string.upper(tostring(title or ""))
local col = focus > 0.3 and theme.ACCENT or theme.TEXT_TITLE
widgets.text(tx, ty, upper, col, fs)
widgets.text(tx + 0.6, ty, upper, col, fs)
local hov_t = anim.transition("fat-group-hover:" .. upper, hot or collapsed, 16)
if hov_t > 0.02 then
local line_fn = draw and (draw.line or draw.Line)
if line_fn then
local cx = x + w - 14
local cy = box_top + theme.GROUP_HEADER_H * 0.5
local icol = theme.alpha(theme.TEXT_DIM, hov_t)
if collapsed then
line_fn(cx - 3, cy - 1.5, cx, cy + 1.5, icol, 1.4)
line_fn(cx, cy + 1.5, cx + 3, cy - 1.5, icol, 1.4)
else
line_fn(cx - 3, cy + 1.5, cx, cy - 1.5, icol, 1.4)
line_fn(cx, cy - 1.5, cx + 3, cy + 1.5, icol, 1.4)
end
end
end
end
local function draw_group_column(groups, x, y, w, h, scroll_key)
local pad = theme.GROUP_PAD
local visible_groups = {}
for _, group in ipairs(groups) do
if group_visible(group) then
local collapse_key = scroll_key .. ":" .. tostring(group.title)
if search_focus and search_focus.group == group then
collapsed_groups[collapse_key] = false
end
local collapsed = collapsed_groups[collapse_key] == true
local expanded = anim.transition(
"group-expand:" .. collapse_key,
not collapsed,
anim.motion_rate(18)
)
if search_focus and search_focus.group == group then expanded = 1 end
if collapsed and expanded < 0.02 then expanded = 0 end
if not collapsed and expanded > 0.98 then expanded = 1 end
-- Eased so items that appear or hide with a setting (e.g. Random hit part sliders) slide
-- open and closed; rows past the eased height stay hidden until the box reaches them.
local full_h = anim.smooth("group-height:" .. collapse_key,
content_height(group.items or {}, group), anim.motion_rate(14))
visible_groups[#visible_groups + 1] = {
group = group,
key = collapse_key,
collapsed = collapsed,
expanded = expanded,
full_h = full_h,
inner_h = full_h * expanded,
}
end
end
local total = 0
for _, entry in ipairs(visible_groups) do
total = total + entry.inner_h + theme.GROUP_HEADER_H + theme.GROUP_GAP
end
clamp_scroll(scroll_key, total, h)
scroll_visual[scroll_key] = anim.smooth(
"column-scroll:" .. scroll_key,
scroll[scroll_key],
anim.motion_rate(18)
)
local gy = y + pad - scroll_visual[scroll_key]
local focus_screen_y = nil
-- Like Fatality, the last section in a column stretches down to fill the column.
local fill_extra = math.max(0, h - pad - total + theme.GROUP_GAP - 2)
widgets.clip = { x = x, y = y, w = w, h = h }
for idx, entry in ipairs(visible_groups) do
local group = entry.group
local items = group.items or {}
local inner_h = entry.inner_h
local box_h = inner_h + theme.GROUP_HEADER_H
if idx == #visible_groups then box_h = box_h + fill_extra end
local box_top = gy
local box_bot = gy + box_h
if search_focus and search_focus.group == group and search_focus.item == nil then
focus_screen_y = box_top + theme.GROUP_HEADER_H * 0.5
elseif search_focus and search_focus.group == group and search_focus.item then
local target_y = gy + theme.GROUP_HEADER_H
for _, candidate in ipairs(items) do
if item_visible(candidate, group) then
local target_h = widgets.estimate_height(candidate)
if candidate == search_focus.item then
focus_screen_y = target_y + target_h * 0.5
break
end
target_y = target_y + target_h + theme.ITEM_GAP
end
end
end
if box_bot > y and box_top < y + h then
local vis_y = math.max(box_top, y)
local vis_b = math.min(box_bot, y + h)
local vis_h = vis_b - vis_y
if vis_h > 1 then
local r = math.max(2, math.floor(4 * (theme.SCALE or 1)))
widgets.rect(x, vis_y, w, vis_h, theme.PANEL, true, r)
widgets.rect(x, vis_y, w, vis_h, theme.LINE, false, r)
if box_top >= y - 2 and box_top < y + h then
local header_hot = gin.hover(x, box_top, w, theme.GROUP_HEADER_H)
local i18n = Infernal.require("ui.i18n")
draw_group_title(x, box_top, w, i18n.t(group.title), entry.collapsed,
header_hot, group.master and master_on(group.master),
focus_strength(group, nil))
if gin.clicked(x, box_top, w, theme.GROUP_HEADER_H)
and not widgets.block_under
and not widgets.open_combo and not widgets.open_multi
and not widgets.open_color and not widgets.open_bind_mode
then
collapsed_groups[entry.key] = not entry.collapsed
end
end
end
local iy = gy + theme.GROUP_HEADER_H
local ix = x + 2
local iw = w - 8
local reveal_bottom = gy + theme.GROUP_HEADER_H + inner_h
for _, item in ipairs(items) do
if item_visible(item, group) then
local est = widgets.estimate_height(item)
if iy >= y and iy + est <= y + h and iy + est <= reveal_bottom then
local focus = focus_strength(group, item)
if focus > 0.01 then
widgets.rect(ix - 2, iy - 2, iw + 4, est + 4,
theme.alpha(theme.ACCENT_DIM, 0.28 + focus * 0.34),
true, theme.CORNER_SMALL)
widgets.rect(ix - 2, iy + 3, 2, math.max(4, est - 6),
theme.alpha(theme.ACCENT, focus), true, 1)
end
local used = widgets.draw_item(item, ix, iy, iw)
if used < 1 then used = est end
iy = iy + used + theme.ITEM_GAP
else
iy = iy + est + theme.ITEM_GAP
end
end
end
end
gy = gy + box_h + theme.GROUP_GAP
end
widgets.clip = nil
if search_scroll_pending and focus_screen_y then
scroll[scroll_key] = scroll[scroll_key] + focus_screen_y - (y + h * 0.42)
clamp_scroll(scroll_key, total, h)
scroll_visual[scroll_key] = scroll[scroll_key]
search_scroll_pending = false
end
handle_column_scroll(x, y, w, h, scroll_key, total)
draw_scrollbar(x + w - 3, y + pad, h - pad * 2, total, scroll_key, h)
end
-- Three Fatality columns, taken from each section's column in the catalog layout.
local function split_columns(groups, tab_id)
local cached = group_layout_cache[tab_id]
if cached and cached.source == groups then return cached.left, cached.center, cached.right end
local cols = { left = {}, center = {}, right = {} }
for _, g in ipairs(groups) do
local key = cols[g.column or ""] and g.column or nil
if not key then
local fewest = "left"
for _, k in ipairs({ "center", "right" }) do
if #cols[k] < #cols[fewest] then fewest = k end
end
key = fewest
end
cols[key][#cols[key] + 1] = g
end
group_layout_cache[tab_id] = { source = groups, left = cols.left, center = cols.center, right = cols.right }
return cols.left, cols.center, cols.right
end
function M.init()
state.define("infernal_ui_theme_preset", 0)
state.define("infernal_ui_window_opacity", 100)
state.define("infernal_ui_panel_opacity", 100)
state.define("infernal_ui_border_strength", 100)
state.define("infernal_ui_corner_style", 0)
state.define("infernal_ui_scale", 102)
state.define("infernal_ui_density", 1)
state.define("infernal_ui_motion_profile", 1)
state.define("infernal_ui_reduce_motion", false)
state.define("infernal_ui_custom_colors", false)
state.define("infernal_ui_custom_anim", false)
state.define("infernal_ui_per_element", false)
state.define("infernal_ui_show_cursor_dot", true)
state.define("infernal_ui_accent", theme.ACCENT)
state.define("infernal_ui_accent_anim", 1)
state.define("infernal_ui_anim_speed", 40)
state.define("infernal_ui_menu_overlay", true)
state.define("infernal_ui_overlay_strength", 70)
state.define("infernal_ui_snow", false)
state.define("infernal_ui_snow_amount", 50)
state.define("infernal_ui_snow_speed", 40)
state.define("infernal_ui_snow_size", 3)
state.define("infernal_ui_snow_opacity", 55)
state.define("infernal_ui_menu_fade", false)
state.define("infernal_ui_russian", false)
state.define("infernal_ui_anim_targets", {
true, true, true, true, true, true, true, true,
})
state.define("infernal_ui_color_overrides", {})
state.define("infernal_ui_style_title", 0)
state.define("infernal_ui_style_section", 0)
state.define("infernal_ui_style_slider", 0)
state.define("infernal_ui_style_scroll", 0)
state.define("infernal_ui_style_sidebar", 0)
state.define("infernal_ui_style_checkbox", 0)
state.define("infernal_ui_style_overlay", 0)
state.define_color("infernal_ui_col_title", theme.ACCENT)
state.define_color("infernal_ui_col_section", theme.ACCENT)
state.define_color("infernal_ui_col_slider", theme.ACCENT)
state.define_color("infernal_ui_col_scroll", theme.ACCENT)
state.define_color("infernal_ui_col_sidebar", theme.ACCENT)
state.define_color("infernal_ui_col_checkbox", theme.ACCENT)
state.define_color("infernal_ui_col_overlay", theme.ACCENT)
search_palette.init()
hud_dock.init()
if state.get_key("infernal_ui_menu_key") == 0 then
state.set_key("infernal_ui_menu_key", TOGGLE_VK_DEFAULT)
end
local sw, sh = screen_size()
theme.sync()
local default_x = math.floor((sw - theme.WINDOW_W) * 0.5)
local default_y = math.floor((sh - theme.WINDOW_H) * 0.3)
state.define("infernal_ui_window_x", default_x)
state.define("infernal_ui_window_y", default_y)
win_x = tonumber(state.get("infernal_ui_window_x", default_x)) or default_x
win_y = tonumber(state.get("infernal_ui_window_y", default_y)) or default_y
clamp_window()
end
function M.is_open()
return open
end
function M.contains_point(px, py)
if not open or not last_menu_rect then return false end
local r = last_menu_rect
return px >= r.x and py >= r.y and px <= r.x + r.w and py <= r.y + r.h
end
function M.draw()
if not draw then return end
gin.begin_frame()
if gin.key_pressed(menu_toggle_vk()) and not widgets.listening_key
and not widgets.active_input and not widgets.active_slider_input then
open = not open
if open then settled_closed = false end
gin.set_menu_open(open)
end
local risk_prompt = Infernal.require("ui.risk_prompt")
if risk_prompt.is_open() and not open then
open = true
settled_closed = false
gin.set_menu_open(true)
end
if not open and settled_closed then
if gin._menu_open or gin._game_cursor_hidden then
gin.set_menu_open(false)
end
return
end
anim.sync_theme()
widgets.begin_popups()
hud_dock.begin_frame()
widgets.tick_key_listen()
widgets.tick_slider_input()
widgets.tick_text_input()
local search_result = search_palette.consume_selection()
if search_result then
if search_result.tab_index then switch_tab(search_result.tab_index) end
scroll.left, scroll.right = 0, 0
scroll_visual.left, scroll_visual.right = 0, 0
if search_result.group then
search_focus = {
group = search_result.group,
item = search_result.item,
started_at = anim.now(),
}
search_scroll_pending = true
else
search_focus = nil
search_scroll_pending = false
end
widgets.open_combo = nil
widgets.open_multi = nil
end
if search_focus and anim.now() - search_focus.started_at >= SEARCH_HIGHLIGHT_SECONDS then
search_focus = nil
search_scroll_pending = false
end
local open_progress = anim.menu_open_progress(open)
if not open and open_progress <= 0.015 then
settled_closed = true
if gin._menu_open or gin._game_cursor_hidden then
gin.set_menu_open(false)
end
return
end
settled_closed = false
if not open then
widgets.block_under = true
end
gin.set_menu_open(open)
theme.apply_global_alpha(open_progress)
if not widgets.dragging_window then
win_x = tonumber(state.get("infernal_ui_window_x", win_x)) or win_x
win_y = tonumber(state.get("infernal_ui_window_y", win_y)) or win_y
end
clamp_window()
local x = win_x
local y = win_y + math.floor((1 - open_progress) * 10 * (theme.SCALE or 1))
local w, h = theme.WINDOW_W, theme.WINDOW_H
if not last_menu_rect then last_menu_rect = {} end
last_menu_rect.x, last_menu_rect.y, last_menu_rect.w, last_menu_rect.h = x, y, w, h
widgets.clip = nil
local sw, sh = screen_size()
pcall(menu_fx.draw_backdrop, sw, sh, open_progress)
gin.set_ui_rect(x, y, w, h)
-- hud dock removed: panel toggles are now in the Config tab
local s = theme.SCALE or 1
local ga = theme.GLOBAL_ALPHA or 1
local R = theme.CORNER or 6
local HB = theme.HEADER_BAR_H or math.floor(42 * s)
local FH = theme.FOOTER_H or math.floor(25 * s)
widgets.rect(x, y, w, h, theme.BG, true, R)
-- header bar (rounded top, square bottom) with a hairline and a soft shade below it
widgets.rect(x, y, w, HB, theme.HEADER_BG, true, R)
widgets.rect(x, y + HB - R, w, R, theme.HEADER_BG, true, 0)
widgets.rect(x, y + HB, w, 1, theme.LINE, true, 0)
widgets.rect(x, y + HB + 1, w, 2, { 0, 0, 0, 0.22 * ga }, true, 0)
widgets.rect(x, y + HB + 3, w, 3, { 0, 0, 0, 0.09 * ga }, true, 0)
-- footer bar (square top, rounded bottom)
local fy = y + h - FH
widgets.rect(x, fy, w, FH, theme.HEADER_BG, true, R)
widgets.rect(x, fy, w, R, theme.HEADER_BG, true, 0)
widgets.rect(x, fy, w, 1, theme.LINE, true, 0)
widgets.rect(x, y, w, h, theme.WINDOW_EDGE, false, R)
local tab = catalog.TABS[tab_index]
local brand_end = draw_brand(x + math.floor(14 * s), y + HB * 0.5)
local tabs_x = brand_end + math.floor(18 * s)
local tab_h = HB - math.floor(14 * s)
local tab_y = y + math.floor((HB - tab_h) * 0.5)
if search_palette.is_open() then
widgets.block_under = true
end
if risk_prompt.is_open() then
widgets.block_under = true
end
local tabs_end = draw_tabs(tabs_x, tab_y, tab_h)
-- footer: search / save / configs on the left, version + info on the right
local i18n = Infernal.require("ui.i18n")
local fcy = math.floor(fy + FH * 0.5 + 2 * s + 0.5)
local function footer_icon(name, cx, tip_text)
local box = math.floor(20 * s)
local bx, by = cx - box * 0.5, fcy - box * 0.5
local hot = gin.hover(bx, by, box, box) and not widgets.block_under
local hov_t = anim.transition("fat-foot:" .. name, hot, 18)
if hov_t > 0.01 then
widgets.rect(bx, by, box, box, theme.alpha(theme.ELEM, hov_t), true, 4)
end
icons.draw(name, cx, fcy, anim.mix(theme.alpha(theme.TEXT_DIM, 0.75), theme.TEXT_ACTIVE, hov_t))
if hot and tip_text then
widgets.register_tooltip_hover("fat-foot:" .. name, tip_text, bx, by, box, box)
end
return hot and gin.lmb_click
end
if footer_icon("search", x + math.floor(16 * s), i18n.t("Search")) then
search_palette.toggle()
widgets.interacted = true
end
if footer_icon("save", x + math.floor(40 * s), i18n.t("Save Config")) then
state.fire_button("infernal_cfg_save")
widgets.interacted = true
end
if footer_icon("folder", x + math.floor(64 * s), i18n.t("Configs")) then
for i, t in ipairs(catalog.TABS) do
if t.id == "config" then tab_index = i end
end
reset_scroll()
widgets.interacted = true
end
local version = "Infernal v" .. tostring(Infernal.version or "")
footer_icon("info", x + w - math.floor(16 * s), version)
local vfs = theme.FONT_TINY or 10
widgets.text(x + w - math.floor(30 * s) - text_width(version, vfs), fcy - math.floor(vfs * 0.5) - 1,
version, theme.alpha(theme.TEXT_DIM, 0.6 * ga), vfs)
-- drag the window from any empty part of the header
local over_tabs = gin.hover(tabs_x, tab_y, tabs_end - tabs_x, tab_h)
if gin.lmb_click and gin.hover(x, y, w, HB) and not over_tabs
and not widgets.active_slider and not widgets.active_slider_input and not widgets.listening_key
and not widgets.active_input
and not widgets.block_under
and not widgets.open_combo and not widgets.open_multi and not widgets.open_color
and not widgets.open_bind_mode then
widgets.dragging_window = true
widgets.drag_offset_x = gin.mx - win_x
widgets.drag_offset_y = gin.my - win_y
end
if widgets.dragging_window then
if gin.lmb then
win_x = gin.mx - widgets.drag_offset_x
win_y = gin.my - widgets.drag_offset_y
clamp_window()
state.set("infernal_ui_window_x", math.floor(win_x))
state.set("infernal_ui_window_y", math.floor(win_y))
else
widgets.dragging_window = false
end
end
local pad = math.floor(10 * s)
local gap = math.floor(9 * s)
local body_y = y + HB + pad
local body_h = h - HB - FH - pad * 2 - math.floor(6 * s)
local col_w = math.floor((w - pad * 2 - gap * 2) / 3)
local tab_id = tab and tab.id or "aim"
local groups = catalog.groups_for(tab_id)
local left_groups, center_groups, right_groups = split_columns(groups, tab_id)
local tab_progress = anim.tab_progress(tab_id)
local tab_shift = math.floor((1 - tab_progress) * 10 * s)
local cx0 = x + pad + tab_shift
draw_group_column(left_groups, cx0, body_y, col_w, body_h, "left")
draw_group_column(center_groups, cx0 + col_w + gap, body_y, col_w, body_h, "center")
draw_group_column(right_groups, cx0 + (col_w + gap) * 2, body_y, col_w, body_h, "right")
widgets.end_tooltip_frame()
hud_dock.draw_overlay()
widgets.draw_color_overlay()
widgets.draw_bind_mode_overlay()
widgets.draw_color_ctx_overlay()
widgets.draw_tooltip_overlay()
search_palette.draw(x + w * 0.5, y + HB + 7, w)
pcall(risk_prompt.draw, sw, sh, { x = x, y = y, w = w, h = h })
widgets.end_popups()
if open then
gin.draw_cursor()
end
end
return M
end)()

Infernal._mods["menu.tabs"] = (function()
local menu_util = Infernal.require("core.menu_util")
local debug = Infernal.require("core.debug")
local bootstrap = Infernal.require("game.bootstrap")
local cache = Infernal.require("core.cache")
local npcs = Infernal.require("game.npcs")
local player_state = Infernal.require("game.player_state")
local weapons = Infernal.require("game.weapons")
local runservice = Infernal.require("core.runservice")
local incremental_scan = Infernal.require("core.incremental_scan")
local rbx_offsets = Infernal.require("core.rbx_offsets")
local M = {}
M.features = {}
M._menu_registered = false
M._update_dispatch = {}
M._draw_dispatch = {}
M.FEATURE_ORDER = {
    "features.visuals.target_overlay",
    "features.visuals.esp_chams",
    "features.visuals.player_esp",
    "features.visuals.sound_esp",
    "features.world.world_esp",
    "features.world.loot_esp",
    "features.world.npc_esp",
    "features.world.raid_esp",
    "features.world.base_esp",
    "features.world.base_xray",

    "features.combat.aimbot",
    "features.combat.ragebot",
    "features.combat.silent_aim",
    "features.combat.heli_aimbot",
    "features.combat.recoil_control",
    "features.visuals.combat_mode",
    "features.movement.bhop",
    "features.movement.anti_fling",
    "features.utility.autofarm",
    "features.utility.farm_helper",
    "features.utility.mod_checker",
    "features.utility.event_status",
    "features.utility.anti_afk",
    "features.utility.keybind_viewer",
    "features.visuals.crosshair",
    "features.visuals.bullet_tracers",
    "features.visuals.arm_chams",
    "features.visuals.hitsounds",
    "features.utility.config",
}
function M.register_all()
    if M._menu_registered then return end
    menu_util.ensure_groups()
    M.features = {}
    M._update_dispatch = {}
    M._draw_dispatch = {}
    local registered = 0
    for _, path in ipairs(M.FEATURE_ORDER) do
        local feat = Infernal.require(path)
        table.insert(M.features, feat)
        if type(feat.update) == "function" then
            M._update_dispatch[#M._update_dispatch + 1] = {
                name = "update:" .. path,
                fn = feat.update,
            }
        end
        if type(feat.draw) == "function" then
            M._draw_dispatch[#M._draw_dispatch + 1] = {
                name = "draw:" .. path,
                fn = feat.draw,
            }
        end
        if feat.register_menu then
            local ok = pcall(feat.register_menu)
            if ok then
                registered = registered + 1
            end
        end
    end
    M._menu_registered = true
    pcall(function()
        local mod = Infernal.require("features.utility.mod_checker")
        if mod.init then mod.init() end
    end)
end
function M.setup_scans()
    local settings = Infernal.require("core.settings")
    local cache = Infernal.require("core.cache")
    local iscan = Infernal.require("core.incremental_scan")
    local world_esp = Infernal.require("features.world.world_esp")
    local loot_esp = Infernal.require("features.world.loot_esp")
    local base_esp = Infernal.require("features.world.base_esp")
    iscan.configure({ budget_ms = 6, items_per_step = 18 })
    local SCAN_MS = cache.WORKSPACE_SCAN_MS or 1000
    local DROPS_SCAN_MS = cache.DROPS_SCAN_MS or 3500
    local function map_on(layer)
        return function()
            if not settings.enabled("infernal_map_enabled") then return false end
            return settings.enabled("infernal_map_show_" .. layer)
        end
    end
    iscan.register("world", SCAN_MS, function()
        return settings.enabled("infernal_world_enabled") or map_on("world")()
    end, world_esp.begin_static_scan, world_esp.step_static_scan, world_esp.complete_static_scan, 0)
    iscan.register("world_dynamic", SCAN_MS, function()
        if not settings.enabled("infernal_world_enabled") then return false end
        return settings.enabled("infernal_deer")
            or settings.enabled("infernal_boar")
            or settings.enabled("infernal_wolf")
    end, world_esp.begin_dynamic_scan, world_esp.step_dynamic_scan, world_esp.complete_dynamic_scan, 120)
    iscan.register("loot", SCAN_MS, function()
        return settings.enabled("infernal_loot_enabled") or map_on("loot")()
    end, loot_esp.begin_static_scan, loot_esp.step_static_scan, loot_esp.complete_static_scan, 240)
    iscan.register("loot_drops", DROPS_SCAN_MS, function()
        if settings.enabled("infernal_loot_enabled") then
            return settings.enabled("infernal_dropped_item")
        end
        return map_on("loot")()
    end, loot_esp.begin_drops_scan, loot_esp.step_drops_scan, loot_esp.complete_drops_scan, 360)
    iscan.register("base", SCAN_MS, function()
        return settings.enabled("infernal_base_enabled") or map_on("base")()
    end, base_esp.begin_static_scan, base_esp.step_static_scan, base_esp.complete_static_scan, 480)
end
function M.update(dt)
    cache.refresh_entities()
    npcs.refresh_cache(cache.workspace_entities)
    player_state.tick(cache.players)
    bootstrap.tick()
    weapons.tick()
    runservice.dispatch(dt)
    incremental_scan.tick()
    pcall(rbx_offsets.tick_fps)
    for i = 1, #M._update_dispatch do
        local call = M._update_dispatch[i]
        debug.guard_fast(call.name, call.fn, dt)
    end
end
function M.draw()
    for i = 1, #M._draw_dispatch do
        local call = M._draw_dispatch[i]
        debug.guard_fast(call.name, call.fn)
    end
end
function M.init()
    local env = Infernal.require("core.env")
    local ok = env.require_apis({ "draw", "utility", "entity", "game" })
    if not ok then
        return false
    end
    pcall(function()
        Infernal.require("ui.menu_shim").install()
    end)
    pcall(function()
        Infernal.require("core.rbx_offsets").boot()
    end)
    M.register_all()
    M.setup_scans()
    M.setup_player_hooks()
    pcall(function()
        Infernal.require("features.utility.config").try_autoload()
    end)
    return true
end
function M.setup_player_hooks()
    local mod = Infernal.require("features.utility.mod_checker")
    _G.on_player_added = function(p)
        debug.guard_fast("on_player_added", mod.on_player_added, p)
    end
    _G.on_player_removed = function(p)
        debug.guard_fast("on_player_removed", mod.on_player_removed, p)
    end
end
return M
end)()

Infernal._mods["app"] = (function()
local tabs = Infernal.require("menu.tabs")
local debug = Infernal.require("core.debug")
local notify = Infernal.require("core.notify")
local custom_menu = Infernal.require("ui.custom_menu")
local startup_intro = Infernal.require("ui.startup_intro")
local api_aliases = Infernal.require("core.api_aliases")
local feature_bind = Infernal.require("core.feature_bind")
local aim_key = Infernal.require("core.aim_key")
local overlay_theme = Infernal.require("core.overlay_theme")
local settings = Infernal.require("core.settings")
local image_cache = Infernal.require("core.image_cache")
local manip_math = { prune_caches = function() end }
local M = {}
local initialized = false
local alias_refresh_elapsed = 0
function M.init()
    if initialized then return true end
    pcall(function()
        Infernal.require("core.entity_props").ensure_api_aliases()
    end)
    initialized = tabs.init()
    if initialized then
        pcall(custom_menu.init)
        pcall(startup_intro.init)
    end
    return initialized
end
function M.on_frame()
    if not initialized then return end
    debug.tick_frame()
    settings.begin_frame(debug.frame_count())
    image_cache.prune()
    manip_math.prune_caches()
    pcall(feature_bind.tick)
    pcall(aim_key.tick, "infernal_aim_key", "infernal_aim_key_mode")
    if startup_intro.is_active() then
        if startup_intro.should_reveal_menu() then
            debug.guard_fast("custom_menu.draw:intro", custom_menu.draw)
        end
        local ok = pcall(startup_intro.draw)
        if ok then
            return
        end
        startup_intro.cancel()
    end
    local dt = 0.016
    if utility and utility.get_delta_time then
        local ok, v = pcall(utility.get_delta_time)
        if ok and type(v) == "number" then dt = v end
    end
    alias_refresh_elapsed = alias_refresh_elapsed + dt
    if alias_refresh_elapsed >= 2 then
        alias_refresh_elapsed = 0
        pcall(api_aliases.apply)
    end
    debug.guard_fast("tabs.update", tabs.update, dt)
    debug.guard_fast("overlay_theme.sync", overlay_theme.sync)
    debug.guard_fast("tabs.draw", tabs.draw)
    debug.guard_fast("notify.draw", notify.draw)
    debug.guard_fast("custom_menu.draw", custom_menu.draw)
end
return M
end)()

do
    Infernal.require("ui.menu_shim").install()
    Infernal.require("menu.tabs").register_all()
end

Infernal._init_ok = false

local ok, err = pcall(function()
    local debug = Infernal.require("core.debug")
    local caps = Infernal.require("core.capabilities")
    local app = Infernal.require("app")

    if not app.init() then
        return
    end

    Infernal.require("core.api_aliases").apply()
    Infernal.require("features.movement.anti_fling").install()

    Infernal._init_ok = true

    local c = caps.probe()

    debug.register_frame_hook(function()
        app.on_frame()
    end)
end)

if not ok then
    print("[Infernal] Fatal: " .. tostring(err))
end